import * as THREE from "three";

// ─── Renderer ────────────────────────────────────────────────────────────────
const canvas = document.getElementById("canvas");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// ─── Scene + Camera ──────────────────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a18);
scene.fog = new THREE.FogExp2(0x0a0a18, 0.05);

const camera = new THREE.PerspectiveCamera(52, innerWidth / innerHeight, 0.1, 80);
camera.position.set(0, 3.0, 8.0);
camera.lookAt(0, 1.1, 0);

// ─── Lights ──────────────────────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x3050a0, 2.2));

const rimLight = new THREE.DirectionalLight(0x6080ff, 1.4);
rimLight.position.set(-4, 6, -4);
rimLight.castShadow = true;
rimLight.shadow.mapSize.setScalar(1024);
scene.add(rimLight);

const fillLight = new THREE.DirectionalLight(0x204080, 0.6);
fillLight.position.set(4, 2, 3);
scene.add(fillLight);

const cursorLight = new THREE.PointLight(0xff9060, 3.5, 11);
scene.add(cursorLight);

// ─── Ground ──────────────────────────────────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(6, 64),
  new THREE.MeshStandardMaterial({ color: 0x0d0d24, roughness: 0.95, metalness: 0.1 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Spotlight ring under character
const ring = new THREE.Mesh(
  new THREE.RingGeometry(0.52, 0.70, 64),
  new THREE.MeshBasicMaterial({
    color: 0x4488ff,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.18,
    depthWrite: false,
  })
);
ring.rotation.x = -Math.PI / 2;
ring.position.y = 0.003;
scene.add(ring);

// ─── Character Materials ──────────────────────────────────────────────────────
const skinMat  = new THREE.MeshToonMaterial({ color: 0xf5b895 });
const shirtMat = new THREE.MeshToonMaterial({ color: 0x2979ff });
const pantsMat = new THREE.MeshToonMaterial({ color: 0x1c2833 });
const shoeMat  = new THREE.MeshToonMaterial({ color: 0x141414 });
const hairMat  = new THREE.MeshToonMaterial({ color: 0x3a1f05 });
const eyeWMat  = new THREE.MeshToonMaterial({ color: 0xffffff });
const pupilMat = new THREE.MeshToonMaterial({
  color: 0x111111,
  emissive: new THREE.Color(0x0022cc),
  emissiveIntensity: 0.9,
});

function shadow(mesh) {
  mesh.castShadow = true;
  return mesh;
}

// ─── Character ───────────────────────────────────────────────────────────────
const character = new THREE.Group();
scene.add(character);

// Hip pivots (legs hang down from here)
const leftHip  = new THREE.Group(); leftHip.position.set(-0.19, 0.70, 0);
const rightHip = new THREE.Group(); rightHip.position.set(0.19, 0.70, 0);

[leftHip, rightHip].forEach(hip => {
  // Thigh + shin (capsule)
  const leg = shadow(new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.46, 4, 8), pantsMat));
  leg.position.y = -0.33;

  // Shoe (flattened sphere)
  const shoe = shadow(new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), shoeMat));
  shoe.position.set(0.0, -0.63, 0.07);
  shoe.scale.set(1.05, 0.58, 1.45);

  hip.add(leg, shoe);
  character.add(hip);
});

// Body / torso
const body = shadow(new THREE.Mesh(
  new THREE.CylinderGeometry(0.245, 0.305, 0.80, 8),
  shirtMat
));
body.position.y = 1.06;
character.add(body);

// Shoulder pivots (arms hang down)
const leftShoulder  = new THREE.Group(); leftShoulder.position.set(-0.385, 1.40, 0);
const rightShoulder = new THREE.Group(); rightShoulder.position.set(0.385, 1.40, 0);

[leftShoulder, rightShoulder].forEach(shoulder => {
  const arm = shadow(new THREE.Mesh(new THREE.CapsuleGeometry(0.09, 0.44, 4, 8), skinMat));
  arm.position.y = -0.27;

  const hand = shadow(new THREE.Mesh(new THREE.SphereGeometry(0.10, 8, 6), skinMat));
  hand.position.y = -0.58;

  shoulder.add(arm, hand);
  character.add(shoulder);
});

// Neck
const neck = shadow(new THREE.Mesh(
  new THREE.CylinderGeometry(0.10, 0.12, 0.14, 8),
  skinMat
));
neck.position.y = 1.54;
character.add(neck);

// Head pivot (tilts independently on x-axis)
const headPivot = new THREE.Group();
headPivot.position.y = 1.82;
character.add(headPivot);

const headMesh = shadow(new THREE.Mesh(new THREE.SphereGeometry(0.33, 16, 16), skinMat));
headPivot.add(headMesh);

// Hair (top hemisphere)
const hair = new THREE.Mesh(
  new THREE.SphereGeometry(0.345, 16, 10, 0, Math.PI * 2, 0, Math.PI * 0.52),
  hairMat
);
hair.position.y = 0.09;
headPivot.add(hair);

// Eyes
[-0.115, 0.115].forEach(x => {
  const white = new THREE.Mesh(new THREE.SphereGeometry(0.082, 8, 8), eyeWMat);
  white.position.set(x, 0.065, 0.285);
  headPivot.add(white);

  const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.050, 8, 8), pupilMat);
  pupil.position.set(x, 0.065, 0.325);
  headPivot.add(pupil);
});

// ─── Cursor State ─────────────────────────────────────────────────────────────
const mouse      = new THREE.Vector2();
const raycaster  = new THREE.Raycaster();
const groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
const cursor3D   = new THREE.Vector3(0, 0, 5);
const prevCursor = new THREE.Vector3(0, 0, 5);

let isWalking = false;
let walkTimer = 0;
let walkPhase = 0;
let idlePhase = 0;

const onPointer = (x, y) => {
  mouse.x = (x / innerWidth)  * 2 - 1;
  mouse.y = -(y / innerHeight) * 2 + 1;
};

window.addEventListener("mousemove", e => onPointer(e.clientX, e.clientY));
window.addEventListener("touchmove", e => {
  onPointer(e.touches[0].clientX, e.touches[0].clientY);
}, { passive: true });

// ─── Animation Loop ───────────────────────────────────────────────────────────
const clock = new THREE.Clock();

(function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  idlePhase += dt;

  // Project cursor onto ground plane
  raycaster.setFromCamera(mouse, camera);
  const hit = new THREE.Vector3();
  if (raycaster.ray.intersectPlane(groundPlane, hit)) {
    cursor3D.lerp(hit, 0.1);
  }

  // Cursor movement speed detection
  const cursorSpeed = cursor3D.distanceTo(prevCursor) / (dt + 0.001);
  prevCursor.copy(cursor3D);

  if (cursorSpeed > 0.28) {
    isWalking = true;
    walkTimer = 0.45;
  }
  if (walkTimer > 0) {
    walkTimer -= dt;
    if (walkTimer <= 0) isWalking = false;
  }

  // Rotate character to face cursor (atan2 on the ground plane)
  const dx = cursor3D.x - character.position.x;
  const dz = cursor3D.z - character.position.z;
  const targetFacing = Math.atan2(dx, dz);
  character.rotation.y += (targetFacing - character.rotation.y) * 0.08;

  // Head tilt — look up/down based on cursor elevation relative to head
  const flatDist = Math.sqrt(dx * dx + dz * dz);
  const targetTilt = Math.atan2(1.5 - 1.82, flatDist + 0.6) * 0.38;
  headPivot.rotation.x += (targetTilt - headPivot.rotation.x) * 0.1;

  // Animate limbs
  if (isWalking) {
    walkPhase += dt * 5.8;
    const s = Math.sin(walkPhase) * 0.45;
    leftHip.rotation.x       =  s;
    rightHip.rotation.x      = -s;
    leftShoulder.rotation.x  = -s * 0.55;
    rightShoulder.rotation.x =  s * 0.55;
    // Slight bounce when walking
    character.position.y = Math.abs(Math.sin(walkPhase * 2)) * 0.045;
  } else {
    // Ease limbs back to rest
    leftHip.rotation.x       *= 0.87;
    rightHip.rotation.x      *= 0.87;
    leftShoulder.rotation.x  *= 0.87;
    rightShoulder.rotation.x *= 0.87;
    // Idle float
    character.position.y = Math.sin(idlePhase * 1.15) * 0.038;
  }

  // Cursor light tracks the 3D cursor position
  cursorLight.position.set(cursor3D.x, Math.max(1.4, cursor3D.y + 1.2), cursor3D.z);

  renderer.render(scene, camera);
})();

// ─── Resize ──────────────────────────────────────────────────────────────────
window.addEventListener("resize", () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

