import * as THREE from "three";

// ─── Renderer ────────────────────────────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({
  canvas: document.getElementById("canvas"),
  antialias: false,
});
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);

// ─── Scene + Camera ──────────────────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050510);

const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 80);
camera.position.set(0, 0, 15);

// ─── Orb System ──────────────────────────────────────────────────────────────
const N = 280;

// Geometry: small sphere for each orb
const orbGeo = new THREE.SphereGeometry(0.18, 8, 6);

// Material with additive blending for automatic glow where orbs overlap
const orbMat = new THREE.MeshBasicMaterial({
  vertexColors: true,
  blending: THREE.AdditiveBlending,
  transparent: true,
  depthWrite: false,
});

const orbMesh = new THREE.InstancedMesh(orbGeo, orbMat, N);
orbMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
scene.add(orbMesh);

// ─── Orb State Arrays ─────────────────────────────────────────────────────────
// Float32Arrays for positions, velocities, and home positions (N × 3)
const pos  = new Float32Array(N * 3);
const vel  = new Float32Array(N * 3);
const home = new Float32Array(N * 3);

// Initialize orbs on a sphere shell of radius 3.5–6
const colorNear = new THREE.Color(0xff6633);
const colorFar  = new THREE.Color(0x4455ff);

for (let i = 0; i < N; i++) {
  const r     = 3.2 + Math.random() * 2.8;
  const theta = Math.random() * Math.PI * 2;
  const phi   = Math.acos(2 * Math.random() - 1);

  const x = r * Math.sin(phi) * Math.cos(theta);
  const y = r * Math.sin(phi) * Math.sin(theta);
  const z = r * Math.cos(phi) * 0.45; // flatten on z axis → disc-like

  home[i*3]   = pos[i*3]   = x;
  home[i*3+1] = pos[i*3+1] = y;
  home[i*3+2] = pos[i*3+2] = z;

  // Init colors to "far" color
  orbMesh.setColorAt(i, colorFar);
}
if (orbMesh.instanceColor) orbMesh.instanceColor.needsUpdate = true;

// ─── Cursor Tracking ─────────────────────────────────────────────────────────
const mouse   = new THREE.Vector2();
const cursor3D = new THREE.Vector3();
const raycaster = new THREE.Raycaster();
// Intersect a plane facing the camera at z=0
const frontPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);

window.addEventListener("mousemove", e => {
  mouse.x = (e.clientX / innerWidth)  * 2 - 1;
  mouse.y = -(e.clientY / innerHeight) * 2 + 1;
});
window.addEventListener("touchmove", e => {
  mouse.x = (e.touches[0].clientX / innerWidth)  * 2 - 1;
  mouse.y = -(e.touches[0].clientY / innerHeight) * 2 + 1;
}, { passive: true });

// ─── Reusable Objects ─────────────────────────────────────────────────────────
const dummy     = new THREE.Object3D();
const colorTemp = new THREE.Color();

// Physics constants
const ATTRACT = 0.048;  // pull toward cursor
const RESTORE = 0.014;  // pull toward home position
const DAMPING = 0.875;  // velocity damping per frame
const NOISE   = 0.008;  // random jitter

// ─── Animation Loop ───────────────────────────────────────────────────────────
(function animate() {
  requestAnimationFrame(animate);

  // Project mouse onto frontal plane to get 3D cursor pos
  raycaster.setFromCamera(mouse, camera);
  const hit = new THREE.Vector3();
  if (raycaster.ray.intersectPlane(frontPlane, hit)) {
    cursor3D.lerp(hit, 0.12);
  }

  for (let i = 0; i < N; i++) {
    const ix = i * 3;
    const iy = ix + 1;
    const iz = ix + 2;

    const px = pos[ix], py = pos[iy], pz = pos[iz];

    // Spring forces: attraction to cursor + restoration to home + noise
    const ax = (cursor3D.x - px) * ATTRACT + (home[ix] - px) * RESTORE + (Math.random() - 0.5) * NOISE;
    const ay = (cursor3D.y - py) * ATTRACT + (home[iy] - py) * RESTORE + (Math.random() - 0.5) * NOISE;
    const az = (cursor3D.z - pz) * ATTRACT + (home[iz] - pz) * RESTORE + (Math.random() - 0.5) * NOISE;

    vel[ix] = (vel[ix] + ax) * DAMPING;
    vel[iy] = (vel[iy] + ay) * DAMPING;
    vel[iz] = (vel[iz] + az) * DAMPING;

    pos[ix] += vel[ix];
    pos[iy] += vel[iy];
    pos[iz] += vel[iz];

    // Distance to cursor → drives color and scale
    const cdx = cursor3D.x - pos[ix];
    const cdy = cursor3D.y - pos[iy];
    const cdz = cursor3D.z - pos[iz];
    const dist = Math.sqrt(cdx*cdx + cdy*cdy + cdz*cdz);

    // Orbs near cursor are larger and warmer
    const t01 = Math.min(dist / 7, 1);
    const scale = (1 - t01 * 0.45) * (0.8 + Math.sin(dist + performance.now() * 0.001) * 0.12);

    dummy.position.set(pos[ix], pos[iy], pos[iz]);
    dummy.scale.setScalar(scale);
    dummy.updateMatrix();
    orbMesh.setMatrixAt(i, dummy.matrix);

    // Color: warm orange near cursor → cool blue far away
    colorTemp.lerpColors(colorNear, colorFar, Math.min(t01 * 1.2, 1));
    orbMesh.setColorAt(i, colorTemp);
  }

  orbMesh.instanceMatrix.needsUpdate = true;
  if (orbMesh.instanceColor) orbMesh.instanceColor.needsUpdate = true;

  renderer.render(scene, camera);
})();

// ─── Resize ──────────────────────────────────────────────────────────────────
window.addEventListener("resize", () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

snippets.css:
:root {
  color-scheme: dark;
  font-family: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: #080808;
  color: #e2e8f0;
}

.grid-stage {
  min-height: 100vh;
  padding: 2rem 1.5rem;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(300px, 100%), 1fr));
  gap: 1rem;
  align-content: start;
}

.resource-card {
  width: 100%;
  padding: 1.25rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
  cursor: default;
}

.resource-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
  transform: translateY(-2px);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.card-category {
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.32);
