.stage {
  width: 100%;
  max-width: 1280px;
  padding: 3rem 2.5rem; /* room for the -18px arrows on both sides */
}

/* ─── Carousel container ─── */
.carousel-wrap {
  position: relative;
}

/* ─── Arrow buttons ─── */
.arrow {
  position: absolute;
  top: 50%;
  z-index: 10;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.arrow:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #f8fafc;
}

.arrow-prev { left: -18px; }
.arrow-next { right: -18px; }

/* ─── Scrollable track ─── */
.carousel-track {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 8px 2px;
  list-style: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ─── Cards ─── */
.carousel-card {
  flex: 0 0 220px;
  scroll-snap-align: start;
  padding: 1.5rem 1.25rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  transition: border-color 0.2s, background 0.2s;
  cursor: default;
}

.carousel-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
}

.card-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.65);
}

.card-count {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f8fafc;
  line-height: 1;
}

/* ─── Responsive ─── */
@media (max-width: 640px) {
  .stage { padding: 2rem 1rem; }

  /* Hide arrows on mobile — use touch swipe instead */
  .arrow { display: none; }

  /* Show partial next card as scroll hint */
  .carousel-track { padding: 8px 0; }
  .carousel-card  { flex: 0 0 min(200px, 72vw); }
}

@media (max-width: 360px) {
  .carousel-card { flex: 0 0 82vw; }
}

