.space-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  perspective: 800px;
  perspective-origin: 50% 50%;
  overflow: hidden;
  pointer-events: none;
}

/* ─── Individual code panels ─── */
.space-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 200px;
  transform: translate(-50%, -50%);
  transform-style: preserve-3d;
  border: 1px solid color-mix(in srgb, var(--color) 35%, transparent);
  border-radius: 8px;
  background: rgba(3, 7, 18, 0.85);
  padding: 10px 12px;
  will-change: transform, opacity;
  transition: opacity 0.1s linear;
}

.space-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: color-mix(in srgb, var(--color) 6%, transparent);
}

/* ─── Code text inside panels ─── */
.space-code {
  position: relative;
  font-family: "Fira Code", "Cascadia Code", "Consolas", ui-monospace, monospace;
  font-size: 0.625rem;
  line-height: 1.6;
  color: color-mix(in srgb, var(--color) 80%, #e2e8f0 20%);
  white-space: pre;
  overflow: hidden;
  pointer-events: none;
  user-select: none;
}

/* ─── Hero content (on top of the background) ─── */
