/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-card: #111111;
  --bg-tertiary: #1a1a1a;
  --bg-bubble-sent: #1a2744;
  --bg-bubble-received: #1a1a1a;
  --border: #222222;
  --border-light: #333333;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-red: #ef4444;
  --radius: 10px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
}

body {
  min-height: 100vh;
  padding-block: 40px;
  padding-inline: 24px;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

code {
  font-family: "SF Mono", "Fira Code", "Cascadia Code", monospace;
  font-size: 0.82em;
  background: var(--bg-tertiary);
  padding-block: 2px;
  padding-inline: 6px;
  border-radius: 4px;
  color: var(--accent-blue);
}

/* ── Page ── */
.page {
  max-inline-size: 800px;
  margin-inline: auto;
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-block-end: 40px;
  flex-wrap: wrap;
  gap: 16px;
}

.page-title {
  font-size: 1.6rem;
  font-weight: 700;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 8px;
  padding-inline: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-tertiary);
}

/* ── Demo sections ── */
.demo-section {
  margin-block-end: 48px;
}

.section-title {
  font-size: 1.15rem;
  font-weight: 600;
  margin-block-end: 8px;
}

.section-desc {
  font-size: 0.88rem;
  color: var(--text-secondary);
  margin-block-end: 20px;
}

/* ── Text cards ── */
.text-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 20px;
  padding-inline: 24px;
  margin-block-end: 12px;
}

.mixed-text {
  font-size: 1rem;
  line-height: 1.8;
  color: var(--text-primary);
}

.embedded-ltr {
  color: var(--accent-blue);
  font-weight: 500;
}

.embedded-rtl {
  color: var(--accent-blue);
  font-weight: 500;
  font-size: 1.05em;
}

/* ── Mixed list ── */
.mixed-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.list-item {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding-block: 14px;
  padding-inline: 20px;
}

.list-number {
  inline-size: 28px;
  block-size: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--accent-blue);
  flex-shrink: 0;
}

.list-text {
  font-size: 0.92rem;
  line-height: 1.5;
}

/* ── Chat ── */
.chat-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 24px;
  padding-inline: 24px;
}

.chat-bubble {
  max-inline-size: 80%;
  padding-block: 12px;
  padding-inline: 16px;
  border-radius: 12px;
  position: relative;
}

.chat-bubble.sent {
  align-self: flex-end;
  background: var(--bg-bubble-sent);
  border-end-end-radius: 4px;
}

.chat-bubble.received {
  align-self: flex-start;
  background: var(--bg-bubble-received);
  border: 1px solid var(--border);
  border-end-start-radius: 4px;
}

.bubble-sender {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-blue);
  margin-block-end: 4px;
}

.bubble-text {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--text-primary);
}

.bubble-text .embedded-ltr {
  color: var(--accent-green);
}

.bubble-time {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-block-start: 6px;
  text-align: end;
}

/* ── Comparison ── */
.comparison-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.comparison-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.comparison-card.correct {
  border-color: rgba(34, 197, 94, 0.3);
}

.comparison-card.incorrect {
  border-color: rgba(239, 68, 68, 0.3);
}

.comparison-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-block: 10px;
  padding-inline: 16px;
  border-block-end: 1px solid var(--border);
  background: var(--bg-primary);
}

.comp-badge {
  font-size: 0.76rem;
  font-weight: 600;
  padding-block: 2px;
  padding-inline: 8px;
  border-radius: 4px;
}

.comp-badge.good {
  background: rgba(34, 197, 94, 0.12);
  color: var(--accent-green);
}

.comp-badge.bad {
  background: rgba(239, 68, 68, 0.12);
  color: var(--accent-red);
}

.comp-code {
  font-size: 0.72rem;
}

.comparison-body {
  padding-block: 16px;
  padding-inline: 16px;
}

.comp-text {
  font-size: 0.92rem;
  line-height: 1.7;
  margin-block-end: 12px;
  padding-block: 10px;
  padding-inline: 14px;
  background: var(--bg-tertiary);
  border-radius: 6px;
}

.comp-note {
  font-size: 0.78rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ── Responsive ── */
@media (max-width: 640px) {
  body {
    padding-inline: 16px;
  }

  .comparison-grid {
    grid-template-columns: 1fr;
  }

  .chat-bubble {
    max-inline-size: 90%;
  }
}

