@import url("https://fonts.cdnfonts.com/css/opendyslexic");

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.6;
  min-height: 100vh;
  transition: background-color 0.4s ease, color 0.4s ease;
}

.container {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

/* ---- Header ---- */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  flex-wrap: wrap;
}

.header__title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #f4f4f5;
  letter-spacing: -0.02em;
}

/* ---- Toggle Button ---- */
.toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.625rem 1.125rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.04);
  color: #a1a1aa;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.25s ease;
  white-space: nowrap;
}

.toggle-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #e4e4e7;
  border-color: rgba(255, 255, 255, 0.2);
}

.toggle-btn[aria-pressed="true"] {
  background: rgba(139, 92, 246, 0.15);
  border-color: rgba(139, 92, 246, 0.4);
  color: #c4b5fd;
}

.toggle-btn__icon {
  display: inline-block;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  border: 2px solid currentColor;
  position: relative;
  transition: all 0.25s ease;
  flex-shrink: 0;
}

.toggle-btn[aria-pressed="true"] .toggle-btn__icon {
  background: #8b5cf6;
  border-color: #8b5cf6;
}

.toggle-btn[aria-pressed="true"] .toggle-btn__icon::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* ---- Article ---- */
.article {
  transition: all 0.4s ease;
}

.article__heading {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f4f4f5;
  margin-bottom: 1.25rem;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.article__subheading {
  font-size: 1.25rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-top: 2rem;
  margin-bottom: 1rem;
  letter-spacing: -0.01em;
}

.article__text {
  font-size: 1rem;
  color: #a1a1aa;
  margin-bottom: 1.25rem;
  max-width: 65ch;
  transition: all 0.4s ease;
}

.article__list {
  list-style: none;
  margin-bottom: 1.5rem;
  padding-left: 0;
  max-width: 65ch;
}

.article__list li {
  position: relative;
  padding-left: 1.5rem;
  margin-bottom: 0.625rem;
  color: #a1a1aa;
  font-size: 0.9375rem;
  line-height: 1.6;
  transition: all 0.4s ease;
}

.article__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #8b5cf6;
}

.article__quote {
  border-left: 3px solid #8b5cf6;
  padding: 1.25rem 1.5rem;
  margin: 1.5rem 0;
  background: rgba(139, 92, 246, 0.06);
  border-radius: 0 8px 8px 0;
  max-width: 65ch;
  transition: all 0.4s ease;
}

.article__quote p {
  font-style: italic;
  color: #c4b5fd;
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: 0.5rem;
}

.article__quote cite {
  font-style: normal;
  font-size: 0.8125rem;
  color: #71717a;
}

/* ---- Footer ---- */
.footer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer__text {
  font-size: 0.8125rem;
  color: #52525b;
}

/* ============================
   Dyslexia-Friendly Mode
   ============================ */

