  grid-template-columns: 260px 1fr;
  gap: 2rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

/* ── Drawer toggle (hidden on desktop) ── */
.drawer-toggle {
  display: none;
}

.drawer-backdrop {
  display: none;
}

/* ── Mobile: drawer pattern ── */
@media (max-width: 768px) {
  .container {
    grid-template-columns: 1fr;
    gap: 0;
    padding: 1rem 0.75rem;
  }

  /* Hide controls as inline block, convert to drawer */
  .controls {
    position: fixed;
    inset-inline-start: 0;
    inset-inline-end: 0;
    bottom: 0;
    top: auto;
    z-index: 1000;
    border-radius: 16px 16px 0 0;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-bottom: none;
    background: #111113;
    padding: 1.25rem 1.25rem 2rem;
    transform: translateY(100%);
    transition: transform 0.3s ease;
    max-height: 70vh;
    overflow-y: auto;
  }

  .controls.drawer-open {
    transform: translateY(0);
  }

  /* Drawer handle */
  .controls::before {
    content: "";
    display: block;
    width: 36px;
    height: 4px;
    background: rgba(255, 255, 255, 0.2);
    border-radius: 2px;
    margin: 0 auto 1rem;
  }

  .controls__title {
    font-size: 0.85rem;
    margin-bottom: 1rem;
  }

  .controls__group {
    margin-bottom: 1rem;
  }

  .controls__modes {
    gap: 0.25rem;
  }

  .mode-btn {
    padding: 0.5rem 0.25rem;
    font-size: 0.7rem;
  }

  /* FAB toggle */
  .drawer-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    position: fixed;
    bottom: 1.25rem;
    right: 1.25rem;
    z-index: 999;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: #8b5cf6;
    color: #fff;
    border: none;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(139, 92, 246, 0.4);
    transition: transform 0.2s, background 0.2s;
  }

  .drawer-toggle:hover {
    transform: scale(1.05);
  }

  .drawer-toggle.active {
    background: #6d28d9;
    transform: rotate(90deg);
  }

  /* Backdrop */
  .drawer-backdrop {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
  }

  .drawer-backdrop.active {
    display: block;
  }

  /* Article adjustments */
  .article__title {
    font-size: 1.3rem;
