  margin-bottom: 1.25rem;
}

.controls__group {
  margin-bottom: 1.25rem;
}

.controls__group:last-child {
  margin-bottom: 0;
}

.controls__label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: #e4e4e7;
  cursor: pointer;
  user-select: none;
}

.controls__checkbox {
  display: none;
}

.controls__check-icon {
