/* ---- Article ---- */
.article__title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f4f4f5;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.article__subtitle {
  font-size: 1.25rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

.article__text {
  font-size: 1rem;
  color: #a1a1aa;
  margin-bottom: 1.25rem;
