  border-radius: 2px;
}

.guide--band.visible {
  opacity: 0.12;
}

.guide-overlay {
  position: fixed;
  left: 0;
  width: 100%;
  background: rgba(0, 0, 0, 0.65);
  pointer-events: none;
  z-index: 9999;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.guide-overlay.visible {
  opacity: 1;
}

.guide-overlay--top {
  top: 0;
}

.guide-overlay--bottom {
  bottom: 0;
}

