.tree-item[aria-level="1"] > .tree-item-content {
  padding-left: 0.75rem;
}

.tree-item[aria-level="2"] > .tree-item-content {
  padding-left: 1.75rem;
}

.tree-item[aria-level="3"] > .tree-item-content {
  padding-left: 2.75rem;
}

/* Indent lines */
.tree-item[aria-level="2"]::before {
  content: "";
  position: absolute;
  left: 1.35rem;
  top: 0;
  bottom: 0;
  width: 1px;
  background: #1e1e22;
}

.tree-item[aria-level="3"]::before {
  content: "";
  position: absolute;
  left: 2.35rem;
  top: 0;
  bottom: 0;
  width: 1px;
  background: #1e1e22;
}

/* Chevron */
.tree-chevron {
  width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.15s;
}

.tree-chevron::before {
  content: "";
  width: 0;
  height: 0;
  border-left: 5px solid #52525b;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
}

.tree-item[aria-expanded="true"] > .tree-item-content .tree-chevron {
  transform: rotate(90deg);
}

.tree-item[aria-expanded="true"] > .tree-item-content .tree-chevron::before {
  border-left-color: #a1a1aa;
}

.tree-spacer {
  width: 16px;
  height: 16px;
  display: inline-block;
  flex-shrink: 0;
}

/* File Icons */
.tree-icon {
  width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 3px;
}

.tree-icon--folder {
  color: #f59e0b;
}

.tree-icon--folder::before {
  content: "";
  width: 14px;
  height: 11px;
  background: currentColor;
  border-radius: 1px 3px 3px 3px;
  position: relative;
  clip-path: polygon(0% 20%, 35% 20%, 45% 0%, 100% 0%, 100% 100%, 0% 100%);
}

.tree-item[aria-expanded="true"] > .tree-item-content .tree-icon--folder {
  color: #fbbf24;
}

.tree-icon--tsx {
  background: #1e40af;
  color: #93c5fd;
}

.tree-icon--tsx::before {
  content: "TX";
}

.tree-icon--ts {
  background: #1e3a5f;
  color: #60a5fa;
}

.tree-icon--ts::before {
  content: "TS";
}

.tree-icon--css {
  background: #1e3a5f;
  color: #38bdf8;
}

.tree-icon--css::before {
  content: "CS";
}

.tree-icon--json {
  background: #365314;
  color: #86efac;
}

.tree-icon--json::before {
  content: "{}";
}

.tree-icon--img {
  background: #4a1d6a;
  color: #c084fc;
}

.tree-icon--img::before {
  content: "IM";
}

.tree-icon--file {
  background: #27272a;
  color: #a1a1aa;
}

.tree-icon--file::before {
  content: "FI";
}

.tree-label {
  color: #d4d4d8;
  user-select: none;
}

.tree-item--folder > .tree-item-content .tree-label {
  font-weight: 500;
  color: #e4e4e7;
}

/* Info Panel */
.info-panel {
  margin-top: 2rem;
  background: #111113;
