}

.section-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: #d4d4d4;
  margin-bottom: 14px;
}

/* ── Toolbar ──────────────────────────────────────── */

.toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #161616;
  border: 1px solid #262626;
  border-radius: 10px;
  padding: 6px 8px;
}

.toolbar-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 36px;
  background: transparent;
  border: none;
  border-radius: 7px;
  color: #999;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
}

.toolbar-btn:hover {
  background: #222;
  color: #d4d4d4;
}

.toolbar-btn:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
  color: #f5f5f5;
}

.toolbar-btn[aria-pressed="true"] {
  background: #2d2d5e;
  color: #a5b4fc;
}

.toolbar-separator {
  width: 1px;
  height: 24px;
  background: #333;
  margin: 0 4px;
  flex-shrink: 0;
}

/* ── Radio Group ──────────────────────────────────── */

.radio-group {
