  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 2px solid #444;
  border-radius: 50%;
  flex-shrink: 0;
  transition: border-color 0.15s;
}

.radio-item[aria-checked="true"] .radio-indicator {
  border-color: #6366f1;
}

.radio-item[aria-checked="true"] .radio-indicator::after {
  content: "";
  width: 8px;
  height: 8px;
  background: #6366f1;
  border-radius: 50%;
}

.radio-label {
