.color-swatch[aria-selected="true"] {
  border-color: #fff;
  box-shadow: 0 0 0 2px #6366f1;
  transform: scale(1.05);
}

.color-selected {
  margin-top: 12px;
  font-size: 0.85rem;
  color: #888;
}

/* ── Tab Order Visualizer ─────────────────────────── */

.tab-order-info {
  font-size: 0.85rem;
  color: #888;
  line-height: 1.6;
  margin-bottom: 14px;
