  height: 22px;
  padding: 0 6px;
  background: #1a1a1a;
  border: 1px solid #333;
  border-bottom-width: 2px;
  border-radius: 4px;
  font-family: inherit;
  font-size: 0.7rem;
  font-weight: 600;
  color: #ccc;
}

.tabindex-display {
  background: #111;
  border: 1px solid #222;
  border-radius: 10px;
  padding: 16px 20px;
  font-family: "SF Mono", "Fira Code", "Cascadia Code", monospace;
  font-size: 0.78rem;
  color: #888;
  line-height: 1.8;
  white-space: pre-wrap;
  word-break: break-all;
}

.tabindex-display .active-tab {
  color: #22c55e;
  font-weight: 600;
}

.tabindex-display .inactive-tab {
  color: #555;
}

.tabindex-display .group-label {
  color: #6366f1;
  font-weight: 600;
}

/* ── Responsive ── */
@media (max-width: 600px) {
  body {
    padding: 1.25rem 0.75rem;
  }

  .demo-title {
    font-size: 1.35rem;
  }

  .demo-subtitle {
    font-size: 0.82rem;
    margin-bottom: 1.25rem;
  }

  .info-panel {
    padding: 14px 16px;
    margin-bottom: 1.5rem;
  }

  .info-title {
    font-size: 0.88rem;
  }

  .info-panel p {
    font-size: 0.8rem;
  }

  .example-section {
    margin-bottom: 1.5rem;
  }

  .section-title {
    font-size: 0.95rem;
    margin-bottom: 10px;
  }

  /* Toolbar: allow wrap */
  .toolbar {
    flex-wrap: wrap;
    padding: 6px;
  }

  .toolbar-btn {
    width: 36px;
    height: 34px;
  }

  /* Radio group: wrap into rows */
  .radio-group {
    flex-wrap: wrap;
    gap: 4px;
    padding: 6px;
  }

  .radio-item {
    padding: 7px 12px;
    font-size: 0.82rem;
    gap: 6px;
  }

  .radio-indicator {
    width: 16px;
    height: 16px;
  }

  .radio-item[aria-checked="true"] .radio-indicator::after {
    width: 7px;
