  }

  /* Color grid: smaller swatches */
  .color-grid {
    padding: 8px;
    gap: 4px;
    max-width: 100%;
  }

  .color-row {
    gap: 4px;
  }

  .color-swatch {
    width: 34px;
    height: 34px;
    border-radius: 6px;
  }

  .color-selected {
    font-size: 0.8rem;
  }

  /* Tab order visualizer */
  .tabindex-display {
    padding: 12px 14px;
    font-size: 0.7rem;
    overflow-x: auto;
  }

  .tab-order-info {
    font-size: 0.8rem;
    margin-bottom: 10px;
  }
}

@media (max-width: 360px) {
  .color-swatch {
    width: 28px;
    height: 28px;
  }

  .toolbar-btn {
    width: 32px;
    height: 30px;
  }

  .toolbar-btn svg {
    width: 15px;
    height: 15px;
  }
}

