*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #0a0a0a;
  color: #e5e5e5;
  min-height: 100vh;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ── Focus Tracker ────────────────────────────────── */

.focus-tracker {
  position: fixed;
  bottom: 20px;
  right: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: #111;
  border: 1px solid #2a2a2a;
  border-radius: 10px;
  font-size: 0.78rem;
  z-index: 500;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  max-width: 360px;
}

.tracker-label {
  color: #666;
  font-weight: 600;
  flex-shrink: 0;
}

.tracker-element {
  color: #22c55e;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.72rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── SPA Navigation ───────────────────────────────── */

.spa-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.spa-nav {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 28px;
  height: 56px;
  background: #111;
  border-bottom: 1px solid #1e1e1e;
}

.nav-brand {
  font-size: 0.95rem;
  font-weight: 700;
  color: #f5f5f5;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}

.spa-link {
  padding: 6px 14px;
  border-radius: 7px;
  font-size: 0.82rem;
  font-weight: 500;
  color: #777;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
}

.spa-link:hover {
  background: #1a1a1a;
  color: #ccc;
}

.spa-link.active {
  background: #1e1e2e;
  color: #e5e5e5;
}

.spa-link:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

/* ── SPA Main ─────────────────────────────────────── */

.spa-main {
  flex: 1;
  padding: 32px 40px;
  max-width: 780px;
  margin: 0 auto;
  width: 100%;
}

.spa-page {
  display: none;
}

.spa-page.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Pattern Info ─────────────────────────────────── */

.pattern-info {
  background: #111827;
  border: 1px solid #1e3a5f;
  border-radius: 10px;
  padding: 20px 24px;
  margin-bottom: 24px;
}

.pattern-badge {
  display: inline-block;
  padding: 3px 10px;
  background: #1e1e2e;
  border: 1px solid #3730a3;
  border-radius: 20px;
  font-size: 0.7rem;
  font-weight: 600;
  color: #a5b4fc;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.pattern-info h2 {
  font-size: 1rem;
  font-weight: 600;
  color: #93c5fd;
  margin-bottom: 6px;
}

.pattern-info p {
  font-size: 0.85rem;
  color: #94a3b8;
  line-height: 1.6;
}

/* ── Page Heading ─────────────────────────────────── */

.page-heading {
  font-size: 1.5rem;
  font-weight: 700;
  color: #f5f5f5;
  margin-bottom: 12px;
}

.page-heading:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 4px;
  border-radius: 4px;
}

.page-content {
  font-size: 0.9rem;
  color: #888;
  line-height: 1.6;
  margin-bottom: 24px;
}

/* ── Content Cards (Route Change) ─────────────────── */

.page-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.content-card {
  background: #111;
  border: 1px solid #222;
  border-radius: 12px;
  padding: 20px;
}

.content-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: #d4d4d4;
  margin-bottom: 6px;
}

.content-card p {
  font-size: 0.82rem;
  color: #777;
  line-height: 1.5;
  margin-bottom: 12px;
}

.card-link {
  font-size: 0.82rem;
