/* ── Menubar ──────────────────────────────────────── */

.menubar-container {
  position: relative;
  margin-bottom: 2rem;
  overflow-x: auto;
  /* smooth scrolling on iOS */
  -webkit-overflow-scrolling: touch;
  /* hide scrollbar but keep functionality */
  scrollbar-width: none;
}

.menubar-container::-webkit-scrollbar {
  display: none;
}

.menubar {
  display: flex;
  list-style: none;
  background: #161616;
