  gap: 2px;
  width: max-content;
  min-width: 100%;
}

.menubar-item {
  position: relative;
}

.menubar-button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: transparent;
  border: none;
  border-radius: 7px;
  color: #b0b0b0;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
}

.menubar-button:hover {
  background: #222;
  color: #e5e5e5;
}

.menubar-button:focus-visible {
