  transform: rotate(180deg);
}

.chevron {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

/* ── Submenu ─────────────────────────────────────── */

.submenu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  list-style: none;
  background: #161616;
  border: 1px solid #2a2a2a;
  border-radius: 10px;
  padding: 4px;
  min-width: 200px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
