(() => {
  const menubar = document.getElementById("menubar");
  const actionLog = document.getElementById("actionLog");
  const menubarButtons = [...menubar.querySelectorAll(".menubar-button")];

  let currentMenubarIndex = 0;
  let typeAheadBuffer = "";
  let typeAheadTimer = null;

  /* ── Helpers ──────────────────────────────────────── */

  function getSubmenu(button) {
    return button.parentElement.querySelector(".submenu");
  }

  function getMenuItems(submenu) {
    return [...submenu.querySelectorAll('[role="menuitem"]')];
  }

  function openSubmenu(button) {
    // Close all others first
    menubarButtons.forEach((btn) => closeSubmenu(btn));
    const submenu = getSubmenu(button);
    button.setAttribute("aria-expanded", "true");
    submenu.classList.add("open");
  }

  function closeSubmenu(button) {
    const submenu = getSubmenu(button);
    button.setAttribute("aria-expanded", "false");
    submenu.classList.remove("open");
    // Remove focused class from all items
    getMenuItems(submenu).forEach((item) => item.classList.remove("focused"));
  }

  function closeAllSubmenus() {
    menubarButtons.forEach((btn) => closeSubmenu(btn));
  }

  function isSubmenuOpen(button) {
    return button.getAttribute("aria-expanded") === "true";
  }

  function focusMenubarItem(index) {
    menubarButtons[currentMenubarIndex].setAttribute("tabindex", "-1");
    currentMenubarIndex = index;
    menubarButtons[currentMenubarIndex].setAttribute("tabindex", "0");
    menubarButtons[currentMenubarIndex].focus();
  }

  function focusSubmenuItem(submenu, index) {
    const items = getMenuItems(submenu);
    items.forEach((item) => item.classList.remove("focused"));
    if (index >= 0 && index < items.length) {
      items[index].classList.add("focused");
      items[index].focus();
    }
  }

  function getFocusedSubmenuIndex(submenu) {
    const items = getMenuItems(submenu);
    return items.findIndex((item) => item.classList.contains("focused"));
  }

  function logAction(text) {
    const placeholder = actionLog.querySelector(".log-placeholder");
    if (placeholder) placeholder.remove();

    const entry = document.createElement("p");
    entry.className = "log-entry";
    entry.textContent = text;
    actionLog.prepend(entry);

    // Keep only last 5 entries
    const entries = actionLog.querySelectorAll(".log-entry");
    if (entries.length > 5) {
      entries[entries.length - 1].remove();
    }
  }

  /* ── Menubar keyboard navigation ─────────────────── */

  menubarButtons.forEach((button, index) => {
    // Click to open/close
    button.addEventListener("click", () => {
      if (isSubmenuOpen(button)) {
        closeSubmenu(button);
      } else {
        openSubmenu(button);
        const submenu = getSubmenu(button);
        focusSubmenuItem(submenu, 0);
      }
      focusMenubarItem(index);
    });

    // Keyboard on menubar buttons
    button.addEventListener("keydown", (e) => {
      switch (e.key) {
        case "ArrowRight": {
          e.preventDefault();
          const wasOpen = isSubmenuOpen(button);
          closeAllSubmenus();
          const next = (index + 1) % menubarButtons.length;
          focusMenubarItem(next);
          if (wasOpen) {
            openSubmenu(menubarButtons[next]);
            focusSubmenuItem(getSubmenu(menubarButtons[next]), 0);
          }
          break;
        }
        case "ArrowLeft": {
          e.preventDefault();
          const wasOpen = isSubmenuOpen(button);
          closeAllSubmenus();
          const prev = (index - 1 + menubarButtons.length) % menubarButtons.length;
          focusMenubarItem(prev);
          if (wasOpen) {
            openSubmenu(menubarButtons[prev]);
            focusSubmenuItem(getSubmenu(menubarButtons[prev]), 0);
          }
          break;
        }
        case "ArrowDown":
        case "Enter":
        case " ": {
          e.preventDefault();
          openSubmenu(button);
          const submenu = getSubmenu(button);
          focusSubmenuItem(submenu, 0);
          break;
        }
        case "Escape": {
          e.preventDefault();
          closeAllSubmenus();
          break;
        }
        case "Home": {
          e.preventDefault();
          closeAllSubmenus();
          focusMenubarItem(0);
          break;
        }
        case "End": {
          e.preventDefault();
          closeAllSubmenus();
          focusMenubarItem(menubarButtons.length - 1);
          break;
        }
      }
    });
  });

  /* ── Submenu keyboard navigation ─────────────────── */

  menubarButtons.forEach((button, menuIndex) => {
    const submenu = getSubmenu(button);
    const items = getMenuItems(submenu);

    items.forEach((item) => {
      item.addEventListener("keydown", (e) => {
        const currentIndex = getFocusedSubmenuIndex(submenu);
        const allItems = getMenuItems(submenu);

        switch (e.key) {
          case "ArrowDown": {
            e.preventDefault();
            let next = currentIndex + 1;
            // Skip separators
            while (next < allItems.length && allItems[next].getAttribute("role") === "separator") {
              next++;
            }
            if (next < allItems.length) {
              focusSubmenuItem(submenu, next);
            }
            break;
          }
          case "ArrowUp": {
            e.preventDefault();
            let prev = currentIndex - 1;
            while (prev >= 0 && allItems[prev].getAttribute("role") === "separator") {
              prev--;
            }
            if (prev >= 0) {
              focusSubmenuItem(submenu, prev);
            }
            break;
          }
          case "ArrowRight": {
            e.preventDefault();
            closeSubmenu(button);
            const nextMenu = (menuIndex + 1) % menubarButtons.length;
            focusMenubarItem(nextMenu);
            openSubmenu(menubarButtons[nextMenu]);
            focusSubmenuItem(getSubmenu(menubarButtons[nextMenu]), 0);
            break;
          }
          case "ArrowLeft": {
            e.preventDefault();
            closeSubmenu(button);
            const prevMenu = (menuIndex - 1 + menubarButtons.length) % menubarButtons.length;
            focusMenubarItem(prevMenu);
            openSubmenu(menubarButtons[prevMenu]);
            focusSubmenuItem(getSubmenu(menubarButtons[prevMenu]), 0);
            break;
          }
          case "Home": {
            e.preventDefault();
            focusSubmenuItem(submenu, 0);
            break;
          }
          case "End": {
            e.preventDefault();
            focusSubmenuItem(submenu, allItems.length - 1);
            break;
          }
          case "Enter":
          case " ": {
            e.preventDefault();
            logAction(`Activated: ${item.textContent.trim()}`);
            closeSubmenu(button);
            focusMenubarItem(menuIndex);
            break;
          }
          case "Escape": {
            e.preventDefault();
            closeSubmenu(button);
            focusMenubarItem(menuIndex);
            break;
          }
          case "Tab": {
            closeAllSubmenus();
            break;
          }
          default: {
            // Type-ahead: single character search
            if (e.key.length === 1 && /[a-zA-Z]/.test(e.key)) {
              e.preventDefault();
              typeAheadBuffer += e.key.toLowerCase();
              clearTimeout(typeAheadTimer);
              typeAheadTimer = setTimeout(() => {
                typeAheadBuffer = "";
              }, 500);

              const match = allItems.findIndex((el, i) => {
                if (el.getAttribute("role") === "separator") return false;
                return el.textContent.trim().toLowerCase().startsWith(typeAheadBuffer);
              });

              if (match !== -1) {
                focusSubmenuItem(submenu, match);
              }
            }
            break;
          }
        }
      });

      // Click on submenu item
      item.addEventListener("click", () => {
        if (item.getAttribute("role") === "separator") return;
        logAction(`Activated: ${item.textContent.trim()}`);
        closeSubmenu(button);
        focusMenubarItem(menuIndex);
      });
    });
  });

  /* ── Click outside to close ──────────────────────── */

  document.addEventListener("click", (e) => {
    if (!menubar.contains(e.target)) {
      closeAllSubmenus();
    }
  });
})();

snippets.css:
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.container {
  width: 100%;
  max-width: 860px;
  padding: 2rem 1.5rem;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #f4f4f5;
  margin-bottom: 0.5rem;
  letter-spacing: -0.02em;
}

.page-desc {
  font-size: 0.8125rem;
  color: #71717a;
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

kbd {
  display: inline-block;
  padding: 0.125rem 0.375rem;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 4px;
  font-family: inherit;
  font-size: 0.75rem;
  color: #a1a1aa;
}

/* ---- Player ---- */
.player {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
  border: 1px solid rgba(255, 255, 255, 0.08);
  outline: none;
}

.player:focus-visible {
  box-shadow: 0 0 0 2px #8b5cf6;
}

.player__viewport {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000;
  cursor: pointer;
}

.player__canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Play overlay */
.player__play-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.3);
  border: none;
  color: #fff;
  cursor: pointer;
  transition: opacity 0.3s ease;
}

.player__play-overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

/* Caption overlay */
.player__captions {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 60px;
  max-width: 80%;
  text-align: center;
  pointer-events: none;
  z-index: 5;
  transition: top 0.3s ease, bottom 0.3s ease;
}

.player__captions[data-pos="top"] {
  bottom: auto;
  top: 20px;
}

.caption-text {
  display: inline-block;
  padding: 0.375rem 0.75rem;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  font-size: 18px;
  line-height: 1.5;
  border-radius: 4px;
  font-weight: 500;
}

.caption-text:empty {
  display: none;
}

/* ---- Controls ---- */
.player__controls {
  background: rgba(0, 0, 0, 0.85);
  padding: 0 0.75rem 0.5rem;
}

/* Progress bar */
.progress-bar {
  width: 100%;
  height: 20px;
  display: flex;
  align-items: center;
  cursor: pointer;
  padding: 8px 0;
}

.progress-bar::before {
  content: "";
  display: none;
}

.progress-bar {
  position: relative;
  background: transparent;
}

.progress-bar::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 4px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 2px;
  transform: translateY(-50%);
}

.progress-bar__fill {
  position: absolute;
  top: 50%;
  left: 0;
  height: 4px;
  background: #8b5cf6;
  border-radius: 2px;
  transform: translateY(-50%);
  z-index: 1;
  width: 0%;
  transition: width 0.1s linear;
}

.progress-bar:hover .progress-bar__fill {
  height: 6px;
}

.controls-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.controls-left,
.controls-right {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.ctrl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: #d4d4d8;
  cursor: pointer;
  transition: all 0.15s ease;
}

.ctrl-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.ctrl-btn:focus-visible {
  outline: 2px solid #8b5cf6;
  outline-offset: 2px;
}

.ctrl-btn[aria-pressed="true"] {
  color: #8b5cf6;
}

/* Volume */
.volume-slider {
  width: 70px;
}

.volume-range {
  width: 100%;
  appearance: none;
  height: 4px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 2px;
  outline: none;
}

.volume-range::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
  height: 12px;
  background: #fff;
  border-radius: 50%;
  cursor: pointer;
}

.time-display {
  font-size: 0.75rem;
  color: #a1a1aa;
  font-variant-numeric: tabular-nums;
  margin-left: 0.25rem;
  white-space: nowrap;
}

/* ---- Settings panel ---- */
.settings-panel {
  position: absolute;
  right: 0.75rem;
  bottom: 70px;
  width: 260px;
  background: rgba(24, 24, 27, 0.97);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 1rem;
  z-index: 20;
  backdrop-filter: blur(12px);
}

.settings-panel__title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: #f4f4f5;
  margin-bottom: 1rem;
}

.setting {
  margin-bottom: 0.875rem;
}

.setting:last-child {
  margin-bottom: 0;
}

.setting__label {
  display: block;
  font-size: 0.75rem;
  color: #71717a;
  margin-bottom: 0.375rem;
}

.setting__row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.setting__range {
  flex: 1;
  appearance: none;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  outline: none;
}

.setting__range::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  background: #8b5cf6;
  border-radius: 50%;
  cursor: pointer;
}

.setting__value {
  font-size: 0.75rem;
  color: #a1a1aa;
  min-width: 32px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.setting__colors {
  display: flex;
  gap: 0.5rem;
}

.cap-color {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}

.cap-color:hover {
  transform: scale(1.15);
}

.cap-color.active {
  border-color: #8b5cf6;
  box-shadow: 0 0 0 2px rgba(139, 92, 246, 0.4);
}

.setting__positions {
  display: flex;
  gap: 0.5rem;
}

.pos-btn {
  flex: 1;
  padding: 0.375rem 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  background: transparent;
  color: #71717a;
  font-size: 0.75rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.pos-btn:hover {
  background: rgba(255, 255, 255, 0.05);
}

.pos-btn.active {
  background: rgba(139, 92, 246, 0.15);
  border-color: rgba(139, 92, 246, 0.3);
  color: #c4b5fd;
}

