body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.5;
  min-height: 100vh;
}

.shell {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 1rem 2rem;
}

/* ---- Top bar ---- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 0;
}

.topbar__logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f4f4f5;
  background: linear-gradient(135deg, #8b5cf6, #6366f1);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.topbar__right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Simplify button */
.simplify-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  color: #a1a1aa;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.simplify-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #e4e4e7;
}

.simplify-btn[aria-pressed="true"] {
  background: rgba(16, 185, 129, 0.12);
  border-color: rgba(16, 185, 129, 0.3);
  color: #6ee7b7;
}

/* Notification bell */
.notification-bell {
  position: relative;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #a1a1aa;
}

.notification-bell__badge {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 16px;
  height: 16px;
  background: #ef4444;
  color: #fff;
  font-size: 0.625rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.notification-bell__badge.pulse {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(239, 68, 68, 0);
  }
}

/* ---- Marquee banner ---- */
.marquee-banner {
  overflow: hidden;
  background: linear-gradient(90deg, rgba(139, 92, 246, 0.08), rgba(99, 102, 241, 0.08));
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0.5rem 0;
}

.marquee-banner__track {
  display: flex;
  width: max-content;
  animation: marquee 30s linear infinite;
}

.marquee-banner__text {
  font-size: 0.8125rem;
  color: #a1a1aa;
  white-space: nowrap;
  padding-right: 2rem;
}

@keyframes marquee {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

/* ---- Dashboard ---- */
.dashboard {
  padding-top: 1.5rem;
}

.section-title {
  font-size: 1rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-bottom: 1rem;
}

.decorative-title {
  position: relative;
  display: inline-block;
}

.decorative-title::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, #8b5cf6, transparent);
  border-radius: 1px;
}

/* Stat cards */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 768px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

.stat-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.75rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.stat-card__icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.stat-card__icon--blue {
  background: rgba(59, 130, 246, 0.15);
  color: #60a5fa;
}
.stat-card__icon--green {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
}
.stat-card__icon--purple {
  background: rgba(139, 92, 246, 0.15);
  color: #a78bfa;
}
.stat-card__icon--amber {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
}

.stat-card__body {
  flex: 1;
  min-width: 0;
}

.stat-card__value {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
  color: #f4f4f5;
  font-variant-numeric: tabular-nums;
}

.stat-card__label {
  font-size: 0.75rem;
  color: #71717a;
}

.stat-card__trend {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
}

.stat-card__trend--up {
  background: rgba(16, 185, 129, 0.12);
  color: #34d399;
}
.stat-card__trend--down {
  background: rgba(239, 68, 68, 0.12);
  color: #f87171;
}

/* Main grid */
.main-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 768px) {
  .main-grid {
    grid-template-columns: 1fr;
  }
}

/* Carousel */
.carousel__viewport {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
}

.carousel__slides {
  position: relative;
  min-height: 200px;
}

.carousel__slide {
  position: absolute;
  inset: 0;
  padding: 1.5rem;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  opacity: 0;
  transform: scale(0.96);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.carousel__slide--active {
  position: relative;
  opacity: 1;
  transform: scale(1);
}

.carousel__slide h3 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.5rem;
}

.carousel__slide p {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.6;
  max-width: 50ch;
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.2);
  cursor: pointer;
  transition: all 0.3s ease;
}

.carousel__dot.active {
  background: #8b5cf6;
  width: 24px;
  border-radius: 4px;
}

/* Activity feed */
.activity__list {
  list-style: none;
}

.activity__item {
  display: flex;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.activity__item:last-child {
  border-bottom: none;
}

.activity__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 0.375rem;
  flex-shrink: 0;
}

.activity__dot--blue {
  background: #3b82f6;
}
.activity__dot--green {
  background: #10b981;
}
.activity__dot--amber {
  background: #f59e0b;
}
.activity__dot--purple {
  background: #8b5cf6;
}

.activity__content {
  flex: 1;
}

.activity__text {
  font-size: 0.8125rem;
  color: #a1a1aa;
  line-height: 1.5;
}

.activity__text strong {
  color: #e4e4e7;
  font-weight: 600;
}

.activity__time {
  display: block;
  font-size: 0.6875rem;
  color: #52525b;
  margin-top: 0.125rem;
}

/* ====================================
   SIMPLIFIED MODE
   ==================================== */

body.simplified {
  background: #111111;
}

/* Kill all animations */
.simplified * {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

.simplified .topbar__logo {
  background: none;
  -webkit-background-clip: initial;
  background-clip: initial;
  -webkit-text-fill-color: #f4f4f5;
}

/* Hide marquee */
.simplified .marquee-banner {
  display: none;
}

/* Hide notification pulse and badge animation */
.simplified .notification-bell__badge {
  box-shadow: none;
}

/* Remove gradients from stat cards */
.simplified .stat-card {
  box-shadow: none;
  border-color: rgba(255, 255, 255, 0.1);
}

.simplified .stat-card__icon--blue,
.simplified .stat-card__icon--green,
.simplified .stat-card__icon--purple,
.simplified .stat-card__icon--amber {
  background: rgba(255, 255, 255, 0.06);
  color: #a1a1aa;
}

.simplified .stat-card__trend {
  background: none;
  color: #71717a;
}

/* Single column layout */
.simplified .stats {
  grid-template-columns: repeat(2, 1fr);
}

.simplified .main-grid {
  grid-template-columns: 1fr;
}

/* Simplify carousel to static card */
.simplified .carousel__slide {
  position: relative;
  opacity: 1;
  background: rgba(255, 255, 255, 0.04) !important;
  border: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 0.75rem;
}

.simplified .carousel__slide h3 {
  color: #e4e4e7;
  font-size: 1rem;
}

.simplified .carousel__slide p {
  color: #a1a1aa;
  font-size: 0.875rem;
}

.simplified .carousel__dots {
  display: none;
}

/* Remove decorative elements */
.simplified .decorative-title::after {
  display: none;
}

/* Bigger text, more whitespace */
.simplified .section-title {
  font-size: 1.125rem;
  margin-bottom: 1.25rem;
}

.simplified .activity__item {
  padding: 1rem 0;
}

.simplified .activity__text {
  font-size: 0.9375rem;
  line-height: 1.7;
}

.simplified .activity__time {
  font-size: 0.75rem;
  margin-top: 0.25rem;
}

/* Reduce color palette */
