/* Info Panel */
.info-panel {
  margin-top: 2rem;
  background: #111113;
  border: 1px solid #27272a;
  border-radius: 12px;
  padding: 1.5rem;
}

.info-title {
  font-size: 1rem;
  font-weight: 600;
  color: #fafafa;
  margin-bottom: 0.75rem;
}

.info-subtitle {
  font-size: 0.9rem;
  font-weight: 600;
  color: #fafafa;
  margin-top: 1.25rem;
  margin-bottom: 0.5rem;
