.info-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.info-list li {
  font-size: 0.825rem;
  color: #a1a1aa;
}

.info-list code {
  background: #1e1e22;
  padding: 0.12rem 0.4rem;
  border-radius: 4px;
  font-size: 0.78rem;
  color: #60a5fa;
  font-family: "SF Mono", "Fira Code", monospace;
}

.kbd-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.kbd-item {
  font-size: 0.825rem;
  color: #a1a1aa;
}

kbd {
  display: inline-block;
  padding: 0.1rem 0.45rem;
  background: #1e1e22;
  border: 1px solid #3f3f46;
