(() => {
  const tablist = document.querySelector('[role="tablist"]');
  const tabs = Array.from(tablist.querySelectorAll('[role="tab"]'));
  const panels = tabs.map((tab) => document.getElementById(tab.getAttribute("aria-controls")));

  function activateTab(tab) {
    // Deactivate all tabs
    tabs.forEach((t) => {
      t.setAttribute("aria-selected", "false");
      t.setAttribute("tabindex", "-1");
      t.classList.remove("tab--active");
    });

    // Hide all panels
    panels.forEach((p) => {
      p.hidden = true;
      p.classList.remove("tabpanel--active");
    });

    // Activate selected tab
    tab.setAttribute("aria-selected", "true");
    tab.setAttribute("tabindex", "0");
    tab.classList.add("tab--active");
    tab.focus();

    // Show associated panel
    const panel = document.getElementById(tab.getAttribute("aria-controls"));
    panel.hidden = false;
    panel.classList.add("tabpanel--active");
  }

  // Click handler
  tabs.forEach((tab) => {
    tab.addEventListener("click", () => activateTab(tab));
  });

  // Keyboard handler
  tablist.addEventListener("keydown", (e) => {
    const currentIndex = tabs.indexOf(document.activeElement);
    if (currentIndex === -1) return;

    let newIndex;

    switch (e.key) {
      case "ArrowRight":
        e.preventDefault();
        newIndex = (currentIndex + 1) % tabs.length;
        activateTab(tabs[newIndex]);
        break;

      case "ArrowLeft":
        e.preventDefault();
        newIndex = (currentIndex - 1 + tabs.length) % tabs.length;
        activateTab(tabs[newIndex]);
        break;

      case "Home":
        e.preventDefault();
        activateTab(tabs[0]);
        break;

      case "End":
        e.preventDefault();
        activateTab(tabs[tabs.length - 1]);
        break;
    }
  });
})();

snippets.css:
/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-secondary: #111111;
  --bg-tertiary: #1a1a1a;
  --bg-dropdown: #151515;
  --border: #222222;
  --border-light: #333333;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --radius: 10px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  min-height: 100vh;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  list-style: none;
}

/* ── Navbar ── */
.navbar {
  position: sticky;
  inset-block-start: 0;
  background: var(--bg-secondary);
  border-block-end: 1px solid var(--border);
  z-index: 100;
}

.nav-container {
  display: flex;
  align-items: center;
  max-inline-size: 1200px;
  margin-inline: auto;
  padding-block: 0;
  padding-inline: 24px;
  block-size: 64px;
}

/* Logo */
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-inline-end: 40px;
  flex-shrink: 0;
}

.logo-icon {
  font-size: 1.4rem;
  color: var(--accent-blue);
}

.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

/* Menu */
.nav-menu {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding-block: 8px;
  padding-inline: 14px;
  font-size: 0.88rem;
  color: var(--text-secondary);
  border-radius: 6px;
  transition: color 0.2s, background 0.2s;
  white-space: nowrap;
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.chevron {
  font-size: 0.65rem;
  transition: transform 0.2s;
}

.dropdown-trigger[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* Dropdown */
.dropdown-menu {
  position: absolute;
  inset-block-start: calc(100% + 8px);
  inset-inline-start: 0;
  inline-size: 280px;
  background: var(--bg-dropdown);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 8px;
  padding-inline: 8px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
}

.dropdown-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-link {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-block: 10px;
  padding-inline: 12px;
  border-radius: 8px;
  transition: background 0.2s;
}

.dropdown-link:hover {
  background: var(--bg-tertiary);
}

.dd-icon {
  font-size: 1.2rem;
  margin-block-start: 2px;
  flex-shrink: 0;
}

.dd-content {
  display: flex;
  flex-direction: column;
}

.dd-title {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-primary);
}

.dd-desc {
  font-size: 0.76rem;
  color: var(--text-muted);
}

/* Nav actions */
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-inline-start: auto;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-block: 6px;
  padding-inline: 12px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-primary);
}

.nav-cta {
  padding-block: 8px;
  padding-inline: 18px;
  background: var(--accent-blue);
  color: #fff;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  transition: background 0.2s;
  white-space: nowrap;
}

.nav-cta:hover {
  background: #2563eb;
}

[dir="rtl"] .nav-cta {
  direction: ltr;
  unicode-bidi: bidi-override;
}

/* Mobile */
.mobile-toggle {
  display: none;
  padding: 8px;
}

.hamburger {
  display: block;
  inline-size: 20px;
  block-size: 2px;
  background: var(--text-primary);
  position: relative;
}

.hamburger::before,
.hamburger::after {
  content: "";
  position: absolute;
  inline-size: 100%;
  block-size: 2px;
  background: var(--text-primary);
  inset-inline-start: 0;
}

.hamburger::before {
  inset-block-start: -6px;
}
.hamburger::after {
  inset-block-start: 6px;
}

/* ── Breadcrumb ── */
.breadcrumb-container {
  border-block-end: 1px solid var(--border);
  background: var(--bg-primary);
}

.breadcrumb {
  max-inline-size: 1200px;
  margin-inline: auto;
  padding-block: 12px;
  padding-inline: 24px;
}

.breadcrumb-list {
  display: flex;
  align-items: center;
  gap: 0;
  flex-wrap: wrap;
}

.breadcrumb-item {
  display: inline-flex;
  align-items: center;
}

.breadcrumb-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--text-secondary);
  padding-block: 4px;
  padding-inline: 6px;
  border-radius: 4px;
  transition: color 0.2s, background 0.2s;
}

.breadcrumb-link:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.bc-home {
  font-size: 0.9rem;
}

.breadcrumb-text {
  font-size: 0.82rem;
  color: var(--text-primary);
  font-weight: 500;
  padding-inline: 6px;
}

.breadcrumb-sep {
  display: inline-flex;
  align-items: center;
  padding-inline: 4px;
}

.sep-arrow {
  font-size: 1rem;
  color: var(--text-muted);
  line-height: 1;
  display: inline-block;
  transition: transform 0.2s;
}

/* Flip breadcrumb arrows in RTL */
[dir="rtl"] .sep-arrow {
  transform: scaleX(-1);
}

/* ── Demo content ── */
.demo-content {
  max-inline-size: 1200px;
  margin-inline: auto;
  padding-block: 48px;
  padding-inline: 24px;
}

.demo-title {
  font-size: 2rem;
  font-weight: 700;
  margin-block-end: 16px;
}

.demo-text {
  font-size: 1rem;
  color: var(--text-secondary);
  max-inline-size: 640px;
  margin-block-end: 32px;
  line-height: 1.7;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 12px;
  padding-inline: 16px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  max-inline-size: 480px;
}

.feature-icon {
  inline-size: 28px;
  block-size: 28px;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.15);
  color: var(--accent-green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  flex-shrink: 0;
}

.feature-text {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Mobile backdrop ── */
.mobile-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 90;
}

.mobile-backdrop.active {
  display: block;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .nav-container {
    padding-inline: 16px;
    position: relative;
  }

  .nav-menu {
    position: fixed;
    inset-block-start: 64px;
    inset-inline-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    background: var(--bg-secondary);
    border-block-start: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    padding-block: 12px;
    padding-inline: 16px;
    overflow-y: auto;
    z-index: 95;
    transform: translateY(-110%);
    opacity: 0;
    transition: transform 0.3s ease, opacity 0.25s ease;
  }

  .nav-menu.open {
    transform: translateY(0);
    opacity: 1;
  }

  .nav-link {
    display: flex;
    width: 100%;
    padding-block: 12px;
    padding-inline: 16px;
    font-size: 0.95rem;
    border-radius: 8px;
  }

  .nav-link:hover,
  .nav-link.active {
    background: var(--bg-tertiary);
  }

  .dropdown-trigger {
    justify-content: space-between;
  }

  /* Dropdown inside mobile menu */
  .nav-menu .dropdown-menu {
    position: static;
    inline-size: 100%;
    box-shadow: none;
    border: none;
    background: transparent;
    padding-block: 4px;
    padding-inline: 0;
    margin-inline-start: 12px;
    opacity: 1;
    visibility: visible;
    transform: none;
    display: none;
    border-inline-start: 2px solid var(--border-light);
  }

  .nav-menu .dropdown-menu.open {
    display: block;
  }

  .nav-menu .dropdown-link {
    padding-block: 10px;
    padding-inline: 14px;
  }

  /* Nav actions in mobile */
  .nav-actions {
    margin-inline-start: auto;
  }

  .nav-cta {
    display: none;
  }

  .mobile-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-inline-start: 8px;
    width: 40px;
    height: 40px;
    border-radius: 8px;
  }

  .mobile-toggle:hover {
    background: var(--bg-tertiary);
  }

  /* Hamburger animation */
  .mobile-toggle.active .hamburger {
    background: transparent;
  }

  .mobile-toggle.active .hamburger::before {
    inset-block-start: 0;
    transform: rotate(45deg);
  }

  .mobile-toggle.active .hamburger::after {
    inset-block-start: 0;
    transform: rotate(-45deg);
  }

  .hamburger,
  .hamburger::before,
  .hamburger::after {
    transition: all 0.25s ease;
  }

  /* Breadcrumb */
  .breadcrumb {
    padding-inline: 16px;
  }

  /* Content */
  .demo-content {
    padding-block: 32px;
    padding-inline: 16px;
  }

  .demo-title {
    font-size: 1.5rem;
  }

  .feature {
    max-inline-size: 100%;
  }
}

