/* ==============================
   Screen Reader Only Utilities
   ============================== */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.sr-only-focusable:focus,
.sr-only-focusable:active {
  position: static;
  width: auto;
  height: auto;
  padding: 0.6rem 1.2rem;
  margin: 0;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
}

/* Reveal mode */
body.reveal-mode .sr-only:not(.sr-only-focusable) {
  position: static;
  width: auto;
  height: auto;
  padding: 0.15rem 0.4rem;
  margin: 0;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
  background: rgba(139, 92, 246, 0.15);
  color: #c084fc;
  border: 1px dashed rgba(139, 92, 246, 0.4);
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
}

body.reveal-mode .sr-reveal {
  display: flex !important;
}

/* ============================== */

.demo {
  max-width: 780px;
  margin: 0 auto;
  padding: 3rem 1.5rem;
}

