(() => {
  const countries = [
    { name: "Argentina", flag: "\uD83C\uDDE6\uD83C\uDDF7" },
    { name: "Australia", flag: "\uD83C\uDDE6\uD83C\uDDFA" },
    { name: "Brazil", flag: "\uD83C\uDDE7\uD83C\uDDF7" },
    { name: "Canada", flag: "\uD83C\uDDE8\uD83C\uDDE6" },
    { name: "China", flag: "\uD83C\uDDE8\uD83C\uDDF3" },
    { name: "Denmark", flag: "\uD83C\uDDE9\uD83C\uDDF0" },
    { name: "Egypt", flag: "\uD83C\uDDEA\uD83C\uDDEC" },
    { name: "France", flag: "\uD83C\uDDEB\uD83C\uDDF7" },
    { name: "Germany", flag: "\uD83C\uDDE9\uD83C\uDDEA" },
    { name: "India", flag: "\uD83C\uDDEE\uD83C\uDDF3" },
    { name: "Italy", flag: "\uD83C\uDDEE\uD83C\uDDF9" },
    { name: "Japan", flag: "\uD83C\uDDEF\uD83C\uDDF5" },
    { name: "Kenya", flag: "\uD83C\uDDF0\uD83C\uDDEA" },
    { name: "Mexico", flag: "\uD83C\uDDF2\uD83C\uDDFD" },
    { name: "Netherlands", flag: "\uD83C\uDDF3\uD83C\uDDF1" },
    { name: "Norway", flag: "\uD83C\uDDF3\uD83C\uDDF4" },
    { name: "Portugal", flag: "\uD83C\uDDF5\uD83C\uDDF9" },
    { name: "South Korea", flag: "\uD83C\uDDF0\uD83C\uDDF7" },
    { name: "Spain", flag: "\uD83C\uDDEA\uD83C\uDDF8" },
    { name: "Sweden", flag: "\uD83C\uDDF8\uD83C\uDDEA" },
    { name: "United Kingdom", flag: "\uD83C\uDDEC\uD83C\uDDE7" },
    { name: "United States", flag: "\uD83C\uDDFA\uD83C\uDDF8" },
  ];

  const input = document.getElementById("country-input");
  const listbox = document.getElementById("country-listbox");
  const combobox = document.querySelector('[role="combobox"]');
  const clearBtn = document.getElementById("clear-input");
  const statusEl = document.getElementById("combobox-status");
  const selectedValue = document.getElementById("selected-value");

  let activeIndex = -1;
  let filteredCountries = [...countries];
  let isOpen = false;

  function renderOptions(filter = "") {
    const query = filter.toLowerCase().trim();
    filteredCountries = query
      ? countries.filter((c) => c.name.toLowerCase().includes(query))
      : [...countries];

    listbox.innerHTML = "";
    activeIndex = -1;

    if (filteredCountries.length === 0) {
      listbox.innerHTML = '<li class="combobox-no-results">No countries found</li>';
      updateStatus("No results");
      return;
    }

    filteredCountries.forEach((country, i) => {
      const li = document.createElement("li");
      li.id = `option-${i}`;
      li.className = "combobox-option";
      li.setAttribute("role", "option");
      li.setAttribute("aria-selected", "false");
      li.innerHTML = `<span class="combobox-option-flag" aria-hidden="true">${country.flag}</span>${country.name}`;

      li.addEventListener("click", () => selectOption(i));
      li.addEventListener("mouseenter", () => {
        setActiveOption(i, false);
      });

      listbox.appendChild(li);
    });

    const count = filteredCountries.length;
    updateStatus(
      count === 1
        ? "1 result available"
        : `${count} results available. Use Up and Down arrows to navigate.`
    );
  }

  function updateStatus(text) {
    statusEl.textContent = text;
  }

  function openListbox() {
    if (isOpen) return;
    isOpen = true;
    listbox.hidden = false;
    combobox.setAttribute("aria-expanded", "true");
    renderOptions(input.value);
  }

  function closeListbox() {
    if (!isOpen) return;
    isOpen = false;
    listbox.hidden = true;
    combobox.setAttribute("aria-expanded", "false");
    input.setAttribute("aria-activedescendant", "");
    activeIndex = -1;
    updateStatus("");
  }

  function setActiveOption(index, scroll = true) {
    // Remove active from previous
    const options = listbox.querySelectorAll('[role="option"]');
    options.forEach((opt) => opt.classList.remove("combobox-option--active"));

    if (index < 0 || index >= filteredCountries.length) {
      activeIndex = -1;
      input.setAttribute("aria-activedescendant", "");
      return;
    }

    activeIndex = index;
    const activeEl = options[index];
    activeEl.classList.add("combobox-option--active");
    input.setAttribute("aria-activedescendant", activeEl.id);

    if (scroll) {
      activeEl.scrollIntoView({ block: "nearest" });
    }
  }

  function selectOption(index) {
    const country = filteredCountries[index];
    if (!country) return;

    input.value = country.name;
    selectedValue.textContent = `${country.flag} ${country.name}`;
    clearBtn.hidden = false;

    // Mark as selected
    const options = listbox.querySelectorAll('[role="option"]');
    options.forEach((opt) => opt.setAttribute("aria-selected", "false"));
    if (options[index]) {
      options[index].setAttribute("aria-selected", "true");
    }

    closeListbox();
    updateStatus(`${country.name} selected`);
  }

  // Input events
  input.addEventListener("input", () => {
    clearBtn.hidden = !input.value;
    if (!isOpen) openListbox();
    renderOptions(input.value);
  });

  input.addEventListener("focus", () => {
    openListbox();
  });

  input.addEventListener("keydown", (e) => {
    const optionCount = filteredCountries.length;

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        if (!isOpen) {
          openListbox();
        } else {
          setActiveOption(activeIndex < optionCount - 1 ? activeIndex + 1 : 0);
        }
        break;

      case "ArrowUp":
        e.preventDefault();
        if (!isOpen) {
          openListbox();
        } else {
          setActiveOption(activeIndex > 0 ? activeIndex - 1 : optionCount - 1);
        }
        break;

      case "Home":
        if (isOpen && optionCount > 0) {
          e.preventDefault();
          setActiveOption(0);
        }
        break;

      case "End":
        if (isOpen && optionCount > 0) {
          e.preventDefault();
          setActiveOption(optionCount - 1);
        }
        break;

      case "Enter":
        e.preventDefault();
        if (isOpen && activeIndex >= 0) {
          selectOption(activeIndex);
        }
        break;

      case "Escape":
        if (isOpen) {
          e.preventDefault();
          closeListbox();
        }
        break;
    }
  });

  // Clear button
  clearBtn.addEventListener("click", () => {
    input.value = "";
    clearBtn.hidden = true;
    selectedValue.textContent = "None";
    input.focus();
    renderOptions("");
  });

  // Close on outside click
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".combobox-wrapper")) {
      closeListbox();
    }
  });

  // Initialize
  renderOptions("");
})();

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── Dark theme (default) ── */
:root {
  color-scheme: dark;
  --bg: #0a0a0a;
  --surface: #141414;
  --elevated: #1a1a1a;
  --border: #262626;
  --text: #e5e5e5;
  --text-secondary: #a3a3a3;
  --text-muted: #737373;
  --link: #60a5fa;
  --accent: #3b82f6;
  --accent-text: #ffffff;
  --input-bg: #171717;
  --input-border: #333333;
  --input-text: #e5e5e5;
  --btn-outline-border: #404040;
  --transition-speed: 0.3s;
}

/* ── Light theme ── */
.light {
  color-scheme: light;
  --bg: #ffffff;
  --surface: #f5f5f5;
  --elevated: #fafafa;
  --border: #e5e5e5;
  --text: #111111;
  --text-secondary: #525252;
  --text-muted: #737373;
  --link: #2563eb;
  --accent: #2563eb;
  --accent-text: #ffffff;
  --input-bg: #ffffff;
  --input-border: #d4d4d4;
  --input-text: #111111;
  --btn-outline-border: #d4d4d4;
}

body {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 0;
  transition: background var(--transition-speed), color var(--transition-speed);
}

.page {
  width: 100%;
  max-width: 760px;
  padding: 1.5rem 2rem;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
  transition: border-color var(--transition-speed);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.logo {
  font-size: 1.125rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.nav {
  display: flex;
  gap: 0.25rem;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  padding: 0.375rem 0.75rem;
  border-radius: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 500;
  transition: background 0.15s, color 0.15s;
}

.nav-link:hover {
  background: var(--surface);
  color: var(--text);
}
.nav-link.active {
  color: var(--text);
  font-weight: 600;
}

/* ── Theme toggle button ── */
.theme-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  color: var(--text);
  padding: 0.5rem 0.875rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

.theme-btn:hover {
  border-color: var(--text-muted);
}

/* Show/hide sun/moon icons */
.icon-sun {
  display: none;
}
.icon-moon {
  display: block;
}
.light .icon-sun {
  display: block;
}
.light .icon-moon {
  display: none;
}

/* ── Hero ── */
.hero {
  margin-bottom: 2rem;
  padding: 2rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.hero-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.hero-text {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ── Cards ── */
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.25rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.card-title {
  font-size: 0.875rem;
  font-weight: 700;
}

.card-body {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.card-body.secondary {
  color: var(--text-secondary);
}

/* ── Ratio badges ── */
.ratio-badge {
  font-size: 0.625rem;
  font-weight: 700;
  font-family: "SF Mono", "Fira Code", monospace;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  background: var(--elevated);
  border: 1px solid var(--border);
  white-space: nowrap;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.ratio-badge.small {
  font-size: 0.5625rem;
  margin-top: 0.25rem;
  display: inline-block;
}
.ratio-badge.inline {
  vertical-align: baseline;
}

/* ── Form ── */
.form-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.5rem;
  margin-bottom: 2rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.section-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.375rem;
}

.form-group input {
  width: 100%;
  background: var(--input-bg);
  border: 1px solid var(--input-border);
  border-radius: 0.5rem;
  color: var(--input-text);
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.15s, background var(--transition-speed);
}

.form-group input:focus {
  border-color: var(--accent);
}

.form-actions {
  display: flex;
  gap: 0.5rem;
}

.btn {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, border-color 0.15s;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
}
.btn-primary:hover {
  opacity: 0.9;
}
.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--btn-outline-border);
}
.btn-outline:hover {
  background: var(--surface);
}

/* ── Text section ── */
.text-section {
  margin-bottom: 2rem;
}

.body-text {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-text a {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.body-text a:hover {
  opacity: 0.8;
}

/* ── Contrast table ── */
.contrast-table-section {
  margin-bottom: 2rem;
}

.contrast-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
}

.contrast-table th {
  text-align: left;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border);
}

.contrast-table td {
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border);
  transition: border-color var(--transition-speed);
}

.contrast-table .swatch-cell {
  width: 24px;
  height: 24px;
  border-radius: 0.25rem;
  border: 1px solid var(--border);
  display: inline-block;
  vertical-align: middle;
}

.pass-cell {
  color: #22c55e;
  font-weight: 700;
}
.fail-cell {
  color: #ef4444;
  font-weight: 700;
}

@media (max-width: 640px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.75rem;
  }
  .header-left {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }
  .cards {
    grid-template-columns: 1fr;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
}

