*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ══════════════════════════════════════
   DARK THEME TOKENS (default)
   ══════════════════════════════════════ */
:root {
  color-scheme: dark;

  /* Text */
  --color-text-primary: #e5e5e5;
  --color-text-secondary: #a3a3a3;
  --color-text-muted: #737373;
  --color-text-inverse: #0a0a0a;

  /* Backgrounds */
  --color-bg-base: #0a0a0a;
  --color-bg-surface: #141414;
  --color-bg-elevated: #1a1a1a;
  --color-bg-overlay: #262626;

  /* Borders */
  --color-border-default: #262626;
  --color-border-strong: #404040;

  /* Accent */
  --color-accent: #3b82f6;
  --color-accent-text: #ffffff;

  /* States */
  --color-success: #4ade80;
  --color-warning: #fbbf24;
  --color-error: #f87171;
  --color-info: #60a5fa;

  --transition: 0.3s;
}

/* ══════════════════════════════════════
   LIGHT THEME TOKENS
   ══════════════════════════════════════ */
.light {
  color-scheme: light;

  --color-text-primary: #111111;
  --color-text-secondary: #525252;
  --color-text-muted: #737373;
  --color-text-inverse: #ffffff;

  --color-bg-base: #ffffff;
  --color-bg-surface: #f5f5f5;
  --color-bg-elevated: #fafafa;
  --color-bg-overlay: #e5e5e5;

  --color-border-default: #e5e5e5;
  --color-border-strong: #d4d4d4;

  --color-accent: #2563eb;
  --color-accent-text: #ffffff;

  --color-success: #16a34a;
  --color-warning: #d97706;
  --color-error: #dc2626;
  --color-info: #2563eb;
}

/* ── Base ── */
body {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  background: var(--color-bg-base);
  color: var(--color-text-primary);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 2rem;
  transition: background var(--transition), color var(--transition);
}

.page {
  width: 100%;
  max-width: 840px;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-border-default);
}

.header-title {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.header-sub {
  color: var(--color-text-muted);
  font-size: 0.8125rem;
  margin-top: 0.25rem;
}

.theme-btn {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  background: var(--color-bg-surface);
  border: 1px solid var(--color-border-default);
  border-radius: 0.5rem;
  color: var(--color-text-primary);
  padding: 0.5rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.theme-btn:hover {
  background: var(--color-bg-elevated);
}

.icon-sun {
  display: none;
}
.icon-moon {
  display: block;
}
.light .icon-sun {
  display: block;
}
.light .icon-moon {
  display: none;
}

/* ── Sections ── */
.section {
  margin-bottom: 2.5rem;
}
.section-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}
.section-desc {
  color: var(--color-text-secondary);
  font-size: 0.8125rem;
  margin-bottom: 1rem;
  line-height: 1.5;
}

/* ── Token grid ── */
.token-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.token-category {
  background: var(--color-bg-surface);
  border: 1px solid var(--color-border-default);
  border-radius: 0.75rem;
  padding: 1rem;
  transition: background var(--transition), border-color var(--transition);
}

.token-cat-title {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: 0.75rem;
}

.token-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0;
  border-bottom: 1px solid var(--color-border-default);
}

.token-row:last-child {
  border-bottom: none;
}

.token-swatch {
  width: 20px;
  height: 20px;
  border-radius: 0.25rem;
  border: 1px solid var(--color-border-strong);
  flex-shrink: 0;
}

.token-row code {
  flex: 1;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.6875rem;
  color: var(--color-text-secondary);
}

.token-value {
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.625rem;
  color: var(--color-text-muted);
}

/* ── Sample components ── */
.sample-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.sample-card {
  background: var(--color-bg-surface);
  border: 1px solid var(--color-border-default);
  border-radius: 0.75rem;
  padding: 1.25rem;
  transition: background var(--transition), border-color var(--transition);
}

.sample-card.elevated {
  background: var(--color-bg-elevated);
}

.sample-card-title {
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--color-text-primary);
}
.sample-card-body {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  line-height: 1.5;
  margin-bottom: 1rem;
}
.sample-card-body code {
  font-size: 0.6875rem;
  background: var(--color-bg-overlay);
  padding: 0.125rem 0.25rem;
  border-radius: 0.25rem;
}

.sample-btn-primary {
  background: var(--color-accent);
  color: var(--color-accent-text);
  border: none;
  border-radius: 0.375rem;
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
}

.sample-btn-outline {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: 0.375rem;
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
}

/* ── Sample alerts ── */
.sample-alerts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}

.sample-alert {
  padding: 0.75rem 1rem;
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  line-height: 1.5;
  border-left: 3px solid;
  background: var(--color-bg-surface);
  color: var(--color-text-secondary);
  transition: background var(--transition);
}

.sample-alert.success {
  border-left-color: var(--color-success);
}
.sample-alert.warning {
  border-left-color: var(--color-warning);
}
.sample-alert.error {
  border-left-color: var(--color-error);
}
.sample-alert.info {
  border-left-color: var(--color-info);
}

.sample-alert.success strong {
  color: var(--color-success);
}
.sample-alert.warning strong {
  color: var(--color-warning);
}
.sample-alert.error strong {
  color: var(--color-error);
}
.sample-alert.info strong {
  color: var(--color-info);
}

/* ── Contrast matrix ── */
.matrix-wrap {
  overflow-x: auto;
}

.matrix {
  border-collapse: collapse;
  font-size: 0.6875rem;
  width: 100%;
  min-width: 500px;
}

.matrix th,
.matrix td {
  padding: 0.375rem 0.5rem;
  border: 1px solid var(--color-border-default);
  text-align: center;
  white-space: nowrap;
}

.matrix th {
  background: var(--color-bg-surface);
  font-weight: 600;
  color: var(--color-text-secondary);
  font-size: 0.5625rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.matrix th:first-child {
  text-align: left;
}
.matrix td:first-child {
  text-align: left;
  font-weight: 600;
  background: var(--color-bg-surface);
  color: var(--color-text-secondary);
  font-size: 0.5625rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.matrix .cell-aaa {
  background: #052e16;
  color: #4ade80;
  font-weight: 700;
}
.matrix .cell-aa {
  background: #422006;
  color: #fbbf24;
  font-weight: 700;
}
.matrix .cell-fail {
  background: #1a0a0a;
  color: #737373;
}

.light .matrix .cell-aaa {
  background: #dcfce7;
  color: #15803d;
}
.light .matrix .cell-aa {
  background: #fef3c7;
  color: #92400e;
}
.light .matrix .cell-fail {
  background: #fef2f2;
  color: #a3a3a3;
}

@media (max-width: 640px) {
  .token-grid {
    grid-template-columns: 1fr;
  }
  .sample-grid {
    grid-template-columns: 1fr;
  }
  .sample-alerts {
    grid-template-columns: 1fr;
  }
}

