*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #0a0a0a;
  color: #e5e5e5;
  min-height: 100vh;
}

/* ── App Layout ───────────────────────────────────── */

.app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.app-header {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 24px;
  height: 56px;
  background: #111;
  border-bottom: 1px solid #222;
}

.app-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  color: #f5f5f5;
  flex-shrink: 0;
}

.app-nav {
  display: flex;
  gap: 4px;
  flex: 1;
}

.nav-link {
  padding: 6px 14px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #888;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
}

.nav-link:hover {
  background: #1a1a1a;
  color: #ccc;
}

.nav-link.active {
  background: #1e1e2e;
  color: #e5e5e5;
}

.app-actions {
  flex-shrink: 0;
}

.hint-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: #161616;
  border: 1px solid #2a2a2a;
  border-radius: 8px;
  font-size: 0.78rem;
  color: #777;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
}

.hint-badge:hover {
  border-color: #444;
  color: #aaa;
}

.hint-badge kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 20px;
  padding: 0 5px;
  background: #1a1a1a;
  border: 1px solid #333;
  border-bottom-width: 2px;
  border-radius: 4px;
  font-family: inherit;
  font-size: 0.7rem;
  font-weight: 700;
  color: #bbb;
}

/* ── App Main ─────────────────────────────────────── */

.app-main {
  display: flex;
  flex: 1;
}

.app-sidebar {
  width: 220px;
  padding: 24px 20px;
  border-right: 1px solid #1a1a1a;
