/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-card: #111111;
  --bg-input: #181818;
  --border: #252525;
  --border-focus: #3b82f6;
  --border-error: #ef4444;
  --border-success: #22c55e;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-amber: #f59e0b;
  --accent-red: #ef4444;
  --radius: 10px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-block: 40px;
  padding-inline: 20px;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* ── Page ── */
.page {
  inline-size: 100%;
  max-inline-size: 560px;
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-block-end: 32px;
}

.toolbar-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 6px;
  padding-inline: 14px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-card);
}

/* ── Form ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 32px;
  padding-inline: 32px;
}

.form-row {
  display: flex;
  gap: 16px;
}

.form-row.two-col > .field {
  flex: 1;
}

/* ── Field ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.input-icon {
  position: absolute;
  inset-inline-start: 12px;
  font-size: 1rem;
  color: var(--text-muted);
  pointer-events: none;
  z-index: 1;
}

.input {
  inline-size: 100%;
  padding-block: 10px;
  padding-inline-start: 40px;
  padding-inline-end: 14px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-primary);
  font: inherit;
  font-size: 0.9rem;
  transition: border-color 0.2s;
  outline: none;
}

.input:focus {
  border-color: var(--border-focus);
}

.input.error {
  border-color: var(--border-error);
}

.input.valid {
  border-color: var(--border-success);
}

.input::placeholder {
  color: var(--text-muted);
}

/* Select */
.select-wrap {
  position: relative;
}

.select {
  appearance: none;
  cursor: pointer;
}

.select-arrow {
  position: absolute;
  inset-inline-end: 14px;
  font-size: 0.8rem;
  color: var(--text-muted);
  pointer-events: none;
}

/* Textarea */
.textarea {
  padding-inline-start: 14px;
  resize: vertical;
  min-block-size: 80px;
}

.char-count {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-align: end;
}

/* Password toggle */
.toggle-pass {
  position: absolute;
  inset-inline-end: 10px;
  font-size: 1rem;
  padding: 4px;
  color: var(--text-muted);
}

.toggle-pass:hover {
  color: var(--text-secondary);
}

/* Password strength */
.password-strength {
  block-size: 4px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.strength-bar {
  block-size: 100%;
  inline-size: 0;
  border-radius: 2px;
  transition: inline-size 0.3s, background 0.3s;
}

/* Error message */
.error-msg {
  font-size: 0.78rem;
  color: var(--accent-red);
  min-block-size: 1.2em;
}

/* Checkbox */
.checkbox-field {
  margin-block-start: 4px;
}

.checkbox-label {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.checkbox {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.checkmark {
  flex-shrink: 0;
  inline-size: 20px;
  block-size: 20px;
  border: 2px solid var(--border);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  margin-block-start: 1px;
}

.checkbox:checked + .checkmark {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
}

.checkbox:checked + .checkmark::after {
  content: "\2713";
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
}

.checkbox:focus-visible + .checkmark {
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.4);
}

.link {
  color: var(--accent-blue);
}

/* Submit */
.submit-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding-block: 12px;
  padding-inline: 24px;
  background: var(--accent-blue);
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  transition: background 0.2s;
  margin-block-start: 8px;
}

.submit-btn:hover {
  background: #2563eb;
}

.submit-btn:active {
  transform: scale(0.98);
}

[dir="rtl"] .btn-arrow {
  transform: scaleX(-1);
}

/* Success */
.success-msg {
  text-align: center;
  padding-block: 48px;
  padding-inline: 32px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-block-start: 24px;
}

.success-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 56px;
  block-size: 56px;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.15);
  color: var(--accent-green);
  font-size: 1.6rem;
  margin-block-end: 16px;
}

.success-title {
  font-size: 1.2rem;
  font-weight: 600;
  margin-block-end: 8px;
}

.success-text {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Responsive ── */
@media (max-width: 600px) {
  .form-row.two-col {
    flex-direction: column;
  }

  .form {
    padding-block: 24px;
    padding-inline: 20px;
  }
}

