  color: #e4e4e7;
}

/* ---- Icon buttons ---- */
.icon-row {
  display: flex;
  gap: 4px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.06);
  color: #a1a1aa;
  cursor: pointer;
  transition: all 0.2s;
}

.icon-btn--tiny {
  width: 20px;
  height: 20px;
}

.icon-btn--proper {
  width: 44px;
  height: 44px;
}

.icon-btn--proper:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #e4e4e7;
}

/* ---- Link list ---- */
.link-list {
  list-style: none;
}

.link-list--tight li {
  margin-bottom: 2px;
}

.link-list__link--small {
  display: inline;
  font-size: 0.75rem;
  color: #60a5fa;
  line-height: 1.2;
}

.link-list--proper li {
  margin-bottom: 2px;
}

.link-list__link--proper {
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 0.375rem 0.75rem;
  font-size: 0.8125rem;
  color: #60a5fa;
  border-radius: 8px;
  transition: background 0.2s;
}

.link-list__link--proper:hover {
  background: rgba(59, 130, 246, 0.08);
}

/* ---- Size tooltip ---- */
.size-tooltip {
  position: fixed;
  pointer-events: none;
  background: rgba(0, 0, 0, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  padding: 0.375rem 0.625rem;
  font-size: 0.6875rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #e4e4e7;
  z-index: 10000;
  opacity: 0;
  transition: opacity 0.15s ease;
  white-space: nowrap;
}

.size-tooltip.visible {
  opacity: 1;
}

.size-tooltip .fail {
  color: #f87171;
}

.size-tooltip .pass {
  color: #34d399;
}

/* ---- Measurement outline on hover ---- */
.target-measure {
  position: relative;
}

.target-measure.measuring {
  outline: 2px dashed rgba(139, 92, 246, 0.6);
  outline-offset: 1px;
}

/* ---- Grid overlay ---- */
.grid-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9998;
  opacity: 0;
  transition: opacity 0.3s ease;
  background-image: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 43px,
      rgba(139, 92, 246, 0.12) 43px,
      rgba(139, 92, 246, 0.12) 44px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 43px,
      rgba(139, 92, 246, 0.12) 43px,
      rgba(139, 92, 246, 0.12) 44px
    );
  background-size: 44px 44px;
}

.grid-overlay.visible {
  opacity: 1;
}

