(() => {
  const gridToggle = document.getElementById("grid-toggle");
  const gridOverlay = document.getElementById("grid-overlay");
  const tooltip = document.getElementById("size-tooltip");
  const measurables = document.querySelectorAll(".target-measure");

  // Grid overlay toggle
  gridToggle.addEventListener("click", () => {
    const active = gridOverlay.classList.toggle("visible");
    gridToggle.setAttribute("aria-pressed", String(active));
  });

  // Show dimensions on hover/click
  let activeEl = null;

  function showTooltip(el, e) {
    const rect = el.getBoundingClientRect();
    const w = Math.round(rect.width);
    const h = Math.round(rect.height);
    const passes = w >= 44 && h >= 44;

    tooltip.innerHTML = `<span class="${passes ? "pass" : "fail"}">${w} &times; ${h}px</span> ${passes ? " Pass" : " Fail"}`;
    tooltip.classList.add("visible");

    // Position tooltip near cursor
    const tx = e.clientX + 14;
    const ty = e.clientY - 10;
    tooltip.style.left = tx + "px";
    tooltip.style.top = ty + "px";

    // Ensure tooltip doesn't go off-screen
    requestAnimationFrame(() => {
      const tr = tooltip.getBoundingClientRect();
      if (tr.right > window.innerWidth) {
        tooltip.style.left = e.clientX - tr.width - 10 + "px";
      }
      if (tr.bottom > window.innerHeight) {
        tooltip.style.top = e.clientY - tr.height - 10 + "px";
      }
    });
  }

  function hideTooltip() {
    tooltip.classList.remove("visible");
    if (activeEl) {
      activeEl.classList.remove("measuring");
      activeEl = null;
    }
  }

  measurables.forEach((el) => {
    el.addEventListener("mouseenter", (e) => {
      if (activeEl) activeEl.classList.remove("measuring");
      activeEl = el;
      el.classList.add("measuring");
      showTooltip(el, e);
    });

    el.addEventListener("mousemove", (e) => {
      if (activeEl === el) {
        const tx = e.clientX + 14;
        const ty = e.clientY - 10;
        tooltip.style.left = tx + "px";
        tooltip.style.top = ty + "px";
      }
    });

    el.addEventListener("mouseleave", () => {
      hideTooltip();
    });

    // Also show on click for touch devices
    el.addEventListener("click", (e) => {
      e.preventDefault();
      if (activeEl === el && tooltip.classList.contains("visible")) {
        hideTooltip();
      } else {
        if (activeEl) activeEl.classList.remove("measuring");
        activeEl = el;
        el.classList.add("measuring");
        showTooltip(el, e);
      }
    });
  });

  // Hide tooltip when clicking elsewhere
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".target-measure") && !e.target.closest(".grid-toggle")) {
      hideTooltip();
    }
  });
})();

snippets.css:
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.6;
  min-height: 100vh;
}

/* Toggle Controls */
.demo-controls {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 10, 10, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid #27272a;
  padding: 0.75rem 1.5rem;
  display: flex;
  justify-content: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  font-size: 0.8rem;
  font-weight: 500;
  font-family: inherit;
  border: 1px solid #27272a;
  border-radius: 8px;
  background: #18181b;
  color: #e4e4e7;
  cursor: pointer;
  transition: all 0.15s;
}

.btn:hover {
  background: #27272a;
}

.btn:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.btn--icon {
  width: 36px;
  height: 36px;
  padding: 0;
  justify-content: center;
  border-radius: 50%;
}

.btn--toggle[aria-pressed="true"] {
  background: rgba(59, 130, 246, 0.15);
  border-color: rgba(59, 130, 246, 0.3);
  color: #60a5fa;
}

/* Landmark Page */
.landmark-page {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Landmark outlines */
.landmark {
  position: relative;
}

.show-outlines .landmark::after {
  content: attr(data-landmark);
  position: absolute;
  top: 4px;
  right: 4px;
  font-size: 0.6rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  pointer-events: none;
  z-index: 10;
  line-height: 1.4;
}

/* Color coding per landmark type */
.show-outlines header.landmark {
  outline: 2px dashed rgba(244, 63, 94, 0.4);
  outline-offset: -2px;
}

.show-outlines header.landmark::after {
  background: rgba(244, 63, 94, 0.2);
  color: #fb7185;
  border: 1px solid rgba(244, 63, 94, 0.3);
}

.show-outlines nav.landmark {
  outline: 2px dashed rgba(245, 158, 11, 0.4);
  outline-offset: -2px;
}

.show-outlines nav.landmark::after {
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.show-outlines main.landmark {
  outline: 2px dashed rgba(59, 130, 246, 0.4);
  outline-offset: -2px;
}

.show-outlines main.landmark::after {
  background: rgba(59, 130, 246, 0.2);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.3);
}

.show-outlines aside.landmark {
  outline: 2px dashed rgba(139, 92, 246, 0.4);
  outline-offset: -2px;
}

.show-outlines aside.landmark::after {
  background: rgba(139, 92, 246, 0.2);
  color: #a78bfa;
  border: 1px solid rgba(139, 92, 246, 0.3);
}

.show-outlines footer.landmark {
  outline: 2px dashed rgba(34, 197, 94, 0.4);
  outline-offset: -2px;
}

.show-outlines footer.landmark::after {
  background: rgba(34, 197, 94, 0.2);
  color: #4ade80;
  border: 1px solid rgba(34, 197, 94, 0.3);
}

/* Header */
.page-header {
  padding: 1rem 0;
  border-bottom: 1px solid #27272a;
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #fafafa;
  text-decoration: none;
  font-weight: 700;
  font-size: 1rem;
}

.nav-primary {
  flex: 1;
}

.nav-list {
  display: flex;
  gap: 0.25rem;
  list-style: none;
}

.nav-link {
  padding: 0.4rem 0.75rem;
  font-size: 0.825rem;
  color: #71717a;
  text-decoration: none;
  border-radius: 6px;
  transition: all 0.15s;
}

.nav-link:hover {
  color: #e4e4e7;
  background: #1e1e22;
}

.nav-link--active {
  color: #fafafa;
  background: #1e1e22;
}

.nav-link:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #3b82f6;
  color: #fff;
  font-size: 0.7rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Content Layout */
.content-layout {
  display: grid;
  grid-template-columns: 1fr 240px;
  gap: 1.5rem;
  padding: 1.5rem 0;
}

/* Main */
.page-main {
  min-height: 400px;
}

.main-title {
  font-size: 1.4rem;
  font-weight: 700;
  color: #fafafa;
  letter-spacing: -0.02em;
}

.main-desc {
  font-size: 0.875rem;
  color: #71717a;
  margin-top: 0.25rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.stat-card {
  background: #111113;
  border: 1px solid #27272a;
  border-radius: 10px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.75rem;
  color: #71717a;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fafafa;
}

.content-section {
  margin-top: 1.5rem;
}

.section-title {
  font-size: 1rem;
  font-weight: 600;
  color: #fafafa;
  margin-bottom: 0.75rem;
}

.activity-list {
  display: flex;
  flex-direction: column;
}

.activity-item {
  display: flex;
  gap: 0.75rem;
  padding: 0.65rem 0;
}

.activity-item + .activity-item {
  border-top: 1px solid #1e1e22;
}

.activity-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 0.45rem;
  flex-shrink: 0;
}

.activity-info {
  display: flex;
  flex-direction: column;
}

.activity-text {
  font-size: 0.85rem;
  color: #d4d4d8;
}

.activity-text strong {
  color: #fafafa;
}

.activity-time {
  font-size: 0.75rem;
  color: #52525b;
}

/* Pagination nav */
.nav-pagination {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.3rem;
}

.page-link {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  background: #18181b;
  border: 1px solid #27272a;
  color: #a1a1aa;
  text-decoration: none;
  font-size: 0.8rem;
  transition: all 0.15s;
}

.page-link:hover {
  background: #27272a;
  color: #fafafa;
}

.page-link[aria-current="page"] {
  background: #3b82f6;
  border-color: #3b82f6;
  color: #fff;
}

.page-link:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Aside */
.page-aside {
  padding: 1rem;
  background: #111113;
  border: 1px solid #27272a;
  border-radius: 12px;
  height: fit-content;
}

.aside-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: #fafafa;
  margin-bottom: 0.5rem;
}

.aside-list {
  list-style: none;
  display: flex;
  flex-direction: column;
}

.aside-link {
  display: block;
  padding: 0.35rem 0;
  font-size: 0.825rem;
  color: #a1a1aa;
  text-decoration: none;
  transition: color 0.15s;
}

.aside-link:hover {
  color: #3b82f6;
}

.aside-link:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.aside-team {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.team-member {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: #d4d4d8;
}

.member-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.member-dot--online {
  background: #22c55e;
}

.member-dot--away {
  background: #f59e0b;
}

/* Footer */
.page-footer {
  border-top: 1px solid #27272a;
  padding: 1rem 0;
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-copy {
  font-size: 0.78rem;
  color: #52525b;
}

.nav-footer {
  display: flex;
  gap: 1rem;
}

.footer-link {
  font-size: 0.78rem;
  color: #71717a;
  text-decoration: none;
  transition: color 0.15s;
}

.footer-link:hover {
  color: #e4e4e7;
}

.footer-link:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Legend */
.legend {
  max-width: 960px;
  margin: 1rem auto 3rem;
  padding: 1.5rem;
  background: #111113;
  border: 1px solid #27272a;
  border-radius: 12px;
}

.legend-title {
  font-size: 1rem;
  font-weight: 600;
  color: #fafafa;
  margin-bottom: 0.75rem;
}

.legend-items {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.825rem;
  color: #a1a1aa;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

.legend-swatch--header {
  background: rgba(244, 63, 94, 0.3);
  border: 1px solid rgba(244, 63, 94, 0.5);
}
.legend-swatch--nav {
  background: rgba(245, 158, 11, 0.3);
  border: 1px solid rgba(245, 158, 11, 0.5);
}
.legend-swatch--main {
  background: rgba(59, 130, 246, 0.3);
  border: 1px solid rgba(59, 130, 246, 0.5);
}
.legend-swatch--aside {
  background: rgba(139, 92, 246, 0.3);
  border: 1px solid rgba(139, 92, 246, 0.5);
}
.legend-swatch--footer {
  background: rgba(34, 197, 94, 0.3);
  border: 1px solid rgba(34, 197, 94, 0.5);
}

.legend-item code {
  background: #1e1e22;
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
  font-size: 0.75rem;
  color: #d4d4d8;
  font-family: "SF Mono", "Fira Code", monospace;
}

.legend-note {
  margin-top: 0.75rem;
  font-size: 0.78rem;
  color: #52525b;
  line-height: 1.5;
}

.legend-note code {
  background: #1e1e22;
  padding: 0.08rem 0.3rem;
  border-radius: 3px;
  font-size: 0.72rem;
  color: #a1a1aa;
  font-family: "SF Mono", "Fira Code", monospace;
}

@media (max-width: 640px) {
  .content-layout {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .header-inner {
    flex-wrap: wrap;
  }
}

