            background: "rgba(255,255,255,0.02)",
            border: "1px solid rgba(255,255,255,0.06)",
            borderRadius: "1rem",
            position: "relative",
            overflow: "hidden",
          }}
        >
          {/* Origin dot */}
          <div
            style={{
              position: "absolute",
              width: 12,
              height: 12,
              borderRadius: "50%",
              background: "rgba(109,40,217,0.3)",
