/* --- Shine Border --- */
.shine-border {
  --shine-color-1: #22d3ee;
  --shine-color-2: #3b82f6;
  --shine-border-width: 2px;
  --shine-speed: 3s;
  --shine-radius: 1.25rem;

  position: relative;
  width: min(400px, calc(100vw - 2rem));
  border-radius: var(--shine-radius);
  overflow: hidden;
  padding: var(--shine-border-width);
  background: linear-gradient(
    var(--shine-angle, 0deg),
    var(--shine-color-1),
    transparent 40%,
    transparent 60%,
    var(--shine-color-2)
  );
  animation: shine-rotate var(--shine-speed) linear infinite;
}

.shine-border--purple {
  --shine-color-1: #a855f7;
  --shine-color-2: #ec4899;
}

@keyframes shine-rotate {
  0% {
    --shine-angle: 0deg;
  }
  100% {
    --shine-angle: 360deg;
  }
}

/* Fallback for browsers without @property */
@supports not (background: paint(something)) {
  .shine-border {
    background: conic-gradient(
      from 0deg,
      var(--shine-color-1),
      transparent 25%,
      transparent 50%,
      var(--shine-color-2),
      transparent 75%,
      var(--shine-color-1)
    );
    animation: shine-conic-rotate var(--shine-speed) linear infinite;
  }

  .shine-border::before {
    content: "";
    position: absolute;
    inset: -100%;
    background: conic-gradient(
      from 0deg,
      var(--shine-color-1),
      transparent 25%,
      transparent 50%,
      var(--shine-color-2),
      transparent 75%,
      var(--shine-color-1)
    );
    animation: shine-conic-rotate var(--shine-speed) linear infinite;
    z-index: -1;
  }
}

@keyframes shine-conic-rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* Use @property for smooth angle transition where supported */
@property --shine-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

/* Inner content */
.shine-border__content {
  position: relative;
  z-index: 1;
  padding: 2rem;
  border-radius: calc(var(--shine-radius) - var(--shine-border-width));
  background: #0a0a0a;
