import { type CSSProperties, type ReactNode } from "react";

interface ShineBorderProps {
  children: ReactNode;
  color1?: string;
  color2?: string;
  borderWidth?: number;
  speed?: string;
  borderRadius?: string;
  className?: string;
}

export function ShineBorder({
  children,
  color1 = "#22d3ee",
  color2 = "#3b82f6",
  borderWidth = 2,
  speed = "3s",
  borderRadius = "1.25rem",
  className = "",
}: ShineBorderProps) {
  const outerStyle: CSSProperties = {
    position: "relative",
    borderRadius,
    overflow: "hidden",
    padding: borderWidth,
  };

  const bgStyle: CSSProperties = {
    position: "absolute",
    inset: "-100%",
    background: `conic-gradient(from 0deg, ${color1}, transparent 25%, transparent 50%, ${color2}, transparent 75%, ${color1})`,
    animation: `shine-border-rotate ${speed} linear infinite`,
  };

  const contentStyle: CSSProperties = {
    position: "relative",
    zIndex: 1,
    borderRadius: `calc(${borderRadius} - ${borderWidth}px)`,
    background: "#0a0a0a",
  };

  return (
    <>
      <style>{`
        @keyframes shine-border-rotate {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
      <div style={outerStyle} className={className}>
        <div style={bgStyle} />
