/* --- Interactive hover button base --- */
.ihover-btn {
  --fill-color: #f1f5f9;
  --text-color: #e2e8f0;
  --text-hover: #0a0a0a;
  --border-color: #334155;
  --border-hover: #f1f5f9;

  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  border-radius: 10px;
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  background: transparent;
  border: 1.5px solid var(--border-color);
  outline: none;
  overflow: hidden;
  transition: border-color 0.35s ease;
}

.ihover-btn:hover {
  border-color: var(--border-hover);
}

/* Fill from bottom */
.ihover-btn::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 0;
  background: var(--fill-color);
  transition: height 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  z-index: 0;
}

.ihover-btn:hover::before {
  height: 100%;
}

/* Label */
.ihover-btn__label {
  position: relative;
  z-index: 1;
  color: var(--text-color);
  transition: color 0.35s ease;
}

.ihover-btn:hover .ihover-btn__label {
  color: var(--text-hover);
}

/* Sizes */
.ihover-btn--sm {
  padding: 0.625rem 1.5rem;
  font-size: 0.8125rem;
}

.ihover-btn--lg {
  padding: 1.125rem 2.75rem;
  font-size: 1.0625rem;
}

/* Variant: Default (white fill) */
.ihover-btn--default {
  --fill-color: #f1f5f9;
  --text-color: #e2e8f0;
  --text-hover: #0a0a0a;
  --border-color: #475569;
  --border-hover: #f1f5f9;
}

/* Variant: Blue */
.ihover-btn--blue {
  --fill-color: #3b82f6;
  --text-color: #93c5fd;
  --text-hover: #fff;
  --border-color: #3b82f6;
  --border-hover: #60a5fa;
}

/* Variant: Purple */
.ihover-btn--purple {
  --fill-color: #8b5cf6;
  --text-color: #c4b5fd;
  --text-hover: #fff;
  --border-color: #8b5cf6;
  --border-hover: #a78bfa;
}

/* Variant: Emerald */
.ihover-btn--emerald {
  --fill-color: #10b981;
  --text-color: #6ee7b7;
  --text-hover: #fff;
  --border-color: #10b981;
  --border-hover: #34d399;
}

/* Variant: Rose */
.ihover-btn--rose {
  --fill-color: #f43f5e;
  --text-color: #fda4af;
  --text-hover: #fff;
  --border-color: #f43f5e;
  --border-hover: #fb7185;
}

/* Variant: Slide right */
.ihover-btn--slide-right::before {
  bottom: auto;
  top: 0;
  left: 0;
  width: 0;
  height: 100%;
  transition: width 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.ihover-btn--slide-right:hover::before {
  width: 100%;
}

.ihover-btn--slide-right {
  --fill-color: #f1f5f9;
  --text-color: #e2e8f0;
  --text-hover: #0a0a0a;
  --border-color: #475569;
  --border-hover: #f1f5f9;
}

/* Variant: Curtain (from center) */
.ihover-btn--curtain::before {
  bottom: auto;
  top: 50%;
  left: 0;
  width: 100%;
  height: 0;
  transform: translateY(-50%);
  transition: height 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.ihover-btn--curtain:hover::before {
  height: 100%;
}

.ihover-btn--curtain {
  --fill-color: #8b5cf6;
  --text-color: #c4b5fd;
  --text-hover: #fff;
  --border-color: #8b5cf6;
  --border-hover: #a78bfa;
}

/* Variant: Glow */
.ihover-btn--glow {
  --fill-color: #3b82f6;
  --text-color: #93c5fd;
  --text-hover: #fff;
  --border-color: #3b82f6;
  --border-hover: #60a5fa;
  transition: border-color 0.35s ease, box-shadow 0.35s ease;
}

.ihover-btn--glow:hover {
  box-shadow: 0 0 20px rgba(59, 130, 246, 0.4), 0 0 40px rgba(59, 130, 246, 0.2);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .ihover-btn::before {
    transition: none;
  }
  .ihover-btn__label {
    transition: none;
  }
  .ihover-btn {
    transition: none;
  }
}

