/* ═══════════════════════════════════════════════════════════════════════
   Uber UHD Ride-Share Landing Page — Styles
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --uber-black: #000000;
  --uber-dark: #0a0a0a;
  --uber-surface: #141414;
  --uber-border: rgba(255, 255, 255, 0.08);
  --uber-green: #06c167;
  --uber-green-glow: rgba(6, 193, 103, 0.25);
  --uber-green-subtle: rgba(6, 193, 103, 0.08);
  --uber-text: #ffffff;
  --uber-muted: #999999;
  --uber-dim: #666666;
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-hover: rgba(255, 255, 255, 0.07);
  --radius: 16px;
  --radius-lg: 24px;
  --font: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--uber-black);
  color: var(--uber-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* ── Canvas background ── */
#mesh-bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

main {
  position: relative;
  z-index: 1;
}

/* ── Shared ── */
section {
  position: relative;
  padding: 120px 1.5rem;
}

.section-container {
  max-width: 1100px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 3.5rem;
}

.section-title {
  font-size: clamp(2.5rem, 7vw, 4.5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.04em;
  margin-bottom: 1rem;
}

.text-muted {
  color: var(--uber-muted);
  font-size: 1.05rem;
  line-height: 1.6;
}

.text-sm {
  font-size: 0.875rem;
}

.tag {
  display: inline-block;
  padding: 6px 16px;
  background: var(--uber-green);
  color: #000;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1.25rem;
}

.reveal {
  opacity: 0;
  transform: translateY(30px);
}

/* ═══════════════════════════════════════════════════════════════════════
   HERO
   ═══════════════════════════════════════════════════════════════════════ */

.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px 1.5rem 60px;
  gap: 2.5rem;
}

.hero-content {
  position: relative;
  z-index: 2;
}

.hero-title {
  font-size: clamp(4rem, 14vw, 11rem);
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 0.9;
  background: linear-gradient(180deg, #fff 30%, #666 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  opacity: 0;
}

.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.35rem);
  color: var(--uber-muted);
  font-weight: 400;
  margin-top: 1.25rem;
  letter-spacing: 0.01em;
  opacity: 0;
}

/* ── Booking card ── */
.hero-booking {
  width: 100%;
  max-width: 440px;
  z-index: 2;
}

.booking-card {
  background: var(--glass-bg);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.booking-input-group {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.booking-input {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  transition: background 0.2s ease;
}

.booking-input:first-child {
  border-radius: 12px 12px 0 0;
}

.booking-input:last-child {
  border-radius: 0 0 12px 12px;
}

.booking-input:hover {
  background: rgba(255, 255, 255, 0.09);
}

.input-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-green {
  background: var(--uber-green);
  box-shadow: 0 0 8px var(--uber-green-glow);
}

.dot-dark {
  background: var(--uber-dim);
}

.input-placeholder {
  font-size: 0.95rem;
  color: var(--uber-muted);
  font-weight: 400;
}

.booking-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.06);
  margin-left: 38px;
}

.booking-btn {
  width: 100%;
  padding: 14px;
  background: var(--uber-text);
  color: var(--uber-black);
  border: none;
  border-radius: 12px;
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.booking-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(255, 255, 255, 0.15);
}

/* ── Scroll indicator ── */
.scroll-indicator {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: var(--uber-dim);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-weight: 700;
  opacity: 0;
}

.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--uber-green), transparent);
}

/* ═══════════════════════════════════════════════════════════════════════
   RIDE TYPES
   ═══════════════════════════════════════════════════════════════════════ */

.rides-section {
  padding: 100px 1.5rem 120px;
}

.rides-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.ride-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  position: relative;
  opacity: 0;
  transform: translateY(30px);
  transition: border-color 0.3s ease, background 0.3s ease, transform 0.3s ease;
}

.ride-card:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateY(-4px);
}

.ride-card-featured {
  border-color: rgba(6, 193, 103, 0.25);
}

.ride-card-featured:hover {
  border-color: rgba(6, 193, 103, 0.45);
  box-shadow: 0 0 40px rgba(6, 193, 103, 0.08);
}

.ride-icon {
  width: 80px;
  height: 40px;
  color: var(--uber-text);
  margin-bottom: 1.25rem;
  opacity: 0.85;
}

.ride-name {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.ride-desc {
  font-size: 0.8rem;
  color: var(--uber-muted);
  margin-bottom: 1.25rem;
  line-height: 1.5;
}

.ride-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.ride-time {
  font-size: 0.8rem;
  color: var(--uber-dim);
  font-weight: 500;
}

.ride-price {
  font-size: 1rem;
  font-weight: 700;
  color: var(--uber-text);
}

.eco-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 4px 10px;
  background: var(--uber-green);
  color: #000;
  border-radius: 100px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ═══════════════════════════════════════════════════════════════════════
   HOW IT WORKS (pinned)
   ═══════════════════════════════════════════════════════════════════════ */

.how-track {
  position: relative;
  height: 300vh;
  padding: 0;
}

.how-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8%;
  gap: 4rem;
}

.how-content {
  max-width: 400px;
  position: relative;
  flex-shrink: 0;
}

/* Step dots */
.step-dots {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.4s ease, transform 0.4s ease;
}

.step-dot.active {
  background: var(--uber-green);
  transform: scale(1.3);
  box-shadow: 0 0 10px var(--uber-green-glow);
}

/* Step cards */
.step-card {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.step-card.active {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
  position: relative;
}

.step-heading {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
  line-height: 1.1;
}

.step-desc {
  font-size: 0.95rem;
  color: var(--uber-muted);
  line-height: 1.7;
}

/* How visuals */
.how-visuals {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 400px;
}

.how-visual {
  position: absolute;
  opacity: 0;
  transform: translateY(20px) scale(0.95);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.how-visual.active {
  opacity: 1;
  transform: translateY(0) scale(1);
}

/* Mini phone in how-it-works */
.visual-phone-mini {
  width: 220px;
  aspect-ratio: 9 / 19;
  background: var(--uber-surface);
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.phone-mini-screen {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.mini-map {
  flex: 1;
  background: linear-gradient(180deg, #1a1a2e 0%, #16213e 100%);
  position: relative;
  overflow: hidden;
}

.mini-map::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
      90deg,
      transparent 49%,
      rgba(255, 255, 255, 0.03) 49%,
      rgba(255, 255, 255, 0.03) 51%,
      transparent 51%
    ),
    linear-gradient(
      0deg,
      transparent 49%,
      rgba(255, 255, 255, 0.03) 49%,
      rgba(255, 255, 255, 0.03) 51%,
      transparent 51%
    );
  background-size: 40px 40px;
}

.mini-bottom-sheet {
  background: var(--uber-surface);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.mini-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mini-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.mini-dot.green {
  background: var(--uber-green);
}

.mini-dot.dark {
  background: var(--uber-dim);
}

.mini-bar {
  height: 8px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 4px;
}

.mini-bar.faded {
  background: rgba(255, 255, 255, 0.05);
}

.w20 {
  width: 20%;
}
.w30 {
  width: 30%;
}
.w40 {
  width: 40%;
}
.w50 {
  width: 50%;
}
.w60 {
  width: 60%;
}
.w70 {
  width: 70%;
}

.mini-btn {
  height: 32px;
  background: var(--uber-text);
  border-radius: 8px;
  margin-top: 4px;
}

/* Visual-1: Driver matching */
.mini-car-icon {
  position: absolute;
  top: 35%;
  left: 40%;
  animation: carDrift 4s ease-in-out infinite;
}

@keyframes carDrift {
  0%,
  100% {
    transform: translate(0, 0);
  }
  50% {
    transform: translate(10px, -8px);
  }
}

.mini-route-line {
  position: absolute;
  top: 30%;
  left: 50%;
  width: 2px;
  height: 40%;
  background: linear-gradient(to bottom, var(--uber-green), transparent);
  opacity: 0.4;
}

.mini-driver-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mini-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--uber-green), #048a46);
  flex-shrink: 0;
}

.mini-bar-stack {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.mini-eta {
  font-size: 11px;
  color: var(--uber-green);
  font-weight: 600;
  text-align: center;
  padding: 6px;
  background: var(--uber-green-subtle);
  border-radius: 6px;
}

/* Visual-2: Riding */
.mini-map-route {
  background: linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%);
}

.mini-route-active {
  position: absolute;
  top: 20%;
  left: 30%;
  width: 40%;
  height: 60%;
  border: 2px dashed rgba(6, 193, 103, 0.3);
  border-radius: 50%;
}

.mini-trip-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mini-music-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 8px;
  margin-top: 4px;
}

.mini-equalizer {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
}

.mini-equalizer span {
  width: 3px;
  background: var(--uber-green);
  border-radius: 1px;
  animation: eqBounce 0.8s ease-in-out infinite alternate;
}

.mini-equalizer span:nth-child(1) {
  height: 4px;
  animation-delay: 0s;
}
.mini-equalizer span:nth-child(2) {
  height: 10px;
  animation-delay: 0.15s;
}
.mini-equalizer span:nth-child(3) {
  height: 6px;
  animation-delay: 0.3s;
}
.mini-equalizer span:nth-child(4) {
  height: 8px;
  animation-delay: 0.45s;
}

@keyframes eqBounce {
  0% {
    height: 3px;
  }
  100% {
    height: 12px;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   STATS
   ═══════════════════════════════════════════════════════════════════════ */

.stats-section {
  padding: 100px 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {
  padding: 3rem 1.5rem;
}

.stat-number {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
  background: linear-gradient(180deg, #fff 0%, var(--uber-green) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 0.75rem;
}

.stat-desc {
  font-size: 0.85rem;
  color: var(--uber-dim);
  max-width: 200px;
  margin: 0 auto;
  line-height: 1.5;
}

/* ═══════════════════════════════════════════════════════════════════════
   SAFETY
   ═══════════════════════════════════════════════════════════════════════ */

.safety-section {
  padding: 100px 1.5rem;
}

.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: 40px;
  padding: 60px;
  transition: border-color 0.4s ease;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

.safety-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.safety-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 2rem;
  color: var(--uber-green);
}

.safety-features {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.safety-feature {
  display: flex;
  align-items: flex-start;
  gap: 1.25rem;
  padding: 1.5rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius);
  transition: background 0.3s ease, transform 0.3s ease;
  opacity: 0;
  transform: translateX(-20px);
}

.safety-feature:hover {
  background: rgba(255, 255, 255, 0.06);
  transform: translateX(4px);
}

.sf-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--uber-green-subtle);
  border-radius: 10px;
  color: var(--uber-green);
  flex-shrink: 0;
}

.sf-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.35rem;
}

/* ═══════════════════════════════════════════════════════════════════════
   APP SHOWCASE
   ═══════════════════════════════════════════════════════════════════════ */

.app-section {
  padding: 120px 1.5rem;
}

.app-grid {
  display: flex;
  align-items: center;
  gap: 5rem;
}

.app-text {
  flex: 1;
}

.app-badges {
  display: flex;
  gap: 0.75rem;
  margin-top: 2.5rem;
  flex-wrap: wrap;
}

.store-badge {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  background: var(--uber-text);
  color: var(--uber-black);
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.store-badge:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(255, 255, 255, 0.15);
}

.store-text {
  display: flex;
  flex-direction: column;
}

.store-small {
  font-size: 9px;
  font-weight: 500;
  opacity: 0.6;
  line-height: 1;
}

.store-name {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
}

/* ── Phone mockup ── */
.app-device {
  position: relative;
  perspective: 1000px;
}

.device-phone {
  position: relative;
  width: 280px;
  aspect-ratio: 9 / 19;
  background: var(--uber-surface);
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-radius: 36px;
  overflow: hidden;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.04), 0 30px 80px rgba(0, 0, 0, 0.6);
  transform-style: preserve-3d;
}

.phone-notch {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 24px;
  background: var(--uber-black);
  border-radius: 12px;
  z-index: 3;
}

.phone-screen {
  width: 100%;
  height: 100%;
  padding: 40px 16px 16px;
}

.app-ui {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-greeting {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
  padding-top: 8px;
}

.app-search-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  font-size: 14px;
  color: var(--uber-muted);
}

.app-search-icon {
  color: var(--uber-muted);
  flex-shrink: 0;
}

.app-suggestions {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.app-suggestion {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 10px;
  transition: background 0.2s ease;
}

.sug-icon {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  color: var(--uber-muted);
  flex-shrink: 0;
}

.sug-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.app-services {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: auto;
  padding-bottom: 8px;
}

.app-service {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--uber-muted);
  font-weight: 500;
}

.service-icon-box {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.06);
}

.ride-svc {
  background: linear-gradient(135deg, rgba(6, 193, 103, 0.2), rgba(6, 193, 103, 0.05));
  border: 1px solid rgba(6, 193, 103, 0.15);
}

.eats-svc {
  background: linear-gradient(135deg, rgba(6, 193, 103, 0.12), rgba(255, 255, 255, 0.04));
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.pkg-svc {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02));
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.rent-svc {
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.12), rgba(59, 130, 246, 0.04));
  border: 1px solid rgba(59, 130, 246, 0.1);
}

.device-glow {
  position: absolute;
  inset: -60px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(6, 193, 103, 0.1) 0%, transparent 70%);
  pointer-events: none;
  animation: glowPulse 6s ease-in-out infinite;
}

@keyframes glowPulse {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.08);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   CTA
   ═══════════════════════════════════════════════════════════════════════ */

.cta-section {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  position: relative;
}

.cta-title {
  position: relative;
  z-index: 2;
}

.cta-subtitle {
  position: relative;
  z-index: 2;
  max-width: 400px;
  margin-bottom: 2.5rem;
}

.cta-rings {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(6, 193, 103, 0.06);
}

.ring-1 {
  width: 300px;
  height: 300px;
}
.ring-2 {
  width: 500px;
  height: 500px;
}
.ring-3 {
  width: 700px;
  height: 700px;
}

.cta-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
}

.cta-orb-1 {
  width: 400px;
  height: 400px;
  background: rgba(6, 193, 103, 0.08);
  bottom: -100px;
  left: -80px;
}

.cta-orb-2 {
  width: 350px;
  height: 350px;
  background: rgba(6, 193, 103, 0.05);
  top: -60px;
  right: -80px;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-block;
  padding: 16px 36px;
  background: var(--uber-text);
  color: var(--uber-black);
  border-radius: 30px;
  font-family: var(--font);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  transition: all 0.3s ease;
  border: none;
  cursor: pointer;
  position: relative;
  z-index: 2;
}

.btn-primary:hover {
  transform: scale(1.05);
  box-shadow: 0 10px 30px rgba(255, 255, 255, 0.15);
}

.btn-glow {
  box-shadow: 0 0 40px rgba(6, 193, 103, 0.2);
}

.btn-glow:hover {
  box-shadow: 0 0 60px rgba(6, 193, 103, 0.3);
}

/* ═══════════════════════════════════════════════════════════════════════
   REDUCED MOTION
   ═══════════════════════════════════════════════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
  }

  .ride-card {
    opacity: 1;
    transform: none;
  }

  .safety-feature {
    opacity: 1;
    transform: none;
  }

  .step-card {
    transition: none;
  }

  .how-visual {
    transition: none;
  }

  .step-dot {
    transition: none;
  }

  .mini-car-icon {
    animation: none;
  }

  .mini-equalizer span {
    animation: none;
  }

  .device-glow {
    animation: none;
    opacity: 0.5;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   RESPONSIVE
   ═══════════════════════════════════════════════════════════════════════ */

@media (max-width: 1024px) {
  .rides-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .app-grid {
    flex-direction: column;
    text-align: center;
    gap: 3rem;
  }

  .app-badges {
    justify-content: center;
  }
}

@media (max-width: 768px) {
  section {
    padding: 80px 1.25rem;
  }

  .rides-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .stat-item {
    padding: 2rem 1rem;
  }

  .how-sticky {
    flex-direction: column;
    justify-content: center;
    padding: 0 1.5rem;
    gap: 2rem;
  }

  .how-content {
    max-width: 100%;
  }

  .how-visuals {
    display: none;
  }

  .glass-card {
    padding: 32px;
    border-radius: 24px;
  }

  .device-phone {
    width: 240px;
  }

  .hero-booking {
    max-width: 360px;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: clamp(3rem, 16vw, 5rem);
  }

  .booking-card {
    padding: 16px;
  }

  .stat-number {
    font-size: 3rem;
  }

  .glass-card {
    padding: 24px;
    border-radius: 20px;
  }

  .safety-feature {
    flex-direction: column;
    gap: 0.75rem;
  }

  .device-phone {
    width: 200px;
  }
}

