          flexDirection: "column",
          alignItems: "center",
          gap: "2rem",
        }}
      >
        <h2 style={{ fontSize: "1.375rem", fontWeight: 700 }}>Statistics</h2>

        <div
          style={{
            background: "rgba(255,255,255,0.03)",
            border: "1px solid rgba(255,255,255,0.07)",
            borderRadius: "1rem",
            padding: "2rem 2.5rem",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "0.5rem",
          }}
        >
          <span
            style={{
              fontSize: "0.8rem",
              color: "#64748b",
              fontWeight: 500,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
            }}
          >
            Total Count
          </span>

          <div style={{ display: "flex", alignItems: "baseline" }}>
            {prefix && (
              <span style={{ fontSize: "2rem", fontWeight: 700, color: "#e2e8f0" }}>{prefix}</span>
            )}

            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                overflow: "hidden",
                height: "1em",
                fontSize: "2.5rem",
                fontWeight: 700,
                lineHeight: 1,
                color: "#f8fafc",
              }}
            >
              {digits.map((digit, i) => {
                const needsSep = separator && i > 0 && (digits.length - i) % 3 === 0;

                return (
                  <span key={i} style={{ display: "contents" }}>
                    {needsSep && (
                      <span
                        style={{
                          height: "1em",
                          display: "flex",
                          alignItems: "center",
                          color: "#475569",
                          fontSize: "0.85em",
                        }}
                      >
                        {separator}
                      </span>
                    )}
                    <DigitColumn
                      digit={digit}
                      index={i}
                      totalDigits={digits.length}
                      animate={animate}
                      duration={duration}
                    />
                  </span>
                );
              })}
            </div>

            {suffix && (
              <span style={{ fontSize: "1.25rem", color: "#64748b", marginLeft: "0.1rem" }}>
                {suffix}
              </span>
            )}
          </div>
        </div>

        <button
          onClick={replay}
          style={{
            background: "rgba(99,102,241,0.1)",
            border: "1px solid rgba(99,102,241,0.2)",
            color: "#a5b4fc",
            fontSize: "0.85rem",
            fontWeight: 500,
            padding: "0.5rem 1.25rem",
            borderRadius: "0.5rem",
            cursor: "pointer",
          }}
        >
          Replay Animation
        </button>
      </div>
    </div>
  );
}

