*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #0a0a0a;
}

/* --- Tweet Card --- */
.tweet-card {
  width: min(480px, calc(100vw - 2rem));
  padding: clamp(1rem, 3vw, 1.5rem);
  overflow: hidden;
  border-radius: 1rem;
  background: #16181c;
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  transition: border-color 0.2s ease;
}

.tweet-card:hover {
  border-color: rgba(255, 255, 255, 0.15);
}

/* Header */
.tweet-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.tweet-avatar {
  flex-shrink: 0;
}

.tweet-avatar__img {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  background: #2f3336;
}

.tweet-user {
  flex: 1;
  min-width: 0;
}

.tweet-user__name {
  font-size: 0.9375rem;
  font-weight: 700;
  color: #e7e9ea;
  display: flex;
  align-items: center;
  gap: 0.25rem;
  line-height: 1.3;
}

.tweet-verified {
  flex-shrink: 0;
}

.tweet-user__handle {
  font-size: 0.8125rem;
  color: #71767b;
  line-height: 1.3;
}

.tweet-logo {
  flex-shrink: 0;
  margin-left: auto;
  opacity: 0.6;
  transition: opacity 0.2s ease;
}

.tweet-card:hover .tweet-logo {
  opacity: 1;
}

/* Body */
.tweet-text {
  font-size: 0.9375rem;
  line-height: 1.55;
  color: #e7e9ea;
  word-wrap: break-word;
}

.tweet-hashtag {
  color: #1d9bf0;
  cursor: pointer;
}

.tweet-hashtag:hover {
  text-decoration: underline;
}

/* Timestamp */
.tweet-timestamp {
  font-size: 0.8125rem;
  color: #71767b;
}

/* Divider */
.tweet-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
}

/* Metrics */
.tweet-metrics {
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 3vw, 1.5rem);
  flex-wrap: wrap;
}

.tweet-metric {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.8125rem;
  color: #71767b;
  cursor: pointer;
  transition: color 0.2s ease;
}

.tweet-metric:nth-child(1):hover {
  color: #f91880;
}

.tweet-metric:nth-child(1):hover svg {
  color: #f91880;
}

.tweet-metric:nth-child(2):hover {
  color: #00ba7c;
}

.tweet-metric:nth-child(2):hover svg {
  color: #00ba7c;
}

.tweet-metric:nth-child(3):hover {
  color: #1d9bf0;
}

.tweet-metric:nth-child(3):hover svg {
  color: #1d9bf0;
}

.tweet-metric:nth-child(4):hover {
  color: #1d9bf0;
}

.tweet-metric svg {
  flex-shrink: 0;
  transition: color 0.2s ease;
}

