body {
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #0a0a0a;
}

/* --- Border Beam Card --- */
.border-beam-card {
  --beam-color: #22d3ee;
  --beam-speed: 4s;
  --border-width: 2px;

  position: relative;
  width: min(400px, calc(100vw - 2rem));
  border-radius: 1.25rem;
  overflow: hidden;
}

/* Rotating beam pseudo-element */
.border-beam-card__beam {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    from 0deg,
    transparent 0%,
    transparent 70%,
    var(--beam-color) 76%,
    rgba(34, 211, 238, 0.6) 78%,
    transparent 82%,
    transparent 100%
  );
  animation: border-beam-rotate var(--beam-speed) linear infinite;
  z-index: 0;
}

/* Expand the gradient beyond card bounds to cover corners */
.border-beam-card__beam::before {
  content: "";
  position: absolute;
  inset: -50%;
  border-radius: inherit;
  background: inherit;
  animation: inherit;
}

@keyframes border-beam-rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* Inner content overlaying the beam */
.border-beam-card__content {
  position: relative;
  z-index: 1;
  margin: var(--border-width);
  padding: 2.5rem;
  border-radius: calc(1.25rem - var(--border-width));
  background: #0a0a0a;
  display: flex;
