}

.fake-toggle {
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  position: relative;
  transition: background 0.2s ease;
}

.fake-toggle::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #64748b;
  transition: transform 0.2s ease, background 0.2s ease;
}

.fake-toggle.active {
  background: rgba(99, 102, 241, 0.3);
}

.fake-toggle.active::after {
  transform: translateX(16px);
  background: #818cf8;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .collapsible-panel,
  .collapsible-chevron {
    transition: none;
  }
}

