    borderRadius: 12,
    fontSize: "1rem",
    fontWeight: 600,
    cursor: "pointer",
    fontFamily: "inherit",
    color: "white",
    transition: "all 0.2s",
  };

  return (
    <CoolMode>
      <div
        style={{
          width: "100vw",
