@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap");

/* =============================================
   SPOTIFY UHD — Custom Properties
   ============================================= */
:root {
  --sp-black: #121212;
  --sp-dark: #191414;
  --sp-surface: #1a1a1a;
  --sp-surface-hover: #282828;
  --sp-border: rgba(255, 255, 255, 0.08);
  --sp-green: #1db954;
  --sp-green-dark: #1aa34a;
  --sp-green-glow: rgba(29, 185, 84, 0.25);
  --sp-green-subtle: rgba(29, 185, 84, 0.08);
  --sp-purple: #8b5cf6;
  --sp-purple-glow: rgba(139, 92, 246, 0.2);
  --sp-text: #ffffff;
  --sp-muted: #b3b3b3;
  --sp-dim: #535353;
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-hover: rgba(255, 255, 255, 0.07);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 36px;
}

/* =============================================
   RESET & BASE
   ============================================= */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: auto;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--sp-black);
  color: var(--sp-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  line-height: 1.6;
}

/* =============================================
   CANVAS BACKGROUND
   ============================================= */
#mesh-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

/* =============================================
   UTILITY CLASSES
   ============================================= */
.reveal {
  opacity: 0;
  transform: translateY(30px);
}

section {
  position: relative;
  z-index: 1;
  padding: 120px 1.5rem;
}

.section-container {
  max-width: 72rem;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 3.5rem;
}

.section-title {
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.04em;
  margin-bottom: 1.25rem;
  background: linear-gradient(180deg, #ffffff 0%, #a0a0a0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.section-desc {
  font-size: 1.15rem;
  color: var(--sp-muted);
  max-width: 520px;
  line-height: 1.6;
}

/* =============================================
   TAGS
   ============================================= */
.tag {
  display: inline-block;
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 1.5rem;
}

.tag-green {
  background: var(--sp-green-subtle);
  color: var(--sp-green);
  border: 1px solid rgba(29, 185, 84, 0.15);
}

/* =============================================
   BUTTONS
   ============================================= */
.btn-primary {
  display: inline-block;
  padding: 16px 40px;
  border-radius: 500px;
  font-weight: 700;
  font-size: 1rem;
  font-family: inherit;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  letter-spacing: 0.01em;
}

.btn-green {
  background: var(--sp-green);
  color: #000;
}

.btn-green:hover {
  background: #1ed760;
  transform: scale(1.04);
  box-shadow: 0 8px 30px var(--sp-green-glow);
}

.btn-secondary {
  display: inline-block;
  padding: 16px 40px;
  border-radius: 500px;
  font-weight: 700;
  font-size: 1rem;
  font-family: inherit;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  background: transparent;
  color: var(--sp-text);
  border: 2px solid rgba(255, 255, 255, 0.3);
  letter-spacing: 0.01em;
}

.btn-secondary:hover {
  border-color: #fff;
  transform: scale(1.04);
}

.btn-glow {
  box-shadow: 0 0 40px var(--sp-green-glow), 0 0 80px rgba(29, 185, 84, 0.1);
