  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  opacity: 0.85;
}

.shoe-svg {
  width: 100%;
  max-width: 180px;
  height: auto;
}

.product-name {
  font-size: 1.15rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.25rem;
}

.product-category {
  font-size: 0.8rem;
  color: var(--nk-muted);
