/* ═══════════════════════════════════════════════════════════════════════
   INNOVATION (pinned)
   ═══════════════════════════════════════════════════════════════════════ */

.how-track {
  position: relative;
  height: 300vh;
  padding: 0;
}

.how-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8%;
  gap: 4rem;
}

