  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.4s ease, transform 0.4s ease;
}

.step-dot.active {
  background: var(--nk-volt);
  transform: scale(1.3);
  box-shadow: 0 0 10px var(--nk-volt-glow);
}

/* Step cards */
.step-card {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.step-card.active {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
  position: relative;
}

.step-heading {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  margin-bottom: 1rem;
  line-height: 1.0;
  text-transform: uppercase;
}

.step-desc {
  font-size: 0.95rem;
  color: var(--nk-muted);
  line-height: 1.7;
}

/* How visuals */
.how-visuals {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 400px;
}

.how-visual {
  position: absolute;
  opacity: 0;
  transform: translateY(20px) scale(0.95);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.how-visual.active {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.innovation-visual {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: 28px;
  padding: 30px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
}

.react-bubble {
  animation: reactFloat 4s ease-in-out infinite alternate;
}

.react-bubble:nth-child(2n) {
  animation-delay: -1s;
  animation-duration: 3.5s;
}

.react-bubble:nth-child(3n) {
  animation-delay: -2s;
  animation-duration: 4.5s;
}

@keyframes reactFloat {
  0% {
    transform: translate(0, 0);
  }
  100% {
    transform: translate(2px, -4px);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   STATS
   ═══════════════════════════════════════════════════════════════════════ */

.stats-section {
  padding: 100px 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {
  padding: 3rem 1.5rem;
}

.stat-number {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  background: linear-gradient(180deg, #fff 0%, var(--nk-volt) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 1rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 0.75rem;
}

.stat-desc {
  font-size: 0.85rem;
  color: var(--nk-dim);
  max-width: 200px;
  margin: 0 auto;
  line-height: 1.5;
}

/* ═══════════════════════════════════════════════════════════════════════
   ATHLETE SPOTLIGHT
   ═══════════════════════════════════════════════════════════════════════ */

.athlete-section {
  padding: 100px 1.5rem;
}

.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: 40px;
  padding: 60px;
  transition: border-color 0.4s ease;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

.athlete-layout {
  display: flex;
  gap: 4rem;
  align-items: center;
}

.athlete-figure {
  flex-shrink: 0;
  opacity: 0.9;
}

.athlete-figure svg {
  display: block;
}

.athlete-content {
  flex: 1;
}

.athlete-features {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 2.5rem;
}

.athlete-feature {
  display: flex;
  align-items: flex-start;
  gap: 1.25rem;
  padding: 1.25rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius);
  transition: background 0.3s ease, transform 0.3s ease;
  opacity: 0;
  transform: translateX(-20px);
}

.athlete-feature:hover {
  background: rgba(255, 255, 255, 0.06);
