.athlete-info {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.athlete-name {
  font-size: 1.15rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.athlete-sport {
  font-size: 0.85rem;
  color: var(--nk-volt);
  font-weight: 600;
