  gap: 4px;
}

.nrc-stat {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.nrc-stat-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--nk-text);
  letter-spacing: -0.02em;
}

.nrc-stat-main .nrc-stat-value {
