  height: 300px;
}
.ring-2 {
  width: 500px;
  height: 500px;
}
.ring-3 {
  width: 700px;
  height: 700px;
}

.cta-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
}

.cta-orb-1 {
  width: 400px;
  height: 400px;
  background: rgba(205, 255, 0, 0.08);
  bottom: -100px;
  left: -80px;
}

.cta-orb-2 {
  width: 350px;
  height: 350px;
  background: rgba(205, 255, 0, 0.05);
  top: -60px;
  right: -80px;
}

/* ═══════════════════════════════════════════════════════════════════════
   REDUCED MOTION
   ═══════════════════════════════════════════════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
  }

  .product-card {
    opacity: 1;
    transform: none;
  }

  .athlete-feature {
    opacity: 1;
    transform: none;
  }

  .step-card {
    transition: none;
  }

  .how-visual {
    transition: none;
  }

  .step-dot {
    transition: none;
  }

  .react-bubble {
    animation: none;
  }

  .nrc-pulse {
    animation: none;
  }

  .device-glow {
    animation: none;
    opacity: 0.5;
  }

  .hero-title,
  .hero-subtitle,
  .hero-ctas,
  .hero-swoosh,
  .scroll-indicator {
    opacity: 1;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   RESPONSIVE
   ═══════════════════════════════════════════════════════════════════════ */

@media (max-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .app-grid {
    flex-direction: column;
    text-align: center;
    gap: 3rem;
  }

  .app-badges {
    justify-content: center;
  }

  .athlete-layout {
    flex-direction: column;
    text-align: center;
    gap: 2.5rem;
  }

  .athlete-quote {
    border-left: none;
    padding-left: 0;
    border-top: 3px solid var(--nk-volt);
    padding-top: 1.5rem;
  }

  .athlete-info {
    justify-content: center;
  }
}

@media (max-width: 768px) {
  section {
    padding: 80px 1.25rem;
  }

  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .stat-item {
    padding: 2rem 1rem;
  }

  .how-sticky {
    flex-direction: column;
    justify-content: center;
    padding: 0 1.5rem;
    gap: 2rem;
  }

  .how-content {
    max-width: 100%;
  }

  .how-visuals {
    display: none;
  }

  .glass-card {
    padding: 32px;
    border-radius: 24px;
  }

  .device-phone {
    width: 240px;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
  }

  .athlete-feature {
    flex-direction: column;
    gap: 0.75rem;
  }

  .athlete-figure svg {
    width: 100px;
    height: auto;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: clamp(3.5rem, 18vw, 6rem);
  }

  .stat-number {
    font-size: 3rem;
  }

  .glass-card {
    padding: 24px;
    border-radius: 20px;
  }

  .device-phone {
    width: 200px;
  }

  .section-title {
    font-size: clamp(2rem, 10vw, 3rem);
  }

  .step-heading {
    font-size: clamp(1.8rem, 8vw, 2.5rem);
  }

  .nrc-stat-value {
    font-size: 15px;
  }

  .nrc-stat-main .nrc-stat-value {
    font-size: 22px;
  }
}

