.shiny-btn--blue:hover {
  box-shadow: 0 8px 24px rgba(59, 130, 246, 0.45);
}

.shiny-btn--purple {
  background: #8b5cf6;
  box-shadow: 0 4px 14px rgba(139, 92, 246, 0.3);
