import { type CSSProperties, type ReactNode } from "react";

interface ProgressiveBlurProps {
  children: ReactNode;
  direction?: "top" | "bottom" | "left" | "right";
  blurHeight?: number;
  layers?: number;
  maxBlur?: number;
  className?: string;
  style?: CSSProperties;
}

export function ProgressiveBlur({
  children,
  direction = "bottom",
  blurHeight = 200,
  layers = 6,
  maxBlur = 20,
  className = "",
  style = {},
}: ProgressiveBlurProps) {
  const isVertical = direction === "top" || direction === "bottom";

  const containerStyle: CSSProperties = {
    position: "relative",
    overflow: "hidden",
    ...style,
  };

  const overlayStyle: CSSProperties = {
    position: "absolute",
    zIndex: 10,
    pointerEvents: "none",
    display: "flex",
    ...(isVertical
      ? {
          left: 0,
          right: 0,
          height: blurHeight,
          flexDirection: direction === "bottom" ? "column" : "column-reverse",
          ...(direction === "bottom" ? { bottom: 0 } : { top: 0 }),
        }
      : {
          top: 0,
          bottom: 0,
          width: blurHeight,
          flexDirection: direction === "right" ? "row" : "row-reverse",
          ...(direction === "right" ? { right: 0 } : { left: 0 }),
        }),
  };

  // Exponential blur progression for smooth gradient
  const blurValues = Array.from({ length: layers }, (_, i) => {
    const t = i / (layers - 1);
    return Math.round(maxBlur * Math.pow(t, 2));
  });

  return (
    <div className={className} style={containerStyle}>
      {children}
      <div style={overlayStyle} aria-hidden="true">
        {blurValues.map((blur, i) => (
          <div
            key={i}
            style={{
              flex: 1,
              backdropFilter: `blur(${blur}px)`,
              WebkitBackdropFilter: `blur(${blur}px)`,
            }}
          />
        ))}
      </div>
    </div>
  );
}

