*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --ray-color: rgba(251, 191, 36, 0.4);
  --ray-color-bright: rgba(251, 191, 36, 0.15);
  --ray-speed: 4s;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  background: #0a0a0a;
  overflow: hidden;
}

.rays-wrapper {
  position: relative;
  width: 100%;
  height: 100vh;
  display: grid;
  place-items: center;
  background: #0a0a0a;
  overflow: hidden;
}

.rays-container {
  position: absolute;
  top: -10%;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 120%;
  pointer-events: none;
}

.ray {
  position: absolute;
  top: 0;
  left: 50%;
  width: var(--ray-width, 2px);
  height: 100%;
  transform-origin: top center;
  transform: translateX(-50%) rotate(var(--ray-angle, 0deg));
  background: linear-gradient(
    180deg,
    var(--ray-color) 0%,
    var(--ray-color-bright) 30%,
    transparent 80%
  );
  opacity: var(--ray-opacity, 0.5);
  animation: rayPulse var(--ray-speed) ease-in-out infinite;
  animation-delay: var(--ray-delay, 0s);
  filter: blur(var(--ray-blur, 4px));
}

@keyframes rayPulse {
  0%,
  100% {
    opacity: var(--ray-opacity, 0.5);
  }
  50% {
    opacity: calc(var(--ray-opacity, 0.5) * 0.3);
  }
}

/* Central glow source */
.rays-container::before {
  content: "";
  position: absolute;
  top: -5%;
  left: 50%;
  transform: translateX(-50%);
