    color: "#f59e0b",
    bg: "rgba(245,158,11,0.06)",
    border: "rgba(245,158,11,0.12)",
    icon: "\u26A0",
  },
  danger: {
    color: "#ef4444",
    bg: "rgba(239,68,68,0.06)",
    border: "rgba(239,68,68,0.12)",
    icon: "\u2717",
  },
};

export function MessageBlock({
  variant = "info",
  title,
  children,
  onDismiss,
  dismissible = true,
}: MessageBlockProps) {
  const [dismissed, setDismissed] = useState(false);
  const [dismissing, setDismissing] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const v = variantStyles[variant];

  const handleDismiss = () => {
    if (ref.current) {
      ref.current.style.maxHeight = ref.current.offsetHeight + "px";
    }
    setDismissing(true);
    setTimeout(() => {
      setDismissed(true);
      onDismiss?.();
    }, 300);
  };

  if (dismissed) return null;

  return (
    <div
      ref={ref}
      role="alert"
      style={{
        background: v.bg,
        border: `1px solid ${v.border}`,
        borderLeft: `4px solid ${v.color}`,
        borderRadius: "0.75rem",
        overflow: "hidden",
        transition: "opacity 0.3s ease, transform 0.3s ease, max-height 0.3s ease",
        opacity: dismissing ? 0 : 1,
        transform: dismissing ? "translateX(12px) scale(0.98)" : "none",
        maxHeight: dismissing ? 0 : undefined,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          gap: "0.625rem",
          padding: "0.875rem 1rem",
        }}
      >
        <span style={{ fontSize: "1rem", color: v.color, flexShrink: 0, lineHeight: 1.5 }}>
          {v.icon}
        </span>

        {title ? (
          <span
            style={{
              flex: 1,
              fontSize: "0.875rem",
              fontWeight: 700,
              color: "#f2f6ff",
              lineHeight: 1.5,
            }}
          >
            {title}
          </span>
        ) : (
          <div style={{ flex: 1, fontSize: "0.8125rem", lineHeight: 1.6, color: "#94a3b8" }}>
            {children}
          </div>
        )}

        {dismissible && (
          <button
            type="button"
            onClick={handleDismiss}
            aria-label="Dismiss"
            style={{
              flexShrink: 0,
              background: "none",
              border: "none",
              color: "#4a4a4a",
              cursor: "pointer",
              fontSize: "1.25rem",
              lineHeight: 1,
              padding: "0.125rem 0.25rem",
              borderRadius: "0.25rem",
              marginLeft: "auto",
            }}
          >
            &times;
          </button>
        )}
      </div>

      {title && (
        <div
          style={{
            padding: "0 1rem 0.875rem 2.625rem",
            fontSize: "0.8125rem",
            lineHeight: 1.6,
            color: "#94a3b8",
          }}
        >
          {children}
        </div>
      )}
    </div>
  );
}

/* Demo */
export default function MessageBlockDemo() {
  return (
    <div
      style={{
        minHeight: "100vh",
