            color: "#fff",
            textAlign: "center",
            textTransform: "uppercase",
            lineHeight: 0.9,
            fontFamily: "system-ui, -apple-system, sans-serif",
          }}
        >
          {lines.map((line, i) => (
            <span key={i}>
              {line}
              {i < lines.length - 1 && <br />}
            </span>
          ))}
        </h1>
      </div>

      {/* Subtle scanlines */}
      <div
        style={{
          position: "absolute",
          inset: 0,
