import { useRef, useState, useCallback } from "react";

interface DockItem {
  icon: React.ReactNode;
  label: string;
  onClick?: () => void;
}

interface DockProps {
  items?: DockItem[];
  baseSize?: number;
  maxSize?: number;
  magnifyRange?: number;
}

const defaultItems: DockItem[] = [
  {
    label: "Finder",
    icon: (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5}>
        <rect x="3" y="3" width="18" height="18" rx="4" />
