import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

const LINES = ["Design is not", "just what it looks like.", "Design is how", "it works."];
const AUTHOR = "— Steve Jobs";
const ACCENT = "#a855f7";

const RevealLine: React.FC<{ text: string; index: number; frame: number; fps: number }> = ({
  text,
  index,
  frame,
  fps,
}) => {
  const delay = 15 + index * 20;
  const f = Math.max(0, frame - delay);

  const clipX = spring({ frame: f, fps, from: 0, to: 100, config: { damping: 30, stiffness: 60 } });
  const blockX = spring({
    frame: f,
    fps,
    from: 0,
    to: 110,
    config: { damping: 30, stiffness: 60 },
  });
  const opacity = interpolate(f, [0, 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div style={{ position: "relative", marginBottom: 8, overflow: "hidden" }}>
      {/* Reveal block */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          bottom: 0,
          width: `${Math.min(blockX, 100)}%`,
          backgroundColor: ACCENT,
          zIndex: 2,
          opacity: blockX > 100 ? 0 : 1,
        }}
      />
      {/* Text */}
      <div style={{ clipPath: `inset(0 ${100 - clipX}% 0 0)`, opacity }}>
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: index % 2 === 0 ? 300 : 700,
            fontSize: 52,
            color: "#ffffff",
            lineHeight: 1.3,
            letterSpacing: -1,
          }}
        >
          {text}
        </span>
      </div>
    </div>
  );
};

export const TextReveal: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const authorDelay = 15 + LINES.length * 20 + 10;
  const authorOpacity = interpolate(Math.max(0, frame - authorDelay), [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const authorY = spring({
    frame: Math.max(0, frame - authorDelay),
    fps,
    from: 10,
    to: 0,
    config: { damping: 14, stiffness: 80 },
  });

  const fadeOut = interpolate(frame, [170, 210], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0f", opacity: fadeOut }}>
      <div
        style={{
          position: "absolute",
          top: -200,
          right: -200,
          width: 600,
          height: 600,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${ACCENT}18 0%, transparent 70%)`,
          opacity: interpolate(frame, [0, 30], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          }),
        }}
      />
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: 120,
          right: 120,
          transform: "translateY(-50%)",
        }}
      >
        {LINES.map((line, i) => (
          <RevealLine key={i} text={line} index={i} frame={frame} fps={fps} />
        ))}
        <div
          style={{ opacity: authorOpacity, transform: `translateY(${authorY}px)`, marginTop: 24 }}
        >
          <span
            style={{
              fontFamily: "system-ui, sans-serif",
              fontWeight: 400,
              fontSize: 22,
              color: ACCENT,
            }}
          >
            {AUTHOR}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="TextReveal"
      component={TextReveal}
      durationInFrames={210}
      fps={30}
      width={1280}
      height={720}
    />
  );
};

import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const HEADLINE = "BREAKING";
const TICKER_ITEMS = [
  "Markets surge 2.4% on tech earnings beat",
  "New AI framework breaks performance records",
  "Global climate summit reaches historic agreement",
  "SpaceX announces Mars mission timeline update",
  "Quantum computing milestone: 1000 qubits achieved",
];
const ACCENT = "#dc2626";
const TICKER_SPEED = 2;

const TickerBar: React.FC<{ frame: number }> = ({ frame }) => {
  const offset = frame * TICKER_SPEED;
  const text = TICKER_ITEMS.join("  \u25CF  ");
  const repeated = `${text}  \u25CF  ${text}  \u25CF  ${text}`;

  return (
    <div
      style={{
        position: "absolute",
        bottom: 0,
        left: 0,
        right: 0,
        height: 48,
        backgroundColor: "rgba(0,0,0,0.9)",
        borderTop: `3px solid ${ACCENT}`,
        overflow: "hidden",
        display: "flex",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          bottom: 0,
          width: 140,
          backgroundColor: ACCENT,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 2,
        }}
      >
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 800,
            fontSize: 16,
            color: "#ffffff",
            letterSpacing: 2,
          }}
        >
          {HEADLINE}
        </span>
      </div>
      <div style={{ marginLeft: 150, whiteSpace: "nowrap", transform: `translateX(-${offset}px)` }}>
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 500,
            fontSize: 16,
            color: "rgba(255,255,255,0.9)",
            letterSpacing: 0.5,
          }}
        >
          {repeated}
        </span>
      </div>
    </div>
  );
};

const NewsCard: React.FC<{ index: number; frame: number; fps: number }> = ({
  index,
  frame,
  fps,
}) => {
  const delay = 20 + index * 25;
  const f = Math.max(0, frame - delay);
  const opacity = interpolate(f, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const x = spring({ frame: f, fps, from: 60, to: 0, config: { damping: 16, stiffness: 100 } });

  const exitStart = delay + 60;
  const exitOpacity = interpolate(frame, [exitStart, exitStart + 15], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const item = TICKER_ITEMS[index];

  return (
    <div
      style={{
        position: "absolute",
        top: 120,
        left: 100,
        right: 100,
        opacity: opacity * exitOpacity,
        transform: `translateX(${x}px)`,
      }}
    >
      <div
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 500,
          fontSize: 14,
          color: ACCENT,
          textTransform: "uppercase",
          letterSpacing: 2,
          marginBottom: 12,
        }}
      >
        Top Story
      </div>
      <div
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 800,
          fontSize: 42,
          color: "#ffffff",
          lineHeight: 1.2,
          letterSpacing: -1,
        }}
      >
        {item}
      </div>
      <div
        style={{ marginTop: 20, width: 60, height: 3, backgroundColor: ACCENT, borderRadius: 2 }}
      />
    </div>
  );
};

const TimeStamp: React.FC<{ frame: number }> = ({ frame }) => {
  const opacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const seconds = Math.floor(frame / 30);
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;

  return (
    <div style={{ position: "absolute", top: 30, right: 40, opacity }}>
      <div
        style={{
          fontFamily: "ui-monospace, monospace",
          fontSize: 14,
          color: "rgba(255,255,255,0.4)",
        }}
      >
        LIVE
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 4 }}>
        <div
          style={{
            width: 8,
            height: 8,
            borderRadius: "50%",
            backgroundColor: ACCENT,
            opacity: frame % 30 < 20 ? 1 : 0.3,
          }}
        />
        <span
          style={{
            fontFamily: "ui-monospace, monospace",
            fontSize: 16,
            color: "rgba(255,255,255,0.6)",
          }}
        >
          {String(mins).padStart(2, "0")}:{String(secs).padStart(2, "0")}
        </span>
      </div>
    </div>
  );
};

export const NewsTicker: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Determine which card is active
  const activeIndex = Math.min(Math.floor(frame / 85), TICKER_ITEMS.length - 1);

  const logoOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const logoScale = spring({
    frame,
    fps,
    from: 0.8,
    to: 1,
    config: { damping: 14, stiffness: 100 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0f0f18" }}>
      {/* Background texture */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 30% 20%, rgba(220,38,38,0.06) 0%, transparent 50%)",
        }}
      />

      {/* Network logo */}
      <div
        style={{
          position: "absolute",
          top: 30,
          left: 40,
          opacity: logoOpacity,
          transform: `scale(${logoScale})`,
        }}
      >
        <div
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 900,
            fontSize: 28,
            color: "#ffffff",
            letterSpacing: -1,
          }}
        >
          NEWS<span style={{ color: ACCENT }}>24</span>
        </div>
      </div>

      <TimeStamp frame={frame} />

      {/* Rotating headlines */}
      {TICKER_ITEMS.map((_, i) => (
        <NewsCard key={i} index={i} frame={frame} fps={fps} />
      ))}

      <TickerBar frame={frame} />
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => (
  <Composition
    id="NewsTicker"
    component={NewsTicker}
    durationInFrames={450}
    fps={30}
    width={1280}
    height={720}
  />
);

import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const NOTIFICATIONS = [
  {
    type: "success",
    icon: "✅",
    title: "Payment received",
    desc: "Invoice #1042 — $2,450.00",
    time: "Just now",
  },
  {
    type: "info",
    icon: "💬",
    title: "New comment",
    desc: "Sarah left a comment on your PR",
    time: "2m ago",
  },
  {
    type: "warning",
    icon: "⚠️",
    title: "Storage almost full",
    desc: "You've used 92% of your quota",
    time: "5m ago",
  },
  {
    type: "error",
    icon: "🔴",
    title: "Build failed",
    desc: "Pipeline #847 failed at deploy step",
    time: "8m ago",
  },
  {
    type: "success",
    icon: "🚀",
    title: "Deployed to production",
    desc: "v2.4.1 is now live",
    time: "12m ago",
  },
];

const TYPE_COLORS: Record<string, string> = {
  success: "#10b981",
  info: "#6366f1",
  warning: "#f59e0b",
  error: "#ef4444",
};

const Toast: React.FC<{
  notif: (typeof NOTIFICATIONS)[number];
  index: number;
  frame: number;
  fps: number;
}> = ({ notif, index, frame, fps }) => {
  const enterDelay = 15 + index * 20;
  const exitDelay = enterDelay + 60;
  const f = Math.max(0, frame - enterDelay);

  const x = spring({ frame: f, fps, from: 400, to: 0, config: { damping: 16, stiffness: 100 } });
  const opacity = interpolate(f, [0, 8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Exit slide
  const exitF = Math.max(0, frame - exitDelay);
  const exitX =
    exitF > 0
      ? spring({ frame: exitF, fps, from: 0, to: 400, config: { damping: 20, stiffness: 120 } })
      : 0;
  const exitOpacity =
    exitF > 0
      ? interpolate(exitF, [0, 10], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
      : 1;

  const color = TYPE_COLORS[notif.type] || "#6366f1";

  // Progress bar shrinks over life
  const lifeProgress = interpolate(frame, [enterDelay, exitDelay], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        transform: `translateX(${x + exitX}px)`,
        opacity: opacity * exitOpacity,
        marginBottom: 12,
      }}
    >
      <div
        style={{
          width: 380,
          borderRadius: 12,
          backgroundColor: "rgba(255,255,255,0.05)",
          border: "1px solid rgba(255,255,255,0.08)",
          overflow: "hidden",
          backdropFilter: "blur(20px)",
        }}
      >
        <div style={{ padding: "14px 16px", display: "flex", gap: 12, alignItems: "flex-start" }}>
          <div style={{ fontSize: 20, lineHeight: 1, flexShrink: 0, marginTop: 2 }}>
            {notif.icon}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span
                style={{
                  fontFamily: "system-ui, sans-serif",
                  fontWeight: 600,
                  fontSize: 14,
                  color: "#ffffff",
                }}
              >
                {notif.title}
              </span>
              <span
                style={{
                  fontFamily: "system-ui, sans-serif",
                  fontWeight: 400,
                  fontSize: 12,
                  color: "rgba(255,255,255,0.3)",
                }}
              >
                {notif.time}
              </span>
            </div>
            <div style={{ marginTop: 4 }}>
              <span
                style={{
                  fontFamily: "system-ui, sans-serif",
                  fontWeight: 400,
                  fontSize: 13,
                  color: "rgba(255,255,255,0.5)",
                }}
              >
                {notif.desc}
              </span>
            </div>
          </div>
        </div>
        <div style={{ height: 2, backgroundColor: "rgba(255,255,255,0.05)" }}>
          <div
            style={{
              width: `${lifeProgress * 100}%`,
              height: "100%",
              backgroundColor: color,
              borderRadius: 1,
            }}
          />
        </div>
      </div>
    </div>
  );
};

export const NotificationStack: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleOpacity = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0f" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 70% 50%, rgba(99,102,241,0.06) 0%, transparent 60%)",
        }}
      />

      <div style={{ position: "absolute", top: 40, left: 80, opacity: titleOpacity }}>
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 700,
            fontSize: 28,
            color: "#ffffff",
          }}
        >
          Notifications
        </span>
        <div style={{ marginTop: 4 }}>
          <span
            style={{
              fontFamily: "system-ui, sans-serif",
              fontWeight: 400,
              fontSize: 14,
              color: "rgba(255,255,255,0.4)",
            }}
          >
            Real-time toast system
          </span>
        </div>
      </div>

      {/* Stacked toasts */}
      <div
        style={{
          position: "absolute",
          top: 100,
          right: 80,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {NOTIFICATIONS.map((notif, i) => (
          <Toast key={i} notif={notif} index={i} frame={frame} fps={fps} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="NotificationStack"
      component={NotificationStack}
      durationInFrames={210}
      fps={30}
      width={1280}
      height={720}
    />
  );
};

import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const TITLE = "How it works";
const STEPS = [
  {
    num: 1,
    title: "Sign Up",
    desc: "Create your free account in seconds",
    icon: "📝",
    color: "#6366f1",
  },
  {
    num: 2,
    title: "Configure",
    desc: "Set up your project and preferences",
    icon: "⚙️",
    color: "#8b5cf6",
  },
  {
    num: 3,
    title: "Build",
    desc: "Start building with our powerful tools",
    icon: "🔨",
    color: "#06b6d4",
  },
  {
    num: 4,
    title: "Ship",
    desc: "Deploy to production with one click",
    icon: "🚀",
    color: "#10b981",
  },
];

const Step: React.FC<{
  step: (typeof STEPS)[number];
  index: number;
  frame: number;
  fps: number;
  isLast: boolean;
}> = ({ step, index, frame, fps, isLast }) => {
  const delay = 20 + index * 25;
  const f = Math.max(0, frame - delay);
  const scale = spring({ frame: f, fps, from: 0, to: 1, config: { damping: 12, stiffness: 120 } });
  const opacity = interpolate(f, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const y = spring({ frame: f, fps, from: 30, to: 0, config: { damping: 14, stiffness: 100 } });

  // Connector line
  const lineProgress = spring({
    frame: Math.max(0, frame - (delay + 15)),
    fps,
    from: 0,
    to: 1,
    config: { damping: 20, stiffness: 60 },
  });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        flex: 1,
        position: "relative",
      }}
    >
      {/* Step card */}
      <div
        style={{
          opacity,
          transform: `translateY(${y}px) scale(${scale})`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 12,
        }}
      >
        {/* Circle */}
        <div
          style={{
            width: 72,
            height: 72,
            borderRadius: "50%",
            backgroundColor: `${step.color}15`,
            border: `2px solid ${step.color}40`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            position: "relative",
          }}
        >
          <span style={{ fontSize: 30 }}>{step.icon}</span>
          {/* Number badge */}
          <div
            style={{
              position: "absolute",
              top: -6,
              right: -6,
              width: 24,
              height: 24,
              borderRadius: "50%",
              backgroundColor: step.color,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span
              style={{
                fontFamily: "system-ui, sans-serif",
                fontWeight: 700,
                fontSize: 12,
                color: "#fff",
              }}
            >
              {step.num}
            </span>
          </div>
        </div>
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 700,
            fontSize: 20,
            color: "#ffffff",
          }}
        >
          {step.title}
        </span>
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 400,
            fontSize: 14,
            color: "rgba(255,255,255,0.45)",
            textAlign: "center",
            maxWidth: 180,
            lineHeight: 1.4,
          }}
        >
          {step.desc}
        </span>
      </div>

      {/* Connector arrow */}
      {!isLast && (
        <div
          style={{
            position: "absolute",
            top: 36,
            right: -40,
            width: 80,
            display: "flex",
            alignItems: "center",
          }}
        >
          <div
            style={{
              height: 2,
              backgroundColor: step.color,
              flex: 1,
              transformOrigin: "left",
              transform: `scaleX(${lineProgress})`,
              opacity: 0.4,
            }}
          />
          <div
            style={{
              width: 0,
              height: 0,
              borderTop: "6px solid transparent",
              borderBottom: "6px solid transparent",
              borderLeft: `8px solid ${step.color}`,
              opacity: lineProgress * 0.4,
              marginLeft: -1,
            }}
          />
        </div>
      )}
    </div>
  );
};

export const StepProcess: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleScale = spring({
    frame,
    fps,
    from: 0.85,
    to: 1,
    config: { damping: 14, stiffness: 100 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0f" }}>
      {/* Background gradient */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 50% 80%, rgba(99,102,241,0.06) 0%, transparent 60%)",
        }}
      />

      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: 80,
          left: 0,
          right: 0,
          textAlign: "center",
          opacity: titleOpacity,
          transform: `scale(${titleScale})`,
        }}
      >
        <span
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 800,
            fontSize: 44,
            color: "#ffffff",
            letterSpacing: -1,
          }}
        >
          {TITLE}
        </span>
      </div>

      {/* Steps */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: 80,
          right: 80,
          transform: "translateY(-10%)",
          display: "flex",
          gap: 16,
        }}
      >
        {STEPS.map((step, i) => (
          <Step
            key={i}
            step={step}
            index={i}
            frame={frame}
            fps={fps}
            isLast={i === STEPS.length - 1}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="StepProcess"
      component={StepProcess}
      durationInFrames={210}
      fps={30}
      width={1280}
      height={720}
    />
  );
};

snippets.css:
:root {
  --bg: #0f1020;
  --panel: #17192e;
  --panel-2: #1f2340;
  --text: #f2f4ff;
  --muted: #aab0d6;
  --accent: #ff7ad9;
  --accent-2: #7afcff;
  --ok: #8dffb1;
  --warn: #ffd27a;
  --border: rgba(255, 255, 255, 0.08);
  --shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
}
body {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif;
  background: radial-gradient(circle at top left, rgba(255, 122, 217, 0.18), transparent 30%),
    radial-gradient(circle at top right, rgba(122, 252, 255, 0.16), transparent 28%),
    linear-gradient(180deg, #111326, #0b0c18);
  color: var(--text);
  min-height: 100vh;
  padding: 20px;
}
.hidden {
  display: none !important;
}

/* App shell */
.app {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  gap: 16px;
}
.header {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01));
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 24px 28px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}
h1 {
  font-size: clamp(24px, 4vw, 40px);
  letter-spacing: -0.03em;
  line-height: 1.1;
}
.header p {
  color: var(--muted);
  font-size: 14px;
  margin-top: 6px;
}

/* Layout */
.layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 16px;
}

/* Track list */
.tracklist {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.005));
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 12px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 580px;
  overflow-y: auto;
}
.track-item {
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 120ms ease;
  font-size: 13px;
  color: var(--muted);
}
.track-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.track-item.active {
  background: linear-gradient(135deg, rgba(255, 122, 217, 0.15), rgba(122, 252, 255, 0.08));
  border-color: rgba(255, 122, 217, 0.2);
  color: var(--text);
}
.track-num {
  font-weight: 700;
  font-size: 12px;
  text-align: center;
  opacity: 0.5;
}
.track-item.active .track-num {
  color: var(--accent);
  opacity: 1;
}
.track-name {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.track-info {
  font-size: 11px;
  opacity: 0.5;
  white-space: nowrap;
}

/* Eq animation on active playing track */
.track-item.active.playing .track-num {
  animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* Player */
.player {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 20px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  display: grid;
  gap: 16px;
}

/* Now playing */
.now-playing {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.now-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-2);
  font-weight: 700;
}
.now-title {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.now-meta {
  font-size: 12px;
  color: var(--muted);
  margin-left: auto;
}

/* Transport */
.transport {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: center;
}
.t-btn {
  appearance: none;
  border: 0;
  border-radius: 14px;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--text);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02));
  border: 1px solid var(--border);
  transition: transform 100ms, background 100ms;
}
.t-btn:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.08);
}
.t-btn:active {
  transform: translateY(0);
}
.t-play {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(255, 122, 217, 0.3), rgba(122, 252, 255, 0.18));
  border-color: rgba(255, 122, 217, 0.25);
}
.t-play:hover {
  background: linear-gradient(135deg, rgba(255, 122, 217, 0.4), rgba(122, 252, 255, 0.25));
}
.t-stop {
  color: #ff8080;
}

/* Sliders */
.sliders {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.slider-row {
  display: grid;
  grid-template-columns: 56px 1fr 36px;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--muted);
}
.slider-val {
  font-weight: 700;
  font-size: 12px;
  text-align: right;
  color: var(--text);
}
input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
}

/* Stats */
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.stat {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 10px 14px;
}
.sk {
  font-size: 11px;
  color: var(--muted);
  display: block;
  margin-bottom: 2px;
}
.sv {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.03em;
}

/* Visualizer */
.visualizer {
  height: 140px;
  border-radius: 18px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(122, 252, 255, 0.04), rgba(255, 122, 217, 0.06));
  position: relative;
  overflow: hidden;
}
.bars {
  position: absolute;
  inset: 10px;
  display: grid;
  grid-template-columns: repeat(32, 1fr);
  gap: 4px;
  align-items: end;
}
.bar {
  border-radius: 999px 999px 0 0;
  min-height: 6px;
  background: linear-gradient(180deg, rgba(122, 252, 255, 0.9), rgba(255, 122, 217, 0.8));
  opacity: 0.8;
  transition: height 60ms;
}

/* Steps */
.steps {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
}
.step {
  height: 52px;
  border-radius: 14px;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.02);
  display: grid;
  place-items: center;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  transition: transform 80ms, background 80ms, box-shadow 80ms;
}
.step.active {
  background: linear-gradient(180deg, rgba(255, 122, 217, 0.22), rgba(122, 252, 255, 0.12));
  color: white;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(255, 122, 217, 0.15);
}

/* Editor */
.editor-section {
  margin-top: 4px;
}
.editor-toggle {
  appearance: none;
  border: 0;
  border-radius: 12px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  color: var(--muted);
  background: var(--panel-2);
  border: 1px solid var(--border);
  transition: color 100ms, background 100ms;
}
.editor-toggle:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.06);
}
.editor-panel {
  margin-top: 10px;
  display: grid;
  gap: 10px;
}
.editor-panel textarea {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 13px;
  line-height: 1.5;
  min-height: 260px;
  resize: vertical;
  width: 100%;
}
.apply-btn {
  appearance: none;
  border: 0;
  border-radius: 12px;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  color: var(--text);
  background: linear-gradient(135deg, rgba(122, 252, 255, 0.2), rgba(255, 122, 217, 0.15));
  border: 1px solid rgba(122, 252, 255, 0.2);
  transition: transform 100ms;
  justify-self: start;
}
.apply-btn:hover {
  transform: translateY(-1px);
}
.editor-status {
  font-size: 12px;
  min-height: 16px;
}
.editor-status.ok {
  color: var(--ok);
}
.editor-status.err {
  color: var(--warn);
}

/* Responsive */
@media (max-width: 860px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .tracklist {
    max-height: 200px;
    flex-direction: row;
    flex-wrap: wrap;
  }
  .track-item {
    flex: 0 0 auto;
  }
  .sliders {
    grid-template-columns: 1fr;
  }
  .stats-row {
    grid-template-columns: 1fr 1fr;
  }
}

