:root {
  --bg: #0f0f14;
  --surface: #1a1a24;
  --accent: #7c6af7;
  --accent-dim: rgba(124, 106, 247, 0.15);
  --text: #e0dff5;
  --muted: #6b6a8a;
  --radius: 10px;
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  max-width: 900px;
  margin: 0 auto;
  padding: 3rem 1.5rem 5rem;
  min-height: 100vh;
}
header {
  margin-bottom: 2rem;
}
header h1 {
  font-size: 2.6rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  background: linear-gradient(135deg, var(--text), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1.1;
}
.subtitle {
  color: var(--muted);
  font-size: 0.95rem;
  margin-top: 0.4rem;
}
.tabs {
  display: flex;
  gap: 0.4rem;
  margin-bottom: 1.8rem;
  flex-wrap: wrap;
}
.tab {
  background: var(--surface);
  border: 1px solid transparent;
  color: var(--muted);
  padding: 0.45rem 1.1rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.88rem;
  font-weight: 500;
  font-family: inherit;
  transition: background 0.15s, color 0.15s;
}
.tab:hover {
  color: var(--text);
  border-color: var(--accent-dim);
}
.tab.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.piece {
  display: none;
}
.piece.active {
  display: block;
  animation: fadeIn 0.22s ease;
}
.piece h2 {
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 0.3rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}
.meta {
  font-family: "SF Mono", "Fira Mono", "Consolas", monospace;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 1.4rem;
  letter-spacing: 0.02em;
}
.gen-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: #e05252;
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
  flex-shrink: 0;
}
midi-visualizer {
  display: block;
  width: 100%;
  height: 280px;
  background: var(--surface);
  border-radius: var(--radius);
  margin-bottom: 0.8rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.04);
}
midi-visualizer svg {
  width: 100%;
  height: 100%;
}
midi-player {
  display: block;
  width: 100%;
  --player-background: var(--surface);
  --player-color: var(--accent);
  --player-playing-color: var(--accent);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.04);
  margin-bottom: 1.2rem;
}

/* Generation code details */
.gen-details {
  margin-top: 0.4rem;
  margin-bottom: 1.2rem;
}
.gen-details summary {
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--accent);
  padding: 0.4rem 0;
  user-select: none;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  list-style: none;
}
.gen-details summary::-webkit-details-marker {
  display: none;
}
.gen-details summary::before {
  content: "\25B6";
  font-size: 0.6rem;
  transition: transform 0.2s ease;
  display: inline-block;
}
.gen-details[open] summary::before {
  transform: rotate(90deg);
}
.gen-details summary:hover {
  color: var(--text);
}
.gen-code {
  background: var(--surface);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius);
  padding: 1rem 1.2rem;
  margin-top: 0.5rem;
  overflow-x: auto;
}
.gen-code pre {
  font-family: "SF Mono", "Fira Mono", "Consolas", monospace;
  font-size: 0.75rem;
  line-height: 1.6;
  color: var(--text);
  white-space: pre-wrap;
  word-wrap: break-word;
}
.gen-code .comment {
  color: var(--muted);
}
.gen-code .key {
  color: #7dd3fc;
}
.gen-code .val {
  color: #a5f3c4;
}
.gen-code .str {
  color: #fcd34d;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(7px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

