        />
      </div>
      <span
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 500,
          fontSize: 14,
          color: "rgba(255,255,255,0.4)",
          textTransform: "uppercase",
          letterSpacing: 2,
        }}
      >
        {label}
      </span>
    </div>
  );
};

const Separator: React.FC<{ frame: number; delay: number }> = ({ frame, delay }) => {
  const opacity = interpolate(Math.max(0, frame - delay), [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const blink = frame % 30 < 15 ? 1 : 0.3;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 16,
        alignItems: "center",
        opacity: opacity * blink,
        paddingTop: 20,
      }}
    >
      <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: ACCENT }} />
      <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: ACCENT }} />
    </div>
  );
};

export const CountdownVideo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const remainingSeconds = Math.max(0, TOTAL_SECONDS - frame / fps);
  const days = Math.floor(remainingSeconds / 86400);
  const hours = Math.floor((remainingSeconds % 86400) / 3600);
  const minutes = Math.floor((remainingSeconds % 3600) / 60);
  const seconds = Math.floor(remainingSeconds % 60);

  // Use fixed display values for visual effect
  const displayDays = 12;
  const displayHours = 8;
  const displayMinutes = 45;
  const displaySeconds = Math.max(0, 30 - Math.floor(frame / fps));

  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = spring({ frame, fps, from: -30, to: 0, config: { damping: 14, stiffness: 80 } });

  const dateOpacity = interpolate(frame, [25, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowOpacity = interpolate(frame, [0, 40], [0, 0.3], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0f" }}>
      {/* Background glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 900,
          height: 400,
          borderRadius: "50%",
          background: `radial-gradient(ellipse, ${ACCENT}25 0%, transparent 70%)`,
          transform: "translate(-50%, -50%)",
          opacity: glowOpacity,
        }}
      />

      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: 80,
          left: 0,
          right: 0,
          textAlign: "center",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 800,
            fontSize: 48,
            color: "#ffffff",
            letterSpacing: -1,
          }}
        >
          {EVENT_NAME}
        </div>
        <div
          style={{
            fontFamily: "system-ui, sans-serif",
            fontWeight: 400,
            fontSize: 20,
            color: ACCENT,
            marginTop: 8,
            opacity: dateOpacity,
          }}
        >
          {EVENT_DATE}
        </div>
      </div>

      {/* Countdown digits */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          display: "flex",
          alignItems: "flex-start",
          gap: 24,
          marginTop: 30,
        }}
      >
        <Digit value={displayDays} label="Days" frame={frame} fps={fps} delay={10} />
        <Separator frame={frame} delay={14} />
        <Digit value={displayHours} label="Hours" frame={frame} fps={fps} delay={16} />
        <Separator frame={frame} delay={20} />
        <Digit value={displayMinutes} label="Minutes" frame={frame} fps={fps} delay={22} />
        <Separator frame={frame} delay={26} />
        <Digit value={displaySeconds} label="Seconds" frame={frame} fps={fps} delay={28} />
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => (
  <Composition
    id="CountdownVideo"
    component={CountdownVideo}
    durationInFrames={210}
    fps={30}
    width={1280}
    height={720}
  />
);

import {
  AbsoluteFill,
  Composition,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const PRODUCT_NAME = "AppFlow";
const TAGLINE = "Ship faster. Build smarter.";
const FEATURES = [
  { icon: "\u26A1", title: "Lightning Fast", desc: "Sub-second builds" },
  {
    icon: "\uD83D\uDD12",
    title: "Secure by Default",
    desc: "Zero-trust architecture",
  },
  {
    icon: "\uD83D\uDD04",
    title: "Auto Scaling",
    desc: "Handle any traffic spike",
  },
  {
    icon: "\uD83D\uDCCA",
    title: "Real-time Analytics",
    desc: "Insights that matter",
  },
];
const ACCENT = "#06b6d4";

const FeatureCard: React.FC<{
  feature: (typeof FEATURES)[number];
  index: number;
  frame: number;
  fps: number;
}> = ({ feature, index, frame, fps }) => {
  const delay = 40 + index * 15;
  const f = Math.max(0, frame - delay);
  const scale = spring({
    frame: f,
    fps,
    from: 0.5,
    to: 1,
    config: { damping: 14, stiffness: 120 },
  });
  const opacity = interpolate(f, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const y = spring({
    frame: f,
    fps,
    from: 30,
    to: 0,
    config: { damping: 16, stiffness: 100 },
  });

  return (
    <div
      style={{
        flex: 1,
        opacity,
        transform: `translateY(${y}px) scale(${scale})`,
        padding: 20,
        borderRadius: 16,
        backgroundColor: "rgba(255,255,255,0.05)",
        border: "1px solid rgba(255,255,255,0.08)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 10,
        textAlign: "center",
      }}
    >
      <div style={{ fontSize: 36, marginBottom: 4 }}>{feature.icon}</div>
      <div
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 700,
          fontSize: 18,
          color: "#ffffff",
        }}
      >
        {feature.title}
      </div>
      <div
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 400,
          fontSize: 14,
          color: "rgba(255,255,255,0.5)",
        }}
      >
        {feature.desc}
      </div>
    </div>
  );
};

export const ProductShowcase: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleScale = spring({
    frame,
    fps,
    from: 0.8,
    to: 1,
    config: { damping: 16, stiffness: 100 },
  });
  const taglineOpacity = interpolate(frame, [15, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const taglineY = spring({
    frame: Math.max(0, frame - 15),
    fps,
    from: 15,
    to: 0,
    config: { damping: 14, stiffness: 80 },
  });

  // Subtle background pulse
  const glowOpacity = interpolate(frame, [0, 30], [0, 0.25], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Fade out
  const fadeOut = interpolate(frame, [170, 210], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0f", opacity: fadeOut }}>
      <div
        style={{
          position: "absolute",
          top: "30%",
          left: "50%",
          width: 800,
          height: 400,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${ACCENT}30 0%, transparent 70%)`,
          transform: "translate(-50%, -50%)",
          opacity: glowOpacity,
        }}
      />

      <div
        style={{
          position: "absolute",
          top: 80,
          left: 0,
          right: 0,
          textAlign: "center",
        }}
      >
        <div
          style={{
            opacity: titleOpacity,
            transform: `scale(${titleScale})`,
          }}
        >
          <span
            style={{
              fontFamily: "system-ui, sans-serif",
              fontWeight: 900,
              fontSize: 64,
              color: "#ffffff",
              letterSpacing: -2,
            }}
          >
            {PRODUCT_NAME}
          </span>
        </div>
        <div
          style={{
            opacity: taglineOpacity,
            transform: `translateY(${taglineY}px)`,
            marginTop: 12,
          }}
        >
          <span
            style={{
              fontFamily: "system-ui, sans-serif",
              fontWeight: 400,
              fontSize: 24,
              color: "rgba(255,255,255,0.6)",
            }}
          >
            {TAGLINE}
          </span>
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          bottom: 80,
          left: 60,
          right: 60,
          display: "flex",
          gap: 16,
        }}
      >
        {FEATURES.map((feature, i) => (
          <FeatureCard key={i} feature={feature} index={i} frame={frame} fps={fps} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => (
  <Composition
    id="ProductShowcase"
    component={ProductShowcase}
    durationInFrames={210}
    fps={30}
    width={1280}
    height={720}
  />
);

import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const WORDS = ["Build", "Something", "People", "Actually", "Want"];
const ACCENT = "#f59e0b";
const STAGGER = 8;

const Word: React.FC<{
  word: string;
  index: number;
  frame: number;
  fps: number;
  total: number;
}> = ({ word, index, frame, fps, total }) => {
  const enter = Math.max(0, frame - index * STAGGER);
  const y = spring({
    frame: enter,
    fps,
    from: 80,
    to: 0,
    config: { damping: 12, stiffness: 120 },
  });
  const opacity = interpolate(enter, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scale = spring({
    frame: enter,
    fps,
    from: 0.6,
    to: 1,
    config: { damping: 14, stiffness: 100 },
  });

  // Exit
  const exitStart = 90 + index * 4;
  const exitOpacity = interpolate(frame, [exitStart, exitStart + 15], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const exitY = interpolate(frame, [exitStart, exitStart + 15], [0, -40], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const isLast = index === total - 1;

  return (
    <div
      style={{
        display: "inline-block",
        margin: "0 12px",
        opacity: opacity * exitOpacity,
        transform: `translateY(${y + exitY}px) scale(${scale})`,
      }}
    >
      <span
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 800,
          fontSize: 80,
          color: isLast ? ACCENT : "#ffffff",
          letterSpacing: -2,
        }}
      >
        {word}
      </span>
    </div>
  );
};

export const KineticText: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#0a0a0f",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 600,
          height: 600,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${ACCENT}15 0%, transparent 70%)`,
          transform: "translate(-50%, -50%)",
          opacity: bgOpacity,
        }}
      />
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
          maxWidth: 1000,
          padding: 40,
        }}
      >
        {WORDS.map((word, i) => (
          <Word key={i} word={word} index={i} frame={frame} fps={fps} total={WORDS.length} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => (
  <Composition
    id="KineticText"
