*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #f5f6f8;
  color: #1a1a2e;
  line-height: 1.5;
  min-height: 100vh;
}

.notifications-page {
  max-width: 720px;
  margin: 0 auto;
  padding: 24px 16px;
}

/* ── Header ──────────────────────────────────── */

.notifications-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.notifications-header h1 {
  font-size: 28px;
  font-weight: 700;
  color: #1a1a2e;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-mark-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  background: #fff;
  color: #4b5563;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-mark-all:hover {
  background: #f9fafb;
  border-color: #9ca3af;
  color: #1a1a2e;
}

.btn-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  background: #fff;
  color: #6b7280;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-icon:hover {
  background: #f9fafb;
  color: #1a1a2e;
}

/* ── Tabs ────────────────────────────────────── */

.tabs {
  display: flex;
  border-bottom: 1px solid #e5e7eb;
  margin-bottom: 4px;
  gap: 4px;
  overflow-x: auto;
}

.tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border: none;
  border-bottom: 2px solid transparent;
  background: none;
  color: #6b7280;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.tab:hover {
  color: #1a1a2e;
}

.tab.active {
  color: #4f46e5;
  border-bottom-color: #4f46e5;
}

.tab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 10px;
  background: #4f46e5;
  color: #fff;
  font-size: 11px;
  font-weight: 600;
}

.tab-badge:empty,
.tab-badge[data-count="0"] {
  display: none;
}

/* ── Date Groups ─────────────────────────────── */

.date-heading {
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 12px 16px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #9ca3af;
  background: #f5f6f8;
}

/* ── Notification Items ──────────────────────── */

.notification-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  background: #fff;
  border-bottom: 1px solid #f0f1f3;
  position: relative;
  cursor: pointer;
  transition: background 0.15s ease;
}

.notification-item:first-of-type {
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
}

.date-group:not(:last-child) .notification-item:last-of-type,
.date-group:last-child .notification-item:last-of-type {
  border-bottom-left-radius: 10px;
  border-bottom-right-radius: 10px;
  border-bottom: none;
}

.notification-item:hover {
  background: #fafbfc;
}

.notification-item.unread {
  background: #eff6ff;
}

.notification-item.unread:hover {
  background: #e8f1fd;
}

/* ── Unread Dot ──────────────────────────────── */

.unread-dot {
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #4f46e5;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.notification-item.unread .unread-dot {
  opacity: 1;
}

/* ── Notification Icons ──────────────────────── */

.notif-icon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
}

.notif-icon--comment {
  background: #dbeafe;
  color: #2563eb;
}

.notif-icon--like {
  background: #fee2e2;
  color: #dc2626;
}

.notif-icon--mention {
  background: #ede9fe;
  color: #7c3aed;
}

.notif-icon--system {
  background: #f3f4f6;
  color: #6b7280;
}

.notif-icon--follow {
  background: #d1fae5;
  color: #059669;
}

/* ── Notification Content ────────────────────── */

.notif-content {
  flex: 1;
  min-width: 0;
}

.notif-text {
  font-size: 14px;
  color: #374151;
  line-height: 1.4;
}

.notif-text strong {
  font-weight: 600;
  color: #1a1a2e;
}

.notif-context {
  color: #4f46e5;
  font-weight: 500;
}

.notif-excerpt {
  font-size: 13px;
  color: #6b7280;
  margin-top: 4px;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.notif-time {
  display: inline-block;
  font-size: 12px;
  color: #9ca3af;
  margin-top: 4px;
}

/* ── Action Menu ─────────────────────────────── */

.notif-actions {
  position: relative;
  flex-shrink: 0;
  align-self: center;
}

.btn-action {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: #9ca3af;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-action:hover {
  background: #f3f4f6;
  color: #4b5563;
}

.action-menu {
  display: none;
  position: absolute;
  right: 0;
  top: 100%;
  z-index: 20;
  min-width: 160px;
  padding: 4px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}

.action-menu.open {
  display: block;
}

.action-menu-item {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-radius: 6px;
  background: none;
  color: #374151;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
  transition: background 0.1s ease;
}

.action-menu-item:hover {
  background: #f3f4f6;
}

.action-menu-item[data-action="delete"] {
  color: #dc2626;
}

.action-menu-item[data-action="delete"]:hover {
  background: #fef2f2;
}

/* ── Empty State ─────────────────────────────── */

.empty-state {
  text-align: center;
  padding: 80px 24px;
}

.empty-state-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: #f3f4f6;
  color: #9ca3af;
  margin-bottom: 20px;
}

.empty-state h3 {
  font-size: 20px;
  font-weight: 600;
  color: #1a1a2e;
  margin-bottom: 8px;
}

.empty-state p {
  font-size: 14px;
  color: #6b7280;
}

/* ── Fade-out animation ──────────────────────── */

.notification-item.removing {
  opacity: 0;
  transform: translateX(40px);
  max-height: 0;
  padding-top: 0;
  padding-bottom: 0;
  margin: 0;
  overflow: hidden;
  transition: opacity 0.25s ease, transform 0.25s ease, max-height 0.3s ease 0.15s, padding 0.3s
    ease 0.15s;
}

/* ── Responsive ──────────────────────────────── */

@media (max-width: 600px) {
  .notifications-page {
    padding: 16px 8px;
  }

  .notifications-header h1 {
    font-size: 22px;
  }

  .btn-mark-all span,
  .btn-mark-all svg + span {
    display: none;
  }

  .btn-mark-all {
    font-size: 0;
    padding: 8px;
  }

  .btn-mark-all svg {
    font-size: initial;
  }

  .notification-item {
    padding: 12px 10px;
    gap: 10px;
  }

  .notif-icon {
    width: 34px;
    height: 34px;
  }

  .notif-icon svg {
    width: 15px;
    height: 15px;
  }

  .notif-excerpt {
    display: none;
  }

  .tab {
    padding: 8px 12px;
    font-size: 13px;
  }
}

