.status-container {
  max-width: 800px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

/* ── Header ─────────────────────────────────── */
.status-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-logo {
  width: 36px;
  height: 36px;
  background: #6366f1;
  color: #fff;
  border-radius: 10px;
