  font-size: 14px;
}

.brand-name {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
}

.btn-subscribe {
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 600;
  color: #6366f1;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.15s;
}

.btn-subscribe:hover {
  background: #6366f1;
  color: #fff;
  border-color: #6366f1;
}

/* ── Status Banner ──────────────────────────── */
.status-banner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 20px;
  border-radius: 12px;
  margin-bottom: 16px;
}

.banner-operational {
  background: #22c55e;
  color: #fff;
}

.banner-degraded {
  background: #eab308;
  color: #fff;
}

.banner-outage {
  background: #ef4444;
  color: #fff;
}

.banner-text {
  font-size: 18px;
  font-weight: 600;
}

/* ── Refresh Indicator ──────────────────────── */
.refresh-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
  margin-bottom: 24px;
}

.refresh-dot {
  width: 6px;
  height: 6px;
  background: #22c55e;
  border-radius: 50%;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
