  color: #111827;
}

.service-status-text {
  font-size: 12px;
  font-weight: 500;
}

.status-text-operational {
  color: #16a34a;
}
.status-text-degraded {
  color: #d97706;
}
.status-text-outage {
  color: #dc2626;
}

.service-right {
