/* Responsive */
@media (max-width: 640px) {
  .faq-hero {
    padding: 40px 0 32px;
  }

  .faq-hero h1 {
    font-size: 1.75rem;
  }

  .category-cards {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .category-card {
    padding: 18px 12px;
  }

  .contact-cta {
    padding: 32px 20px;
  }
}

