*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #fff;
  color: #1a1a2e;
  line-height: 1.6;
  min-height: 100vh;
}

a {
  text-decoration: none;
}

/* ── Header / Search Bar ─────────────────────── */

.search-header {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 16px 24px;
  border-bottom: 1px solid #e5e7eb;
  background: #fff;
  position: sticky;
  top: 0;
  z-index: 50;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 18px;
  font-weight: 700;
  color: #4f46e5;
  flex-shrink: 0;
}

.search-bar {
  display: flex;
  flex: 1;
  max-width: 640px;
}

.search-input {
  flex: 1;
  padding: 10px 16px;
  border: 1px solid #d1d5db;
  border-right: none;
  border-radius: 8px 0 0 8px;
  font-size: 15px;
  color: #1a1a2e;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.search-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border: 1px solid #4f46e5;
  border-radius: 0 8px 8px 0;
  background: #4f46e5;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease;
}

.search-btn:hover {
  background: #4338ca;
}

/* ── Type Tabs ───────────────────────────────── */

.type-tabs {
  display: flex;
  gap: 4px;
  padding: 0 24px;
  border-bottom: 1px solid #e5e7eb;
  overflow-x: auto;
}

.type-tab {
  padding: 10px 16px;
  border: none;
  border-bottom: 2px solid transparent;
  background: none;
  color: #6b7280;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.type-tab:hover {
  color: #1a1a2e;
}

.type-tab.active {
  color: #4f46e5;
  border-bottom-color: #4f46e5;
}

/* ── Layout ──────────────────────────────────── */

.search-layout {
  display: flex;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Filter Sidebar ──────────────────────────── */

.filter-sidebar {
  width: 240px;
  flex-shrink: 0;
  padding: 24px 20px 24px 0;
  border-right: 1px solid #f0f1f3;
}

.filter-group {
  margin-bottom: 24px;
}

.filter-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6b7280;
  margin-bottom: 10px;
}

.filter-radio,
.filter-check {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  font-size: 14px;
  color: #374151;
  cursor: pointer;
}

.filter-radio input,
.filter-check input {
  accent-color: #4f46e5;
  width: 15px;
  height: 15px;
}

.filter-select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 14px;
  color: #374151;
  background: #fff;
  cursor: pointer;
  outline: none;
}

.filter-select:focus {
  border-color: #4f46e5;
}

#mobileFilterClose {
  display: none;
}

/* ── Results Main ────────────────────────────── */

.results-main {
  flex: 1;
  min-width: 0;
  padding: 24px 0 40px 32px;
}

.results-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.results-count {
  font-size: 13px;
  color: #6b7280;
}

.results-count strong {
  color: #1a1a2e;
}

.mobile-filter-btn {
  display: none;
}

.filter-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  background: #fff;
  color: #374151;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.filter-toggle-btn:hover {
  background: #f9fafb;
}

/* ── Result Cards ────────────────────────────── */

.result-card {
  padding: 20px 0;
  border-bottom: 1px solid #f0f1f3;
}

.result-card:last-child {
  border-bottom: none;
}

.result-title {
  font-size: 18px;
  font-weight: 500;
  line-height: 1.3;
  margin-bottom: 4px;
}

.result-title a {
  color: #1a0dab;
  transition: color 0.1s ease;
}

.result-title a:hover {
  text-decoration: underline;
}

.result-title a:visited {
  color: #681da8;
}

.result-url {
  font-size: 13px;
  color: #188038;
  margin-bottom: 6px;
}

.result-url mark {
  background: none;
  color: #188038;
  font-weight: 600;
}

.result-desc {
  font-size: 14px;
  color: #4d5156;
  line-height: 1.5;
}

.result-desc mark {
  background: #fef3c7;
  color: #1a1a2e;
  padding: 1px 2px;
  border-radius: 2px;
  font-weight: 600;
}

.result-tags {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.tag {
  display: inline-block;
  padding: 2px 8px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  font-size: 11px;
  color: #6b7280;
  background: #f9fafb;
}

/* ── Pagination ──────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid #f0f1f3;
}

.page-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 8px;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  background: #fff;
  color: #374151;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.page-btn:hover:not(:disabled):not(.active) {
  background: #f3f4f6;
  border-color: #d1d5db;
}

.page-btn.active {
  background: #4f46e5;
  border-color: #4f46e5;
  color: #fff;
  font-weight: 600;
}

.page-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.page-ellipsis {
  padding: 0 6px;
  color: #9ca3af;
  font-size: 14px;
}

/* ── Empty State ─────────────────────────────── */

.empty-results {
  text-align: center;
  padding: 60px 20px;
}

.empty-icon {
  margin-bottom: 16px;
}

.empty-results h3 {
  font-size: 18px;
  font-weight: 600;
  color: #1a1a2e;
  margin-bottom: 8px;
}

.empty-results p {
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 16px;
}

.empty-results ul {
  list-style: none;
  font-size: 14px;
  color: #6b7280;
}

.empty-results li {
  padding: 3px 0;
}

.empty-results li::before {
  content: "\2022";
  color: #9ca3af;
  margin-right: 8px;
}

/* ── Responsive ──────────────────────────────── */

@media (max-width: 768px) {
  .search-header {
    padding: 12px 16px;
    gap: 12px;
  }

  .logo span {
    display: none;
  }

  .type-tabs {
    padding: 0 16px;
  }

  .search-layout {
    flex-direction: column;
    padding: 0 16px;
  }

  .filter-sidebar {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 100;
    width: 100%;
    background: #fff;
    padding: 24px;
    border-right: none;
    overflow-y: auto;
  }

  .filter-sidebar.open {
    display: block;
  }

  #mobileFilterClose {
    display: block;
    width: 100%;
    margin-top: 16px;
    text-align: center;
  }

  .mobile-filter-btn {
    display: inline-flex;
  }

  .results-main {
    padding: 16px 0 40px;
  }

  .result-title {
    font-size: 16px;
  }

  .page-btn {
    min-width: 32px;
    height: 32px;
    font-size: 13px;
  }
}

