:root {
  --bg: #050910;
  --nav-bg: #0d1117;
  --card-bg: #3b82f6;
  --card-hover: #2563eb;
  --accent: #38bdf8;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --muted: #475569;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--bg);
