/* ============================================================
   TERMINAL / CLI — Interactive Script
   - Button click simulates command execution with typed output
   - Input enter key echoes typed command as output
   - Typewriter effect for output lines
   - Header uptime counter (live ticking)
   ============================================================ */

(function () {
  "use strict";

  /* ----------------------------------------------------------
     1. Button click → simulate command execution
     Each button has data-cmd and data-output attributes
  ---------------------------------------------------------- */
  const outputArea = document.getElementById("cmd-output");
  const buttons = document.querySelectorAll(".btn[data-cmd]");

  function appendLine(text, cssClass) {
    if (!outputArea) return;
    const line = document.createElement("span");
    line.className = "cmd-output-line " + (cssClass || "");
    line.textContent = text;
    outputArea.appendChild(line);
    outputArea.scrollTop = outputArea.scrollHeight;
  }

  function typewriterAppend(text, cssClass, delay, callback) {
    if (!outputArea) return;
    const line = document.createElement("span");
    line.className = "cmd-output-line " + (cssClass || "");
    outputArea.appendChild(line);

    let i = 0;
    const interval = setInterval(function () {
      line.textContent += text[i];
      i++;
      outputArea.scrollTop = outputArea.scrollHeight;
      if (i >= text.length) {
        clearInterval(interval);
        if (callback) setTimeout(callback, 80);
      }
    }, delay || 18);
  }

  buttons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      const cmd = btn.dataset.cmd || "";
      const output = btn.dataset.output || "";

      // Flash button
      btn.style.opacity = "0.6";
      setTimeout(function () {
        btn.style.opacity = "";
      }, 120);

      // Show command line
      typewriterAppend("$ " + cmd, "cmd-line", 14, function () {
        // Show each output line
        const lines = output.split("\n");
        let lineIdx = 0;

        function nextLine() {
          if (lineIdx >= lines.length) return;
          const txt = lines[lineIdx];
          lineIdx++;
          appendLine("> " + txt, "out-line");
          if (lineIdx < lines.length) {
            setTimeout(nextLine, 100);
          } else {
            appendLine("> Exit code: 0", "out-line");
          }
        }

        setTimeout(nextLine, 120);
      });
    });
  });

  /* ----------------------------------------------------------
     2. Input enter key: echo typed line as terminal output
  ---------------------------------------------------------- */
  const termInput = document.getElementById("term-input");

  if (termInput && outputArea) {
    termInput.addEventListener("keydown", function (e) {
      if (e.key !== "Enter") return;
      const val = termInput.value.trim();
      if (!val) return;

      appendLine("$ " + val, "cmd-line");

      // Simulate a "command not found" response for unknown commands
      const knownCmds = {
        help: "Usage: terminal-ui [--demo|--verbose|--help]\nAll systems nominal.",
        ls: "profile.sh  actions.sh  input.sh  flags.sh",
        whoami: "root_user",
        pwd: "/usr/local/terminal-ui/demo",
        clear: "__CLEAR__",
        date: new Date().toString(),
        uptime: "up 99 days, 23 hours, 59 minutes",
        version: "terminal-ui v2.1.0",
      };

      const response = knownCmds[val.toLowerCase()];

      setTimeout(function () {
        if (response === "__CLEAR__") {
          outputArea.innerHTML = "";
        } else if (response) {
          response.split("\n").forEach(function (line) {
            appendLine("> " + line, "out-line");
          });
        } else {
          appendLine("> command not found: " + val, "out-line");
          appendLine('> Try "help" for available commands.', "out-line");
        }
        termInput.value = "";
      }, 200);
    });
  }

  /* ----------------------------------------------------------
     3. Live uptime counter in the header
  ---------------------------------------------------------- */
  const uptimeEl = document.querySelector(".header-uptime");
  if (uptimeEl) {
    let seconds = 0;
    setInterval(function () {
      seconds++;
      const h = String(Math.floor(seconds / 3600)).padStart(2, "0");
      const m = String(Math.floor((seconds % 3600) / 60)).padStart(2, "0");
      const s = String(seconds % 60).padStart(2, "0");
      uptimeEl.textContent = "UPTIME: " + h + ":" + m + ":" + s;
    }, 1000);
  }

  /* ----------------------------------------------------------
     4. Badges — toggle active state on click
  ---------------------------------------------------------- */
  const badges = document.querySelectorAll(".badge");
  badges.forEach(function (badge) {
    if (badge.classList.contains("badge-off")) return; // deprecated can't be toggled
    badge.style.cursor = "pointer";

    badge.addEventListener("click", function () {
      if (badge.classList.contains("badge-on")) {
        badge.classList.remove("badge-on");
        badge.style.textDecoration = "line-through";
        badge.style.opacity = "0.5";
      } else {
        badge.classList.add("badge-on");
        badge.style.textDecoration = "";
        badge.style.opacity = "";
      }
    });
  });

  /* ----------------------------------------------------------
     5. Cursor blink speed on input focus
  ---------------------------------------------------------- */
  if (termInput) {
    const cursorInInput = document.querySelector(".cursor-blink");
    termInput.addEventListener("focus", function () {
      if (cursorInInput) cursorInInput.style.animationDuration = "0.4s";
    });
    termInput.addEventListener("blur", function () {
      if (cursorInInput) cursorInInput.style.animationDuration = "0.8s";
    });
  }
})();

snippets.css:
/* ============================================================
   Purple Space — Design Style Showcase
   ============================================================ */

:root {
  /* Deep space surfaces */
  --bg-body: #0a0012;
  --bg-card: rgba(139, 92, 246, 0.07);
  --bg-input: rgba(139, 92, 246, 0.1);
  --bg-hover: rgba(139, 92, 246, 0.15);

  /* Borders */
  --border: rgba(139, 92, 246, 0.3);
  --border-light: rgba(167, 139, 250, 0.2);
  --border-focus: #8b5cf6;

  /* Text */
  --text-primary: #ffffff;
  --text-muted: #c4b5fd;
  --text-placeholder: #7c3aed;
  --text-dim: #9370db;

  /* Accent — violet spectrum */
  --violet: #8b5cf6;
  --violet-light: #a78bfa;
  --violet-dark: #7c3aed;
  --violet-bright: #c4b5fd;

  /* Glow */
  --glow-sm: 0 0 12px rgba(139, 92, 246, 0.4);
  --glow-md: 0 0 24px rgba(139, 92, 246, 0.4);
  --glow-lg: 0 0 40px rgba(139, 92, 246, 0.35);

  /* Shadows */
  --shadow-card: 0 8px 32px rgba(139, 92, 246, 0.15);

  /* Radius */
  --radius-sm: 8px;
  --radius: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
}

/* ---- Reset ---- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ---- Stars background ---- */
body {
  background-color: var(--bg-body);
  background-image:
    radial-gradient(ellipse at 20% 50%, #1a0033 0%, transparent 55%),
    radial-gradient(ellipse at 80% 20%, #150028 0%, transparent 45%),
    /* Star field */
    radial-gradient(circle at 10% 15%, rgba(255, 255, 255, 0.7) 0.5px, transparent 0.5px),
    radial-gradient(circle at 25% 40%, rgba(255, 255, 255, 0.5) 0.5px, transparent 0.5px),
    radial-gradient(circle at 40% 8%, rgba(255, 255, 255, 0.8) 0.5px, transparent 0.5px),
    radial-gradient(circle at 55% 25%, rgba(255, 255, 255, 0.4) 0.5px, transparent 0.5px),
    radial-gradient(circle at 70% 60%, rgba(255, 255, 255, 0.6) 0.5px, transparent 0.5px),
    radial-gradient(circle at 85% 35%, rgba(255, 255, 255, 0.7) 0.5px, transparent 0.5px),
    radial-gradient(circle at 90% 80%, rgba(255, 255, 255, 0.5) 0.5px, transparent 0.5px),
    radial-gradient(circle at 15% 75%, rgba(255, 255, 255, 0.6) 0.5px, transparent 0.5px),
    radial-gradient(circle at 35% 88%, rgba(255, 255, 255, 0.4) 0.5px, transparent 0.5px),
    radial-gradient(circle at 60% 90%, rgba(255, 255, 255, 0.7) 0.5px, transparent 0.5px),
    radial-gradient(circle at 75% 12%, rgba(255, 255, 255, 0.5) 0.5px, transparent 0.5px),
    radial-gradient(circle at 48% 55%, rgba(200, 180, 255, 0.5) 0.5px, transparent 0.5px),
    radial-gradient(circle at 92% 48%, rgba(255, 255, 255, 0.6) 0.5px, transparent 0.5px),
    radial-gradient(circle at 5% 50%, rgba(255, 255, 255, 0.4) 0.5px, transparent 0.5px);
  color: var(--text-primary);
  font-family: "Space Grotesk", system-ui, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}
button {
  font-family: inherit;
  cursor: pointer;
}

/* ---- Floating orbs ---- */
.orb {
  position: fixed;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
  z-index: 0;
  opacity: 0.45;
}

.orb-1 {
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, #6b21a8, transparent 70%);
  top: -100px;
  left: -100px;
  animation: float-1 18s ease-in-out infinite;
}

.orb-2 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, #4c1d95, transparent 70%);
  bottom: -150px;
  right: -120px;
  animation: float-2 22s ease-in-out infinite;
}

.orb-3 {
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, #7e22ce, transparent 70%);
  top: 40%;
  left: 50%;
  transform: translateX(-50%);
  animation: float-3 15s ease-in-out infinite;
}

@keyframes float-1 {
  0%,
  100% {
    transform: translate(0, 0);
  }
  33% {
    transform: translate(40px, 30px);
  }
  66% {
    transform: translate(-20px, 50px);
  }
}

@keyframes float-2 {
  0%,
  100% {
    transform: translate(0, 0);
  }
  40% {
    transform: translate(-50px, -40px);
  }
  70% {
    transform: translate(30px, -20px);
  }
}

@keyframes float-3 {
  0%,
  100% {
    transform: translateX(-50%) translateY(0);
  }
  50% {
    transform: translateX(-50%) translateY(-40px);
  }
}

/* ---- Header ---- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 0, 18, 0.75);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-light);
}

.header-inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 28px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
  position: relative;
  z-index: 1;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: "Orbitron", monospace;
  font-weight: 900;
  font-size: 16px;
  letter-spacing: 4px;
  color: var(--text-primary);
  flex-shrink: 0;
}

.logo-glyph {
  color: var(--violet-light);
  font-size: 20px;
  line-height: 1;
  text-shadow: 0 0 10px var(--violet);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-link {
  padding: 6px 14px;
  border-radius: 100px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  transition: color 0.15s, background 0.15s;
}

.nav-link:hover {
  color: var(--text-primary);
  background: rgba(139, 92, 246, 0.12);
}

.nav-link.active {
  color: var(--violet-bright);
  background: rgba(139, 92, 246, 0.15);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.icon-btn {
  position: relative;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: rgba(139, 92, 246, 0.08);
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s, box-shadow 0.2s;
}

.icon-btn:hover {
  background: rgba(139, 92, 246, 0.2);
  color: var(--violet-bright);
  box-shadow: var(--glow-sm);
}

.notif-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--violet-dark), var(--violet-light));
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--bg-body);
}

/* Gradient border avatar */
.avatar-sm {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(var(--bg-body), var(--bg-body)) padding-box,
    linear-gradient(135deg, #8b5cf6, #c4b5fd) border-box;
  border: 2px solid transparent;
  color: var(--violet-bright);
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 0.5px;
}

/* ---- Layout ---- */
.main {
  position: relative;
  z-index: 1;
  padding: 48px 0 80px;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ---- Page title ---- */
.page-title-area {
  padding: 8px 0 16px;
}

.page-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  color: var(--violet);
  margin-bottom: 10px;
  font-family: "Orbitron", monospace;
}

.page-title {
  font-family: "Orbitron", monospace;
  font-size: 42px;
  font-weight: 900;
  letter-spacing: 2px;
  line-height: 1.05;
  background: linear-gradient(135deg, #ffffff 0%, #c4b5fd 50%, #a78bfa 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.page-tagline {
  margin-top: 10px;
  font-size: 15px;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

/* ---- Card ---- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 26px;
  box-shadow: var(--shadow-card);
  backdrop-filter: blur(12px);
  transition: border-color 0.2s, box-shadow 0.25s, transform 0.2s;
  position: relative;
  z-index: 1;
}

.card:hover {
  border-color: rgba(139, 92, 246, 0.55);
  box-shadow: 0 8px 32px rgba(139, 92, 246, 0.2), var(--glow-md);
  transform: translateY(-1px);
}

.section-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  margin-bottom: 16px;
  font-family: "Orbitron", monospace;
}

/* ---- Profile card ---- */
.profile-card {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.profile-avatar-wrap {
  flex-shrink: 0;
}

/* Gradient border ring on large avatar */
.profile-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(var(--bg-body), var(--bg-body)) padding-box,
    linear-gradient(135deg, #8b5cf6, #c4b5fd, #7c3aed) border-box;
  border: 2.5px solid transparent;
  color: var(--violet-bright);
  font-size: 24px;
  font-weight: 700;
  font-family: "Orbitron", monospace;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 24px rgba(139, 92, 246, 0.35);
}

.profile-info {
  flex: 1;
  min-width: 160px;
}

.profile-name {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.2px;
  color: var(--text-primary);
  font-family: "Space Grotesk", sans-serif;
}

.profile-role {
  font-size: 14px;
  color: var(--text-muted);
  margin-top: 3px;
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 16px;
}

.stat {
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
}

.stat-label {
  display: block;
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
  letter-spacing: 0.04em;
}

.stat-divider {
  width: 1px;
  height: 32px;
  background: var(--border-light);
}

.profile-rank {
  margin-left: auto;
}

.rank-chip {
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 0 14px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  font-family: "Orbitron", monospace;
  background: linear-gradient(135deg, rgba(124, 58, 237, 0.3), rgba(167, 139, 250, 0.2));
  color: var(--violet-bright);
  border: 1px solid rgba(139, 92, 246, 0.5);
  box-shadow: 0 0 12px rgba(139, 92, 246, 0.2);
}

/* ---- Buttons ---- */
.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 44px;
  padding: 0 24px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 700;
  border: 1px solid transparent;
  transition: all 0.2s ease;
  letter-spacing: 0.02em;
}

.btn:active {
  transform: scale(0.96);
}

.btn-primary {
  background: linear-gradient(135deg, var(--violet-dark), var(--violet-light));
  color: #fff;
  box-shadow: 0 0 20px rgba(139, 92, 246, 0.45);
}

.btn-primary:hover {
  box-shadow: 0 0 30px rgba(139, 92, 246, 0.65), 0 4px 16px rgba(0, 0, 0, 0.3);
  transform: translateY(-1px);
}

.btn-secondary {
  background: rgba(139, 92, 246, 0.15);
  border-color: var(--violet);
  color: var(--violet-bright);
}

.btn-secondary:hover {
  background: rgba(139, 92, 246, 0.25);
  box-shadow: var(--glow-sm);
}

.btn-ghost {
  background: transparent;
  border-color: rgba(167, 139, 250, 0.4);
  color: var(--text-muted);
}

.btn-ghost:hover {
  border-color: rgba(167, 139, 250, 0.7);
  color: var(--text-primary);
  background: rgba(139, 92, 246, 0.08);
}

/* ---- Input ---- */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.input-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.input {
  height: 46px;
  padding: 0 16px;
  background: var(--bg-input);
  border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: "Space Grotesk", inherit;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.2s;
}

.input::placeholder {
  color: var(--text-placeholder);
  opacity: 0.7;
}

.input:focus {
  border-color: var(--violet);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.15), 0 0 20px rgba(139, 92, 246, 0.15);
}

.input-hint {
  font-size: 12px;
  color: var(--text-dim);
}

/* ---- Badges ---- */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-flex;
  align-items: center;
  height: 30px;
  padding: 0 14px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  font-family: "Orbitron", monospace;
}

.badge-gradient {
  background: linear-gradient(135deg, rgba(124, 58, 237, 0.4), rgba(167, 139, 250, 0.25));
  color: var(--violet-bright);
  border: 1px solid rgba(139, 92, 246, 0.45);
