*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --nav-bg: #0d1117;
  --accent: #3b82f6;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --muted: #475569;
  --drawer-width: 75%;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  padding: 2rem;
}

/* ── Demo wrapper ── */
.demo {
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  border-radius: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  background: var(--nav-bg);
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.phone-screen {
  position: relative;
  width: 100%;
  height: 520px;
  overflow: hidden;
}

/* ── Status bar ── */
.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.status-icons {
  font-size: 9px;
  letter-spacing: 3px;
}

/* ── Top bar ── */
.top-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 8px 16px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.top-bar-title {
  font-size: 18px;
  font-weight: 600;
}

/* ── Hamburger button ── */
.hamburger-btn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.hamburger-btn span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--text);
  border-radius: 2px;
  transition: background 0.3s;
}

.hamburger-btn:hover span {
  background: var(--accent);
}

/* ── Page content ── */
.page-content {
  padding: 28px 20px;
}
.page-content h2 {
  font-size: 1.25rem;
  margin-bottom: 10px;
}
.page-content p {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 20px;
}

.card-placeholder {
  height: 64px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 10px;
  margin-bottom: 10px;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

/* ── Backdrop overlay ── */
.backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
  z-index: 10;
}

.drawer-open .backdrop {
  opacity: 1;
  visibility: visible;
}

/* ── Drawer panel ── */
.drawer {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--drawer-width);
  height: 100%;
  background: var(--accent);
  transform: translateX(-100%);
  transition: transform 0.3s ease;
  z-index: 20;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
}

.drawer-open .drawer {
  transform: translateX(0);
}

/* ── Close button ── */
.close-btn {
  align-self: flex-end;
  background: none;
  border: none;
  color: #fff;
  font-size: 28px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.3s;
}

.close-btn:hover {
  background: rgba(255, 255, 255, 0.15);
}

/* ── Nav links ── */
.nav-links {
  list-style: none;
  margin-top: 32px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nav-links a {
