  padding: 14px 16px;
  color: #fff;
  text-decoration: none;
  font-size: 16px;
  font-weight: 500;
  border-radius: 10px;
  transition: background 0.3s;
}

.nav-links a:hover {
  background: rgba(255, 255, 255, 0.15);
}

