}

body {
  font-family: var(--font);
  background: var(--bg);
  background-image: radial-gradient(
      ellipse at 30% 20%,
      rgba(249, 115, 22, 0.06) 0%,
      transparent 50%
    ), radial-gradient(ellipse at 70% 80%, rgba(139, 92, 246, 0.06) 0%, transparent 50%);
  color: var(--text);
  min-height: 100vh;
  overflow-x: hidden;
}

/* ── Page ── */
.page {
  max-width: 680px;
  margin: 0 auto;
  padding: 48px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 40px;
  perspective: 1000px;
}

/* ── Header ── */
.header {
  text-align: center;
}

.header__pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.header__title {
  font-size: clamp(44px, 10vw, 80px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.04em;
}

.header__title span {
  background: var(--gradient-warm);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.header__tagline {
  margin-top: 14px;
  font-size: 15px;
  color: var(--text-muted);
}

/* ── 3D Card ── */
.card-3d {
  position: relative;
  background: var(--gradient-card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow-close), var(--shadow-far);
  overflow: hidden;
  transition: box-shadow 0.4s ease;
  transform-style: preserve-3d;
}

.card-3d__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 40%,
    rgba(255, 255, 255, 0.04) 45%,
    rgba(255, 255, 255, 0.08) 50%,
    rgba(255, 255, 255, 0.04) 55%,
    transparent 60%
  );
  pointer-events: none;
  transition: opacity 0.4s ease;
  opacity: 0;
}

.card-3d:hover .card-3d__shine {
  opacity: 1;
}

/* ── Tilt container ── */
.tilt-container {
  perspective: 800px;
  transform-style: preserve-3d;
}

.card-section {
  display: flex;
  justify-content: center;
  perspective: 800px;
}

/* ── Profile card ── */
.profile-card {
  max-width: 400px;
  width: 100%;
}

.card__top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 22px;
}

.avatar-3d {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: var(--gradient-warm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 800;
  color: white;
  flex-shrink: 0;
  box-shadow: 0 4px 16px rgba(249, 115, 22, 0.35);
  transform: translateZ(20px);
}

.card__info {
  flex: 1;
}

.card__name {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.card__role {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 3px;
}

.depth-badge {
  font-size: 11px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 8px;
  background: var(--gradient-cool);
  color: white;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
  transform: translateZ(10px);
}

.card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.stat-3d {
  text-align: center;
  padding: 14px 8px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.stat-3d:hover {
  transform: translateY(-3px) translateZ(10px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.stat__value {
  display: block;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.stat__label {
  display: block;
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
}

/* ── Stacked cards section ── */
.stack-section {
  padding: 20px 0;
}

.card-stack {
  position: relative;
  max-width: 500px;
  margin: 0 auto;
  height: auto;
}

.stack-card {
  width: 100%;
}

.stack-card--back {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  transform: rotate(-3deg) translateY(8px) scale(0.94);
  opacity: 0.3;
  z-index: 1;
}

.stack-card--mid {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  transform: rotate(-1.5deg) translateY(4px) scale(0.97);
  opacity: 0.5;
  z-index: 2;
}

.stack-card--front {
  position: relative;
  z-index: 3;
}

.stack-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stack-title {
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

/* ── Buttons ── */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.btn {
  font-family: var(--font);
  font-size: 13px;
  font-weight: 700;
  padding: 11px 20px;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn--gradient {
  background: var(--gradient-warm);
  color: white;
  box-shadow: 0 4px 16px rgba(249, 115, 22, 0.3);
}

.btn--gradient:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 28px rgba(249, 115, 22, 0.45);
}

.btn--glass {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text);
  border: 1px solid var(--card-border);
}

.btn--glass:hover {
  background: rgba(255, 255, 255, 0.1);
  transform: translateY(-1px);
}

.btn--outline {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.btn--outline:hover {
  border-color: rgba(255, 255, 255, 0.3);
  color: var(--text);
  transform: translateY(-1px);
}

/* ── Input card ── */
.input-card {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field__label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.input-3d {
  font-family: var(--font);
  font-size: 14px;
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  color: var(--text);
  outline: none;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.input-3d:focus {
  border-color: rgba(249, 115, 22, 0.5);
  box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.1), 0 4px 16px rgba(249, 115, 22, 0.1);
}

.input-3d::placeholder {
  color: rgba(255, 255, 255, 0.2);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  font-size: 12px;
  font-weight: 600;
  padding: 5px 14px;
  border-radius: 100px;
  border: 1px solid;
  transition: transform 0.2s ease;
}

.badge:hover {
  transform: translateY(-1px);
}

.badge--warm {
  background: rgba(249, 115, 22, 0.1);
  border-color: rgba(249, 115, 22, 0.25);
  color: #fb923c;
}

.badge--cool {
  background: rgba(59, 130, 246, 0.1);
  border-color: rgba(59, 130, 246, 0.25);
  color: #93c5fd;
}

.badge--neutral {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.12);
  color: var(--text-muted);
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .page {
    padding: 32px 16px 48px;
    gap: 28px;
  }

  .header__title {
    font-size: clamp(36px, 12vw, 44px);
  }

  .card-3d {
    padding: 20px;
  }

  .profile-card {
    max-width: 100%;
  }

  .card__top {
    gap: 12px;
  }

  .avatar-3d {
    width: 44px;
    height: 44px;
    font-size: 14px;
  }

  .card__name {
    font-size: 16px;
  }

  .stat__value {
    font-size: 18px;
  }

  .stat-3d {
    padding: 10px 4px;
  }

  .stack-card--back,
  .stack-card--mid {
    display: none;
  }

  .btn {
    font-size: 12px;
    padding: 10px 16px;
  }
}

