:root {
  --m-bg: #0f0f0f;
  --m-surface: #171717;
  --m-surface-2: #1f1f1f;
  --m-orange: #ff3d00;
  --m-orange-light: #ff6e40;
  --m-text: #f0f0f0;
  --m-text-muted: rgba(240, 240, 240, 0.5);
  --m-border: rgba(255, 255, 255, 0.08);
  --m-radius: 10px;
  --font: "Plus Jakarta Sans", system-ui, sans-serif;
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--m-bg);
  color: var(--m-text);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ── Animated bg gradient ── */
.bg-gradient {
  position: fixed;
  inset: 0;
  z-index: 0;
  background: linear-gradient(
    135deg,
    rgba(255, 61, 0, 0.06) 0%,
    rgba(15, 15, 15, 0) 40%,
    rgba(0, 229, 255, 0.04) 100%
  );
  background-size: 400% 400%;
  animation: bgPulse 10s ease infinite;
  pointer-events: none;
}

@keyframes bgPulse {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 820px;
  margin: 0 auto;
  padding: 60px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 56px;
}

/* ── Entrance animations ── */
@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes wordIn {
  from {
    opacity: 0;
    transform: translateY(60px) skewY(3deg);
  }
  to {
    opacity: 1;
    transform: translateY(0) skewY(0deg);
  }
}

@keyframes badgeSlide {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.anim-up {
  opacity: 0;
  animation: slideUp 0.6s var(--ease-spring) var(--delay, 0s) forwards;
}

.word {
  display: inline-block;
  overflow: hidden;
  opacity: 0;
  animation: wordIn 0.7s var(--ease-spring) calc(var(--i) * 0.15s + 0.1s) forwards;
}

.anim-badge {
  opacity: 0;
  animation: badgeSlide 0.4s var(--ease-out) calc(var(--bi) * 0.07s + 1.1s) forwards;
}

/* ── Header ── */
.header {
  text-align: center;
}

.header__eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--m-orange);
  text-transform: uppercase;
  margin-bottom: 20px;
}

.header__title {
  font-size: clamp(52px, 10vw, 100px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.04em;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}

.header__title .accent {
  color: var(--m-orange);
}

.header__tagline {
  margin-top: 20px;
  font-size: 17px;
  color: var(--m-text-muted);
  font-weight: 400;
  line-height: 1.6;
}

/* ── Card ── */
.card-section {
  display: flex;
  justify-content: center;
}

.motion-card {
  background: var(--m-surface);
  border: 1px solid var(--m-border);
  border-radius: 16px;
  padding: 28px;
  width: 100%;
  max-width: 400px;
  transition: transform 0.3s var(--ease-spring), box-shadow 0.3s ease;
  cursor: default;
  will-change: transform;
}

.motion-card:hover {
  box-shadow: 0 24px 60px rgba(255, 61, 0, 0.12), 0 4px 20px rgba(0, 0, 0, 0.4);
}

.card__top {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
}

.avatar {
  flex-shrink: 0;
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid var(--m-border);
}

.card__info {
  flex: 1;
}

.card__name {
  font-size: 17px;
  font-weight: 700;
  color: var(--m-text);
}

.card__role {
  font-size: 13px;
  color: var(--m-text-muted);
  margin-top: 2px;
}

.card__badge {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--m-orange);
  background: rgba(255, 61, 0, 0.12);
  border: 1px solid rgba(255, 61, 0, 0.3);
  padding: 4px 8px;
  border-radius: 4px;
}

.card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  border-top: 1px solid var(--m-border);
  padding-top: 20px;
}

.stat {
  text-align: center;
}

.stat__value {
  display: block;
  font-size: 24px;
  font-weight: 800;
  color: var(--m-text);
  letter-spacing: -0.03em;
}

.stat__label {
  display: block;
  font-size: 11px;
  color: var(--m-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
}

/* ── Controls ── */
.controls {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  position: relative;
  overflow: hidden;
  font-family: var(--font);
  font-size: 14px;
  font-weight: 700;
  padding: 13px 28px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  letter-spacing: 0.04em;
  transition: transform 0.2s var(--ease-spring), background 0.2s ease, box-shadow 0.2s ease;
}

.btn__inner {
  position: relative;
  z-index: 1;
  pointer-events: none;
}

.btn--primary {
  background: var(--m-orange);
  color: white;
}

.btn--primary:hover {
  transform: scale(1.06);
  background: var(--m-orange-light);
  box-shadow: 0 8px 30px rgba(255, 61, 0, 0.45);
}

.btn--primary:active {
  transform: scale(0.96);
}

.btn--secondary {
  background: var(--m-surface-2);
  color: var(--m-text);
  border: 1px solid var(--m-border);
}

.btn--secondary:hover {
  background: var(--m-text);
  color: var(--m-bg);
  transform: scale(1.04);
  border-color: transparent;
}

.btn--secondary:active {
  transform: scale(0.96);
}

.btn--ghost {
  background: transparent;
  color: var(--m-text);
  border: 1.5px solid var(--m-orange);
}

.btn--ghost:hover {
  background: var(--m-orange);
  color: white;
  transform: scale(1.04);
  box-shadow: 0 6px 24px rgba(255, 61, 0, 0.3);
}

.btn--ghost:active {
  transform: scale(0.96);
}

/* ── Floating label input ── */
.field {
  position: relative;
  width: 100%;
  max-width: 400px;
}

.field__input {
  width: 100%;
  padding: 20px 16px 8px;
  font-family: var(--font);
  font-size: 15px;
  font-weight: 500;
  color: var(--m-text);
  background: var(--m-surface);
  border: 1.5px solid var(--m-border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.field__input:focus {
  border-color: var(--m-orange);
  box-shadow: 0 0 0 3px rgba(255, 61, 0, 0.12);
}

.field__label {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  font-weight: 500;
  color: var(--m-text-muted);
  pointer-events: none;
  transform-origin: left center;
  transition: transform 0.25s var(--ease-spring), color 0.25s ease, font-size 0.25s ease;
}

.field__input:focus ~ .field__label,
.field__input:not(:placeholder-shown) ~ .field__label {
  transform: translateY(-145%) scale(0.8);
  color: var(--m-orange);
  font-size: 13px;
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 6px;
  background: var(--m-surface-2);
  color: var(--m-text-muted);
  border: 1px solid var(--m-border);
  transition: color 0.2s ease, background 0.2s ease, transform 0.2s var(--ease-spring);
}

.badge:hover {
  color: var(--m-orange);
  background: rgba(255, 61, 0, 0.08);
  border-color: rgba(255, 61, 0, 0.25);
  transform: translateY(-2px);
}

