/* ============================================================
   BRUTALISM — Raw Web Design Showcase
   Hard borders, offset shadows, zero radius, clashing colors
   ============================================================ */

:root {
  --black: #000000;
  --white: #ffffff;
  --yellow: #ffed00;
  --blue: #0000ff;
  --red: #ff0000;

  /* Hard shadow — zero blur, black offset */
  --shadow-sm: 4px 4px 0 var(--black);
  --shadow-md: 6px 6px 0 var(--black);
  --shadow-lg: 8px 8px 0 var(--black);
  --shadow-xl: 10px 10px 0 var(--black);

  /* Typography */
  --font-head: "Arial Black", "Impact", "Haettenschweiler", sans-serif;
  --font-mono: "Courier New", "Courier", monospace;
  --font-body: Arial, Helvetica, sans-serif;

  /* Borders */
  --border: 3px solid var(--black);
  --border-thick: 4px solid var(--black);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background-color: var(--yellow);
  color: var(--black);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 0 60px;
  overflow-x: hidden;
}

/* ── Header ── */
.brut-header {
  width: 100%;
  max-width: 560px;
  padding-top: 20px;
}

/* Scrolling tape strip */
.header-tape {
  width: 100%;
  background: var(--black);
  color: var(--yellow);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 6px 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
  animation: tape-scroll 18s linear infinite;
}

@keyframes tape-scroll {
  from {
    text-indent: 0;
  }
  to {
    text-indent: -600px;
  }
}

.header-content {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px 24px 20px;
}

.header-mark {
  width: 64px;
  height: 64px;
  background: var(--white);
  border: var(--border-thick);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-size: 2.2rem;
  color: var(--black);
  flex-shrink: 0;
}

.header-title {
  font-family: var(--font-head);
  font-size: 3rem;
  letter-spacing: -1px;
  color: var(--black);
  line-height: 1;
  text-transform: uppercase;
}

.header-tagline {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--black);
  opacity: 0.7;
  margin-top: 4px;
  letter-spacing: 0.3px;
}

/* ── Main layout ── */
.page-main {
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: 100%;
  max-width: 560px;
  padding: 0 24px;
}

/* ── Cards ── */
.brut-card {
  background: var(--white);
  border: var(--border-thick);
  box-shadow: var(--shadow-lg);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

/* Slight rotations — collage feel */
#card-profile {
  transform: rotate(-0.8deg);
}
#card-buttons {
  transform: rotate(0.5deg);
}
#card-input {
  transform: rotate(-0.3deg);
}
#card-badges {
  transform: rotate(0.7deg);
}

.brut-card:hover {
  transform: rotate(0deg) translate(-3px, -3px) !important;
  box-shadow: var(--shadow-xl);
}

.card-header-strip {
  background: var(--black);
  color: var(--yellow);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 5px 14px;
  text-transform: uppercase;
  border-bottom: var(--border-thick);
}

.card-body {
  padding: 20px 20px 18px;
}

/* ── Profile Card ── */
.profile-row {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
}

.avatar {
  width: 72px;
  height: 72px;
  background: var(--yellow);
  border: var(--border-thick);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.avatar-initials {
  font-family: var(--font-head);
  font-size: 1.5rem;
  color: var(--black);
  position: relative;
  z-index: 1;
}

.avatar-noise {
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.08'/%3E%3C/svg%3E");
  background-size: 100px 100px;
  opacity: 0.15;
}

.profile-name {
  font-family: var(--font-head);
  font-size: 1.35rem;
  letter-spacing: 0.5px;
  color: var(--black);
  line-height: 1.1;
  text-transform: uppercase;
}

.profile-role {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  color: var(--black);
  opacity: 0.65;
  margin-top: 5px;
}

.profile-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border: var(--border-thick);
}

.stat-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  border-right: var(--border);
  background: var(--white);
}

.stat-box:last-child {
  border-right: none;
}

.stat-box-yellow {
  background: var(--yellow);
}
.stat-box-blue {
  background: var(--blue);
}
.stat-box-blue .stat-value,
.stat-box-blue .stat-label {
  color: var(--white);
}

.stat-value {
  font-family: var(--font-head);
  font-size: 1.5rem;
  color: var(--black);
  line-height: 1;
}

.stat-label {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--black);
  opacity: 0.65;
  margin-top: 3px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font-head);
  font-size: 0.95rem;
  letter-spacing: 1px;
  padding: 11px 20px;
  border: var(--border-thick);
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: var(--shadow-md);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  outline: none;
  position: relative;
}

.btn:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--shadow-xl);
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn-black {
  background: var(--black);
  color: var(--white);
}

.btn-yellow {
  background: var(--yellow);
  color: var(--black);
}

.btn-ghost {
  background: var(--white);
  color: var(--black);
}

.btn:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 2px;
}

/* ── Input ── */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--black);
}

.input-wrap {
  display: flex;
  align-items: center;
  border: var(--border-thick);
  box-shadow: var(--shadow-sm);
  background: var(--white);
  transition: box-shadow 0.12s ease;
}

.input-wrap:focus-within {
  box-shadow: var(--shadow-md);
}

.input-prefix {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--black);
  padding: 0 10px 0 14px;
  flex-shrink: 0;
  user-select: none;
}

.brut-input {
  flex: 1;
  background: transparent;
  border: none;
  padding: 12px 8px 12px 0;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--black);
  outline: none;
  letter-spacing: 0.5px;
}

.brut-input::placeholder {
  color: var(--black);
  opacity: 0.35;
  font-style: italic;
}

.input-cursor {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--black);
  padding: 0 12px 0 4px;
  animation: cursor-blink 1s step-end infinite;
  flex-shrink: 0;
}

@keyframes cursor-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* Hide cursor when input has focus (text cursor is already there) */
.input-wrap:focus-within .input-cursor {
  display: none;
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 5px 10px;
  border: var(--border);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
