}

/* ── Responsive ── */
@media (max-width: 520px) {
  .brut-header {
    max-width: 100%;
  }
  .page-main {
    padding: 0 16px;
    max-width: 100%;
  }
  .header-content {
    padding: 16px 16px 14px;
    gap: 12px;
  }
  .header-mark {
    width: 48px;
    height: 48px;
