  }
  .avatar-initials {
    font-size: 1.2rem;
  }
  .profile-name {
    font-size: 1.1rem;
  }
  .stat-value {
    font-size: 1.2rem;
  }
  .stat-label {
    font-size: 0.52rem;
  }
  .stat-box {
