:root {
  --au-text: rgba(255, 255, 255, 0.95);
  --au-text-muted: rgba(255, 255, 255, 0.6);
  --au-glass-bg: rgba(255, 255, 255, 0.2);
  --au-glass-border: rgba(255, 255, 255, 0.3);
  --au-glass-hover: rgba(255, 255, 255, 0.28);
  --au-radius: 20px;
  --font: "Plus Jakarta Sans", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
  color: var(--au-text);
  /* Animated aurora gradient mesh */
  background: linear-gradient(135deg, #0ea5e9 0%, #8b5cf6 33%, #ec4899 66%, #f59e0b 100%);
  background-size: 400% 400%;
  animation: aurora 8s ease infinite;
}

@keyframes aurora {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

/* ── Aurora streaks ── */
.aurora-streaks {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.streak {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.45;
  animation: streakPulse 6s ease-in-out infinite;
  will-change: transform;
}

.streak--1 {
  width: 600px;
  height: 200px;
  background: rgba(255, 255, 255, 0.25);
  top: 10%;
  left: -10%;
  transform: rotate(-20deg);
  animation-delay: 0s;
}

.streak--2 {
  width: 700px;
  height: 150px;
  background: rgba(251, 191, 36, 0.3);
  top: 35%;
  right: -15%;
  transform: rotate(15deg);
  animation-delay: 1.5s;
}

.streak--3 {
  width: 500px;
  height: 180px;
  background: rgba(167, 139, 250, 0.35);
  bottom: 25%;
  left: 5%;
  transform: rotate(-10deg);
  animation-delay: 3s;
}

.streak--4 {
  width: 400px;
  height: 120px;
  background: rgba(34, 211, 238, 0.3);
  bottom: 10%;
  right: 10%;
  transform: rotate(25deg);
  animation-delay: 2s;
}

@keyframes streakPulse {
  0%,
  100% {
    opacity: 0.4;
    transform-origin: center;
  }
  50% {
    opacity: 0.65;
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 760px;
  margin: 0 auto;
  padding: 60px 24px 80px;
  display: flex;
  flex-direction: column;
