/* ============================================================
   NES RETRO / PIXEL — Interactive Script
   - Pixel press effect on button click
   - Hover scale flash
   - Simulated HP bar damage animation
   - Scanline flicker on page load
   - Score counter easter egg
   ============================================================ */

(function () {
  "use strict";

  /* ----------------------------------------------------------
     1. Pixel button press effect
  ---------------------------------------------------------- */
  const buttons = document.querySelectorAll(".btn[data-pixel-sound]");

  buttons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      btn.classList.add("pressed");

      // Flash the button color briefly
      const originalBg = btn.style.background;
      if (btn.classList.contains("btn-primary")) {
        btn.style.background = "#FFFFFF";
        btn.style.color = "#0B0B0B";
      } else if (btn.classList.contains("btn-secondary")) {
        btn.style.background = "#FFFFFF";
        btn.style.color = "#4169E1";
      } else if (btn.classList.contains("btn-ghost")) {
        btn.style.background = "rgba(255,215,0,0.3)";
      }

      setTimeout(function () {
        btn.classList.remove("pressed");
        btn.style.background = "";
        btn.style.color = "";
      }, 120);
    });

    // Hover scale pop
    btn.addEventListener("mouseenter", function () {
      btn.style.transform = "translate(-2px, -2px)";
    });

    btn.addEventListener("mouseleave", function () {
      btn.style.transform = "";
    });
  });

  /* ----------------------------------------------------------
     2. HP bar animation on load
  ---------------------------------------------------------- */
  const hpFill = document.querySelector(".hp-fill");
  if (hpFill) {
    const targetWidth = hpFill.style.width || "74%";
    hpFill.style.width = "0%";

    // Drain from full to target, simulating damage received
    let current = 100;
    const target = parseInt(targetWidth, 10);
    const decrement = (100 - target) / 20;

    const hpInterval = setInterval(function () {
      if (current <= target) {
        hpFill.style.width = target + "%";
        clearInterval(hpInterval);
        return;
      }
      current -= decrement;
      hpFill.style.width = Math.max(current, target) + "%";
    }, 40);
  }

  /* ----------------------------------------------------------
     3. Score counter easter egg — click the logo to increment
  ---------------------------------------------------------- */
  const logo = document.querySelector(".header-logo");
  const ticker = document.querySelector(".ticker-inner");
  let score = 0;

  if (logo && ticker) {
    logo.style.cursor = "pointer";
    logo.title = "Click for points!";

    logo.addEventListener("click", function () {
      score += 100;

      // Flash logo
      logo.style.color = "#FFD700";
      setTimeout(function () {
        logo.style.color = "";
      }, 200);

      // Spawn floating +100 label
      const float = document.createElement("span");
      float.textContent = "+100";
      float.style.cssText = [
        "position: fixed",
        'font-family: "Press Start 2P", monospace',
        "font-size: 10px",
        "color: #FFD700",
        "pointer-events: none",
        "z-index: 10000",
        "text-shadow: 2px 2px 0 #0B0B0B",
        "animation: floatUp 0.8s ease-out forwards",
        "left: " + (logo.getBoundingClientRect().left + 20) + "px",
        "top: " + (logo.getBoundingClientRect().top + 10) + "px",
      ].join(";");
      document.body.appendChild(float);
      setTimeout(function () {
        float.remove();
      }, 800);

      // Update ticker text
      ticker.textContent = ticker.textContent.replace(
        /HIGH SCORE: [\d,]+/,
        "HIGH SCORE: " + score.toLocaleString()
      );
    });
  }

  // Float-up keyframe injection
  const styleEl = document.createElement("style");
  styleEl.textContent = `
    @keyframes floatUp {
      0%   { opacity: 1; transform: translateY(0); }
      100% { opacity: 0; transform: translateY(-40px); }
    }
  `;
  document.head.appendChild(styleEl);

  /* ----------------------------------------------------------
     4. Scanline flicker on page load (CRT power-on effect)
  ---------------------------------------------------------- */
  document.body.style.opacity = "0";
  let flickerCount = 0;
  const maxFlickers = 5;

  const flicker = setInterval(function () {
    flickerCount++;
    document.body.style.opacity = flickerCount % 2 === 0 ? "0" : "0.85";
    if (flickerCount >= maxFlickers) {
      clearInterval(flicker);
      document.body.style.opacity = "1";
      document.body.style.transition = "opacity 0.1s";
    }
  }, 60);

  /* ----------------------------------------------------------
     5. Pixel input: play with characters counter
  ---------------------------------------------------------- */
  const playerInput = document.getElementById("player-name");
  const hintEl = document.querySelector(".input-hint");

  if (playerInput && hintEl) {
    playerInput.addEventListener("input", function () {
      const remaining = 10 - playerInput.value.length;
      if (remaining <= 0) {
        hintEl.textContent = "MAX REACHED!";
        hintEl.style.color = "#FF4500";
      } else {
        hintEl.textContent = remaining + " CHARS REMAINING";
        hintEl.style.color = "";
      }
    });
  }

  /* ----------------------------------------------------------
     6. Stat boxes — wobble on hover
  ---------------------------------------------------------- */
  const statBoxes = document.querySelectorAll(".stat-box");
  statBoxes.forEach(function (box) {
    box.style.cursor = "pointer";
    box.addEventListener("mouseenter", function () {
      box.style.transform = "translate(-2px, -2px)";
      box.style.boxShadow = "4px 4px 0 #FFD700";
    });
    box.addEventListener("mouseleave", function () {
      box.style.transform = "";
      box.style.boxShadow = "";
    });
  });
})();

snippets.css:
:root {
  --gd-bg: #080808;
  --gd-blue: rgba(59, 130, 246, 0.3);
  --gd-purple: rgba(139, 92, 246, 0.25);
  --gd-cyan: rgba(6, 182, 212, 0.2);
  --gd-glass-bg: rgba(255, 255, 255, 0.05);
  --gd-glass-border: rgba(255, 255, 255, 0.1);
  --gd-glass-hover: rgba(255, 255, 255, 0.08);
  --gd-text: rgba(255, 255, 255, 0.95);
  --gd-text-muted: rgba(255, 255, 255, 0.45);
  --gd-radius: 20px;
  --font: "Inter", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--gd-bg);
  color: var(--gd-text);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ── Background blobs ── */
.blob {
  position: fixed;
  border-radius: 50%;
  filter: blur(120px);
  pointer-events: none;
  z-index: 0;
  transition: transform 1.5s ease;
}

.blob--blue {
  width: 500px;
  height: 500px;
  background: var(--gd-blue);
  top: -100px;
  left: -100px;
  animation: blobDrift1 18s ease-in-out infinite;
}

.blob--purple {
  width: 600px;
  height: 600px;
  background: var(--gd-purple);
  top: 20%;
  right: -150px;
  animation: blobDrift2 22s ease-in-out infinite;
}

.blob--cyan {
  width: 400px;
  height: 400px;
  background: var(--gd-cyan);
  bottom: -100px;
  left: 30%;
  animation: blobDrift3 16s ease-in-out infinite;
}

@keyframes blobDrift1 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  33% {
    transform: translate(60px, 40px) scale(1.05);
  }
  66% {
    transform: translate(-30px, 80px) scale(0.95);
  }
}

@keyframes blobDrift2 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  40% {
    transform: translate(-80px, -60px) scale(1.08);
  }
  70% {
    transform: translate(40px, 40px) scale(0.96);
  }
}

@keyframes blobDrift3 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  30% {
    transform: translate(-40px, -30px) scale(1.1);
  }
  60% {
    transform: translate(70px, -20px) scale(0.92);
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 760px;
  margin: 0 auto;
  padding: 60px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

/* ── Header ── */
.header {
  text-align: center;
  margin-bottom: 12px;
}

.header__pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gd-text-muted);
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid var(--gd-glass-border);
  padding: 6px 16px;
  border-radius: 100px;
  margin-bottom: 24px;
  backdrop-filter: blur(10px);
}

.header__title {
  font-size: clamp(52px, 10vw, 96px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--gd-text);
}

.header__title span {
  color: transparent;
  background: linear-gradient(135deg, #60a5fa, #a78bfa, #22d3ee);
  -webkit-background-clip: text;
  background-clip: text;
}

.header__tagline {
  margin-top: 20px;
  font-size: 16px;
  font-weight: 300;
  color: var(--gd-text-muted);
  letter-spacing: 0.01em;
}

/* ── Glass card ── */
.glass-card {
  background: var(--gd-glass-bg);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--gd-glass-border);
  border-radius: var(--gd-radius);
  padding: 28px;
  transition: border-color 0.3s ease, background 0.3s ease;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.18);
  background: var(--gd-glass-hover);
}

/* ── Profile card ── */
.card-section {
  display: flex;
  justify-content: center;
}

.profile-card {
  width: 100%;
  max-width: 400px;
}

.card__top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
}

.avatar {
  flex-shrink: 0;
  border-radius: 16px;
  overflow: hidden;
}

.card__meta {
  flex: 1;
}

.card__name {
  font-size: 18px;
  font-weight: 600;
  color: var(--gd-text);
  letter-spacing: -0.01em;
}

.card__role {
  font-size: 13px;
  color: var(--gd-text-muted);
  margin-top: 3px;
  font-weight: 400;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 8px #22c55e, 0 0 16px rgba(34, 197, 94, 0.4);
  flex-shrink: 0;
}

.card__divider {
  height: 1px;
  background: var(--gd-glass-border);
  margin: 0 0 20px;
}

.card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat {
  text-align: center;
  padding: 12px 8px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  transition: background 0.2s ease;
}

.stat:hover {
  background: rgba(255, 255, 255, 0.06);
}

.stat__value {
  display: block;
  font-size: 22px;
