:root {
  --il-bg: #fffbf0;
  --il-orange: #ffb347;
  --il-blue: #87ceeb;
  --il-mint: #98fb98;
  --il-plum: #dda0dd;
  --il-coral: #f08080;
  --il-text: #3d2b1f;
  --il-text-muted: #8b6f5e;
  --il-card-bg: #fff9ec;
  --il-blob: 40% 60% 55% 45% / 45% 50% 50% 55%;
  --il-blob-alt: 55% 45% 40% 60% / 50% 55% 45% 50%;
  --font-hand: "Caveat", cursive;
  --font-body: "Nunito", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background: var(--il-bg);
  color: var(--il-text);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ── Doodle decorations ── */
.deco {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.deco-item {
  position: absolute;
}

.deco-star1 {
  top: 5%;
  left: 4%;
  animation: wobble 4s ease-in-out infinite;
  animation-delay: 0s;
}

.deco-star2 {
  top: 12%;
  right: 8%;
  animation: wobble 5s ease-in-out infinite;
  animation-delay: 1s;
}

.deco-star3 {
  bottom: 20%;
  left: 10%;
  animation: wobble 3.5s ease-in-out infinite;
  animation-delay: 0.5s;
}

.deco-dots1 {
  top: 40%;
  right: 2%;
  animation: float 6s ease-in-out infinite;
}

.deco-dots2 {
  bottom: 10%;
  left: 2%;
  animation: float 7s ease-in-out infinite;
  animation-delay: 2s;
}

.deco-wave {
  bottom: 35%;
  right: 5%;
  animation: wobble 5s ease-in-out infinite;
  animation-delay: 1.5s;
}

@keyframes wobble {
  0%,
  100% {
    transform: rotate(-5deg) scale(1);
  }
  50% {
    transform: rotate(5deg) scale(1.05);
  }
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 780px;
  margin: 0 auto;
  padding: 52px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 48px;
}

/* ── Header ── */
.header {
  text-align: center;
}

.header__eyebrow {
  font-family: var(--font-hand);
  font-size: 20px;
  color: var(--il-orange);
  margin-bottom: 12px;
}

.header__title {
  font-family: var(--font-hand);
  font-size: clamp(52px, 9vw, 96px);
