  transform: rotate(2deg) scale(1.06);
  box-shadow: 6px 8px 0 rgba(61, 43, 31, 0.15);
}

.btn--ghost {
  background: transparent;
  color: var(--il-text-muted);
  border: 2px dashed var(--il-text-muted);
  border-radius: 50% 50% 48% 52% / 48% 52% 50% 50%;
  font-size: 16px;
}

.btn--ghost:hover {
