}

.badge:hover {
  transform: rotate(-3deg) scale(1.08);
}

.badge--orange {
  background: #ffe0b2;
  color: #bf360c;
}
.badge--blue {
  background: #b3e5fc;
  color: #01579b;
}
.badge--mint {
  background: #c8e6c9;
  color: #1b5e20;
}
.badge--plum {
  background: #e1bee7;
  color: #4a148c;
}

/* ── Confetti ── */
#confettiContainer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
}

.confetti-bit {
