  width: 10px;
  height: 10px;
  border-radius: 50%;
  animation: confettiBurst 0.7s ease-out forwards;
}

@keyframes confettiBurst {
  to {
    transform: translate(var(--tx), var(--ty)) scale(0);
    opacity: 0;
  }
}

