/**
 * ═══════════════════════════════════════════════════════════════
 *  Geographic Distribution Chart — Real Colombia SVG Map
 * ═══════════════════════════════════════════════════════════════
 *
 *  Uses a real Colombia departments SVG map (from MapSVG.com,
 *  Creative Commons). Departments are grouped into macro-regions
 *  and colored by value. Horizontal bars match each region.
 *
 *  HOW TO CHANGE COUNTRY:
 *  1. Replace COLOMBIA_SVG_URL with your country SVG path
 *  2. Update REGIONS and the department-to-region mapping
 *  3. Adjust viewBox if needed
 *
 * ═══════════════════════════════════════════════════════════════
 */

/**
 * Path to the SVG map. The SVG must have <path> elements with
 * `id` attributes matching department codes (e.g. CO-ANT).
 */
var COLOMBIA_SVG_URL = "/colombia.svg";

/**
 * Regions with display name and value.
 * Each region maps to one or more department IDs in the SVG.
 */
var REGIONS = [
  {
    region: "East",
    value: 95,
    depts: ["CO-SAN", "CO-NSA", "CO-ARA"],
  },
  {
    region: "Central",
    value: 88,
    depts: ["CO-CUN", "CO-DC", "CO-TOL", "CO-HUI"],
  },
  {
    region: "West",
    value: 76,
    depts: ["CO-CHO", "CO-VAC"],
  },
  {
    region: "Coffee Axis",
    value: 68,
    depts: ["CO-CAL", "CO-RIS", "CO-QUI"],
  },
  {
    region: "North",
    value: 60,
    depts: ["CO-ATL", "CO-BOL", "CO-CES", "CO-COR", "CO-GUJ", "CO-MAG", "CO-SUC", "CO-SAP"],
  },
  {
    region: "Antioquia",
    value: 52,
    depts: ["CO-ANT"],
  },
  {
    region: "Boyaca",
    value: 40,
    depts: ["CO-BOY", "CO-CAS"],
  },
  {
    region: "Bogota",
    value: 34,
    depts: ["CO-DC"],
  },
  {
    region: "South",
    value: 25,
    depts: ["CO-NAR", "CO-CAU", "CO-PUT", "CO-CAQ", "CO-AMA", "CO-GUV", "CO-GUA", "CO-VAU"],
  },
  {
    region: "Plains",
    value: 18,
    depts: ["CO-MET", "CO-VIC"],
  },
];

/* ── Color scale (dark → light blue) ──────────────── */

var BLUES = [
  "#1e3a5f",
  "#1e40af",
  "#1d4ed8",
  "#2563eb",
  "#3b82f6",
  "#60a5fa",
  "#93c5fd",
  "#bfdbfe",
];

function pickColor(value, max) {
  var ratio = 1 - value / max;
  var idx = Math.min(Math.floor(ratio * (BLUES.length - 1)), BLUES.length - 1);
  return BLUES[idx];
}

/* ── Build dept→color lookup ──────────────────────── */

var maxVal = Math.max.apply(
  null,
  REGIONS.map(function (r) {
    return r.value;
  })
);
var deptColorMap = {};

REGIONS.forEach(function (r) {
  var color = pickColor(r.value, maxVal);
  r.depts.forEach(function (id) {
    deptColorMap[id] = { color: color, region: r.region };
  });
});

/* ── Load and render SVG map ──────────────────────── */

var mapContainer = document.getElementById("geoMap");
var barsContainer = document.getElementById("geoBars");

var xhr = new XMLHttpRequest();
xhr.open("GET", COLOMBIA_SVG_URL, true);
xhr.onload = function () {
  if (xhr.status !== 200) return;

  // Parse SVG
  var parser = new DOMParser();
  var doc = parser.parseFromString(xhr.responseText, "image/svg+xml");
  var svg = doc.querySelector("svg");

  // Set viewBox from the original width/height so the SVG scales
  var origW = svg.getAttribute("width") || 612;
  var origH = svg.getAttribute("height") || 693;
  svg.setAttribute("viewBox", "0 0 " + origW + " " + origH);
  svg.removeAttribute("width");
  svg.removeAttribute("height");
  svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  svg.style.width = "100%";
  svg.style.height = "auto";

  // Hide San Andrés island — it's far off-screen and breaks the layout
  var sanAndres = svg.querySelector("#CO-SAP");
  if (sanAndres) sanAndres.style.display = "none";

  // Color each department path
  var paths = svg.querySelectorAll("path");
  paths.forEach(function (p) {
    if (p.style.display === "none") return;
    var id = p.getAttribute("id");
    var info = deptColorMap[id];
    if (info) {
      p.setAttribute("fill", info.color);
      p.dataset.region = info.region;
    } else {
      // Departments not in any region get a neutral light blue
      p.setAttribute("fill", "#dbeafe");
      p.dataset.region = "";
    }
    p.setAttribute("stroke", "#ffffff");
    p.setAttribute("stroke-width", "1");
    p.style.cursor = "pointer";
    p.style.transition = "opacity .2s, filter .2s";
  });

  mapContainer.appendChild(svg);

  // After map is in DOM, set up interactions
  setupTooltip(svg);
  setupHighlightSync(svg);
};
xhr.send();

/* ── Render bars ──────────────────────────────────── */

REGIONS.forEach(function (item, i) {
  var row = document.createElement("div");
  row.className = "bar-row";
  row.dataset.region = item.region;

  var name = document.createElement("div");
  name.className = "bar-name";
  name.textContent = item.region;

  var fill = document.createElement("div");
  fill.className = "bar-fill";
  fill.style.width = (item.value / maxVal) * 100 + "%";
  fill.style.background = pickColor(item.value, maxVal);

  row.appendChild(name);
  row.appendChild(fill);
  barsContainer.appendChild(row);

  setTimeout(function () {
    fill.classList.add("show");
  }, 80 * i);
});

/* ── Tooltip ──────────────────────────────────────── */

function setupTooltip(svg) {
  var tip = document.createElement("div");
  tip.className = "geo-tip";
  document.body.appendChild(tip);

  var paths = svg.querySelectorAll("path");
  paths.forEach(function (p) {
    p.addEventListener("mouseenter", function () {
      var title = p.getAttribute("title") || "";
      var region = p.dataset.region || "";
      tip.textContent = title + (region ? " — " + region : "");
      tip.classList.add("on");
    });
    p.addEventListener("mousemove", function (e) {
      tip.style.left = e.clientX + 14 + "px";
      tip.style.top = e.clientY - 30 + "px";
    });
    p.addEventListener("mouseleave", function () {
      tip.classList.remove("on");
    });
    p.addEventListener("mouseenter", function () {
      p.style.opacity = "0.8";
      p.style.filter = "brightness(1.15)";
    });
    p.addEventListener("mouseleave", function () {
      p.style.opacity = "";
      p.style.filter = "";
    });
  });
}

/* ── Highlight sync: bar ↔ map ────────────────────── */

function setupHighlightSync(svg) {
  var barRows = barsContainer.querySelectorAll(".bar-row");

  barRows.forEach(function (row) {
    var regionName = row.dataset.region;

    row.addEventListener("mouseenter", function () {
      // Highlight matching departments on map
      svg.querySelectorAll("path").forEach(function (p) {
        if (p.dataset.region === regionName) {
          p.style.filter = "brightness(1.3)";
          p.style.stroke = "#1a1a2e";
          p.style.strokeWidth = "2";
        }
      });
    });

    row.addEventListener("mouseleave", function () {
      svg.querySelectorAll("path").forEach(function (p) {
        if (p.dataset.region === regionName) {
          p.style.filter = "";
          p.style.stroke = "#ffffff";
          p.style.strokeWidth = "1";
        }
      });
    });
  });
}

snippets.css:
/* ============================================================
   VAPORWAVE — Style Showcase
   Fonts: Orbitron (headings), Space Mono (body)
   Palette: #FF71CE | #01CDFE | #05FFA1 | #B967FF | #FFFB96
   ============================================================ */

@import url("https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Space+Mono:ital,wght@0,400;0,700;1,400&display=swap");

/* --- Root variables --- */
:root {
  --pink: #ff71ce;
  --cyan: #01cdfe;
  --mint: #05ffa1;
  --purple: #b967ff;
  --yellow: #fffb96;
  --bg: #0d0015;
  --bg2: #1a0030;
  --card-bg: rgba(255, 113, 206, 0.06);
  --card-border: rgba(255, 113, 206, 0.35);
  --text: #f0d0ff;
  --muted: rgba(240, 208, 255, 0.5);
  --font-head: "Orbitron", sans-serif;
  --font-body: "Space Mono", monospace;
  --glow-pink: 0 0 10px #ff71ce, 0 0 20px rgba(255, 113, 206, 0.5);
  --glow-cyan: 0 0 10px #01cdfe, 0 0 20px rgba(1, 205, 254, 0.5);
  --glow-purple: 0 0 10px #b967ff, 0 0 20px rgba(185, 103, 255, 0.5);
  --glow-mint: 0 0 10px #05ffa1, 0 0 20px rgba(5, 255, 161, 0.5);
}

/* --- Reset & base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  background: linear-gradient(to bottom, var(--bg) 0%, var(--bg2) 100%);
  background-attachment: fixed;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.7;
  min-height: 100vh;
  overflow-x: hidden;
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: var(--bg);
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--pink), var(--purple));
  border-radius: 3px;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 0, 21, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--card-border);
  box-shadow: 0 1px 20px rgba(255, 113, 206, 0.15);
}

.header-inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-head);
  font-size: 16px;
  font-weight: 900;
  color: var(--pink);
  text-shadow: var(--glow-pink);
}

.logo-symbol {
  font-size: 18px;
  color: var(--purple);
  text-shadow: var(--glow-purple);
}

.logo-accent {
  color: var(--cyan);
}

.header-nav {
  display: flex;
  gap: 24px;
}

.nav-link {
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  text-decoration: none;
  letter-spacing: 0.1em;
  transition: color 0.2s, text-shadow 0.2s;
}

.nav-link:hover,
.nav-active {
  color: var(--cyan);
  text-shadow: var(--glow-cyan);
}

.header-time {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-head);
}

.time-label {
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.15em;
}

.time-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--yellow);
  letter-spacing: 0.2em;
  text-shadow: 0 0 8px var(--yellow);
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 60px 20px 0;
}

/* Vaporwave sun */
.vaporwave-sun {
  position: absolute;
  top: 40px;
  left: 50%;
  transform: translateX(-50%);
  width: 220px;
  height: 110px;
  overflow: hidden;
  z-index: 0;
}

.sun-inner {
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: linear-gradient(to bottom, #ff71ce 0%, #ff9cee 30%, #fffb96 60%, #ffd700 100%);
  box-shadow: 0 0 40px rgba(255, 113, 206, 0.6), 0 0 80px rgba(255, 113, 206, 0.3);
  position: relative;
}

/* Stripe cutouts over the sun */
.sun-stripes {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.stripe {
  height: 11px;
  background: var(--bg2);
}

.stripe:nth-child(1) {
  margin-top: 40px;
}
.stripe:nth-child(2) {
  height: 10px;
  margin-top: 4px;
}
.stripe:nth-child(3) {
  height: 8px;
  margin-top: 5px;
}
.stripe:nth-child(4) {
  height: 7px;
  margin-top: 6px;
}
.stripe:nth-child(5) {
  height: 5px;
  margin-top: 7px;
}

/* Hero content */
.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  margin-top: 130px;
  padding-bottom: 40px;
}

.hero-eyebrow {
  font-family: var(--font-head);
  font-size: 10px;
  letter-spacing: 0.5em;
  color: var(--cyan);
  text-shadow: var(--glow-cyan);
  margin-bottom: 12px;
}

.hero-title {
  font-family: var(--font-head);
  font-size: clamp(36px, 8vw, 72px);
  font-weight: 900;
  color: var(--pink);
  text-shadow: 0 0 10px var(--pink), 0 0 30px var(--pink), 0 0 60px rgba(255, 113, 206, 0.5), 4px 0
    0 var(--cyan);
  letter-spacing: 0.1em;
  line-height: 1;
  margin-bottom: 16px;
  transition: text-shadow 0.15s;
}

.hero-sub {
  font-family: var(--font-head);
  font-size: 11px;
  letter-spacing: 0.3em;
  color: var(--yellow);
  text-shadow: 0 0 8px var(--yellow);
}

/* Retro perspective grid */
.retro-grid {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 140px;
  z-index: 1;
  background: linear-gradient(to bottom, transparent 0%, rgba(185, 103, 255, 0.08) 100%),
    repeating-linear-gradient(
      90deg,
      rgba(185, 103, 255, 0.18) 0,
      rgba(185, 103, 255, 0.18) 1px,
      transparent 1px,
      transparent 60px
    ),
    repeating-linear-gradient(
      0deg,
      rgba(185, 103, 255, 0.18) 0,
      rgba(185, 103, 255, 0.18) 1px,
      transparent 1px,
      transparent 40px
    );
  transform: perspective(300px) rotateX(60deg);
  transform-origin: bottom center;
}

/* --- Main content --- */
.main-content {
  max-width: 960px;
  margin: 0 auto;
  padding: 48px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

/* --- Card --- */
.card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  box-shadow: 0 4px 30px rgba(255, 113, 206, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(8px);
  padding: 0 0 28px;
  position: relative;
  overflow: hidden;
}

.card-glow-bar {
  height: 3px;
  background: linear-gradient(90deg, var(--pink) 0%, var(--purple) 50%, var(--cyan) 100%);
  box-shadow: 0 0 12px var(--pink), 0 0 24px rgba(255, 113, 206, 0.4);
}

.card-glow-bar--cyan {
  background: linear-gradient(90deg, var(--cyan) 0%, var(--mint) 100%);
  box-shadow: 0 0 12px var(--cyan), 0 0 24px rgba(1, 205, 254, 0.4);
}

.card-glow-bar--mint {
  background: linear-gradient(90deg, var(--mint) 0%, var(--cyan) 100%);
  box-shadow: 0 0 12px var(--mint), 0 0 24px rgba(5, 255, 161, 0.4);
}

.card-section-label {
  padding: 16px 24px 12px;
  font-family: var(--font-head);
  font-size: 10px;
  letter-spacing: 0.25em;
  color: var(--pink);
  text-shadow: var(--glow-pink);
  border-bottom: 1px solid rgba(255, 113, 206, 0.15);
  margin-bottom: 20px;
}

.card-section-label--cyan {
  color: var(--cyan);
  text-shadow: var(--glow-cyan);
  border-bottom-color: rgba(1, 205, 254, 0.15);
}

.card-section-label--mint {
  color: var(--mint);
  text-shadow: var(--glow-mint);
  border-bottom-color: rgba(5, 255, 161, 0.15);
}

/* --- Profile card --- */
.profile-body {
  padding: 28px 28px 0;
  display: flex;
  gap: 28px;
  align-items: flex-start;
  flex-wrap: wrap;
}

.avatar-wrap {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--purple) 0%, var(--pink) 50%, var(--cyan) 100%);
  position: relative;
  box-shadow: 0 0 0 3px var(--bg2), 0 0 0 5px var(--pink), var(--glow-pink);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 35%, rgba(255, 255, 255, 0.15) 0%, transparent 70%),
    linear-gradient(180deg, rgba(185, 103, 255, 0.4) 0%, rgba(255, 113, 206, 0.4) 100%);
}

/* Silhouette using pure CSS */
.avatar::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 50px;
  height: 55px;
  background: rgba(13, 0, 21, 0.7);
  border-radius: 50% 50% 0 0 / 40% 40% 0 0;
  box-shadow: 0 -18px 0 16px rgba(13, 0, 21, 0.5);
}

.avatar-status {
  font-family: var(--font-head);
  font-size: 9px;
  color: var(--mint);
  text-shadow: var(--glow-mint);
  letter-spacing: 0.1em;
}

.profile-info {
  flex: 1;
  min-width: 200px;
}

.profile-badge {
  display: inline-block;
  font-family: var(--font-head);
  font-size: 9px;
  color: var(--yellow);
  background: rgba(255, 251, 150, 0.08);
  border: 1px solid rgba(255, 251, 150, 0.3);
  padding: 4px 10px;
  letter-spacing: 0.12em;
  margin-bottom: 12px;
  text-shadow: 0 0 8px var(--yellow);
}

.profile-name {
  font-family: var(--font-head);
  font-size: 22px;
  font-weight: 900;
  color: var(--pink);
  text-shadow: var(--glow-pink);
  letter-spacing: 0.25em;
  margin-bottom: 6px;
}

.profile-role {
  font-size: 13px;
  color: var(--cyan);
  text-shadow: var(--glow-cyan);
  margin-bottom: 10px;
}

.profile-tagline {
  font-size: 12px;
  font-style: italic;
  color: var(--muted);
  margin-bottom: 20px;
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: 0;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 20px 0 0;
}

.stat-item:first-child {
  padding-left: 0;
}

.stat-num {
  font-family: var(--font-head);
  font-size: 18px;
  font-weight: 700;
  color: var(--purple);
  text-shadow: var(--glow-purple);
}

.stat-lbl {
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.15em;
  margin-top: 2px;
}

.stat-divider {
  width: 1px;
  height: 36px;
  background: linear-gradient(to bottom, transparent, var(--card-border), transparent);
  margin: 0 20px 0 0;
  flex-shrink: 0;
}

/* --- Buttons --- */
.button-row {
  padding: 0 28px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.btn {
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  cursor: pointer;
  border: none;
  padding: 13px 28px;
  transition: transform 0.15s, box-shadow 0.15s, filter 0.15s;
  outline: none;
}

.btn:focus-visible {
  outline: 2px solid var(--yellow);
  outline-offset: 3px;
}

/* Primary */
.btn-primary {
  background: linear-gradient(90deg, var(--pink) 0%, var(--purple) 100%);
  color: #fff;
  box-shadow: 0 0 16px rgba(255, 113, 206, 0.5), 0 0 32px rgba(185, 103, 255, 0.2);
  border-radius: 3px;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 24px var(--pink), 0 0 48px rgba(255, 113, 206, 0.35);
  filter: brightness(1.1);
}

.btn-primary:active {
  transform: translateY(1px);
  filter: brightness(0.9);
}

/* Secondary */
.btn-secondary {
  background: rgba(1, 205, 254, 0.12);
  color: var(--cyan);
  border: 1px solid var(--cyan);
  box-shadow: 0 0 12px rgba(1, 205, 254, 0.25), inset 0 0 12px rgba(1, 205, 254, 0.05);
  text-shadow: var(--glow-cyan);
  border-radius: 3px;
}

.btn-secondary:hover {
  background: rgba(1, 205, 254, 0.2);
  transform: translateY(-2px);
  box-shadow: 0 0 20px var(--cyan), 0 0 40px rgba(1, 205, 254, 0.3);
}

.btn-secondary:active {
  transform: translateY(1px);
}

/* Ghost */
.btn-ghost {
  background: transparent;
  color: var(--pink);
  border: 1px solid rgba(255, 113, 206, 0.5);
  text-shadow: var(--glow-pink);
  box-shadow: 0 0 8px rgba(255, 113, 206, 0.15);
  border-radius: 3px;
}

.btn-ghost:hover {
  background: rgba(255, 113, 206, 0.08);
  border-color: var(--pink);
  transform: translateY(-2px);
  box-shadow: 0 0 16px rgba(255, 113, 206, 0.4);
}

.btn-ghost:active {
  transform: translateY(1px);
}

/* --- Input --- */
.input-group {
  padding: 0 28px;
}

.input-label {
  display: block;
  font-family: var(--font-head);
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--cyan);
  text-shadow: var(--glow-cyan);
  margin-bottom: 12px;
}

.vapor-input {
  font-family: var(--font-body);
  font-size: 14px;
  background: rgba(1, 205, 254, 0.04);
  color: var(--text);
  border: 1px solid rgba(255, 113, 206, 0.35);
  padding: 12px 18px;
  width: 100%;
  max-width: 440px;
  outline: none;
  border-radius: 3px;
  transition: border-color 0.2s, box-shadow 0.2s;
  caret-color: var(--pink);
}

.vapor-input::placeholder {
  color: var(--muted);
}

.vapor-input:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 0 2px rgba(1, 205, 254, 0.2), 0 0 16px rgba(1, 205, 254, 0.15), inset 0 0 20px
    rgba(1, 205, 254, 0.04);
}

.input-hint {
  margin-top: 8px;
  font-size: 11px;
  color: var(--muted);
  font-style: italic;
}

/* --- Badges --- */
.badge-row {
  padding: 0 28px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.badge {
  font-family: var(--font-head);
  font-size: 9px;
  font-weight: 700;
  padding: 6px 14px;
  letter-spacing: 0.1em;
  border-radius: 2px;
  transition: transform 0.15s, box-shadow 0.15s;
  cursor: default;
}

.badge:hover {
  transform: translateY(-2px);
}

.badge-pink {
  background: rgba(255, 113, 206, 0.12);
  color: var(--pink);
  border: 1px solid rgba(255, 113, 206, 0.4);
  text-shadow: var(--glow-pink);
  box-shadow: 0 0 8px rgba(255, 113, 206, 0.15);
}

.badge-cyan {
  background: rgba(1, 205, 254, 0.1);
  color: var(--cyan);
  border: 1px solid rgba(1, 205, 254, 0.35);
  text-shadow: var(--glow-cyan);
  box-shadow: 0 0 8px rgba(1, 205, 254, 0.15);
}

.badge-purple {
  background: rgba(185, 103, 255, 0.12);
  color: var(--purple);
  border: 1px solid rgba(185, 103, 255, 0.35);
  text-shadow: var(--glow-purple);
  box-shadow: 0 0 8px rgba(185, 103, 255, 0.15);
}

.badge-yellow {
  background: rgba(255, 251, 150, 0.08);
  color: var(--yellow);
  border: 1px solid rgba(255, 251, 150, 0.3);
  text-shadow: 0 0 8px var(--yellow);
}

.badge-mint {
  background: rgba(5, 255, 161, 0.08);
  color: var(--mint);
  border: 1px solid rgba(5, 255, 161, 0.3);
  text-shadow: var(--glow-mint);
}

/* --- Responsive --- */
@media (max-width: 640px) {
  .header-inner {
    flex-wrap: wrap;
  }
  .hero-title {
    font-size: 36px;
  }
  .profile-body {
    flex-direction: column;
  }
  .button-row {
    gap: 12px;
  }
  .btn {
    width: 100%;
    text-align: center;
    justify-content: center;
  }
}

