*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --nav-bg: #0d1117;
  --bar-bg: #3b82f6;
  --bar-text: #ffffff;
  --content-bg: #1a1f2e;
  --card-bg: #232a3a;
  --card-text: #c9d1d9;
  --card-label: #e6edf3;
  --tag-bg: rgba(59, 130, 246, 0.15);
  --tag-text: #60a5fa;
  --menu-bg: #ffffff;
  --menu-text: #1f2937;
  --menu-hover: #f3f4f6;
  --menu-danger: #ef4444;
  --menu-divider: #e5e7eb;
  --text: #f2f6ff;
  --muted: #475569;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
