/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  height: 520px;
  border-radius: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  background: var(--nav-bg);
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
  display: flex;
  flex-direction: column;
  position: relative;
}

/* ── App Bar ── */
.app-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--bar-bg);
  color: var(--bar-text);
  position: relative;
  z-index: 10;
}

.back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  background: rgba(255, 255, 255, 0.12);
  color: var(--bar-text);
  border-radius: 50%;
  cursor: pointer;
  transition: background 0.2s;
}

.back-btn:hover {
  background: rgba(255, 255, 255, 0.22);
}

.app-bar-title {
  flex: 1;
  font-size: 17px;
  font-weight: 600;
}

/* ── Dots Button & Wrapper ── */
.dots-wrapper {
  position: relative;
}

.dots-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  background: rgba(255, 255, 255, 0.12);
  color: var(--bar-text);
  border-radius: 50%;
  cursor: pointer;
  transition: background 0.2s;
}

.dots-btn:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* ── Dropdown Menu ── */
.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 170px;
  background: var(--menu-bg);
  border-radius: 8px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  padding: 6px 0;
  opacity: 0;
  transform: scale(0.9);
  transform-origin: top right;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 100;
}

.menu-open .dropdown-menu {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.menu-item {
  display: block;
  width: 100%;
  padding: 10px 16px;
  border: none;
  background: none;
  color: var(--menu-text);
  font-size: 14px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s;
}

.menu-item:hover {
  background: var(--menu-hover);
}
.menu-item--danger {
  color: var(--menu-danger);
}
.menu-divider {
  height: 1px;
  background: var(--menu-divider);
  margin: 4px 0;
}

/* ── Content Area ── */
.content-area {
  flex: 1;
  background: var(--content-bg);
  padding: 24px 20px;
  overflow-y: auto;
}

.card {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 20px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.card-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--bar-bg);
}

.card-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--card-label);
}

.card-text {
  font-size: 13px;
  line-height: 1.6;
  color: var(--card-text);
  margin-bottom: 16px;
}

.card-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.tag {
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 20px;
  background: var(--tag-bg);
  color: var(--tag-text);
}

