/* ─────────────────────────────────────────────
   Minimalist UI — style.css
   Palette: white, off-white, near-black, single
   accent blue. No shadows. No gradients.
───────────────────────────────────────────── */

:root {
  --bg: #ffffff;
  --bg-subtle: #fafafa;
  --border: #e5e5e5;
  --text-primary: #111111;
  --text-secondary: #555555;
  --text-tertiary: #999999;
  --accent: #0066ff;
  --accent-hover: #0052cc;
  --badge-bg: #f5f5f5;
  --badge-text: #555555;

  --font: "Inter", system-ui, sans-serif;
  --radius-sm: 4px;
  --radius-md: 8px;

  --space-xs: 8px;
  --space-sm: 16px;
  --space-md: 32px;
  --space-lg: 56px;
  --space-xl: 80px;
}

/* ── Reset ── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* ── Header ── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  max-width: 720px;
  margin: 0 auto;
  padding: var(--space-sm) var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.header-nav {
  display: flex;
  gap: var(--space-md);
}

.header-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.15s;
}

.header-nav a:hover {
  color: var(--text-primary);
}

/* ── Main layout ── */
.main {
  max-width: 720px;
  margin: 0 auto;
  padding: var(--space-xl) var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

/* ── Card ── */
.card {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-subtle);
  padding: var(--space-md);
}

/* ── Profile card ── */
.profile-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.profile-avatar {
  flex-shrink: 0;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar-initials {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--text-secondary);
}

.profile-name {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.03em;
  margin-bottom: 4px;
}

.profile-role {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: var(--space-sm);
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-value {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.stat-label {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-divider {
  width: 1px;
  height: 28px;
  background: var(--border);
}

/* ── Section ── */
.section {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.section-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font);
  font-size: 13px;
  font-weight: 500;
  padding: 10px 20px;
  border: none;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  border-radius: var(--radius-sm);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  border: 1px solid var(--accent);
}

.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--text-primary);
}

.btn-secondary:hover {
  background: var(--bg-subtle);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  border: 1px solid transparent;
}

.btn-ghost:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ── Input ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 360px;
}

.field-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  letter-spacing: 0.01em;
}

.field-input {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text-primary);
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border);
  padding: 8px 0;
  outline: none;
  width: 100%;
  transition: border-color 0.15s;
}

.field-input::placeholder {
  color: var(--text-tertiary);
}

.field-input:focus {
  border-bottom-color: var(--text-primary);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 500;
  border-radius: 2px;
  letter-spacing: 0.02em;
}

/* ── Responsive ── */
@media (max-width: 600px) {
  .header-inner {
    padding: var(--space-sm);
  }
  .main {
    padding: var(--space-lg) var(--space-sm);
    gap: var(--space-md);
  }
  .profile-card {
    flex-direction: column;
    align-items: flex-start;
  }
  .header-nav {
    gap: var(--space-sm);
  }
}

