* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: #0f172a;
  color: #e2e8f0;
  font-family: system-ui, sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
}

.demo {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  justify-content: center;
  padding: 2rem;
}

/* Skeleton shimmer */
.skeleton {
  background: #1e293b;
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}

.skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.06) 50%,
    transparent 100%
  );
  animation: shimmer 1.8s ease-in-out infinite;
}

@keyframes shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

/* Card skeleton */
.skeleton-card {
  width: 280px;
  background: #1a2332;
  border-radius: 14px;
  padding: 1rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.skeleton-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.skeleton-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  flex-shrink: 0;
}

.skeleton-avatar--sm {
  width: 32px;
  height: 32px;
}

.skeleton-meta {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.skeleton-line {
  height: 12px;
  border-radius: 6px;
}

.skeleton-line--sm {
  height: 9px;
}

.skeleton-image {
  width: 100%;
  height: 140px;
  border-radius: 10px;
  margin-bottom: 1rem;
}

.skeleton-body {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.skeleton-footer {
  display: flex;
  gap: 0.5rem;
}

.skeleton-btn {
  height: 32px;
  border-radius: 8px;
}

/* List skeleton */
.skeleton-list {
  width: 260px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.skeleton-list-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: #1a2332;
  border-radius: 12px;
  padding: 0.75rem 1rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.skeleton-list-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

@media (prefers-reduced-motion: reduce) {
  .skeleton::after {
    animation: none;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: #0f172a;
  color: #e2e8f0;
  font-family: system-ui, sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}

.open-btn {
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  color: #fff;
  background: #3b82f6;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.12s ease;
}

.open-btn:active {
  transform: scale(0.97);
}

.open-btn--right {
  background: #8b5cf6;
}

/* Backdrop */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: 100;
}

.drawer-backdrop.open {
  opacity: 1;
}

/* Drawer panel */
.drawer {
  position: fixed;
  top: 0;
  bottom: 0;
  width: min(320px, 85vw);
  background: #1e293b;
  z-index: 101;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s cubic-bezier(0.32, 0.72, 0, 1);
}

.drawer--left {
  left: 0;
  transform: translateX(-100%);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.drawer--right {
  right: 0;
  transform: translateX(100%);
  border-left: 1px solid rgba(255, 255, 255, 0.08);
}

.drawer-backdrop.open .drawer--left {
  transform: translateX(0);
}

.drawer-backdrop.open .drawer--right {
  transform: translateX(0);
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.drawer-header h3 {
  margin: 0;
  font-size: 1.1rem;
}

.drawer-close {
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 1.5rem;
  cursor: pointer;
  line-height: 1;
  padding: 0.25rem;
}

.drawer-close:hover {
  color: #fff;
}

.drawer-nav {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0;
}

.drawer-link {
  padding: 0.75rem 1.25rem;
