.glitch {
  font-size: clamp(80px, 18vw, 120px);
  font-weight: 900;
  color: #111;
  position: relative;
  letter-spacing: -4px;
}

.glitch::before,
.glitch::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.glitch::before {
  color: #6366f1;
  animation: glitch-1 2.5s infinite;
  clip-path: polygon(0 0, 100% 0, 100% 45%, 0 45%);
}

.glitch::after {
  color: #ef4444;
  animation: glitch-2 2.5s infinite;
  clip-path: polygon(0 55%, 100% 55%, 100% 100%, 0 100%);
}

@keyframes glitch-1 {
  0%,
  90%,
  100% {
    transform: translate(0);
    opacity: 0;
  }
  92% {
    transform: translate(-3px, 2px);
    opacity: 0.8;
  }
  94% {
    transform: translate(3px, -2px);
    opacity: 0.8;
  }
  96% {
    transform: translate(0);
    opacity: 0;
  }
}

@keyframes glitch-2 {
  0%,
