.chat-input-wrap:focus-within {
  border-color: #6366f1;
}

.chat-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  font-size: 14px;
  color: #111;
  resize: none;
  font-family: inherit;
  line-height: 1.5;
  max-height: 160px;
  overflow-y: auto;
}
.chat-input::placeholder {
  color: #9ca3af;
}

.send-btn {
  width: 34px;
  height: 34px;
  background: #6366f1;
  border: none;
  border-radius: 8px;
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: opacity 0.15s;
}
.send-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.send-btn:not(:disabled):hover {
  opacity: 0.85;
}

.chat-disclaimer {
  font-size: 11px;
  color: #9ca3af;
  text-align: center;
  margin-top: 8px;
}

