}

function streamText(bubble, text, callback) {
  // Convert newlines to <br> and **bold** to <strong>
  const lines = text.split("\n");
  let charIndex = 0;
  let allChars = text.split("");

  bubble.innerHTML = "";
  let p = document.createElement("p");
  bubble.appendChild(p);

  function tick() {
    if (charIndex >= allChars.length) {
      // Final format
      bubble.innerHTML = text
        .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
        .replace(/`([^`]+)`/g, "<code>$1</code>")
        .split("\n")
        .map((l) => (l ? `<p>${l}</p>` : "<br>"))
        .join("");
      callback?.();
      return;
    }
    const char = allChars[charIndex++];
    if (char === "\n") {
      p = document.createElement("p");
      bubble.appendChild(p);
    } else {
      p.textContent += char;
    }
    messages.scrollTop = messages.scrollHeight;
    setTimeout(tick, 12 + Math.random() * 6);
  }
  tick();
}

function send() {
  const text = input.value.trim();
  if (!text || streaming) return;

  addMessage("user", text);
  input.value = "";
  input.style.height = "auto";
  sendBtn.disabled = true;
  streaming = true;

  showTyping();

  setTimeout(
    () => {
      removeTyping();
      const response = RESPONSES[responseIndex % RESPONSES.length];
      responseIndex++;
      const bubble = addMessage("assistant", "");
      streamText(bubble, response, () => {
        streaming = false;
        sendBtn.disabled = false;
      });
    },
    900 + Math.random() * 400
  );
}

sendBtn.addEventListener("click", send);

input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) {
    e.preventDefault();
    send();
  }
});

// Auto-resize textarea
input.addEventListener("input", () => {
  input.style.height = "auto";
  input.style.height = Math.min(input.scrollHeight, 160) + "px";
});

