*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f9fafb;
  height: 100vh;
  display: flex;
}

.sl-layout {
  display: flex;
  width: 100%;
  height: 100%;
}

.sl-sidebar {
  width: 300px;
  flex-shrink: 0;
  background: #fff;
  border-right: 1px solid #e5e7eb;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.sl-search-wrap {
  padding: 16px;
  border-bottom: 1px solid #f3f4f6;
}

.sl-search {
  width: 100%;
  padding: 9px 12px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 13px;
  outline: none;
  color: #111;
  transition: border-color 0.15s;
}
.sl-search:focus {
  border-color: #6366f1;
}

.sl-filters {
  display: flex;
  gap: 6px;
  padding: 10px 16px;
  border-bottom: 1px solid #f3f4f6;
}

.sf-btn {
  background: #f3f4f6;
  border: none;
  color: #6b7280;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 12px;
  border-radius: 20px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.sf-btn.active {
  background: #6366f1;
  color: #fff;
}

.sl-list {
  flex: 1;
  overflow-y: auto;
}

.sl-item {
  padding: 14px 16px;
  border-bottom: 1px solid #f9fafb;
  cursor: pointer;
  transition: background 0.12s;
}
.sl-item:hover {
  background: #f9fafb;
}
.sl-item.active {
  background: #f0f4ff;
  border-left: 3px solid #6366f1;
}
.sl-item.hidden {
  display: none;
}

.sl-item-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}
.sl-item-name {
  font-size: 13px;
  font-weight: 700;
  color: #111827;
}
.sl-item-dist {
  font-size: 11px;
  font-weight: 700;
  color: #6366f1;
  flex-shrink: 0;
}
.sl-item-addr {
  font-size: 12px;
  color: #9ca3af;
  margin-bottom: 5px;
}

.sl-item-tags {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.sl-tag {
  font-size: 10px;
  font-weight: 600;
  background: #f3f4f6;
  color: #6b7280;
  padding: 2px 7px;
  border-radius: 4px;
}
.sl-tag--open {
  background: #dcfce7;
  color: #166534;
}
.sl-tag--flagship {
  background: #fef9c3;
  color: #92400e;
}

/* Map */
.sl-map {
  flex: 1;
  position: relative;
  background: #e0e7ff;
  overflow: hidden;
}

.map-bg {
  position: absolute;
  inset: 0;
  background-color: #dbeafe;
  background-image: radial-gradient(ellipse 120px 80px at 25% 35%, #93c5fd 0%, transparent 70%),
    radial-gradient(ellipse 90px 60px at 70% 65%, #93c5fd 0%, transparent 70%),
    radial-gradient(ellipse 60px 100px at 85% 20%, #bfdbfe 0%, transparent 60%),
    radial-gradient(ellipse 200px 150px at 50% 50%, #d1fae5 0%, transparent 60%),
    radial-gradient(ellipse 140px 100px at 20% 70%, #d1fae5 0%, transparent 60%),
    radial-gradient(ellipse 160px 110px at 80% 40%, #dcfce7 0%, transparent 60%),
    linear-gradient(rgba(0, 0, 0, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.04) 1px, transparent 1px),
    linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 100% 100%, 100% 100%, 100% 100%, 100% 100%, 80px 80px, 80px
    80px, 20px 20px, 20px 20px;
}

.map-pin-el {
  position: absolute;
  transform: translate(-50%, -100%);
  cursor: pointer;
  transition: transform 0.2s;
}
.map-pin-el:hover {
  transform: translate(-50%, -100%) scale(1.2);
}
.map-pin-el.active svg path {
  fill: #f59e0b;
}

.selected-popup {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: #fff;
  border-radius: 12px;
  padding: 14px 18px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
