  text-align: center;
  animation: pop-in 0.2s ease;
}
@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

.popup-name {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  margin-bottom: 2px;
}
.popup-addr {
  font-size: 12px;
  color: #9ca3af;
  margin-bottom: 8px;
}
.popup-link {
  font-size: 12px;
  color: #6366f1;
  text-decoration: none;
  font-weight: 600;
}

