    ]
      .filter(Boolean)
      .join("");
    div.innerHTML = `
      <div class="sl-item-header"><span class="sl-item-name">${s.name}</span><span class="sl-item-dist">${s.dist}</span></div>
      <p class="sl-item-addr">${s.addr}</p>
      <div class="sl-item-tags">${tags}</div>
    `;
