          children: [
            { name: "index.tsx", type: "file" },
            { name: "about.tsx", type: "file" },
            {
              name: "api",
              type: "folder",
              open: false,
              children: [
                { name: "auth.ts", type: "file" },
                { name: "users.ts", type: "file" },
              ],
            },
          ],
        },
        {
