.thinking-dots {
  display: flex;
  gap: 6px;
  align-items: center;
  height: 24px;
}
.thinking-dots span {
  width: 8px;
  height: 8px;
  background: #6366f1;
  border-radius: 50%;
  animation: bounce-dot 1.2s ease-in-out infinite;
}
.thinking-dots span:nth-child(2) {
  animation-delay: 0.2s;
}
.thinking-dots span:nth-child(3) {
  animation-delay: 0.4s;
}
@keyframes bounce-dot {
  0%,
  80%,
  100% {
    transform: scale(0.8) translateY(0);
    opacity: 0.5;
  }
  40% {
    transform: scale(1) translateY(-8px);
    opacity: 1;
  }
}

/* 2. Pulse ring */
.thinking-pulse {
  position: relative;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pulse-ring {
  position: absolute;
  inset: 0;
  border: 2px solid #6366f1;
  border-radius: 50%;
  animation: pulse-expand 2s ease-out infinite;
}
.pulse-ring--2 {
  animation-delay: 0.8s;
}
.pulse-core {
  width: 12px;
  height: 12px;
  background: #6366f1;
  border-radius: 50%;
}
@keyframes pulse-expand {
  0% {
    transform: scale(0.5);
    opacity: 1;
  }
  100% {
