.shimmer-line--full {
  width: 100%;
}
.shimmer-line--80 {
  width: 80%;
}
.shimmer-line--60 {
  width: 60%;
}
@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* 4. Wave bars */
.thinking-wave {
  display: flex;
  gap: 4px;
