body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0d1117;
  color: #e6edf3;
  min-height: 100vh;
  padding: 32px 16px;
  display: flex;
  justify-content: center;
}

.demo {
  width: 100%;
  max-width: 720px;
}

.doc-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.doc-card {
  display: flex;
  align-items: center;
  gap: 16px;
  background: #161b22;
  border: 1px solid #21262d;
  border-radius: 12px;
  padding: 14px 16px;
  transition: border-color 0.2s, transform 0.15s;
}
.doc-card:hover {
  border-color: #30363d;
  transform: translateX(2px);
}

/* Thumbnail */
.doc-thumb {
  width: 56px;
  height: 70px;
  border-radius: 8px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.doc-thumb--pdf {
  background: linear-gradient(160deg, #1e1e2e, #2d1b34);
  border: 1px solid rgba(248, 81, 73, 0.2);
}
.doc-thumb--doc {
  background: linear-gradient(160deg, #1a2035, #1a2e4a);
  border: 1px solid rgba(56, 139, 253, 0.2);
}
.doc-thumb--xls {
  background: linear-gradient(160deg, #0f2a1a, #1a3a2a);
  border: 1px solid rgba(63, 185, 80, 0.2);
}
.doc-thumb--ppt {
  background: linear-gradient(160deg, #2a1a10, #3a2010);
  border: 1px solid rgba(210, 153, 34, 0.2);
}

.doc-type-badge {
  position: absolute;
  bottom: 4px;
  right: 4px;
  font-size: 8px;
  font-weight: 800;
  padding: 1px 4px;
  border-radius: 3px;
  letter-spacing: 0.04em;
}
.doc-thumb--pdf .doc-type-badge {
  background: rgba(248, 81, 73, 0.2);
  color: #f85149;
}
.doc-thumb--doc .doc-type-badge {
  background: rgba(56, 139, 253, 0.2);
  color: #58a6ff;
}
.doc-thumb--xls .doc-type-badge {
  background: rgba(63, 185, 80, 0.2);
  color: #3fb950;
}
.doc-thumb--ppt .doc-type-badge {
  background: rgba(210, 153, 34, 0.2);
  color: #d29922;
}

/* Document lines */
.doc-page-lines {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 6px 14px;
  width: 100%;
}
.dpl {
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
}
.dpl--title {
  height: 6px;
  width: 70%;
  background: rgba(255, 255, 255, 0.2);
}
.dpl--80 {
  width: 80%;
}
.dpl--60 {
  width: 60%;
}
.dpl--90 {
  width: 90%;
}
.dpl--40 {
  width: 40%;
}
.dpl--70 {
  width: 70%;
}
.dpl--55 {
  width: 55%;
}
.dpl--75 {
  width: 75%;
}
.dpl--50 {
  width: 50%;
}
.dpl--85 {
  width: 85%;
}

/* Spreadsheet thumb */
.doc-spreadsheet {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px;
  width: 100%;
}
.ds-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
}
.ds-row span {
  height: 6px;
  border-radius: 1px;
  background: rgba(255, 255, 255, 0.08);
}
.ds-row--head span {
  background: rgba(63, 185, 80, 0.2);
}

/* Slide thumb */
.doc-slide {
  padding: 6px;
  width: 100%;
}
.ds-title {
  height: 7px;
  width: 80%;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
  margin-bottom: 5px;
}
.ds-subtitle {
  height: 5px;
  width: 60%;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 2px;
