}
.ds-body {
  height: 20px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
}

/* Info */
.doc-info {
  flex: 1;
  min-width: 0;
}
.doc-name {
  font-size: 14px;
  font-weight: 600;
  color: #e6edf3;
