  function toggle() {
    if (!liked) {
      setBurst(true);
      setTimeout(() => setBurst(false), 600);
    }
    setLiked((l) => !l);
    setCount((c) => (liked ? c - 1 : c + 1));
  }

  const PARTICLES = Array.from({ length: 6 }, (_, i) => ({
    angle: (i / 6) * 360,
    color: ["#ff6b6b", "#ff8e53", "#ff6b9d", "#c56cf0", "#ff9ff3", "#ffd32a"][i],
  }));

  return (
