      {/* Single like button */}
      <div className="relative flex flex-col items-center">
        <button
          onClick={toggle}
          aria-label={liked ? "Unlike" : "Like"}
          className="relative flex items-center gap-2.5 px-6 py-3 rounded-full border transition-all duration-200 select-none"
          style={{
