*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #16181f;
  --surface2: #1e2130;
  --border: #2a2d3a;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --accent: #818cf8;
  --accent-hover: #a5b4fc;
  --red: #f87171;
  --green: #34d399;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

/* ── Layout ── */
.auth-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 100vh;
}

/* Left */
.auth-left {
  background: linear-gradient(160deg, #161828 0%, #0f1117 60%, #1a1040 100%);
  border-right: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
  position: relative;
  overflow: hidden;
}

.auth-left-content {
  position: relative;
  z-index: 1;
  max-width: 380px;
}

.auth-logo-big {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--accent);
  text-decoration: none;
  display: block;
  margin-bottom: 48px;
}

.auth-quote {
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--text);
  font-style: italic;
  margin-bottom: 16px;
  quotes: "\201C" "\201D";
}

.auth-quote::before {
  content: open-quote;
}

.auth-quote::after {
  content: close-quote;
}

.auth-cite {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.auth-left-pattern {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
      circle at 20% 20%,
      rgba(129, 140, 248, 0.08) 0%,
      transparent 50%
    ), radial-gradient(circle at 80% 80%, rgba(168, 85, 247, 0.06) 0%, transparent 50%);
}

/* Right */
.auth-right {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
  background: var(--bg);
}

.auth-card {
  width: 100%;
  max-width: 400px;
}

.auth-header {
  margin-bottom: 28px;
}

.auth-title {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.auth-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* OAuth */
.oauth-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.oauth-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 10px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 9px;
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  transition: background .15s, border-color .15s;
}

.oauth-btn:hover {
  background: var(--surface2);
  border-color: #3a3d4a;
}

/* Divider */
.auth-divider {
  position: relative;
  text-align: center;
  margin: 20px 0;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  position: absolute;
  top: 50%;
  width: calc(50% - 18px);
  height: 1px;
  background: var(--border);
}

.auth-divider::before {
  left: 0;
}

.auth-divider::after {
  right: 0;
}

.auth-divider span {
  font-size: 0.75rem;
  color: var(--text-muted);
  background: var(--bg);
  padding: 0 8px;
}

/* Form */
.auth-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text);
}

.field-label-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.forgot-link {
  font-size: 0.78rem;
  color: var(--accent);
  text-decoration: none;
}

.forgot-link:hover {
  color: var(--accent-hover);
}

.field-input-wrap {
  position: relative;
}

.field-input {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 9px;
  color: var(--text);
  font-size: 0.875rem;
  padding: 10px 14px;
  outline: none;
  font-family: inherit;
  transition: border-color .15s;
}

.field-input::placeholder {
  color: var(--text-muted);
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(129, 140, 248, 0.1);
}

.field-input.invalid {
  border-color: var(--red);
}

.field-input-wrap .field-input {
  padding-right: 42px;
}

.pwd-toggle {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  padding: 4px;
  transition: color .15s;
}

.pwd-toggle:hover {
  color: var(--text);
}

.field-error {
  font-size: 0.78rem;
  color: var(--red);
  margin-top: 2px;
}

/* Remember */
.remember-row {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 0.82rem;
  color: var(--text-muted);
}

.remember-row input {
  accent-color: var(--accent);
  width: 14px;
  height: 14px;
}

.remember-text {
  user-select: none;
}

/* Submit */
.auth-submit {
  width: 100%;
  background: var(--accent);
  border: none;
  border-radius: 9px;
  color: #fff;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 11px;
  cursor: pointer;
  font-family: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: background .15s, opacity .15s;
  margin-top: 4px;
}

.auth-submit:hover {
  background: var(--accent-hover);
}

.auth-submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.btn-spinner svg {
  animation: spin .8s linear infinite;
}

/* Switch */
.auth-switch {
  margin-top: 20px;
  text-align: center;
  font-size: 0.82rem;
  color: var(--text-muted);
}

.auth-switch-link {
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
}

.auth-switch-link:hover {
  color: var(--accent-hover);
}

/* ── Responsive ── */
@media (max-width: 700px) {
  .auth-layout {
    grid-template-columns: 1fr;
  }

  .auth-left {
    display: none;
  }
}

