*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --sidebar-w: 260px;
  --sidebar-w-collapsed: 64px;
  --bg: #0f1117;
  --surface: #16181f;
  --surface2: #1e2130;
  --border: #2a2d3a;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --accent: #818cf8;
  --accent-bg: rgba(129, 140, 248, 0.12);
  --green: #34d399;
  --red: #f87171;
  --transition: 260ms cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  height: 100vh;
  overflow: hidden;
}

/* ── Overlay (mobile) ── */
.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  z-index: 40;
}
.overlay.visible {
  display: block;
}

/* ── Sidebar ── */
.sidebar {
  width: var(--sidebar-w);
  min-height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  transition: width var(--transition);
  overflow: hidden;
  position: relative;
  flex-shrink: 0;
  z-index: 50;
}

.sidebar.collapsed {
  width: var(--sidebar-w-collapsed);
}

/* Logo */
.s-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 16px 16px;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  white-space: nowrap;
}
.s-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent-bg);
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.s-logo-text {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text);
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-logo-text {
  opacity: 0;
  pointer-events: none;
}

/* Collapse button */
.s-collapse-btn {
  position: absolute;
  top: 20px;
  right: 10px;
  width: 24px;
  height: 24px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--surface2);
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background .2s, color .2s;
  z-index: 2;
}
.s-collapse-btn:hover {
  background: var(--accent-bg);
  color: var(--accent);
}
.sidebar.collapsed .s-collapse-btn svg {
  transform: rotate(180deg);
}
.s-collapse-btn svg {
  transition: transform var(--transition);
}

/* Nav */
.s-nav {
  flex: 1;
  padding: 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: hidden;
}

.s-section-label {
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--text-muted);
  padding: 8px 6px 4px;
  white-space: nowrap;
  overflow: hidden;
  transition: opacity var(--transition), height var(--transition);
}
.sidebar.collapsed .s-section-label {
  opacity: 0;
  height: 0;
  padding: 0;
}

.s-divider {
  height: 1px;
  background: var(--border);
  margin: 8px 0;
}

.s-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 8px;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  transition: background .15s, color .15s;
  position: relative;
}
.s-item:hover {
  background: var(--surface2);
  color: var(--text);
}
.s-item.active {
  background: var(--accent-bg);
  color: var(--accent);
}
.s-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  background: var(--accent);
  border-radius: 0 3px 3px 0;
}

.s-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
}
.s-label {
  flex: 1;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-label {
  opacity: 0;
}

.s-badge {
  font-size: 0.65rem;
  font-weight: 700;
  background: var(--accent);
  color: #fff;
  padding: 1px 6px;
  border-radius: 999px;
  line-height: 1.5;
  transition: opacity var(--transition);
}
.s-badge--dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  padding: 0;
}
.sidebar.collapsed .s-badge {
  opacity: 0;
}

/* Tooltip in collapsed mode */
.sidebar.collapsed .s-item::after {
  content: attr(data-tooltip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .15s;
  z-index: 100;
}
.sidebar.collapsed .s-item:hover::after {
  opacity: 1;
}

/* User */
.s-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 12px;
  border-top: 1px solid var(--border);
  overflow: hidden;
  cursor: pointer;
  white-space: nowrap;
  transition: background .15s;
}
.s-user:hover {
  background: var(--surface2);
}
.s-user-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.s-user-info {
  display: flex;
  flex-direction: column;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-user-info {
  opacity: 0;
}
.s-user-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text);
}
.s-user-role {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-top: 1px;
}

/* Tooltip for user */
.sidebar.collapsed .s-user::after {
  content: attr(data-tooltip);
  position: absolute;
  left: calc(100% + 12px);
  bottom: 12px;
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .15s;
  z-index: 100;
}
.sidebar.collapsed .s-user:hover::after {
  opacity: 1;
}

/* ── Main area ── */
.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Topbar */
.topbar {
  height: 60px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 12px;
}
.hamburger {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}
.hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--text-muted);
  border-radius: 2px;
  transition: background .15s;
}
.hamburger:hover span {
  background: var(--text);
}

.topbar-title {
  font-size: 1rem;
  font-weight: 600;
  flex: 1;
}
.topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.topbar-icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  position: relative;
  transition: background .15s, color .15s;
}
.topbar-icon-btn:hover {
  color: var(--text);
  background: var(--border);
}
.topbar-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 16px;
  height: 16px;
  background: var(--red);
  border-radius: 50%;
  font-size: 0.6rem;
  font-weight: 700;
  color: #fff;
  display: grid;
  place-items: center;
}
.topbar-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
}

/* Content */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 28px 24px;
}
.content-title {
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 4px;
}
.content-subtitle {
  color: var(--text-muted);
  margin-bottom: 28px;
  font-size: 0.875rem;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  transition: border-color .2s;
}
.stat-card:hover {
  border-color: var(--accent);
}
.stat-label {
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  font-weight: 500;
}
.stat-value {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 4px;
}
.stat-delta {
  font-size: 0.78rem;
  font-weight: 600;
}
.stat-delta.up {
  color: var(--green);
}
.stat-delta.down {
  color: var(--red);
}

/* ── Mobile ── */
@media (max-width: 768px) {
  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    transform: translateX(-100%);
    transition: transform var(--transition), width var(--transition);
    width: var(--sidebar-w) !important;
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
  .s-collapse-btn {
    display: none;
  }
  .hamburger {
    display: flex;
  }
}

