                  <line
                    x1={PAD.left}
                    x2={PAD.left + cW}
                    y1={y}
                    y2={y}
                    stroke="#21262d"
                    strokeWidth={1}
                  />
                  <text x={PAD.left - 6} y={y + 3.5} textAnchor="end" fill="#484f58" fontSize={10}>
                    {v}
                  </text>
                </g>
              );
            })}
            {/* Regression line */}
            <line
              x1={xOf(0)}
              y1={yOf(ry1)}
              x2={xOf(maxX)}
              y2={yOf(ry2)}
              stroke="#484f58"
              strokeWidth={1.5}
              strokeDasharray="6 3"
            />
            {/* Dots */}
            {GROUPS.map(
              (g, gi) =>
