import { type FormEvent, useRef, useState } from "react";

type Task = {
  id: number;
  label: string;
  pending: boolean;
};

type NoticeTone = "idle" | "info" | "ok" | "error";

const fakeRequest = () =>
  new Promise<void>((resolve, reject) => {
    const delay = 280 + Math.random() * 720;
    setTimeout(() => {
      if (Math.random() < 0.28) {
        reject(new Error("Request failed"));
      } else {
        resolve();
      }
    }, delay);
  });

export default function OptimisticUiPattern() {
  const [tasks, setTasks] = useState<Task[]>([
    { id: 1, label: "Ship release notes", pending: false },
    { id: 2, label: "Clean API logs", pending: false },
  ]);
  const [value, setValue] = useState("");
  const [notice, setNotice] = useState<{ message: string; tone: NoticeTone }>({
    message: "Use optimistic updates to keep interactions instant.",
    tone: "info",
  });

  const nextIdRef = useRef(3);
  const nextTempIdRef = useRef(-1);

  const onAdd = async (event: FormEvent) => {
    event.preventDefault();
    const label = value.trim();
    if (!label) {
      setNotice({ message: "Enter a task name before adding.", tone: "error" });
      return;
    }

    const tempId = nextTempIdRef.current;
    nextTempIdRef.current -= 1;

    setValue("");
    setTasks((prev) => [{ id: tempId, label, pending: true }, ...prev]);
    setNotice({ message: "Task added optimistically. Syncing with server...", tone: "info" });

    try {
      await fakeRequest();
      const confirmedId = nextIdRef.current;
      nextIdRef.current += 1;

      setTasks((prev) =>
        prev.map((task) =>
          task.id === tempId ? { ...task, id: confirmedId, pending: false } : task
        )
      );
      setNotice({ message: "Task confirmed by server.", tone: "ok" });
    } catch {
      setTasks((prev) => prev.filter((task) => task.id !== tempId));
      setNotice({ message: "Add failed. Optimistic task was rolled back.", tone: "error" });
    }
  };

  const onDelete = async (id: number) => {
    let removed: Task | null = null;
    let removedIndex = -1;

    setTasks((prev) => {
      removedIndex = prev.findIndex((task) => task.id === id);
      if (removedIndex === -1) return prev;
      removed = prev[removedIndex];
      return prev.filter((task) => task.id !== id);
    });

    if (!removed) return;
    const rollbackTask = removed;
    const rollbackIndex = removedIndex;

    setNotice({ message: "Task removed optimistically. Syncing with server...", tone: "info" });

    try {
      await fakeRequest();
      setNotice({ message: "Deletion confirmed by server.", tone: "ok" });
    } catch {
      setTasks((prev) => {
        if (prev.some((task) => task.id === rollbackTask.id)) return prev;
        const next = prev.slice();
        const safeIndex = Math.min(Math.max(rollbackIndex, 0), next.length);
        next.splice(safeIndex, 0, rollbackTask);
        return next;
      });
      setNotice({ message: "Delete failed. Item restored.", tone: "error" });
    }
  };

  const noticeClass =
    notice.tone === "ok"
      ? "text-emerald-300"
      : notice.tone === "error"
        ? "text-rose-300"
        : "text-sky-300";

  return (
    <section className="min-h-screen bg-[#0d1117] px-4 py-6 text-[#e6edf3]">
      <div className="mx-auto max-w-2xl space-y-4">
        <header className="rounded-2xl border border-[#30363d] bg-[#161b22] p-4">
          <p className="text-xs font-bold uppercase tracking-wide text-[#8b949e]">Pattern</p>
          <h1 className="mt-1 text-lg font-bold">Optimistic UI</h1>
          <p className="mt-1 text-sm text-[#8b949e]">
            UI updates immediately and rolls back only if the request fails.
          </p>
        </header>

        <form
          onSubmit={onAdd}
          className="flex gap-2 rounded-2xl border border-[#30363d] bg-[#161b22] p-3"
        >
          <input
            value={value}
            onChange={(event) => setValue(event.target.value)}
            placeholder="Add task"
            className="flex-1 rounded-lg border border-[#30363d] bg-[#0d1117] px-3 py-2 text-sm text-[#e6edf3] placeholder-[#6b7280] outline-none transition-colors focus:border-[#58a6ff]"
          />
          <button
            type="submit"
            className="rounded-lg border border-[#58a6ff]/45 bg-[#58a6ff]/15 px-4 py-2 text-sm font-semibold text-[#c9e6ff] transition-colors hover:bg-[#58a6ff]/25"
          >
            Add
          </button>
        </form>

        <p className={`min-h-5 text-xs ${noticeClass}`}>{notice.message}</p>

        <ul className="grid gap-2">
          {tasks.map((task) => (
            <li
              key={task.id}
              className="flex items-center justify-between gap-3 rounded-xl border border-[#30363d] bg-[#161b22] px-3 py-2.5"
            >
              <div className="flex items-center gap-2 text-sm">
                <span className={task.pending ? "text-[#cdd9e5]" : "text-[#e6edf3]"}>
                  {task.label}
                </span>
                {task.pending && (
                  <span className="rounded-full border border-sky-300/30 bg-sky-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-sky-200">
                    syncing
                  </span>
                )}
              </div>
              <button
                type="button"
                disabled={task.pending}
                onClick={() => onDelete(task.id)}
                className="rounded-md border border-rose-500/35 bg-rose-500/10 px-2.5 py-1 text-xs font-semibold text-rose-300 transition-colors enabled:hover:bg-rose-500/20 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Delete
              </button>
            </li>
          ))}
          {tasks.length === 0 && (
            <li className="rounded-xl border border-dashed border-[#30363d] bg-[#161b22] px-3 py-5 text-center text-sm text-[#8b949e]">
              No tasks left. Add one to test optimistic create.
            </li>
          )}
        </ul>
      </div>
    </section>
  );
}

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #16181f;
  --surface2: #1e2130;
  --border: #2a2d3a;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --accent: #818cf8;
  --green: #34d399;
  --red: #f87171;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
}

.page {
  text-align: center;
}

.page h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.page p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* -- Widget container -- */
.chat-widget {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}

/* Launcher */
.chat-launcher {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--accent);
  border: none;
  cursor: pointer;
  display: grid;
  place-items: center;
  position: relative;
  box-shadow: 0 6px 24px rgba(129, 140, 248, 0.4);
  transition: transform .2s, box-shadow .2s;
}

.chat-launcher:hover {
  transform: scale(1.08);
  box-shadow: 0 8px 30px rgba(129, 140, 248, 0.55);
}

.launcher-icon {
  color: #fff;
  display: grid;
  place-items: center;
}

.launcher-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 18px;
  height: 18px;
  background: var(--red);
  border-radius: 50%;
  font-size: 0.62rem;
  font-weight: 700;
  color: #fff;
  display: grid;
  place-items: center;
  border: 2px solid var(--bg);
}

/* Window */
.chat-window {
  width: 340px;
  max-width: calc(100vw - 48px);
  height: 480px;
  max-height: calc(100vh - 120px);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: winIn .2s ease;
}

@keyframes winIn {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(10px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

/* Header */
.chat-header {
  padding: 14px 16px;
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.agent-wrap {
  position: relative;
  flex-shrink: 0;
}

.agent-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  font-weight: 700;
  color: #fff;
}

.status-dot {
  position: absolute;
  bottom: 1px;
  right: 1px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
  border: 2px solid var(--surface2);
}

.agent-info {
  flex: 1;
  min-width: 0;
}

.agent-name {
  font-size: 0.875rem;
  font-weight: 700;
}

.agent-status {
  font-size: 0.7rem;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chat-min-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  padding: 4px;
  border-radius: 6px;
  transition: color .15s;
  flex-shrink: 0;
}

.chat-min-btn:hover {
  color: var(--text);
}

/* Messages */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}

.chat-messages::-webkit-scrollbar {
  width: 4px;
}

.chat-messages::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

.msg {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  max-width: 85%;
  animation: msgIn .2s ease;
}

@keyframes msgIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.msg--bot {
  align-self: flex-start;
}

.msg--user {
  align-self: flex-end;
  flex-direction: row-reverse;
}

.msg-av {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.6rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.msg-bubble {
  padding: 9px 13px;
  border-radius: 14px;
  font-size: 0.82rem;
  line-height: 1.5;
  word-wrap: break-word;
  overflow-wrap: break-word;
  min-width: 0;
}

.msg--bot .msg-bubble {
  background: var(--surface2);
  border-bottom-left-radius: 4px;
  color: var(--text);
}

.msg--user .msg-bubble {
  background: var(--accent);
  color: #fff;
  border-bottom-right-radius: 4px;
}

.msg-time {
  font-size: 0.65rem;
  color: var(--text-muted);
  margin-top: 4px;
  display: block;
}

/* Typing indicator */
.typing-indicator {
  display: flex;
  gap: 4px;
  align-items: center;
  padding: 10px 14px;
  background: var(--surface2);
  border-radius: 14px;
  border-bottom-left-radius: 4px;
  width: fit-content;
}

.typing-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-muted);
  animation: typingBounce 1.2s infinite;
}

.typing-dot:nth-child(2) {
  animation-delay: .2s;
}

.typing-dot:nth-child(3) {
  animation-delay: .4s;
}

@keyframes typingBounce {
  0%,
  80%,
  100% {
    transform: none;
    opacity: 0.4;
  }

  40% {
    transform: translateY(-5px);
    opacity: 1;
  }
}

/* Emoji picker */
.emoji-picker {
  padding: 8px;
  border-top: 1px solid var(--border);
  background: var(--surface2);
  flex-shrink: 0;
}

.emoji-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
}

.emoji-btn {
  background: none;
  border: none;
  font-size: 1.1rem;
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
  transition: background .1s;
  line-height: 1;
}

.emoji-btn:hover {
  background: rgba(255, 255, 255, 0.08);
}

/* Input bar */
.chat-input-bar {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  padding: 10px 12px;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

.emoji-toggle {
  background: none;
  border: none;
  font-size: 1.2rem;
  cursor: pointer;
  padding: 4px;
  flex-shrink: 0;
}

.chat-textarea {
  flex: 1;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text);
  font-size: 0.82rem;
  padding: 8px 12px;
  outline: none;
  font-family: inherit;
  resize: none;
  max-height: 100px;
  overflow-y: auto;
  transition: border-color .15s;
  line-height: 1.4;
  min-width: 0;
}

.chat-textarea:focus {
  border-color: var(--accent);
}

.chat-textarea::placeholder {
  color: var(--text-muted);
}

.send-btn {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: var(--accent);
  border: none;
  color: #fff;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background .15s;
  flex-shrink: 0;
}

.send-btn:hover {
  background: #a5b4fc;
}

/* Responsive: small screens */
@media (max-width: 480px) {
  .chat-widget {
    bottom: 8px;
    right: 8px;
  }

  .chat-window {
    width: calc(100vw - 16px);
    max-width: calc(100vw - 16px);
    max-height: calc(100vh - 80px);
    border-radius: 12px;
  }

  .chat-header {
    padding: 10px 12px;
  }

  .chat-messages {
    padding: 12px;
    gap: 10px;
  }

  .chat-input-bar {
    padding: 8px 10px;
  }

  .emoji-grid {
    grid-template-columns: repeat(8, 1fr);
  }

  .chat-launcher {
    width: 48px;
    height: 48px;
  }
}

