*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --footer-bg: #0a0c12;
  --surface: #16181f;
  --border: #1e2130;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --text-dim: #475569;
