*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* ── Demo label ── */
.drp-demo {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: flex-start;
}
.drp-demo-label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #94a3b8;
  margin-bottom: 0.25rem;
}

/* ── Trigger ── */
.drp-trigger-wrap {
  position: relative;
}

.drp-trigger {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.6875rem 1rem;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.75rem;
  color: #e2e8f0;
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  min-width: 280px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.drp-trigger:hover {
  border-color: rgba(56, 189, 248, 0.3);
}
.drp-trigger[aria-expanded="true"] {
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.1);
}

.drp-trigger-icon {
  color: #64748b;
  flex-shrink: 0;
}
.drp-chevron {
  color: #64748b;
  margin-left: auto;
  flex-shrink: 0;
  transition: transform 0.2s;
}
.drp-trigger[aria-expanded="true"] .drp-chevron {
  transform: rotate(180deg);
}

/* ── Dropdown ── */
.drp-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: #141e2e;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 1rem;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);
  z-index: 100;
  opacity: 0;
  transform: translateY(-6px) scale(0.98);
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  min-width: 560px;
}
.drp-dropdown.open {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: all;
}

.drp-dropdown-inner {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: inherit;
}

/* ── Calendars row ── */
.drp-calendars {
  display: flex;
  padding: 1.25rem 1.5rem;
  gap: 1rem;
}

.drp-cal-divider {
  width: 1px;
  background: rgba(255, 255, 255, 0.06);
  margin: 0;
  align-self: stretch;
}

/* ── Single calendar ── */
.drp-cal {
  flex: 1;
  min-width: 220px;
}

.drp-cal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.drp-cal-title {
  font-size: 0.9375rem;
  font-weight: 700;
  color: #f1f5f9;
}

.drp-nav-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.375rem;
  color: #94a3b8;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
