.drp-cal-dow span {
  text-align: center;
  font-size: 0.6875rem;
  font-weight: 600;
  color: #64748b;
  padding: 0.25rem 0;
  text-transform: uppercase;
}

/* ── Calendar grid ── */
.drp-cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
}

.drp-day {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 34px;
