}

/* ── Footer ── */
.drp-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  gap: 1rem;
