  font-variant-numeric: tabular-nums;
}

.drp-footer-actions {
  display: flex;
  gap: 0.5rem;
}

.btn-primary {
  padding: 0.5rem 1rem;
  background: #38bdf8;
  border: none;
  border-radius: 0.5rem;
