*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  padding: 1.5rem;
}

/* ── Wrapper ── */
.scheduler-wrapper {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Header ── */
.scheduler-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.scheduler-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f1f5f9;
  margin-right: auto;
}

.week-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.week-nav-btn {
  width: 2rem;
  height: 2rem;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  color: #94a3b8;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.week-nav-btn:hover {
  background: rgba(255, 255, 255, 0.09);
  color: #e2e8f0;
}

.week-label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #e2e8f0;
  min-width: 190px;
  text-align: center;
}

/* ── Legend ── */
.legend {
  display: flex;
  gap: 0.625rem;
  flex-wrap: wrap;
}

.legend-item {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: 999px;
}

.legend-morning {
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
}
.legend-afternoon {
  background: rgba(251, 146, 60, 0.15);
  color: #fb923c;
}
.legend-night {
  background: rgba(167, 139, 250, 0.15);
  color: #a78bfa;
}
.legend-dayoff {
  background: rgba(100, 116, 139, 0.15);
  color: #94a3b8;
}

/* ── Grid scroll ── */
.grid-scroll {
  overflow-x: auto;
  border-radius: 1rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

/* ── Table ── */
.shift-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
}

/* ── Header row ── */
.shift-table thead tr {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.shift-table th,
.shift-table td {
  text-align: center;
  padding: 0.75rem 0.5rem;
  font-size: 0.8125rem;
  vertical-align: middle;
}

.col-employee {
  text-align: left !important;
  width: 140px;
  min-width: 130px;
  padding-left: 1rem !important;
  font-weight: 600;
  color: #64748b;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.col-total {
  width: 72px;
  min-width: 60px;
  color: #64748b;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.day-header {
  color: #94a3b8;
  font-weight: 600;
  white-space: nowrap;
}

.day-header .day-name {
  display: block;
  font-size: 0.6875rem;
  color: #64748b;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.day-header .day-date {
  display: block;
  font-size: 0.875rem;
  color: #e2e8f0;
  font-weight: 700;
}

.day-header.today .day-date {
  color: #38bdf8;
}

/* ── Body rows ── */
.shift-table tbody tr {
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  transition: background 0.12s ease;
}

.shift-table tbody tr:last-child {
  border-bottom: none;
}

.shift-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.02);
}

/* ── Employee cell ── */
.employee-cell {
  text-align: left !important;
  padding-left: 1rem !important;
}

.employee-info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.employee-avatar {
  width: 1.875rem;
  height: 1.875rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.6875rem;
  font-weight: 700;
  flex-shrink: 0;
}

.employee-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: #e2e8f0;
  white-space: nowrap;
}

/* ── Shift cells ── */
.shift-cell {
  cursor: pointer;
  position: relative;
}

.shift-cell:hover .add-btn {
  opacity: 1;
}

/* ── Shift pill ── */
.shift-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.3rem 0.6rem;
  border-radius: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: filter 0.12s ease, transform 0.12s ease;
  user-select: none;
}

.shift-pill:hover {
  filter: brightness(1.15);
  transform: scale(1.04);
}

.shift-pill.morning {
  background: rgba(56, 189, 248, 0.18);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.3);
}
.shift-pill.afternoon {
  background: rgba(251, 146, 60, 0.18);
  color: #fb923c;
  border: 1px solid rgba(251, 146, 60, 0.3);
}
.shift-pill.night {
  background: rgba(167, 139, 250, 0.18);
  color: #a78bfa;
  border: 1px solid rgba(167, 139, 250, 0.3);
}
.shift-pill.dayoff {
  background: rgba(100, 116, 139, 0.12);
  color: #94a3b8;
  border: 1px solid rgba(100, 116, 139, 0.2);
}

/* ── Add button ── */
.add-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 0.4rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px dashed rgba(255, 255, 255, 0.15);
  color: #475569;
  font-size: 1rem;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease;
  line-height: 1;
}

.shift-cell:hover .add-btn {
  opacity: 1;
}

.add-btn:hover {
  background: rgba(56, 189, 248, 0.1);
  border-color: rgba(56, 189, 248, 0.3);
  color: #38bdf8;
}

/* ── Total column ── */
.total-cell {
  font-size: 0.8125rem;
  font-weight: 700;
  color: #94a3b8;
}

/* ── Footer ── */
.shift-table tfoot {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.shift-table tfoot td {
  font-size: 0.75rem;
  color: #64748b;
  font-weight: 600;
}

.foot-label {
  text-align: left !important;
  padding-left: 1rem !important;
  color: #475569;
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.foot-total {
  color: #475569;
}

.foot-day-count {
  color: #64748b;
  font-weight: 700;
}

/* ── Popover ── */
.cell-popover {
  position: fixed;
  z-index: 200;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0.875rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  min-width: 180px;
  overflow: hidden;
}

.cell-popover[hidden] {
  display: none;
}

.popover-body {
  display: flex;
  flex-direction: column;
}

.shift-type-list {
  display: flex;
  flex-direction: column;
}

.shift-type-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  background: none;
  border: none;
  color: #e2e8f0;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s ease;
  font-family: inherit;
}

.shift-type-btn:hover {
  background: rgba(255, 255, 255, 0.05);
}

.shift-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.shift-type-btn.morning .shift-dot {
  background: #38bdf8;
}
.shift-type-btn.afternoon .shift-dot {
  background: #fb923c;
}
.shift-type-btn.night .shift-dot {
  background: #a78bfa;
}
.shift-type-btn.dayoff .shift-dot {
  background: #64748b;
}

.shift-sub {
  margin-left: auto;
  font-size: 0.6875rem;
  color: #475569;
  font-weight: 400;
}

.popover-divider {
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  margin: 0;
}

.popover-delete-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  background: none;
  border: none;
  color: #f87171;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  width: 100%;
  text-align: left;
  transition: background 0.12s ease;
  font-family: inherit;
}

.popover-delete-btn:hover {
  background: rgba(248, 113, 113, 0.08);
}

.popover-delete-btn[hidden] {
  display: none;
}

@media (max-width: 600px) {
  body {
    padding: 1rem;
  }
  .scheduler-header {
    gap: 0.75rem;
  }
  .scheduler-title {
    font-size: 1.0625rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shift-pill,
  .add-btn,
  .week-nav-btn {
    transition: none;
  }
}

