  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

// ── Config ────────────────────────────────────────────────────────────
const HEADLINE = "Ready to level up?";
const SUBTEXT = "Join 10,000+ developers already inside.";
const BUTTON_LABEL = "Get Started Free";
const BRAND_COLOR = "#6366f1";
const BG_COLOR = "#0a0a0f";

// ── Headline ──────────────────────────────────────────────────────────
const Headline: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const translateX = spring({
    frame,
    fps,
    from: -60,
    to: 0,
    config: { damping: 16, stiffness: 120 },
  });
  const opacity = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        opacity,
        transform: `translateX(${translateX}px)`,
        fontFamily: "system-ui, -apple-system, sans-serif",
        fontWeight: 800,
        fontSize: 64,
        color: "#ffffff",
        letterSpacing: -2,
        lineHeight: 1.1,
        textAlign: "center",
      }}
    >
      {HEADLINE}
    </div>
  );
};

// ── Subtext ───────────────────────────────────────────────────────────
const Subtext: React.FC<{ frame: number }> = ({ frame }) => {
  const delayed = Math.max(0, frame - 15);
  const opacity = interpolate(delayed, [0, 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        opacity,
        fontFamily: "system-ui, -apple-system, sans-serif",
        fontWeight: 400,
        fontSize: 24,
        color: "rgba(255,255,255,0.55)",
        textAlign: "center",
        marginTop: 16,
      }}
    >
      {SUBTEXT}
    </div>
  );
};

// ── CTA button with shimmer ───────────────────────────────────────────
const CTAButton: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const delayed = Math.max(0, frame - 30);

  const scale = spring({
    frame: delayed,
    fps,
    from: 0,
    to: 1,
    config: { damping: 11, stiffness: 180, mass: 0.6 },
  });

  // Shimmer sweep after button appears
  const shimmerX = interpolate((frame - 60) % 60, [0, 60], [-200, 420], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const showShimmer = frame > 60;

  return (
    <div
      style={{
        marginTop: 40,
        transform: `scale(${scale})`,
        position: "relative",
        overflow: "hidden",
        borderRadius: 50,
      }}
    >
      <div
        style={{
          backgroundColor: BRAND_COLOR,
          borderRadius: 50,
          padding: "20px 52px",
          display: "flex",
          alignItems: "center",
          gap: 12,
          position: "relative",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontWeight: 700,
            fontSize: 22,
            color: "#ffffff",
            letterSpacing: 0.3,
          }}
        >
          {BUTTON_LABEL}
        </div>

        {/* Arrow */}
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontSize: 22,
            color: "#ffffff",
          }}
        >
          →
        </div>

        {/* Shimmer overlay */}
        {showShimmer && (
          <div
            style={{
              position: "absolute",
              top: 0,
              left: shimmerX,
              width: 80,
              height: "100%",
              background:
                "linear-gradient(90deg, transparent, rgba(255,255,255,0.25), transparent)",
              transform: "skewX(-15deg)",
              pointerEvents: "none",
            }}
          />
        )}
      </div>
    </div>
  );
};

// ── Bouncing arrow indicator ──────────────────────────────────────────
const BouncingArrow: React.FC<{ frame: number }> = ({ frame }) => {
  const delayed = Math.max(0, frame - 45);
  const opacity = interpolate(delayed, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const bounce = delayed > 15 ? Math.sin(((frame - 60) / 18) * Math.PI) * 8 : 0;

  return (
    <div
      style={{
        marginTop: 32,
        opacity,
        transform: `translateX(${bounce}px)`,
        fontFamily: "system-ui, -apple-system, sans-serif",
        fontSize: 32,
        color: "rgba(255,255,255,0.4)",
      }}
    >
      ›
    </div>
  );
};

// ── Main composition ──────────────────────────────────────────────────
export const CTAAnimation: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const globalOpacity = interpolate(frame, [100, 120], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: BG_COLOR,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        opacity: globalOpacity,
      }}
    >
      {/* Background radial glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 700,
          height: 700,
          borderRadius: "50%",
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(circle, ${BRAND_COLOR}20 0%, transparent 70%)`,
        }}
      />

      <Headline frame={frame} fps={fps} />
      <Subtext frame={frame} />
      <CTAButton frame={frame} fps={fps} />
      <BouncingArrow frame={frame} />
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="CTAAnimation"
    component={CTAAnimation}
    durationInFrames={120}
    fps={30}
    width={1280}
    height={720}
  />
);

import React from "react";
import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

// ── Config ────────────────────────────────────────────────────────────
const HANDLE = "@youraccount";
const HEADLINE_WORDS = ["Big", "News.", "Coming", "Soon!"];
const SUBTITLE = "Stay tuned for our big announcement this week.";
const CTA_TEXT = "Swipe Up to Learn More";
const BG_TOP = "#667eea";
const BG_BOTTOM = "#764ba2";
const DURATION = 450; // 15 s × 30 fps

// ── Progress bar ──────────────────────────────────────────────────────
const ProgressBar: React.FC<{ frame: number }> = ({ frame }) => {
  const progress = interpolate(frame, [0, DURATION], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        height: 3,
        backgroundColor: "rgba(255,255,255,0.3)",
      }}
    >
      <div
        style={{
          width: `${progress * 100}%`,
          height: "100%",
          backgroundColor: "#ffffff",
        }}
      />
    </div>
  );
};

// ── Account handle ────────────────────────────────────────────────────
const AccountHandle: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const opacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        top: 28,
        left: 24,
        display: "flex",
        alignItems: "center",
        gap: 10,
        opacity,
      }}
    >
      {/* Avatar circle */}
      <div
        style={{
          width: 40,
          height: 40,
          borderRadius: "50%",
          backgroundColor: "rgba(255,255,255,0.25)",
          border: "2px solid rgba(255,255,255,0.7)",
        }}
      />
      <div
        style={{
          fontFamily: "system-ui, -apple-system, sans-serif",
          fontWeight: 600,
          fontSize: 16,
          color: "#ffffff",
        }}
      >
        {HANDLE}
      </div>
    </div>
  );
};

// ── Stagger headline ──────────────────────────────────────────────────
const HeadlineWords: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  return (
    <div
      style={{
        position: "absolute",
        top: "38%",
        left: 0,
        right: 0,
        paddingLeft: 40,
        paddingRight: 40,
        display: "flex",
        flexWrap: "wrap",
        gap: 12,
      }}
    >
      {HEADLINE_WORDS.map((word, i) => {
        const delay = 20 + i * 14;
        const f = Math.max(0, frame - delay);
        const opacity = interpolate(f, [0, 15], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const translateY = spring({
          frame: f,
          fps,
          from: 24,
          to: 0,
          config: { damping: 14, stiffness: 100 },
        });

        return (
          <div
            key={i}
            style={{
              opacity,
              transform: `translateY(${translateY}px)`,
              fontFamily: "system-ui, -apple-system, sans-serif",
              fontWeight: 800,
              fontSize: 64,
              color: "#ffffff",
              lineHeight: 1.1,
            }}
          >
            {word}
          </div>
        );
      })}
    </div>
  );
};

// ── Subtitle ──────────────────────────────────────────────────────────
const SubtitleText: React.FC<{ frame: number }> = ({ frame }) => {
  const delayed = Math.max(0, frame - 80);
  const opacity = interpolate(delayed, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        top: "62%",
        left: 40,
        right: 40,
        opacity,
        fontFamily: "system-ui, -apple-system, sans-serif",
        fontWeight: 400,
        fontSize: 24,
        color: "rgba(255,255,255,0.75)",
        lineHeight: 1.5,
      }}
    >
      {SUBTITLE}
    </div>
  );
};

// ── CTA ───────────────────────────────────────────────────────────────
const CTAButton: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const delayed = Math.max(0, frame - 120);
  const translateY = spring({
    frame: delayed,
    fps,
    from: 40,
    to: 0,
    config: { damping: 14, stiffness: 80 },
  });
  const opacity = interpolate(delayed, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        bottom: 80,
        left: "50%",
        transform: `translateX(-50%) translateY(${translateY}px)`,
        opacity,
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255,255,255,0.22)",
          backdropFilter: "blur(8px)",
          border: "2px solid rgba(255,255,255,0.5)",
          borderRadius: 50,
          padding: "18px 40px",
          fontFamily: "system-ui, -apple-system, sans-serif",
          fontWeight: 700,
          fontSize: 18,
          color: "#ffffff",
          whiteSpace: "nowrap",
        }}
      >
        ↑ {CTA_TEXT}
      </div>
    </div>
  );
};

// ── Main composition ──────────────────────────────────────────────────
export const InstagramStory: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
    <AbsoluteFill
      style={{
        background: `linear-gradient(160deg, ${BG_TOP} 0%, ${BG_BOTTOM} 100%)`,
      }}
    >
      <ProgressBar frame={frame} />
      <AccountHandle frame={frame} fps={fps} />
      <HeadlineWords frame={frame} fps={fps} />
      <SubtitleText frame={frame} />
      <CTAButton frame={frame} fps={fps} />
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="InstagramStory"
    component={InstagramStory}
    durationInFrames={450}
    fps={30}
    width={1080}
    height={1920}
  />
);

import React from "react";
import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// ── Props ─────────────────────────────────────────────────────────────
interface SumbnailProps {
  title?: string;
  tag?: string;
  bg1?: string;
  bg2?: string;
  accentColor?: string;
}

const defaultProps: Required<SumbnailProps> = {
  title: "Build in Public",
  tag: "Tutorial",
  bg1: "#0f0c29",
  bg2: "#302b63",
  accentColor: "#f59e0b",
};

// ── Tag badge ─────────────────────────────────────────────────────────
const TagBadge: React.FC<{ tag: string; accentColor: string; frame: number; fps: number }> = ({
  tag,
  accentColor,
  frame,
  fps,
}) => {
  const scale = spring({ frame, fps, from: 0, to: 1, config: { damping: 12, stiffness: 200 } });

  return (
    <div
      style={{
        position: "absolute",
        top: 40,
        left: 48,
        transform: `scale(${scale})`,
        transformOrigin: "left top",
      }}
    >
      <div
        style={{
          backgroundColor: accentColor,
          borderRadius: 6,
          padding: "8px 20px",
          fontFamily: "system-ui, -apple-system, sans-serif",
          fontWeight: 700,
          fontSize: 18,
          color: "#000000",
          textTransform: "uppercase",
          letterSpacing: 2,
        }}
      >
        {tag}
      </div>
    </div>
  );
};

// ── Title text ────────────────────────────────────────────────────────
const TitleText: React.FC<{ title: string; frame: number; fps: number }> = ({
  title,
  frame,
  fps,
}) => {
  const words = title.split(" ");

  return (
    <div
      style={{
        position: "absolute",
        bottom: 160,
        left: 48,
        right: 320,
        display: "flex",
        flexWrap: "wrap",
        gap: "0 12px",
      }}
    >
      {words.map((word, i) => {
        const delay = 5 + i * 6;
        const f = Math.max(0, frame - delay);
        const opacity = interpolate(f, [0, 12], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const translateY = spring({
          frame: f,
          fps,
          from: 20,
          to: 0,
          config: { damping: 14, stiffness: 120 },
        });

        return (
          <span
            key={i}
            style={{
              opacity,
              transform: `translateY(${translateY}px)`,
              fontFamily: "system-ui, -apple-system, sans-serif",
              fontWeight: 900,
              fontSize: 88,
              color: "#ffffff",
              lineHeight: 1,
              letterSpacing: -3,
            }}
          >
            {word}
          </span>
        );
      })}
    </div>
  );
};

// ── Image/face placeholder ────────────────────────────────────────────
const ImageSlot: React.FC<{ frame: number; fps: number; accentColor: string }> = ({
  frame,
  fps,
  accentColor,
}) => {
  const delayed = Math.max(0, frame - 8);
  const translateX = spring({
    frame: delayed,
    fps,
    from: 80,
    to: 0,
    config: { damping: 14, stiffness: 100 },
  });
  const opacity = interpolate(delayed, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        right: 48,
        bottom: 0,
        width: 280,
        height: 520,
        opacity,
        transform: `translateX(${translateX}px)`,
      }}
    >
      {/* Placeholder silhouette */}
      <div
        style={{
          width: "100%",
          height: "100%",
          background: `linear-gradient(180deg, ${accentColor}40 0%, ${accentColor}10 100%)`,
          borderRadius: "140px 140px 0 0",
          border: `2px solid ${accentColor}40`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontSize: 14,
            color: "rgba(255,255,255,0.25)",
            textAlign: "center",
            letterSpacing: 1,
            textTransform: "uppercase",
          }}
        >
          Face / Image
          <br />
          Slot
        </div>
      </div>
    </div>
  );
};

// ── Accent line ───────────────────────────────────────────────────────
const AccentLine: React.FC<{ frame: number; accentColor: string }> = ({ frame, accentColor }) => {
  const scaleX = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        bottom: 140,
        left: 48,
        width: 160,
        height: 5,
        backgroundColor: accentColor,
        borderRadius: 3,
        transformOrigin: "left center",
        transform: `scaleX(${scaleX})`,
      }}
    />
  );
};

// ── Main composition ──────────────────────────────────────────────────
export const Sumbnail: React.FC<SumbnailProps> = (inputProps) => {
  const props = { ...defaultProps, ...inputProps };
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
    <AbsoluteFill
      style={{
        background: `linear-gradient(135deg, ${props.bg1} 0%, ${props.bg2} 100%)`,
        overflow: "hidden",
      }}
    >
      {/* Diagonal noise overlay */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(255,255,255,0.02) 2px, rgba(255,255,255,0.02) 4px)",
        }}
      />

      <TagBadge tag={props.tag} accentColor={props.accentColor} frame={frame} fps={fps} />
      <AccentLine frame={frame} accentColor={props.accentColor} />
      <TitleText title={props.title} frame={frame} fps={fps} />
      <ImageSlot frame={frame} fps={fps} accentColor={props.accentColor} />
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="Sumbnail"
    component={Sumbnail}
    durationInFrames={150}
    fps={30}
    width={1280}
    height={720}
    defaultProps={defaultProps}
  />
);

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem;
}

/* ── Container ── */
.tor-container {
  width: min(520px, 100%);
  display: flex;
  flex-direction: column;
  gap: 0;
  background: #141e33;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 1.25rem;
  overflow: hidden;
}

/* ── Header ── */
.tor-header {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 1.375rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.tor-header__icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 0.625rem;
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
  display: grid;
  place-items: center;
}

.tor-header__title {
  font-size: 1rem;
  font-weight: 700;
  color: #f1f5f9;
  line-height: 1.2;
}

.tor-header__subtitle {
  font-size: 0.8rem;
  color: #64748b;
  margin-top: 0.15rem;
}

/* ── Form ── */
.tor-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.375rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

/* ── Field ── */
.tor-field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.tor-label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #94a3b8;
}

.tor-label__optional {
  font-weight: 400;
  color: #475569;
}

/* ── Inputs ── */
.tor-input,
.tor-select,
.tor-textarea {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 0.625rem;
  color: #f1f5f9;
  font-size: 0.875rem;
  font-family: inherit;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
  width: 100%;
}

.tor-input,
.tor-select {
  padding: 0.6rem 0.875rem;
  height: 40px;
}

.tor-textarea {
  padding: 0.65rem 0.875rem;
  resize: vertical;
  min-height: 72px;
  line-height: 1.55;
}

.tor-input:focus,
.tor-select:focus,
.tor-textarea:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.12);
}

.tor-input::placeholder,
.tor-textarea::placeholder {
  color: #334155;
}

/* ── Custom select ── */
.tor-select-wrap {
  position: relative;
}

.tor-select {
  appearance: none;
  cursor: pointer;
  padding-right: 2.25rem;
}

.tor-select option {
  background: #1e2d45;
  color: #f1f5f9;
}

.tor-select-arrow {
  position: absolute;
  right: 0.875rem;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  color: #475569;
}

/* ── Date row ── */
.tor-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

/* ── Days display ── */
.tor-days-display {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  color: #475569;
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 0.5rem;
  padding: 0.5rem 0.875rem;
  transition: color 0.2s ease;
}

.tor-days-display.has-days {
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.18);
  background: rgba(56, 189, 248, 0.06);
}

/* ── Error ── */
.tor-error {
  font-size: 0.8rem;
  color: #f87171;
  background: rgba(248, 113, 113, 0.08);
  border: 1px solid rgba(248, 113, 113, 0.18);
  border-radius: 0.5rem;
  padding: 0.5rem 0.875rem;
}

/* ── Submit button ── */
.tor-submit {
  width: 100%;
  padding: 0.65rem 1rem;
  background: #38bdf8;
  color: #0c1a2e;
  font-size: 0.9rem;
  font-weight: 700;
  font-family: inherit;
  border: none;
  border-radius: 0.625rem;
  cursor: pointer;
  transition: background 0.18s ease, box-shadow 0.18s ease, transform 0.12s ease;
}

