*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem;
}

/* ── Page layout ── */
.page-center {
  width: min(560px, 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
}

.page-hint {
  font-size: 0.8125rem;
  color: #475569;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

/* ── Container ── */
.search-container {
  width: 100%;
  position: relative;
}

/* ── Input row ── */
.search-input-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.875rem;
  padding: 0.875rem 1rem;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
  cursor: text;
}

.search-container.open .search-input-row {
  border-color: rgba(56, 189, 248, 0.4);
  background: rgba(56, 189, 248, 0.04);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.1);
  border-radius: 0.875rem 0.875rem 0 0;
  border-bottom-color: transparent;
}

.search-icon {
  color: #475569;
  flex-shrink: 0;
  transition: color 0.15s ease;
}

.search-container.open .search-icon {
  color: #38bdf8;
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  color: #f1f5f9;
  font-size: 1rem;
  font-family: inherit;
  caret-color: #38bdf8;
}

.search-input::placeholder {
  color: #475569;
}

.shortcut-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.45rem;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.3rem;
  font-size: 0.75rem;
  font-family: inherit;
  color: #64748b;
  white-space: nowrap;
  flex-shrink: 0;
}

.shortcut-inline {
  font-size: 0.6875rem;
}

/* ── Dropdown ── */
.search-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: #1e293b;
  border: 1px solid rgba(56, 189, 248, 0.35);
  border-top: none;
  border-radius: 0 0 0.875rem 0.875rem;
  overflow: hidden;
  z-index: 50;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  animation: dropdownIn 0.15s ease;
}

.search-dropdown[hidden] {
  display: none;
}

@keyframes dropdownIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Sections ── */
.result-section {
  padding: 0.5rem 0;
}

.result-section + .result-section {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.section-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #475569;
  padding: 0.5rem 1rem 0.375rem;
}

/* ── Result items ── */
.result-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 1rem;
  cursor: pointer;
  transition: background 0.1s ease;
  outline: none;
}

.result-item:hover,
.result-item.active {
  background: rgba(56, 189, 248, 0.08);
}

.result-item.active .result-title {
  color: #f1f5f9;
}

.result-icon {
  width: 2rem;
  height: 2rem;
  border-radius: 0.5rem;
  background: rgba(255, 255, 255, 0.06);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: #64748b;
}

.result-item.active .result-icon,
.result-item:hover .result-icon {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}

.result-body {
  flex: 1;
  min-width: 0;
}

.result-title {
  font-size: 0.9rem;
  font-weight: 500;
  color: #e2e8f0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.result-title mark {
  background: rgba(56, 189, 248, 0.25);
  color: #7dd3fc;
  border-radius: 0.2em;
  padding: 0 0.1em;
}

.result-category {
  font-size: 0.75rem;
  color: #475569;
  margin-top: 0.1rem;
}

.result-shortcut {
  font-size: 0.6875rem;
  color: #475569;
  display: flex;
  gap: 0.2rem;
  flex-shrink: 0;
}

.result-shortcut kbd {
  padding: 0.15rem 0.4rem;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.25rem;
  font-family: inherit;
}

/* ── Empty state ── */
.empty-state {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 1.5rem 1rem;
  color: #475569;
  font-size: 0.9rem;
}

.empty-state[hidden] {
  display: none;
}

/* ── Footer ── */
.dropdown-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(0, 0, 0, 0.15);
}

.dropdown-footer #footerHint {
  font-size: 0.75rem;
  color: #475569;
}

.result-count-badge {
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 0.2rem 0.55rem;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 999px;
  color: #64748b;
}

.no-recent {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  color: #475569;
}

.no-recent[hidden] {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .search-dropdown {
    animation: none;
  }
  .result-item {
    transition: none;
  }
}

