(function () {
  "use strict";

  // ── Data ──
  const SUGGESTED = [
    {
      id: "dash",
      title: "Dashboard Overview",
      category: "Page",
      icon: "page",
      shortcut: ["⌘", "D"],
    },
    { id: "team", title: "Team Members", category: "User", icon: "user", shortcut: null },
    { id: "api", title: "API Documentation", category: "Document", icon: "doc", shortcut: null },
    {
      id: "revenue",
      title: "Revenue Reports",
      category: "Chart",
      icon: "chart",
      shortcut: ["⌘", "R"],
    },
    {
      id: "settings",
      title: "Account Settings",
      category: "Settings",
      icon: "settings",
      shortcut: null,
    },
    { id: "inbox", title: "Inbox", category: "Page", icon: "page", shortcut: null },
    { id: "projects", title: "Projects", category: "Page", icon: "page", shortcut: null },
    {
      id: "billing",
      title: "Billing & Plans",
      category: "Settings",
      icon: "settings",
      shortcut: null,
    },
  ];

  const ICONS = {
    page: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>`,
    user: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>`,
    doc: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 4h16v16H4z"/><line x1="8" y1="9" x2="16" y2="9"/><line x1="8" y1="13" x2="16" y2="13"/><line x1="8" y1="17" x2="12" y2="17"/></svg>`,
    chart: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>`,
    settings: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>`,
    clock: `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>`,
  };

  const RECENT_KEY = "search-autocomplete-recent";
  const MAX_RECENT = 5;

  // ── DOM refs ──
  const container = document.getElementById("searchContainer");
  const input = document.getElementById("searchInput");
  const dropdown = document.getElementById("searchDropdown");
  const recentSection = document.getElementById("recentSection");
  const recentList = document.getElementById("recentList");
  const noRecent = document.getElementById("noRecent");
  const suggestedSection = document.getElementById("suggestedSection");
  const suggestedList = document.getElementById("suggestedList");
  const emptyState = document.getElementById("emptyState");
  const emptyQuery = document.getElementById("emptyQuery");
  const footerHint = document.getElementById("footerHint");
  const resultCountBadge = document.getElementById("resultCountBadge");

  if (!input) return;

  let isOpen = false;
  let activeIndex = -1;
  let currentItems = []; // flat list of rendered item elements

  // ── Recent searches ──
  function getRecent() {
    try {
      return JSON.parse(localStorage.getItem(RECENT_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function addRecent(title) {
    let list = getRecent().filter((t) => t !== title);
    list.unshift(title);
    list = list.slice(0, MAX_RECENT);
    try {
      localStorage.setItem(RECENT_KEY, JSON.stringify(list));
    } catch {}
  }

  // ── Fuzzy filter ──
  function fuzzyMatch(str, query) {
    const s = str.toLowerCase();
    const q = query.toLowerCase();
    return s.includes(q);
  }

  function highlight(title, query) {
    if (!query) return title;
    const idx = title.toLowerCase().indexOf(query.toLowerCase());
    if (idx === -1) return title;
    return (
      escapeHtml(title.slice(0, idx)) +
      `<mark>${escapeHtml(title.slice(idx, idx + query.length))}</mark>` +
      escapeHtml(title.slice(idx + query.length))
    );
  }

  function escapeHtml(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // ── Render ──
  function renderDropdown(query) {
    currentItems = [];
    activeIndex = -1;

    const recent = getRecent();
    const filtered = SUGGESTED.filter((item) => !query || fuzzyMatch(item.title, query));

    const showEmpty = query.length > 0 && filtered.length === 0;
    const showRecent = query.length === 0;
    const showSuggested = filtered.length > 0;

    // Recent section
    recentSection.hidden = !showRecent;
    if (showRecent) {
      if (recent.length === 0) {
        noRecent.hidden = false;
        recentList.innerHTML = "";
      } else {
        noRecent.hidden = true;
        recentList.innerHTML = recent
          .map(
            (title, i) => `
          <div class="result-item" data-type="recent" data-value="${escapeHtml(title)}" tabindex="-1" role="option">
            <div class="result-icon">${ICONS.clock}</div>
            <div class="result-body">
              <div class="result-title">${escapeHtml(title)}</div>
              <div class="result-category">Recent</div>
            </div>
          </div>
        `
          )
          .join("");
      }
    }

    // Suggested section
    suggestedSection.hidden = !showSuggested;
    if (showSuggested) {
      suggestedList.innerHTML = filtered
        .map((item) => {
          const shortcutHtml = item.shortcut
            ? `<div class="result-shortcut">${item.shortcut.map((k) => `<kbd>${k}</kbd>`).join("")}</div>`
            : "";
          return `
          <div class="result-item" data-type="suggested" data-value="${escapeHtml(item.title)}" data-id="${item.id}" tabindex="-1" role="option">
            <div class="result-icon">${ICONS[item.icon] || ICONS.page}</div>
            <div class="result-body">
              <div class="result-title">${highlight(item.title, query)}</div>
              <div class="result-category">${escapeHtml(item.category)}</div>
            </div>
            ${shortcutHtml}
          </div>
        `;
        })
        .join("");
    }

    // Empty state
    emptyState.hidden = !showEmpty;
    if (showEmpty) emptyQuery.textContent = query;

    // Footer
    const totalVisible = (showRecent ? recent.length : 0) + (showSuggested ? filtered.length : 0);
    resultCountBadge.textContent = `${totalVisible} result${totalVisible !== 1 ? "s" : ""}`;
    footerHint.textContent = query
      ? `Press Enter to search all results for "${query}"`
      : "Press Enter to search all";

    // Build flat item list for keyboard nav
    currentItems = Array.from(dropdown.querySelectorAll(".result-item"));
  }

  // ── Open / close ──
  function openDropdown() {
    if (isOpen) return;
    isOpen = true;
    container.classList.add("open");
    input.setAttribute("aria-expanded", "true");
    dropdown.hidden = false;
    renderDropdown(input.value);
  }

  function closeDropdown() {
    if (!isOpen) return;
    isOpen = false;
    container.classList.remove("open");
    input.setAttribute("aria-expanded", "false");
    dropdown.hidden = true;
    setActive(-1);
  }

  function setActive(index) {
    currentItems.forEach((el) => el.classList.remove("active"));
    activeIndex = index;
    if (index >= 0 && index < currentItems.length) {
      currentItems[index].classList.add("active");
      currentItems[index].scrollIntoView({ block: "nearest" });
    }
  }

  function selectItem(el) {
    const value = el.dataset.value;
    if (!value) return;
    addRecent(value);
    input.value = value;
    closeDropdown();
    input.select();
  }

  // ── Event listeners ──
  input.addEventListener("focus", openDropdown);
  input.addEventListener("input", () => {
    openDropdown();
    renderDropdown(input.value);
  });

  input.addEventListener("keydown", (e) => {
    if (!isOpen) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        openDropdown();
      }
      return;
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setActive(Math.min(activeIndex + 1, currentItems.length - 1));
        break;
      case "ArrowUp":
        e.preventDefault();
        setActive(Math.max(activeIndex - 1, -1));
        if (activeIndex === -1) input.focus();
        break;
      case "Enter":
        e.preventDefault();
        if (activeIndex >= 0 && currentItems[activeIndex]) {
          selectItem(currentItems[activeIndex]);
        } else if (input.value.trim()) {
          addRecent(input.value.trim());
          closeDropdown();
        }
        break;
      case "Escape":
        e.preventDefault();
        closeDropdown();
        break;
    }
  });

  dropdown.addEventListener("mousedown", (e) => {
    const item = e.target.closest(".result-item");
    if (item) {
      e.preventDefault();
      selectItem(item);
    }
  });

  dropdown.addEventListener("mousemove", (e) => {
    const item = e.target.closest(".result-item");
    if (item) setActive(currentItems.indexOf(item));
  });

  document.addEventListener("mousedown", (e) => {
    if (!container.contains(e.target)) closeDropdown();
  });

  // ── Global shortcut ⌘K / Ctrl+K ──
  document.addEventListener("keydown", (e) => {
    const isMac = navigator.platform.toUpperCase().includes("MAC");
    const trigger = isMac ? e.metaKey : e.ctrlKey;
    if (trigger && e.key === "k") {
      e.preventDefault();
      input.focus();
      input.select();
      openDropdown();
    }
  });
})();

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  padding: 1.5rem;
}

/* ── Layout ── */
.app-wrapper {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
}

/* ── Sidebar ── */
.filter-sidebar {
  width: 280px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1rem;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  position: sticky;
  top: 1.5rem;
}

.filter-sidebar.hidden {
  display: none;
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.sidebar-title-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.sidebar-title {
  font-size: 1rem;
  font-weight: 700;
  color: #f1f5f9;
}

.filter-count-badge {
  background: #38bdf8;
  color: #0f172a;
  font-size: 0.6875rem;
  font-weight: 700;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.3rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  line-height: 1;
  transition: opacity 0.15s ease;
}

.filter-count-badge[data-count="0"] {
  opacity: 0;
}

.clear-all-btn {
  font-size: 0.8125rem;
  color: #64748b;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  border-radius: 0.375rem;
  transition: color 0.15s ease, background 0.15s ease;
}

.clear-all-btn:hover {
  color: #f87171;
  background: rgba(248, 113, 113, 0.08);
}

/* ── Filter groups ── */
.filter-group {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.filter-group:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.filter-group-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.filter-input {
  width: 100%;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  color: #e2e8f0;
  font-size: 0.875rem;
  padding: 0.5rem 0.75rem;
  font-family: inherit;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.filter-input:focus {
  outline: none;
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(56, 189, 248, 0.05);
}

.filter-input::placeholder {
  color: #475569;
}

input[type="date"].filter-input::-webkit-calendar-picker-indicator {
  filter: invert(0.6);
  cursor: pointer;
}

.search-input-wrapper {
  position: relative;
}

.search-icon {
  position: absolute;
  left: 0.625rem;
  top: 50%;
  transform: translateY(-50%);
  color: #475569;
  pointer-events: none;
}

.search-input-wrapper .filter-input {
  padding-left: 2rem;
}

/* ── Checkboxes ── */
.checkbox-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.checkbox-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: #94a3b8;
  cursor: pointer;
  padding: 0.25rem 0;
  transition: color 0.12s ease;
}

.checkbox-item:hover {
  color: #e2e8f0;
}

.checkbox-item input[type="checkbox"] {
  width: 1rem;
  height: 1rem;
  accent-color: #38bdf8;
  cursor: pointer;
  flex-shrink: 0;
}

/* ── Toggle buttons ── */
.toggle-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.toggle-btn {
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.03);
  color: #64748b;
  cursor: pointer;
  transition: all 0.15s ease;
}

.toggle-btn:hover {
  color: #e2e8f0;
  border-color: rgba(255, 255, 255, 0.2);
}

.toggle-btn.active {
  background: rgba(56, 189, 248, 0.15);
  border-color: rgba(56, 189, 248, 0.4);
  color: #38bdf8;
}

/* ── Range inputs ── */
.range-inputs {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.range-input {
  flex: 1;
  min-width: 0;
}

.date-input {
  flex: 1;
  min-width: 0;
}

.range-sep {
  color: #475569;
  font-size: 0.875rem;
  flex-shrink: 0;
}

/* ── Preset row ── */
.preset-dropdown-row {
  display: flex;
  gap: 0.5rem;
}

.preset-select {
  flex: 1;
  min-width: 0;
}

.save-preset-btn {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.5rem 0.75rem;
  background: rgba(56, 189, 248, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 0.5rem;
  color: #38bdf8;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.save-preset-btn:hover {
  background: rgba(56, 189, 248, 0.18);
  border-color: rgba(56, 189, 248, 0.4);
}

/* ── Results area ── */
.results-area {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.results-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.results-count {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #94a3b8;
}

.toggle-sidebar-btn {
  display: none;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.85rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  color: #94a3b8;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background 0.15s ease;
}

.toggle-sidebar-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #e2e8f0;
}

/* ── Chips ── */
.active-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  min-height: 0;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.7rem;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 999px;
  font-size: 0.8125rem;
  color: #7dd3fc;
  font-weight: 500;
}

.chip-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1rem;
  height: 1rem;
  background: none;
  border: none;
  color: #38bdf8;
  cursor: pointer;
  border-radius: 50%;
  padding: 0;
  line-height: 1;
  transition: background 0.12s ease, color 0.12s ease;
}

.chip-remove:hover {
  background: rgba(248, 113, 113, 0.15);
  color: #f87171;
}

/* ── Employee list ── */
.employee-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.employee-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.875rem;
  padding: 1rem 1.25rem;
  display: grid;
  grid-template-columns: 2.5rem 1fr auto auto;
  align-items: center;
  gap: 1rem;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.employee-card:hover {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
}

.employee-avatar {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.875rem;
  font-weight: 700;
  color: #0f172a;
  flex-shrink: 0;
}

.employee-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.employee-name {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #f1f5f9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.employee-meta {
  font-size: 0.8125rem;
  color: #64748b;
}

.employee-salary {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

.status-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  white-space: nowrap;
}

.status-active {
  background: rgba(52, 211, 153, 0.15);
  color: #34d399;
}
.status-inactive {
  background: rgba(248, 113, 113, 0.12);
  color: #f87171;
}
.status-leave {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
}

.no-results {
  text-align: center;
  padding: 3rem 1rem;
  color: #475569;
  font-size: 0.9375rem;
}

/* ── Modal ── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  z-index: 100;
}

.modal-overlay[hidden] {
  display: none;
}

.modal-card {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 1rem;
  padding: 1.5rem;
  width: min(380px, calc(100vw - 2rem));
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-title {
  font-size: 1.0625rem;
  font-weight: 700;
  color: #f1f5f9;
}

.modal-actions {
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
}

.modal-cancel {
  padding: 0.5rem 1rem;
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0.5rem;
  color: #94a3b8;
  font-size: 0.875rem;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease;
}

.modal-cancel:hover {
  background: rgba(255, 255, 255, 0.05);
}

.modal-save {
  padding: 0.5rem 1.125rem;
  background: #38bdf8;
  border: none;
  border-radius: 0.5rem;
  color: #0f172a;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease;
}

.modal-save:hover {
  background: #7dd3fc;
}

/* ── Responsive ── */
@media (max-width: 700px) {
  .app-wrapper {
    flex-direction: column;
  }

  .filter-sidebar {
    width: 100%;
    position: static;
  }

  .toggle-sidebar-btn {
    display: flex;
  }
}

@media (prefers-reduced-motion: reduce) {
  .employee-card,
  .toggle-btn,
  .chip-remove {
    transition: none;
  }
}

