import React from "react";
import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

// ── Config ────────────────────────────────────────────────────────────
const NAME = "Jane Doe";
const TITLE = "Senior Product Designer";
const ACCENT_COLOR = "#6366f1";
const BG_HOLD_START = 15; // frame when hold begins
const BG_HOLD_END = 105; // frame when slide-out starts
const DURATION = 120;

// ── Lower Third Component ─────────────────────────────────────────────
export const LowerThird: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Slide in: frames 0 → 15
  const slideIn = spring({
    frame,
    fps,
    from: -340,
    to: 0,
    config: { damping: 20, stiffness: 160 },
  });

  // Slide out: frames 105 → 120
  const slideOut =
    frame >= BG_HOLD_END
      ? spring({
          frame: frame - BG_HOLD_END,
          fps,
          from: 0,
          to: -340,
          config: { damping: 20, stiffness: 160 },
        })
      : 0;

  const translateX = frame < BG_HOLD_END ? slideIn : slideOut;

  // Accent bar width
  const barScaleX =
    frame < BG_HOLD_END
      ? interpolate(frame, [5, 20], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.quad),
        })
      : interpolate(frame, [BG_HOLD_END, DURATION], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

  // Text opacity
  const textOpacity = interpolate(frame, [12, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "transparent" }}>
      {/* Container positioned at bottom-left */}
      <div
        style={{
          position: "absolute",
          bottom: 80,
          left: 60,
          transform: `translateX(${translateX}px)`,
        }}
      >
        {/* Accent bar */}
        <div
          style={{
            width: 280,
            height: 4,
            backgroundColor: ACCENT_COLOR,
            borderRadius: 2,
            transformOrigin: "left center",
            transform: `scaleX(${barScaleX})`,
            marginBottom: 10,
          }}
        />

        {/* Card */}
        <div
          style={{
            backgroundColor: "rgba(0,0,0,0.82)",
            backdropFilter: "blur(8px)",
            padding: "14px 24px 16px",
            borderLeft: `4px solid ${ACCENT_COLOR}`,
            opacity: textOpacity,
          }}
        >
          <div
            style={{
              fontFamily: "system-ui, -apple-system, sans-serif",
              fontWeight: 700,
              fontSize: 28,
              color: "#ffffff",
              lineHeight: 1.1,
              letterSpacing: -0.5,
            }}
          >
            {NAME}
          </div>
          <div
            style={{
              fontFamily: "system-ui, -apple-system, sans-serif",
              fontWeight: 400,
              fontSize: 15,
              color: "rgba(255,255,255,0.65)",
              marginTop: 4,
              letterSpacing: 0.3,
            }}
          >
            {TITLE}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="LowerThird"
    component={LowerThird}
    durationInFrames={120}
    fps={30}
    width={1280}
    height={720}
  />
);

import React from "react";
import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// ── Config ────────────────────────────────────────────────────────────
const QUOTE =
  "This product completely changed how our team works. The results speak for themselves.";
const AUTHOR_NAME = "Sarah Mitchell";
const AUTHOR_ROLE = "Head of Design, Acme Corp";
const STAR_COUNT = 5;
const BRAND_COLOR = "#f59e0b";
const BG_COLOR = "#0a0a0f";

// ── Star rating ───────────────────────────────────────────────────────
const StarRating: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  return (
    <div style={{ display: "flex", gap: 8, marginBottom: 24 }}>
      {Array.from({ length: STAR_COUNT }).map((_, i) => {
        const delay = 90 + i * 8;
        const f = Math.max(0, frame - delay);
        const scale = spring({
          frame: f,
          fps,
          from: 0,
          to: 1,
          config: { damping: 9, stiffness: 200, mass: 0.5 },
        });

        return (
          <div
            key={i}
            style={{
              fontSize: 36,
              transform: `scale(${scale})`,
              filter: `drop-shadow(0 0 8px ${BRAND_COLOR})`,
            }}
          >
            ★
          </div>
        );
      })}
    </div>
  );
};

// ── Quote text (word-by-word reveal) ─────────────────────────────────
const QuoteText: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const words = QUOTE.split(" ");

  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        gap: "0 10px",
        marginBottom: 40,
        maxWidth: 840,
      }}
    >
      {/* Opening quote mark */}
      <div
        style={{
          width: "100%",
          fontFamily: "Georgia, serif",
          fontSize: 80,
          color: BRAND_COLOR,
          opacity: 0.7,
          lineHeight: 0.7,
          marginBottom: 8,
        }}
      >
        "
      </div>

      {words.map((word, i) => {
        const delay = 15 + i * 5;
        const f = Math.max(0, frame - delay);
        const opacity = interpolate(f, [0, 10], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <span
            key={i}
            style={{
              opacity,
              fontFamily: "Georgia, serif",
              fontStyle: "italic",
              fontWeight: 400,
              fontSize: 30,
              color: "#ffffff",
              lineHeight: 1.6,
            }}
          >
            {word}
          </span>
        );
      })}
    </div>
  );
};

// ── Author info ───────────────────────────────────────────────────────
const AuthorBlock: React.FC<{ frame: number; fps: number }> = ({ frame, fps }) => {
  const delayed = Math.max(0, frame - 105);
  const translateX = spring({
    frame: delayed,
    fps,
    from: -40,
    to: 0,
    config: { damping: 14, stiffness: 100 },
  });
  const opacity = interpolate(delayed, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 16,
        opacity,
        transform: `translateX(${translateX}px)`,
      }}
    >
      {/* Avatar */}
      <div
        style={{
          width: 56,
          height: 56,
          borderRadius: "50%",
          backgroundColor: BRAND_COLOR,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "system-ui, -apple-system, sans-serif",
          fontWeight: 700,
          fontSize: 22,
          color: "#000000",
        }}
      >
        {AUTHOR_NAME.split(" ")
          .map((n) => n[0])
          .join("")}
      </div>

      {/* Name + role */}
      <div>
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontWeight: 700,
            fontSize: 20,
            color: "#ffffff",
          }}
        >
          {AUTHOR_NAME}
        </div>
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontWeight: 400,
            fontSize: 14,
            color: "rgba(255,255,255,0.5)",
            marginTop: 2,
          }}
        >
          {AUTHOR_ROLE}
        </div>
      </div>
    </div>
  );
};

// ── Main composition ──────────────────────────────────────────────────
export const TestimonialVideo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Card fade in
  const cardOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: BG_COLOR }}>
      {/* Background glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 800,
          height: 800,
          borderRadius: "50%",
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(circle, ${BRAND_COLOR}15 0%, transparent 70%)`,
        }}
      />

      {/* Card */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: 900,
          padding: "48px 56px",
          backgroundColor: "rgba(255,255,255,0.04)",
          border: "1px solid rgba(255,255,255,0.08)",
          borderRadius: 16,
          opacity: cardOpacity,
        }}
      >
        <StarRating frame={frame} fps={fps} />
        <QuoteText frame={frame} fps={fps} />
        <AuthorBlock frame={frame} fps={fps} />
      </div>
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="TestimonialVideo"
    component={TestimonialVideo}
    durationInFrames={180}
    fps={30}
    width={1280}
    height={720}
  />
);

