  font-weight: 700;
  color: #f1f5f9;
}

.stats-subheading {
  font-size: 0.875rem;
  color: #64748b;
  margin-bottom: 1rem;
}

/* ── Grid ── */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
