  color: #f1f5f9;
}
.tl-subtitle {
  font-size: 0.8125rem;
  color: #64748b;
  font-weight: 500;
}

.tl-header-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.view-toggle {
