  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.view-btn.active {
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
}

.btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
