(() => {
  const dataList = document.getElementById("dataList");
  const searchInput = document.getElementById("searchInput");
  const selectAll = document.getElementById("selectAll");
  const bulkBar = document.getElementById("bulkBar");
  const bulkCount = document.getElementById("bulkCount");
  const rowCount = document.getElementById("rowCount");
  const emptyState = document.getElementById("emptyState");

  let sortState = { col: null, dir: "asc" };

  // ── Helpers ──
  function getRows() {
    return Array.from(dataList.querySelectorAll(".dl-row--data"));
  }

  function updateRowCount() {
    const visible = getRows().filter((r) => r.style.display !== "none").length;
    const total = getRows().length;
    rowCount.textContent = `${visible}${visible !== total ? " of " + total : ""} member${total !== 1 ? "s" : ""}`;
    emptyState.style.display = visible === 0 ? "flex" : "none";
  }

  function updateBulkBar() {
    const checked = dataList.querySelectorAll(".row-check:checked");
    const allVisible = getRows().filter((r) => r.style.display !== "none");
    const allChecked = allVisible.every((r) => r.querySelector(".row-check").checked);
    const someChecked = allVisible.some((r) => r.querySelector(".row-check").checked);

    selectAll.checked = allChecked && allVisible.length > 0;
    selectAll.indeterminate = someChecked && !allChecked;

    if (checked.length > 0) {
      bulkBar.classList.add("visible");
      bulkCount.textContent = `${checked.length} selected`;
    } else {
      bulkBar.classList.remove("visible");
    }

    getRows().forEach((row) => {
      const cb = row.querySelector(".row-check");
      row.classList.toggle("selected", cb.checked);
    });
  }

  // ── Search ──
  searchInput.addEventListener("input", () => {
    const q = searchInput.value.trim().toLowerCase();
    getRows().forEach((row) => {
      const name = (row.dataset.name || "").toLowerCase();
      const email = (row.dataset.email || "").toLowerCase();
      row.style.display = !q || name.includes(q) || email.includes(q) ? "" : "none";
    });
    updateRowCount();
    updateBulkBar();
  });

  // ── Select All ──
  selectAll.addEventListener("change", () => {
    const visibleRows = getRows().filter((r) => r.style.display !== "none");
    visibleRows.forEach((row) => {
      row.querySelector(".row-check").checked = selectAll.checked;
    });
    updateBulkBar();
  });

  // ── Row checkboxes (delegated) ──
  dataList.addEventListener("change", (e) => {
    if (e.target.classList.contains("row-check")) updateBulkBar();
  });

  // ── Sort ──
  document.querySelectorAll(".sortable").forEach((header) => {
    header.addEventListener("click", () => {
      const col = header.dataset.sort;
      if (sortState.col === col) {
        sortState.dir = sortState.dir === "asc" ? "desc" : "asc";
      } else {
        sortState.col = col;
        sortState.dir = "asc";
      }

      // Update header indicators
      document.querySelectorAll(".sortable").forEach((h) => {
        h.classList.remove("asc", "desc");
      });
      header.classList.add(sortState.dir);

      // Sort rows
      const rows = getRows();
      rows.sort((a, b) => {
        let valA = (a.dataset[col] || "").toLowerCase();
        let valB = (b.dataset[col] || "").toLowerCase();
        // Date comparison
        if (col === "joined") {
          valA = new Date(a.dataset.joined);
          valB = new Date(b.dataset.joined);
          return sortState.dir === "asc" ? valA - valB : valB - valA;
        }
        return sortState.dir === "asc" ? valA.localeCompare(valB) : valB.localeCompare(valA);
      });

      rows.forEach((row) => dataList.appendChild(row));
    });
  });

  // ── Action dropdown ──
  let openDropdown = null;

  dataList.addEventListener("click", (e) => {
    // Toggle dropdown
    const menuBtn = e.target.closest(".action-menu-btn");
    if (menuBtn) {
      e.stopPropagation();
      const dropdown = menuBtn.nextElementSibling;
      if (openDropdown && openDropdown !== dropdown) {
        openDropdown.classList.remove("open");
      }
      dropdown.classList.toggle("open");
      openDropdown = dropdown.classList.contains("open") ? dropdown : null;
      return;
    }

    // Action item
    const actionItem = e.target.closest(".action-item");
    if (actionItem) {
      const row = actionItem.closest(".dl-row--data");
      if (actionItem.classList.contains("action-item--danger") && row) {
        row.classList.add("removing");
        setTimeout(() => {
          row.remove();
          updateRowCount();
          updateBulkBar();
        }, 300);
      }
      if (openDropdown) {
        openDropdown.classList.remove("open");
        openDropdown = null;
      }
    }
  });

  // Close dropdown on outside click
  document.addEventListener("click", (e) => {
    if (openDropdown && !e.target.closest(".dl-col--actions")) {
      openDropdown.classList.remove("open");
      openDropdown = null;
    }
  });

  // ── Edit Modal ──
  const editModalBackdrop = document.getElementById("editModalBackdrop");
  let editingRow = null;

  function openEditModal(row) {
    editingRow = row;
    document.getElementById("editName").value = row.dataset.name || "";
    document.getElementById("editEmail").value = row.dataset.email || "";
    document.getElementById("editRole").value = row.dataset.role || "Viewer";
    document.getElementById("editStatus").value = row.dataset.status || "Active";
    editModalBackdrop.classList.add("open");
  }

  function closeEditModal() {
    editModalBackdrop.classList.remove("open");
    editingRow = null;
  }

  document.getElementById("editModalClose").addEventListener("click", closeEditModal);
  document.getElementById("editModalCancel").addEventListener("click", closeEditModal);
  editModalBackdrop.addEventListener("click", (e) => {
    if (e.target === editModalBackdrop) closeEditModal();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeEditModal();
  });

  document.getElementById("editModalSave").addEventListener("click", () => {
    if (!editingRow) return;
    const newName = document.getElementById("editName").value.trim();
    const newEmail = document.getElementById("editEmail").value.trim();
    const newRole = document.getElementById("editRole").value;
    const newStatus = document.getElementById("editStatus").value;
    if (!newName || !newEmail) return;

    // Update data attributes
    editingRow.dataset.name = newName;
    editingRow.dataset.email = newEmail;
    editingRow.dataset.role = newRole;
    editingRow.dataset.status = newStatus;

    // Update visible cells
    const nameEl = editingRow.querySelector(".member-name");
    const emailEl = editingRow.querySelector(".member-email");
    const roleEl = editingRow.querySelector(".role-badge");
    const statusEl = editingRow.querySelector(".status-badge");

    if (nameEl) nameEl.textContent = newName;
    if (emailEl) emailEl.textContent = newEmail;

    if (roleEl) {
      roleEl.textContent = newRole;
      roleEl.className = `role-badge role-badge--${newRole.toLowerCase()}`;
    }
    if (statusEl) {
      statusEl.textContent = newStatus;
      statusEl.className = `status-badge status-badge--${newStatus.toLowerCase()}`;
    }

    closeEditModal();
  });

  // Wire Edit buttons via delegated click on dataList
  dataList.addEventListener("click", (e) => {
    const actionItem = e.target.closest(".action-item");
    if (
      actionItem &&
      !actionItem.classList.contains("action-item--danger") &&
      actionItem.textContent.trim() === "Edit"
    ) {
      const row = actionItem.closest(".dl-row--data");
      if (row) openEditModal(row);
      if (openDropdown) {
        openDropdown.classList.remove("open");
        openDropdown = null;
      }
    }
  });

  // ── Init ──
  updateRowCount();
})();

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}

/* ── Header ── */
.kb-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  gap: 1rem;
  flex-wrap: wrap;
  flex-shrink: 0;
}

.kb-header-left {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.kb-title {
  font-size: 1.25rem;
  font-weight: 800;
  color: #f1f5f9;
}

.kb-sprint-badge {
  padding: 0.25rem 0.625rem;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #38bdf8;
}

.kb-header-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.kb-search-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.kb-search-icon {
  position: absolute;
  left: 0.625rem;
  color: #475569;
  pointer-events: none;
}
.kb-search {
  padding: 0.4375rem 0.75rem 0.4375rem 2rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  color: #f1f5f9;
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  width: 180px;
  transition: border-color 0.15s;
}
.kb-search:focus {
  border-color: #38bdf8;
}
.kb-search::placeholder {
  color: #475569;
}

.kb-assignee-filter {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}
.filter-label {
  font-size: 0.75rem;
  color: #475569;
  font-weight: 500;
}

.av-filter-btn {
  width: 1.875rem;
  height: 1.875rem;
  border-radius: 50%;
  border: 2px solid transparent;
  background: rgba(255, 255, 255, 0.1);
  color: #0f172a;
  font-size: 0.55rem;
  font-weight: 700;
  cursor: pointer;
  transition: border-color 0.12s, transform 0.12s;
}
.av-filter-btn.all {
  background: rgba(255, 255, 255, 0.1);
  color: #94a3b8;
  font-size: 0.6875rem;
}
.av-filter-btn.active {
  border-color: #f1f5f9;
  transform: scale(1.1);
}
.av-filter-btn[data-assignee="all"] {
  font-size: 0.6875rem;
  color: #94a3b8;
}
.av-filter-btn[data-assignee="all"].active {
  border-color: #38bdf8;
  color: #38bdf8;
}

.btn-secondary {
  padding: 0.4375rem 0.875rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  color: #94a3b8;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
}
.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #f1f5f9;
}

/* ── Board ── */
.kb-board {
  display: flex;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  overflow-x: auto;
  flex: 1;
  align-items: flex-start;
}

/* ── Column ── */
.kb-col {
  width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 1rem;
  padding: 0.875rem;
  transition: background 0.15s;
}
.kb-col.drag-over {
  background: rgba(56, 189, 248, 0.05);
  border-color: rgba(56, 189, 248, 0.2);
}

.kb-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}
.kb-col-left {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.kb-col-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.kb-col-name {
  font-size: 0.875rem;
  font-weight: 700;
  color: #e2e8f0;
}

.kb-col-count {
  padding: 0.15rem 0.5rem;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
}

.kb-col-add {
  width: 1.625rem;
  height: 1.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.375rem;
  color: #64748b;
  font-size: 1.1rem;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
  line-height: 1;
}
.kb-col-add:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #f1f5f9;
}

.kb-cards {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-height: 40px;
}

/* ── Drop placeholder ── */
.kb-drop-placeholder {
  height: 4px;
  background: rgba(56, 189, 248, 0.3);
  border-radius: 2px;
  display: none;
}
.kb-drop-placeholder.visible {
  display: block;
}

/* ── Card ── */
.kb-card {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.75rem;
  padding: 0.875rem;
  cursor: grab;
  transition: box-shadow 0.15s, border-color 0.15s, opacity 0.15s;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.kb-card:hover {
  border-color: rgba(255, 255, 255, 0.15);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}
.kb-card:active {
  cursor: grabbing;
}
.kb-card.dragging {
  opacity: 0.4;
}
.kb-card.hidden {
  display: none;
}

.kb-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
}

.kb-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: #e2e8f0;
  line-height: 1.4;
  cursor: pointer;
}
.kb-card-title:hover {
  color: #38bdf8;
}

.kb-card-checkbox {
  width: 1rem;
  height: 1rem;
  border-radius: 0.25rem;
  border: 1.5px solid #334155;
  background: transparent;
  cursor: pointer;
  flex-shrink: 0;
  appearance: none;
  transition: background 0.12s, border-color 0.12s;
}
.kb-card-checkbox:checked {
  background: #38bdf8;
  border-color: #38bdf8;
}

.kb-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}
.kb-tag {
  padding: 0.15rem 0.5rem;
  border-radius: 0.3rem;
  font-size: 0.6875rem;
  font-weight: 600;
  color: #0f172a;
}

.kb-priority {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 0.2rem 0.5rem;
  border-radius: 0.3rem;
}

.kb-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.kb-card-due {
  font-size: 0.7rem;
  color: #64748b;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
