  color: var(--accent);
  margin-bottom: 32px;
}

.live-dot {
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

@keyframes live-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.35;
    transform: scale(0.6);
  }
}

.hero-content {
  display: flex;
  align-items: flex-start;
  gap: 64px;
}

.hero-text {
  flex: 1;
}

.hero-show-label {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 12px;
}

.hero-title {
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.hero-desc {
  font-size: 1.05rem;
  color: var(--muted);
  max-width: 440px;
  margin-bottom: 32px;
  line-height: 1.7;
}

/* Episode card in hero */
.hero-episode-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 20px;
  max-width: 460px;
}

.episode-card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.ep-number {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.ep-tag {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(29, 185, 84, 0.12);
  border: 1px solid rgba(29, 185, 84, 0.3);
  padding: 2px 9px;
  border-radius: 50px;
}

.ep-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 6px;
}

.ep-guest {
  font-size: 0.82rem;
  color: var(--muted);
  margin-bottom: 16px;
}

.ep-footer {
  display: flex;
  align-items: center;
  gap: 14px;
}

.play-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  color: #000;
  border: none;
  padding: 9px 18px;
  border-radius: 50px;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.2s;
}

.play-btn:hover {
  opacity: 0.85;
  transform: scale(1.02);
}
.play-btn.playing {
  background: rgba(29, 185, 84, 0.2);
  color: var(--accent);
  border: 1px solid rgba(29, 185, 84, 0.4);
}

.ep-duration {
  font-size: 0.8rem;
  color: var(--muted);
}

/* Waveform visual */
.hero-waveform {
  flex: 0 0 280px;
  padding-top: 56px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.waveform-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.waveform-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 72px;
}

.waveform-bars span {
  flex: 1;
  height: var(--h, 50%);
  background: var(--accent);
  border-radius: 2px 2px 0 0;
  opacity: 0.65;
  animation: wave-bar 1.4s ease-in-out infinite;
}

.waveform-bars span:nth-child(2n) {
  animation-delay: 0.15s;
}
.waveform-bars span:nth-child(3n) {
  animation-delay: 0.3s;
}
.waveform-bars span:nth-child(5n) {
  animation-delay: 0.45s;
}
.waveform-bars span:nth-child(7n) {
  animation-delay: 0.6s;
}
.waveform-bars span:nth-child(11n) {
  animation-delay: 0.75s;
}

@keyframes wave-bar {
  0%,
  100% {
    opacity: 0.3;
    transform: scaleY(0.5);
  }
  50% {
    opacity: 1;
    transform: scaleY(1);
  }
}

.waveform-progress {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.waveform-track {
  height: 3px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.waveform-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 2px;
}

.waveform-times {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* ── Section Shared ────────────────────────────────────────────────────────── */
.episodes-section,
.platforms-section {
  padding: 96px 48px;
}

.host-section {
  padding: 96px 48px;
  background: var(--dark2);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
}

.section-title {
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
}

.ep-count {
  font-size: 0.85rem;
  color: var(--muted);
  padding-bottom: 4px;
}

/* ── Filter Pills ──────────────────────────────────────────────────────────── */
.filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 36px;
}

.pill {
  padding: 7px 16px;
  border-radius: 50px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.pill:hover {
  border-color: rgba(29, 185, 84, 0.3);
  color: var(--text);
}

.pill.active {
  background: rgba(29, 185, 84, 0.12);
  border-color: rgba(29, 185, 84, 0.5);
  color: var(--accent);
}

/* ── Episodes Grid ─────────────────────────────────────────────────────────── */
.episodes-grid {
