  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.ep-card-number {
  font-size: 0.7rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.ep-card-tag {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
