}

.ep-play-icon {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  padding: 0;
  transition: color 0.2s;
}

.ep-play-icon:hover {
  color: var(--accent);
}
.ep-play-icon.playing {
  color: var(--accent);
}

.load-more-row {
  display: flex;
  justify-content: center;
  margin-top: 40px;
}

.btn-load-more {
  padding: 12px 32px;
  border-radius: 50px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-load-more:hover {
  border-color: rgba(29, 185, 84, 0.4);
  color: var(--accent);
}

/* ── Host Section ──────────────────────────────────────────────────────────── */
.host-inner {
  display: flex;
  align-items: flex-start;
  gap: 40px;
}

.host-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, #0f2a14 0%, #0a1a1a 100%);
  border: 1px solid rgba(29, 185, 84, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  font-weight: 800;
  flex-shrink: 0;
  color: var(--accent);
}

.host-info {
  flex: 1;
}

.host-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 8px;
}

.host-name {
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 16px;
}

.host-quote {
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.75;
  border-left: 2px solid var(--accent);
  padding-left: 16px;
  margin-bottom: 24px;
  font-style: italic;
  quotes: none;
}

.host-socials {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.social-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 50px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s;
}

.social-link:hover {
  border-color: rgba(29, 185, 84, 0.4);
  color: var(--accent);
}

/* ── Platforms Section ─────────────────────────────────────────────────────── */
.platforms-section {
  text-align: center;
}

.platforms-title {
  font-size: 1rem;
  color: var(--muted);
  margin-bottom: 32px;
  font-weight: 500;
}

.platforms-grid {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.platform-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 24px;
  border-radius: 50px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s;
}

.platform-btn:hover {
  border-color: rgba(29, 185, 84, 0.35);
  background: rgba(29, 185, 84, 0.06);
  color: var(--accent);
  transform: translateY(-2px);
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.footer {
  padding: 48px;
  border-top: 1px solid var(--border);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-logo {
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.footer-copy {
  font-size: 0.8rem;
  color: var(--muted);
}

.footer-links {
  display: flex;
  gap: 24px;
}

.footer-links a {
  font-size: 0.8rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover {
  color: var(--text);
}

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 900px) {
  .nav {
    padding: 14px 20px;
  }
  .nav-links {
    display: none;
  }
  .hero {
    padding: 100px 20px 60px;
  }
  .hero-content {
    flex-direction: column;
  }
  .hero-waveform {
    display: none;
  }
  .episodes-section,
  .host-section,
  .platforms-section {
    padding: 60px 20px;
  }
  .host-inner {
    flex-direction: column;
  }
  .footer {
    padding: 32px 20px;
  }
}

