*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --card: #0d1117;
  --text: #f2f6ff;
  --muted: #475569;
  --border: rgba(255, 255, 255, 0.08);
  --accent: #38bdf8;
  --nav-h: 60px;
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

/* ── Navbar ── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: rgba(5, 9, 16, 0.8);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.navbar__inner {
  max-width: 1100px;
  margin: 0 auto;
  height: var(--nav-h);
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 0 1.5rem;
}

/* Logo */
.navbar__logo {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
  color: var(--text);
  font-weight: 700;
  font-size: 1rem;
  flex-shrink: 0;
}

.logo-gem {
  color: var(--accent);
}

/* Nav */
.navbar__nav {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-link {
  padding: 0.4rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
  border-radius: 6px;
  transition: color 0.18s, background 0.18s;
}

.nav-link:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.nav-item-wrap {
  position: static;
}

.nav-trigger {
  padding: 0.4rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted);
  background: none;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  transition: color 0.18s, background 0.18s;
  white-space: nowrap;
}

.nav-trigger:hover,
.nav-trigger[aria-expanded="true"] {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.trigger-chevron {
  flex-shrink: 0;
  transition: transform 0.22s var(--ease);
}

.nav-trigger[aria-expanded="true"] .trigger-chevron {
  transform: rotate(180deg);
}

.navbar__cta {
  margin-left: auto;
  flex-shrink: 0;
  padding: 0.4rem 1.1rem;
  background: var(--accent);
  color: #050910;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 999px;
  transition: opacity 0.18s;
}

.navbar__cta:hover {
  opacity: 0.85;
}

/* ── Mega Panel ── */
.mega-panel {
  position: absolute;
  top: var(--nav-h);
  left: 0;
  right: 0;
  background: var(--card);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5);
  padding: 2rem 0;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px);
  transition: opacity 0.22s var(--ease), transform 0.22s var(--ease);
  z-index: 100;
}

.mega-panel.open {
  opacity: 1;
  pointer-events: all;
  transform: translateY(0);
}

.mega-panel__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.mega-panel__inner--2col {
  grid-template-columns: repeat(2, 1fr);
  max-width: 640px;
}

/* ── Column ── */
.mega-col {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mega-col__title {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.625rem;
}

/* ── Mega link with icon ── */
.mega-link {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text);
  transition: background 0.18s;
  font-size: 0.875rem;
}

.mega-link:hover {
  background: rgba(255, 255, 255, 0.05);
}

.mega-link strong {
  display: block;
  font-weight: 600;
  margin-bottom: 0.125rem;
}

.mega-link__icon {
  font-size: 1.1rem;
  width: 30px;
  height: 30px;
  background: rgba(56, 189, 248, 0.08);
  border-radius: 7px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  margin-top: 1px;
}

.mega-link__desc {
  display: block;
  font-size: 0.78rem;
  color: var(--muted);
  line-height: 1.4;
  font-weight: 400;
}

/* Plain links (no icon) */
.mega-link--plain {
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  color: var(--muted);
  gap: 0;
}

.mega-link--plain:hover {
  color: var(--text);
}

/* ── Featured column ── */
.mega-col--featured {
}

.mega-featured-card {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1.25rem;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.08) 0%, rgba(56, 189, 248, 0.03) 100%);
  border: 1px solid rgba(56, 189, 248, 0.15);
  text-decoration: none;
  color: var(--text);
  transition: border-color 0.2s, background 0.2s;
  position: relative;
}

.mega-featured-card:hover {
  border-color: rgba(56, 189, 248, 0.35);
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.12) 0%, rgba(56, 189, 248, 0.06) 100%);
}

.featured-card__badge {
  position: absolute;
  top: 0.875rem;
  right: 0.875rem;
  background: var(--accent);
  color: #050910;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.featured-card__icon {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
