.dash-nav__link {
  font-size: 0.82rem;
  color: #5a6a8a;
  text-decoration: none;
  padding: 0.4rem 0.75rem;
  border-radius: 0.4rem;
  transition: color 0.15s, background 0.15s;
}

.dash-nav__link:hover {
  color: #c5d3f0;
  background: rgba(255, 255, 255, 0.05);
}
.dash-nav__link.is-active {
  color: #f2f6ff;
  background: rgba(255, 255, 255, 0.07);
}

.dash-avatar {
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #4f6ef7, #7c3aed);
}

/* Main */
.dash-main {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Stats */
.dash-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.875rem;
}

.stat-card {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 1.1rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.75rem;
}

.stat-card__label {
  font-size: 0.75rem;
  color: #5a6a8a;
  font-weight: 500;
}

.stat-card__value {
  font-size: 1.3rem;
  font-weight: 700;
  color: #f2f6ff;
  letter-spacing: -0.02em;
}

.stat-card__change {
  font-size: 0.75rem;
  font-weight: 500;
}

.stat-card__change--up {
  color: #4ade80;
}
.stat-card__change--down {
  color: #f87171;
}

/* Chart */
.dash-chart {
  padding: 1.25rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.875rem;
}

.chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
}

.chart-title {
  font-size: 0.9rem;
  font-weight: 600;
  color: #c5d3f0;
}

.chart-filters {
  display: flex;
  gap: 0.25rem;
}

.chart-filter {
  font-size: 0.75rem;
  padding: 0.3rem 0.65rem;
  border-radius: 0.35rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: transparent;
  color: #5a6a8a;
  cursor: pointer;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
}

.chart-filter:hover {
  color: #c5d3f0;
  background: rgba(255, 255, 255, 0.05);
}
.chart-filter.is-active {
  color: #f2f6ff;
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.14);
}

.chart-body {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.chart-bars {
  height: 120px;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
}

.chart-bar {
  flex: 1;
  height: var(--h);
  border-radius: 0.25rem 0.25rem 0 0;
  background: rgba(79, 110, 247, 0.25);
  transition: background 0.2s;
}

.chart-bar.is-selected {
  background: rgba(79, 110, 247, 0.8);
}
.chart-bar:hover {
  background: rgba(79, 110, 247, 0.5);
}

.chart-axis {
  display: flex;
  justify-content: space-between;
  padding: 0 0.1rem;
}

.chart-axis span {
  font-size: 0.7rem;
  color: #3a4a6a;
}

/* Actions */
.dash-actions {
  display: flex;
  justify-content: flex-end;
}

.action-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  border-radius: 0.55rem;
  border: none;
  cursor: pointer;
  font-size: 0.87rem;
  font-weight: 600;
  background: linear-gradient(135deg, #4f6ef7, #7c3aed);
  color: #fff;
  box-shadow: 0 4px 14px rgba(79, 110, 247, 0.35);
  transition: opacity 0.2s, transform 0.2s;
}

.action-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

/* Start tour CTA */
.tour-start {
  position: fixed;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
}

.tour-start__btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.4rem;
  border-radius: 2rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(20, 30, 50, 0.9);
  color: #c5d3f0;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  transition: background 0.2s, color 0.2s, transform 0.2s;
}

.tour-start__btn:hover {
  background: rgba(30, 45, 70, 0.95);
  color: #f2f6ff;
  transform: translateY(-2px);
}

/* ═══════════ Tour overlay ═══════════ */
.tour-overlay {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 100;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.tour-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

/* Hole rect animation via CSS transition on SVG element */
#mask-hole {
  transition: x 0.4s cubic-bezier(0.4, 0, 0.2, 1), y 0.4s cubic-bezier(0.4, 0, 0.2, 1), width 0.4s
    cubic-bezier(0.4, 0, 0.2, 1), height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ═══════════ Tooltip ═══════════ */
.tour-tooltip {
  position: fixed;
  z-index: 110;
  width: 280px;
  background: #0d1526;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.875rem;
  padding: 1.1rem 1.2rem;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.04);
  opacity: 0;
  pointer-events: none;
  transform: scale(0.94) translateY(4px);
  transition: opacity 0.25s ease, transform 0.3s cubic-bezier(0.34, 1.3, 0.64, 1);
}

.tour-tooltip.is-active {
  opacity: 1;
  pointer-events: auto;
  transform: scale(1) translateY(0);
}

.tour-tooltip__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.tour-tooltip__step {
  font-size: 0.72rem;
  font-weight: 600;
  color: #4f6ef7;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.tour-tooltip__skip {
  font-size: 0.75rem;
  color: #4a5a7a;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.2rem 0.4rem;
  border-radius: 0.3rem;
  transition: color 0.15s, background 0.15s;
}

.tour-tooltip__skip:hover {
  color: #c5d3f0;
  background: rgba(255, 255, 255, 0.05);
}

.tour-tooltip__title {
  font-size: 1rem;
  font-weight: 700;
  color: #f2f6ff;
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
}

.tour-tooltip__body {
  font-size: 0.84rem;
  color: #7888a8;
  line-height: 1.6;
  margin-bottom: 1rem;
}

.tour-tooltip__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Dots */
.tour-dots {
  display: flex;
  gap: 0.35rem;
}

.tour-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  transition: background 0.2s, transform 0.2s;
}

.tour-dot.is-active {
  background: #4f6ef7;
  transform: scale(1.25);
}

/* Nav buttons */
.tour-tooltip__nav {
  display: flex;
  gap: 0.5rem;
}

.tour-btn {
  padding: 0.45rem 0.9rem;
  border-radius: 0.45rem;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background 0.15s, color 0.15s, opacity 0.15s;
}

.tour-btn--ghost {
  background: rgba(255, 255, 255, 0.06);
  color: #7888a8;
}

.tour-btn--ghost:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #c5d3f0;
}
.tour-btn--ghost:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.tour-btn--primary {
  background: #4f6ef7;
  color: #fff;
}

.tour-btn--primary:hover {
  background: #6080ff;
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .dash-stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .dash-nav {
    display: none;
  }
  .tour-tooltip {
    width: 240px;
  }
}

