  padding: 0;
}

:root {
  --bg: #050910;
  --card: #0d1117;
  --border: rgba(255, 255, 255, 0.08);
  --text: #f2f6ff;
  --muted: #475569;
  --accent: #38bdf8;
  --track-bg: rgba(255, 255, 255, 0.08);
  --thumb-size: 18px;
  --track-h: 5px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  padding: 3rem 1.5rem;
}

.demo {
  max-width: 480px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.demo-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.demo-sub {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.section-label {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--muted);
}

/* ── Shared input ── */
.rs-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.rs-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: var(--track-h);
  border-radius: 999px;
  outline: none;
  cursor: pointer;
  background: linear-gradient(
    to right,
    var(--accent) 0%,
    var(--accent) var(--fill, 50%),
    var(--track-bg) var(--fill, 50%),
    var(--track-bg) 100%
  );
}

.rs-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: var(--thumb-size);
  height: var(--thumb-size);
  border-radius: 50%;
  background: var(--accent);
  border: 3px solid #050910;
  box-shadow: 0 0 0 1px var(--accent), 0 2px 8px rgba(56, 189, 248, 0.35);
  transition: transform 0.12s, box-shadow 0.12s;
  cursor: grab;
}

.rs-input::-webkit-slider-thumb:active {
  transform: scale(1.15);
  cursor: grabbing;
}

.rs-input::-moz-range-thumb {
  width: var(--thumb-size);
  height: var(--thumb-size);
  border-radius: 50%;
  background: var(--accent);
  border: 3px solid #050910;
  box-shadow: 0 0 0 1px var(--accent);
  cursor: grab;
}

/* ── Tooltip ── */
.rs-tooltip-wrap {
  position: relative;
  padding-top: 2rem;
}

.rs-tooltip {
  position: absolute;
  top: 0;
  left: var(--fill, 50%);
  transform: translateX(-50%);
  background: var(--accent);
  color: #050910;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
  border-radius: 6px;
  pointer-events: none;
  white-space: nowrap;
  transition: left 0.06s;
}

.rs-tooltip::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 4px solid transparent;
  border-top-color: var(--accent);
}

/* ── Labels row ── */
.rs-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--muted);
}

/* ── Stepped ticks ── */
.rs-ticks {
  display: flex;
  justify-content: space-between;
  font-size: 0.68rem;
  color: var(--muted);
}

/* ── Dual handle ── */
.rs-dual-wrap {
  position: relative;
  height: var(--thumb-size);
  display: flex;
  align-items: center;
}

.rs-dual-track {
  position: absolute;
  left: 0;
  right: 0;
  height: var(--track-h);
  background: var(--track-bg);
  border-radius: 999px;
}

.rs-dual-fill {
  position: absolute;
  height: 100%;
  background: var(--accent);
  border-radius: 999px;
}

.rs-dual-input {
  position: absolute;
  left: 0;
  right: 0;
  width: 100%;
  pointer-events: none;
  background: transparent;
}

.rs-dual-input::-webkit-slider-thumb {
  pointer-events: all;
}

.rs-dual-input::-moz-range-thumb {
  pointer-events: all;
}

/* ── Color variants ── */
.rs-colors {
  gap: 1.25rem;
}

.rs-blue {
  --accent: #38bdf8;
}
.rs-green {
  --accent: #4ade80;
}
.rs-red {
  --accent: #f87171;
}

