  right: -8px;
  top: 110px;
  width: 7px;
  height: 52px;
  border-radius: 0 2px 2px 0;
}

/* ── Phone frame ── */
.phone-frame {
  width: 240px;
  background: #0f172a;
  border-radius: 2.5rem;
  border: 1.5px solid rgba(255, 255, 255, 0.12);
  padding: 0.875rem;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.5), inset 0 0 0 1px rgba(255, 255, 255, 0.04), 0 40px 80px
    rgba(0, 0, 0, 0.8);
  position: relative;
  overflow: hidden;
}

/* Gloss sheen */
.phone-frame::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 50%;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.04) 0%, transparent 100%);
  border-radius: 2.5rem 2.5rem 0 0;
  pointer-events: none;
  z-index: 10;
}

/* ── Notch area ── */
.phone-notch {
  display: flex;
  justify-content: center;
  margin-bottom: 0.375rem;
}

.dynamic-island {
  width: 80px;
  height: 24px;
  background: #000;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.5rem;
  gap: 0.3rem;
