  height: 100%;
  background: linear-gradient(135deg, #7c3aed 0%, #2563eb 40%, #0891b2 70%, #059669 100%);
}

.album-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.12) 0%, transparent 60%);
