}

/* ── Base separator ── */
.sep {
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  margin: 0;
}

/* ── Dashed ── */
.sep--dashed {
  border-top-style: dashed;
}

/* ── Dotted ── */
.sep--dotted {
  border-top-style: dotted;
}

/* ── Text variants ── */
.sep--text {
  display: flex;
  align-items: center;
  gap: 1rem;
  border: none;
  color: #334155;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
}
.sep--text::before,
.sep--text::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
}
.sep--text::before {
  content: "";
}
.sep--text::after {
  content: "";
}

/* Inject label text */
.sep--text[data-label]::before {
  flex: 1;
}
.sep--text[data-label]::after {
  flex: 1;
}

/* Override: inject content after ::before using a trick */
.sep--text {
  position: relative;
}
.sep--text[data-label] {
  display: flex;
  align-items: center;
  gap: 1rem;
}
/* Use the data attribute as text via JS-free approach with ::after on parent */
/* Actually use a pseudo trick: can't use attr() in content for styled text easily without JS */
/* So we simply rely on the data-label being rendered via additional span below */

/* Left-aligned text */
.sep--text-left::before {
  flex: 0 0 0;
  display: none;
}
.sep--text-left {
  justify-content: flex-start;
}

/* ── Gradient ── */
.sep--gradient {
  border: none;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.15) 50%,
    transparent 100%
  );
}

/* ── Diamond ── */
.sep--diamond {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: rgba(255, 255, 255, 0.15);
  font-size: 0.6rem;
}
.sep--diamond::before,
.sep--diamond::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
}
.sep--diamond::after {
  content: "◆";
  flex: 0;
  color: rgba(255, 255, 255, 0.2);
  font-size: 0.6rem;
}
.sep--diamond::before {
  content: "";
}

/* ── Vertical ── */
.sep--vertical {
