/* ── Diff Slider container ── */
.diff-slider {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 1rem;
  overflow: hidden;
  user-select: none;
  cursor: ew-resize;
  border: 1px solid rgba(255, 255, 255, 0.08);
  touch-action: pan-y;
}

/* ── Layers ── */
.diff-layer {
  position: absolute;
  inset: 0;
}

/* Before image: dark monochrome gradient */
.diff-image--before {
  width: 100%;
  height: 100%;
  background: radial-gradient(ellipse at 30% 50%, #1e293b 0%, #0f172a 50%, #020617 100%);
}

/* After image: vivid colorful gradient */
.diff-image--after {
  width: 100%;
  height: 100%;
  background: radial-gradient(
    ellipse at 70% 40%,
    #7c3aed 0%,
    #2563eb 35%,
    #0891b2 60%,
    #059669 85%,
    #065f46 100%
  );
}

/* After layer clip — JS updates --split CSS variable */
.diff-layer--after {
  clip-path: inset(0 calc(100% - var(--split, 50%)) 0 0);
  transition: clip-path 0s;
}

/* ── Labels ── */
.diff-label {
  position: absolute;
  bottom: 0.875rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.3rem 0.65rem;
  border-radius: 999px;
  backdrop-filter: blur(8px);
}

.diff-label--before {
  left: 0.875rem;
  background: rgba(0, 0, 0, 0.5);
  color: #94a3b8;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.diff-label--after {
  right: 0.875rem;
  background: rgba(124, 58, 237, 0.3);
  color: #c4b5fd;
  border: 1px solid rgba(124, 58, 237, 0.4);
}

/* ── Divider line ── */
.diff-divider {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--split, 50%);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
  z-index: 10;
}

.diff-line {
  width: 2px;
  flex: 1;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.4);
}

/* ── Handle ── */
.diff-handle {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  background: #fff;
  color: #0f172a;
  border: none;
  cursor: ew-resize;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5), 0 0 0 3px rgba(255, 255, 255, 0.2);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  z-index: 11;
}

.diff-handle:hover,
.diff-handle:focus-visible {
  transform: translate(-50%, -50%) scale(1.1);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.6), 0 0 0 4px rgba(255, 255, 255, 0.35);
  outline: none;
}

/* Active drag state */
.diff-slider.dragging .diff-handle {
  transform: translate(-50%, -50%) scale(1.12);
}

.diff-slider.dragging .diff-layer--after {
  transition: none;
}

