(function () {
  "use strict";

  const slider = document.querySelector(".diff-slider");
  const handle = slider && slider.querySelector(".diff-handle");
  if (!slider || !handle) return;

  let isDragging = false;
  let split = 50; // percentage

  function setSplit(pct) {
    split = Math.max(2, Math.min(98, pct));
    slider.style.setProperty("--split", split + "%");
    handle.setAttribute("aria-valuenow", Math.round(split));
  }

  function getPercent(clientX) {
    const rect = slider.getBoundingClientRect();
    return ((clientX - rect.left) / rect.width) * 100;
  }

  // Mouse events
  handle.addEventListener("mousedown", function (e) {
    e.preventDefault();
    isDragging = true;
    slider.classList.add("dragging");
  });

  document.addEventListener("mousemove", function (e) {
    if (!isDragging) return;
    setSplit(getPercent(e.clientX));
  });

  document.addEventListener("mouseup", function () {
    if (!isDragging) return;
    isDragging = false;
    slider.classList.remove("dragging");
  });

  // Touch events
  handle.addEventListener(
    "touchstart",
    function (e) {
      e.preventDefault();
      isDragging = true;
      slider.classList.add("dragging");
    },
    { passive: false }
  );

  document.addEventListener(
    "touchmove",
    function (e) {
      if (!isDragging) return;
      setSplit(getPercent(e.touches[0].clientX));
    },
    { passive: true }
  );

  document.addEventListener("touchend", function () {
    if (!isDragging) return;
    isDragging = false;
    slider.classList.remove("dragging");
  });

  // Keyboard support
  handle.addEventListener("keydown", function (e) {
    const step = e.shiftKey ? 10 : 2;
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      setSplit(split - step);
    }
    if (e.key === "ArrowRight") {
      e.preventDefault();
      setSplit(split + step);
    }
    if (e.key === "Home") {
      e.preventDefault();
      setSplit(2);
    }
    if (e.key === "End") {
      e.preventDefault();
      setSplit(98);
    }
  });

  // Click on slider background to jump
  slider.addEventListener("click", function (e) {
    if (e.target === handle) return;
    setSplit(getPercent(e.clientX));
  });

  // Initialize
  setSplit(50);
})();

snippets.css:
/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --accent: #f2f6ff;
  --muted: #334155;
  --mid: #64748b;
  --border: rgba(242, 246, 255, 0.07);
  --surface: rgba(242, 246, 255, 0.03);
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--accent);
  font-family: "Space Grotesk", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 48px;
  background: rgba(5, 9, 16, 0);
}

.nav-name {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--accent);
  text-decoration: none;
}

.available-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 14px;
  border-radius: 50px;
  border: 1px solid rgba(34, 197, 94, 0.35);
  background: rgba(34, 197, 94, 0.08);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #22c55e;
}

.avail-dot {
  width: 6px;
  height: 6px;
  background: #22c55e;
  border-radius: 50%;
  animation: avail-blink 2s ease-in-out infinite;
}

@keyframes avail-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px 40px;
  position: relative;
}

.hero-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero-index {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 24px;
}

.hero-name {
  display: flex;
  flex-direction: column;
  font-family: "Syne", "Space Grotesk", sans-serif;
  font-size: clamp(4rem, 14vw, 11rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 0.9;
  color: var(--accent);
  margin-bottom: 24px;
}

.name-line {
  display: block;
}

.hero-roles {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: clamp(1rem, 2.5vw, 1.6rem);
  font-weight: 300;
  color: var(--muted);
  letter-spacing: 0.02em;
  margin-bottom: 32px;
  height: 2em;
  overflow: hidden;
}

.role-prefix {
  color: var(--mid);
  flex-shrink: 0;
}

.roles-ticker {
  position: relative;
  overflow: hidden;
}

.role {
  display: none;
}
.role.active {
  display: inline;
}

.hero-tagline {
  font-size: 0.95rem;
  color: var(--mid);
  max-width: 440px;
  margin-bottom: 48px;
  line-height: 1.65;
}

.hero-scroll-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.scroll-track {
  width: 2px;
  height: 48px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.scroll-thumb {
  width: 100%;
  height: 40%;
  background: var(--mid);
  border-radius: 2px;
  animation: scroll-anim 2s ease-in-out infinite;
}

@keyframes scroll-anim {
  0% {
    transform: translateY(-100%);
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
  }
  100% {
    transform: translateY(250%);
    opacity: 0;
  }
}

/* Hero deco labels */
.hero-deco {
  position: absolute;
  bottom: 40px;
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding: 0 48px;
}

.deco-year,
.deco-location {
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ── Work ──────────────────────────────────────────────────────────────────── */
.work-section {
  padding: 96px 48px;
  border-top: 1px solid var(--border);
}

.work-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 40px;
}

.work-title {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
}

.work-count {
  font-size: 0.7rem;
  color: var(--muted);
}

.work-list {
  list-style: none;
}

.work-item {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 24px 0;
  text-decoration: none;
  color: var(--accent);
  border-top: 1px solid var(--border);
  position: relative;
  overflow: hidden;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s, transform 0.5s;
}

.work-item:last-child {
  border-bottom: 1px solid var(--border);
}

.work-item.revealed {
  opacity: 1;
  transform: translateY(0);
}

.work-item::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(242, 246, 255, 0.03);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.work-item:hover::before {
  transform: scaleX(1);
}

.work-thumbnail {
  width: 48px;
  height: 48px;
