  stroke: rgba(255, 255, 255, 0.06);
  stroke-width: 2.5;
}

.btt-ring__fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2.5;
  stroke-linecap: round;
  /* set dynamically by JS: stroke-dasharray and stroke-dashoffset */
  transition: stroke-dashoffset 0.1s linear;
}

/* ── Arrow icon ── */
.btt-arrow {
  position: relative;
  z-index: 1;
  color: var(--text);
  transition: transform 0.2s var(--ease);
}

