  background: #050910;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  color: #f2f6ff;
  font-size: 0.8rem;
  outline: none;
  font-family: inherit;
}
.pop-input:focus {
  border-color: #38bdf8;
}
.pop-submit {
  padding: 0.5rem 0.875rem;
  background: #38bdf8;
  color: #0f172a;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
}

