*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --card: #0d1117;
  --text: #f2f6ff;
  --muted: #475569;
  --border: rgba(255, 255, 255, 0.08);
  --accent: #38bdf8;
  --sidebar-w: 220px;
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

/* ── Progress bar ── */
.progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: rgba(255, 255, 255, 0.06);
  z-index: 300;
}

.progress-bar__fill {
  height: 100%;
  width: 0%;
  background: var(--accent);
  transition: width 0.1s linear;
  border-radius: 0 2px 2px 0;
}

/* ── Layout ── */
.layout {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr;
  max-width: 900px;
  margin: 0 auto;
  padding: 3rem 1.5rem;
  gap: 3rem;
  min-height: 100vh;
  align-items: start;
}

/* ── Sidebar ── */
.sidebar {
  position: sticky;
  top: 2rem;
}

/* ── Anchor nav ── */
.anchor-nav {
}

.anchor-nav__title {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.875rem;
}

.anchor-nav__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-left: 1px solid var(--border);
}

.anchor-nav__link {
  display: block;
  padding: 0.45rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
  border-left: 2px solid transparent;
  margin-left: -1px;
  transition: color 0.2s var(--ease), border-color 0.2s var(--ease);
}

.anchor-nav__link:hover {
  color: var(--text);
}

.anchor-nav__link--active {
  color: var(--accent);
  border-left-color: var(--accent);
  font-weight: 600;
}

/* ── Content ── */
.content {
  min-width: 0;
}

.content__header {
  margin-bottom: 3rem;
}

.content__page-title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 0.75rem;
}

.content__lead {
  font-size: 1.0625rem;
  color: var(--muted);
  line-height: 1.7;
}

/* ── Section ── */
.section {
  padding-top: 2rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid var(--border);
  scroll-margin-top: 2rem;
}

.section:last-child {
  border-bottom: none;
}

.section__title {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1.125rem;
}

.section__body {
  font-size: 0.9375rem;
  color: #94a3b8;
  line-height: 1.75;
  margin-bottom: 1rem;
}

.section__body:last-child {
  margin-bottom: 0;
}

.code {
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.8125em;
  background: rgba(255, 255, 255, 0.07);
  padding: 0.1em 0.4em;
  border-radius: 4px;
  color: var(--accent);
}

/* ── Callout ── */
.callout {
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  font-size: 0.875rem;
  color: #94a3b8;
  line-height: 1.6;
}

.callout strong {
  color: var(--text);
}

.callout--blue {
  background: rgba(56, 189, 248, 0.05);
  border-color: rgba(56, 189, 248, 0.2);
}

/* ── Feature list ── */
.feature-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  margin-top: 1rem;
}

.feature-item {
  display: flex;
  gap: 0.75rem;
  font-size: 0.9rem;
  color: #94a3b8;
  line-height: 1.6;
}

.feature-item strong {
  color: var(--text);
}

.feature-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
  margin-top: 0.45em;
}

/* ── Mobile ── */
@media (max-width: 640px) {
  .layout {
    grid-template-columns: 1fr;
    padding: 1.5rem 1rem;
    gap: 1.5rem;
  }

  .sidebar {
    position: static;
  }

  .anchor-nav__list {
    flex-direction: row;
    flex-wrap: wrap;
    border-left: none;
    gap: 0.5rem;
  }

  .anchor-nav__link {
    border-left: none;
    border-bottom: 2px solid transparent;
    padding: 0.3rem 0.75rem;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.04);
    margin-left: 0;
  }

  .anchor-nav__link--active {
    border-bottom-color: var(--accent);
    background: rgba(56, 189, 248, 0.08);
  }
}

