  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.35);
}

/* ── Webkit scrollbar — shared ── */
.scroll-area::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.scroll-area::-webkit-scrollbar-track {
  background: transparent;
}

.scroll-area::-webkit-scrollbar-corner {
  background: transparent;
}

.scroll-area::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 3px;
  transition: background 0.25s;
}

/* Show thumb only while scrolling */
.scroll-area.scrolling::-webkit-scrollbar-thumb {
  background: var(--sb-thumb);
}

.scroll-area::-webkit-scrollbar-thumb:hover {
  background: var(--sb-thumb-hover);
}

/* Firefox */
.scroll-area {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

.scroll-area.scrolling {
  scrollbar-color: var(--sb-thumb) transparent;
}

/* ── Vertical ── */
.scroll-area--vertical {
  height: 280px;
  overflow-y: auto;
  overflow-x: hidden;
}

/* ── Horizontal ── */
.scroll-area--horizontal {
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.5rem; /* space for scrollbar */
}

/* ── Both ── */
.scroll-area--both {
  height: 260px;
  overflow: auto;
}

/* ── Item list (vertical) ── */
.item-list {
  list-style: none;
  padding: 0.5rem;
}

.item {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.625rem 0.75rem;
  border-radius: 8px;
  font-size: 0.875rem;
  transition: background 0.15s;
}

.item:hover {
  background: rgba(255, 255, 255, 0.03);
}

.item-num {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  width: 22px;
  flex-shrink: 0;
}

/* ── Horizontal cards ── */
.card-row {
  display: flex;
  gap: 0.75rem;
  padding: 0.75rem;
  width: max-content;
}

.h-card {
  width: 120px;
  height: 100px;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 0.875rem;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.h-card--1 {
  background: linear-gradient(135deg, #0f2044, #0a3a5c);
}
.h-card--2 {
  background: linear-gradient(135deg, #1a0a3c, #3b0f6e);
}
.h-card--3 {
  background: linear-gradient(135deg, #072a1e, #0d4a32);
}
.h-card--4 {
  background: linear-gradient(135deg, #2a0f0a, #5c1f10);
}
.h-card--5 {
  background: linear-gradient(135deg, #1a1a0a, #3d3800);
}
.h-card--6 {
  background: linear-gradient(135deg, #0a1f2a, #0d3650);
}
.h-card--7 {
  background: linear-gradient(135deg, #1f0a2a, #450f5e);
}
.h-card--8 {
  background: linear-gradient(135deg, #0a2a10, #0d4818);
}
.h-card--9 {
  background: linear-gradient(135deg, #2a1a0a, #5c3a10);
}
.h-card--10 {
  background: linear-gradient(135deg, #001f2a, #003655);
}

.h-card__num {
  position: absolute;
  top: 0.625rem;
  right: 0.75rem;
  font-size: 0.68rem;
  color: rgba(255, 255, 255, 0.3);
  font-variant-numeric: tabular-nums;
}

.h-card__title {
  font-size: 0.85rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.9);
  letter-spacing: -0.01em;
}

/* ── Both-axes grid ── */
.both-content {
  padding: 0.75rem;
  width: max-content;
}

.both-grid {
  display: grid;
  grid-template-columns: repeat(10, 80px);
  grid-template-rows: repeat(8, 60px);
  gap: 6px;
}

.grid-cell {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border);
  border-radius: 6px;
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  transition: background 0.15s, border-color 0.15s;
}

.grid-cell:hover {
  background: rgba(56, 189, 248, 0.06);
  border-color: rgba(56, 189, 248, 0.2);
  color: var(--text);
}

