*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --card: #0d1117;
  --card2: #111827;
  --border: rgba(255, 255, 255, 0.08);
  --text: #f2f6ff;
  --muted: #475569;
  --accent: #38bdf8;
  --accent-bg: rgba(56, 189, 248, 0.14);
  --radius: 12px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  padding: 3rem 1.5rem;
}

.demo {
  max-width: 480px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.demo-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.demo-sub {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.section-label {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--muted);
}

/* ── Wrapper ── */
.cs-wrap {
  position: relative;
}

/* ── Trigger ── */
.cs-trigger {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  background: var(--card);
  border: 1.5px solid var(--border);
  color: var(--text);
  padding: 0.6rem 0.875rem;
  border-radius: 10px;
  font-size: 0.875rem;
  cursor: pointer;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  user-select: none;
}

.cs-trigger:hover,
.cs-trigger:focus {
  border-color: rgba(255, 255, 255, 0.18);
}

.cs-wrap.open .cs-trigger,
.cs-trigger[aria-expanded="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.12);
}

.cs-value {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cs-value:empty::before {
  content: attr(data-placeholder);
  color: var(--muted);
}

.cs-arrow {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  color: var(--muted);
  transition: transform 0.2s;
}

.cs-wrap.open .cs-arrow {
  transform: rotate(180deg);
}

/* ── Multi-trigger ── */
.cs-trigger--multi {
  flex-wrap: wrap;
  gap: 0.35rem;
  min-height: 2.5rem;
  padding: 0.35rem 0.875rem;
  align-items: center;
  cursor: text;
}

.cs-tag-input {
  flex: 1;
  min-width: 80px;
  background: none;
  border: none;
  color: var(--text);
  font-size: 0.875rem;
  outline: none;
  padding: 0;
}

.cs-tag-input::placeholder {
  color: var(--muted);
}

.cs-tags {
  display: contents;
}

.cs-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 6px;
  padding: 0.2rem 0.5rem;
  font-size: 0.78rem;
  font-weight: 500;
  white-space: nowrap;
}

.cs-tag-remove {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font-size: 0.9rem;
  line-height: 1;
  opacity: 0.7;
  transition: opacity 0.15s;
}

.cs-tag-remove:hover {
  opacity: 1;
}

/* ── Dropdown ── */
.cs-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  background: var(--card2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  z-index: 200;
  overflow: hidden;
  display: none;
  animation: cs-in 0.13s ease;
}

@keyframes cs-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.cs-wrap.open .cs-dropdown {
  display: block;
}

/* ── Search ── */
.cs-search-wrap {
  padding: 0.5rem;
  border-bottom: 1px solid var(--border);
}

.cs-search {
  width: 100%;
  background: var(--card);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.45rem 0.75rem;
  border-radius: 8px;
  font-size: 0.85rem;
  outline: none;
}

.cs-search:focus {
  border-color: var(--accent);
}

/* ── List ── */
.cs-list {
  list-style: none;
  max-height: 220px;
  overflow-y: auto;
  padding: 0.375rem;
}

.cs-list::-webkit-scrollbar {
  width: 4px;
}
.cs-list::-webkit-scrollbar-track {
  background: transparent;
}
.cs-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 4px;
}

.cs-group-label {
  padding: 0.35rem 0.75rem 0.2rem;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.cs-option {
  padding: 0.5rem 0.75rem;
  border-radius: 7px;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background 0.12s;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.cs-option:hover,
.cs-option.focused {
  background: rgba(255, 255, 255, 0.05);
}

.cs-option.selected {
  background: var(--accent-bg);
  color: var(--accent);
}

.cs-option[hidden] {
  display: none;
}

.cs-empty {
  padding: 0.75rem;
  text-align: center;
  font-size: 0.85rem;
  color: var(--muted);
}

