/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #080b14;
  --bg2: #0d1117;
  --accent: #7c3aed;
  --accent2: #38bdf8;
  --pink: #f472b6;
  --text: #e2e8f0;
  --muted: #64748b;
  --border: rgba(255, 255, 255, 0.07);
  --surface: rgba(255, 255, 255, 0.04);
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 14px 40px;
  background: rgba(8, 11, 20, 0.88);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: "Space Grotesk", sans-serif;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text);
  text-decoration: none;
  flex-shrink: 0;
}

.logo-prism {
  display: flex;
  align-items: center;
}

.nav-search {
  flex: 1;
  max-width: 360px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-radius: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--muted);
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 0.85rem;
  font-family: inherit;
}

.search-input::placeholder {
  color: var(--muted);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.nav-link {
  font-size: 0.85rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-link:hover {
  color: var(--text);
}

.btn-wallet {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 8px;
  background: var(--accent);
  border: none;
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-wallet:hover {
  opacity: 0.85;
}

.btn-wallet.connected {
  background: rgba(16, 185, 129, 0.12);
  color: #10b981;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.nav-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--accent), var(--pink));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 700;
  color: #fff;
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  min-height: calc(100vh - 57px);
  display: grid;
  grid-template-columns: 1fr 276px;
  grid-template-rows: 1fr auto;
  gap: 20px;
  padding: 32px 40px;
  align-items: start;
}

.hero-featured {
  grid-column: 1;
  grid-row: 1 / 3;
  display: flex;
}

.featured-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.featured-art {
  position: relative;
  height: 340px;
  overflow: hidden;
  background: #070711;
}

.art-gradient {
  position: absolute;
  inset: 0;
}

.featured-gradient {
  background: radial-gradient(ellipse at 30% 50%, rgba(124, 58, 237, 0.45) 0%, transparent 55%),
    radial-gradient(ellipse at 72% 28%, rgba(56, 189, 248, 0.3) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 78%, rgba(244, 114, 182, 0.2) 0%, transparent 50%);
}

.art-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.orb {
  position: absolute;
  left: var(--x, 50%);
  top: var(--y, 50%);
  width: var(--s, 100px);
  height: var(--s, 100px);
  border-radius: 50%;
  background: radial-gradient(circle, var(--c, #7c3aed) 0%, transparent 70%);
  transform: translate(-50%, -50%);
  opacity: 0.7;
  filter: blur(22px);
  animation: orb-float 6s ease-in-out infinite;
}

.orb:nth-child(2) {
  animation-delay: -2s;
  animation-duration: 8s;
}
.orb:nth-child(3) {
  animation-delay: -4s;
  animation-duration: 5s;
}

@keyframes orb-float {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    transform: translate(-50%, calc(-50% - 14px)) scale(1.1);
  }
}

.art-grid-overlay {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px);
  background-size: 40px 40px;
}

.featured-live-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border-radius: 50px;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.35);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #ef4444;
}

.live-pulse {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  animation: live-blink 1.4s ease-in-out infinite;
}

@keyframes live-blink {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.35;
    transform: scale(0.75);
  }
}

.featured-info {
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.featured-collection {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.featured-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.featured-artist {
  font-size: 0.88rem;
  color: var(--muted);
}

.artist-highlight {
  color: var(--accent2);
  font-weight: 500;
}

.featured-auction {
  display: flex;
  gap: 32px;
  padding: 14px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.auction-col {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auction-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.auction-price {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: "Space Mono", monospace;
  font-size: 1.15rem;
  font-weight: 700;
}

.auction-price svg {
  color: #627eea;
  flex-shrink: 0;
}

.auction-timer {
  font-family: "Space Mono", monospace;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--accent2);
}

.auction-usd {
  font-size: 0.7rem;
  color: var(--muted);
}

.featured-actions {
  display: flex;
  gap: 12px;
  margin-top: auto;
}

.btn-bid {
  flex: 1;
  padding: 12px 20px;
  background: linear-gradient(135deg, var(--accent), #5b21b6);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s, transform 0.15s;
}

.btn-bid:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn-watch {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--muted);
  font-size: 0.88rem;
  cursor: pointer;
  font-family: inherit;
  transition: color 0.2s, border-color 0.2s;
}

.btn-watch:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.18);
}

/* ── Mini cards (right column, top) ────────────────────────────────────────── */
.hero-grid-mini {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mini-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.2s;
}

.mini-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

.mini-art {
  height: 80px;
  background: linear-gradient(135deg, var(--c1, #7c3aed), var(--c2, #06b6d4));
}

.mini-info {
  padding: 8px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.mini-title {
  font-size: 0.77rem;
  font-weight: 500;
}

.mini-eth {
  font-family: "Space Mono", monospace;
  font-size: 0.7rem;
  color: var(--accent2);
}

/* ── Hero stats (right column, bottom) ─────────────────────────────────────── */
.hero-stats {
  grid-column: 2;
  grid-row: 2;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hero-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.hstat-val {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.1rem;
  font-weight: 700;
}

.hstat-label {
  font-size: 0.7rem;
  color: var(--muted);
}

/* ── Shared section styles ─────────────────────────────────────────────────── */
.auctions-section,
.artists-section,
.how-section {
  padding: 64px 40px;
  border-top: 1px solid var(--border);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
}

.section-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #ef4444;
  margin-bottom: 6px;
}

.live-dot-small {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  animation: live-blink 1.4s ease-in-out infinite;
}

.section-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.3rem, 2.5vw, 1.8rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.see-all {
  font-size: 0.82rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
  white-space: nowrap;
}

.see-all:hover {
  color: var(--text);
}

/* ── Auctions Grid ─────────────────────────────────────────────────────────── */
.auctions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.nft-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  transition: transform 0.25s, border-color 0.25s, box-shadow 0.25s;
}

.nft-card:hover {
