  border-color: rgba(255, 255, 255, 0.13);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

.nft-art {
  height: 200px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--c1, #4f46e5), var(--c2, #7c3aed));
}

.nft-art-inner {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      ellipse at 70% 30%,
      var(--c3, rgba(167, 139, 250, 0.5)) 0%,
      transparent 55%
    ), radial-gradient(ellipse at 25% 75%, rgba(0, 0, 0, 0.3) 0%, transparent 55%);
}

.nft-info {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.nft-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.nft-title {
  font-weight: 600;
  font-size: 0.92rem;
}

.nft-edition {
  font-size: 0.66rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  flex-shrink: 0;
  padding: 3px 8px;
  border-radius: 50px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--muted);
}

.nft-artist {
  font-size: 0.78rem;
  color: var(--muted);
}

.nft-bid-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

.bid-label {
  display: block;
  font-size: 0.66rem;
  color: var(--muted);
  margin-bottom: 3px;
}

.bid-eth {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: "Space Mono", monospace;
  font-size: 0.88rem;
  font-weight: 700;
}

.bid-eth svg {
  color: #627eea;
  flex-shrink: 0;
}
.bid-eth.flash {
  color: #10b981;
  transition: color 0.2s;
}

.nft-timer {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.72rem;
  color: var(--muted);
}

.btn-bid-sm {
  width: 100%;
  padding: 9px;
  background: linear-gradient(135deg, var(--accent), #5b21b6);
  border: none;
  border-radius: 6px;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-bid-sm:hover {
  opacity: 0.85;
}

/* ── Top Artists ───────────────────────────────────────────────────────────── */
.artists-row {
  display: flex;
  flex-direction: column;
}

.artist-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.artist-item:first-child {
  border-top: 1px solid var(--border);
}

.artist-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--bg, #7c3aed);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 700;
  color: #fff;
}

.artist-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.artist-name {
  font-size: 0.9rem;
  font-weight: 500;
}

.artist-volume {
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  color: var(--accent2);
}

.artist-rank {
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  color: var(--muted);
  flex-shrink: 0;
}

/* ── How It Works ──────────────────────────────────────────────────────────── */
.how-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 40px;
  text-align: center;
}

.how-steps {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 16px;
}

.how-step {
  flex: 1;
  max-width: 280px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.step-num {
  font-family: "Space Mono", monospace;
  font-size: 0.7rem;
  color: var(--accent2);
  font-weight: 700;
  letter-spacing: 0.1em;
}

.step-icon {
  color: var(--muted);
}
.step-title {
  font-size: 1rem;
  font-weight: 600;
}
.step-desc {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.65;
}

.how-step-arrow {
  font-size: 1.4rem;
  color: var(--muted);
  align-self: center;
  padding-top: 48px;
  flex-shrink: 0;
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.footer {
  background: var(--bg2);
  border-top: 1px solid var(--border);
  padding: 56px 40px 24px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 48px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.footer-brand {
  max-width: 300px;
}

.footer-logo {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  display: block;
  margin-bottom: 10px;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.footer-tagline {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.6;
}

.newsletter-label {
  display: block;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.newsletter-row {
  display: flex;
  gap: 8px;
}

.newsletter-input {
  flex: 1;
  padding: 10px 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
}

.newsletter-input::placeholder {
  color: var(--muted);
}
.newsletter-input:focus {
  border-color: rgba(124, 58, 237, 0.5);
}

.newsletter-btn {
  padding: 10px 20px;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
  white-space: nowrap;
}

.newsletter-btn:hover {
  opacity: 0.85;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  font-size: 0.78rem;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}

.footer-links {
  display: flex;
  gap: 20px;
}
.footer-links a {
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover {
  color: var(--text);
}

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 900px) {
  .hero {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto;
    padding: 20px;
  }
  .hero-featured {
    grid-column: 1;
    grid-row: 1;
  }
  .hero-grid-mini {
    grid-column: 1;
    grid-row: 2;
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 4px;
  }
  .mini-card {
    flex: 0 0 160px;
  }
  .hero-stats {
    grid-column: 1;
    grid-row: 3;
    flex-direction: row;
  }
  .nav {
    padding: 12px 20px;
  }
  .nav-search {
    display: none;
  }
  .auctions-section,
  .artists-section,
  .how-section {
    padding: 48px 20px;
  }
  .how-steps {
    flex-wrap: wrap;
  }
  .how-step-arrow {
    display: none;
  }
  .footer {
    padding: 40px 20px 20px;
  }
  .footer-top {
    flex-direction: column;
  }
}

