  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.toggle__track {
  display: block;
  width: 2.5rem;
  height: 1.375rem;
  background: #d1d5db;
  border-radius: 999px;
  transition: background 0.2s;
}
.toggle input:checked + .toggle__track {
