  font-weight: 700;
  border-radius: 0.875rem;
  text-decoration: none;
}
.btn-plan-free {
  display: block;
  text-align: center;
  padding: 0.875rem;
  border: 1px solid #e7e5e4;
  color: var(--text);
  font-weight: 700;
  border-radius: 0.875rem;
  text-decoration: none;
}

/* DOWNLOAD */
.download-inner {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
}
.download-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #fff;
}
.download-sub {
  font-size: 0.9375rem;
  color: rgba(255, 255, 255, 0.7);
}
.store-badges {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
}
.store-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.75rem 1.5rem;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 0.75rem;
  color: #fff;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.875rem;
