*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: #050910;
  color: #f2f6ff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 560px;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}
.demo-sub {
  color: #475569;
  font-size: 0.875rem;
  margin-bottom: 2rem;
}

.inputs-grid {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Form group ── */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}
.form-label {
  font-size: 0.8rem;
  font-weight: 500;
  color: #94a3b8;
}
.form-helper {
  font-size: 0.75rem;
  color: #475569;
}
.form-error {
  font-size: 0.75rem;
  color: #ef4444;
}

/* ── Base input ── */
.input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  background: #0d1117;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.625rem;
  color: #f2f6ff;
  font-size: 0.875rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  resize: vertical;
}
.input::placeholder {
  color: #334155;
}
.input:focus {
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15);
}

/* ── Icon wrapper ── */
.input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.input-icon {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #475569;
  pointer-events: none;
}
.input-icon--left {
  left: 0.75rem;
}
.input-icon--right {
  right: 0.75rem;
}
.input-icon--btn {
  pointer-events: auto;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.15s;
}
.input-icon--btn:hover {
  color: #94a3b8;
}

.input--icon-left {
  padding-left: 2.5rem;
}
.input--icon-right {
  padding-right: 2.5rem;
}

/* ── States ── */
.input--valid {
  border-color: #22c55e;
}
.input--invalid {
  border-color: #ef4444;
}
.input--valid:focus {
  box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.15);
}
.input--invalid:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

/* ── Floating label ── */
.float-wrap {
  position: relative;
}
.input--float {
  padding-top: 1.25rem;
  padding-bottom: 0.375rem;
}
.float-label {
  position: absolute;
  top: 50%;
  left: 0.875rem;
  transform: translateY(-50%);
  font-size: 0.875rem;
  color: #475569;
  pointer-events: none;
  transition: top 0.15s, font-size 0.15s, color 0.15s;
}
.input--float:not(:placeholder-shown) + .float-label,
.input--float:focus + .float-label {
  top: 0.5rem;
  transform: none;
  font-size: 0.7rem;
  color: #38bdf8;
}

/* ── Textarea ── */
.input--textarea {
  resize: vertical;
  min-height: 80px;
}

/* ── Character count ── */
.input-wrap--count {
  flex-direction: column;
  align-items: flex-end;
  gap: 0.25rem;
}
.input-wrap--count .input {
  width: 100%;
}
.char-count {
  font-size: 0.72rem;
  color: #334155;
}

