  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  background: rgba(5, 9, 16, 0.8);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.nav-logo {
  font-size: 1.1rem;
  font-weight: 900;
  letter-spacing: 0.1em;
}
.nav-right {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}
.raise-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.15);
  border: 1px solid rgba(99, 102, 241, 0.3);
  color: #818cf8;
}
.btn-nav {
  font-size: 0.85rem;
  font-weight: 600;
  padding: 0.5rem 1.25rem;
  border-radius: 0.5rem;
  background: var(--accent);
  color: #fff;
  text-decoration: none;
  transition: opacity 0.15s;
}
.btn-nav:hover {
  opacity: 0.85;
}

/* SLIDES */
.slide {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 7rem 4rem 4rem;
  gap: 4rem;
}
.slide--dark {
  background: var(--dark2);
}
.slide--cta {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12), rgba(56, 189, 248, 0.08));
}
.slide-inner {
  flex: 1;
  max-width: 580px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.slide-inner--center {
  align-items: center;
  text-align: center;
  margin: 0 auto;
}
.slide-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.eyebrow--red {
  color: #f87171;
}
.eyebrow--blue {
  color: #38bdf8;
}
.eyebrow--green {
  color: #4ade80;
}
.slide-title {
  font-size: clamp(2.2rem, 4vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.1;
}
.slide-body {
  font-size: 1rem;
  color: #94a3b8;
  line-height: 1.7;
  max-width: 480px;
}
.grad {
  background: linear-gradient(90deg, #6366f1, #38bdf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.highlight-num {
  color: #f87171;
  font-style: italic;
}

.cta-row {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 0.75rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-weight: 700;
  font-size: 0.9rem;
  border-radius: 0.625rem;
  text-decoration: none;
  transition: opacity 0.15s;
}
.btn-primary:hover {
  opacity: 0.85;
}
.btn-ghost {
  display: inline-flex;
  align-items: center;
  padding: 0.75rem 1.5rem;
  background: rgba(255, 255, 255, 0.06);
  color: #cbd5e1;
  font-weight: 600;
  font-size: 0.9rem;
  border-radius: 0.625rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  text-decoration: none;
  transition: background 0.15s;
}
.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.1);
}
.btn-large {
  padding: 1rem 2rem;
  font-size: 1rem;
}

/* Dashboard mock */
.slide-visual {
  flex: 1;
  display: flex;
  justify-content: center;
}
.dashboard-mock {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1rem;
  padding: 1.5rem;
  width: 320px;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.mock-bar {
  height: 8px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 4px;
}
.mock-stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.ms-label {
  font-size: 0.72rem;
  color: var(--muted);
}
.ms-val {
  font-size: 1.75rem;
  font-weight: 800;
  color: #4ade80;
}
.mock-chart {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 80px;
}
.chart-bar {
  flex: 1;
  background: rgba(99, 102, 241, 0.3);
  border-radius: 4px 4px 0 0;
  transition: background 0.2s;
}
.chart-bar[data-active] {
  background: #6366f1;
}

/* Pain grid */
.pain-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-top: 0.5rem;
}
.pain-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.75rem;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.pain-icon {
  font-size: 1.5rem;
}
.pain-card p {
  font-size: 0.875rem;
  color: #94a3b8;
  line-height: 1.6;
}

/* Solution steps */
.solution-steps {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.step {
  display: flex;
  gap: 1.25rem;
  align-items: flex-start;
}
.step-num {
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--accent);
  background: rgba(99, 102, 241, 0.12);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 0.375rem;
  padding: 0.2rem 0.5rem;
  flex-shrink: 0;
  margin-top: 0.2rem;
}
.step h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 0.35rem;
}
.step p {
  font-size: 0.875rem;
  color: #94a3b8;
  line-height: 1.6;
}

/* Traction */
.traction-inner {
  max-width: 700px;
}
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 0.5rem;
}
.metric {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.875rem;
  padding: 1.5rem;
}
.metric-val {
  font-size: 2.5rem;
  font-weight: 900;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, #4ade80, #38bdf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.metric-label {
  font-size: 0.8rem;
  color: var(--muted);
}

/* Team */
.team-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
}
.founder-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1rem;
  padding: 1.5rem;
  flex: 1;
  min-width: 200px;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.founder-avatar {
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #38bdf8);
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 0.9rem;
}
.founder-card h3 {
  font-size: 1rem;
  font-weight: 700;
}
.founder-role {
  font-size: 0.8rem;
  color: #6366f1;
  font-weight: 600;
}
.founder-bio {
  font-size: 0.8rem;
  color: #94a3b8;
  line-height: 1.6;
}

/* CTA */
.cta-title {
  text-align: center;
}
.cta-sub {
  font-size: 0.9rem;
  color: #94a3b8;
  text-align: center;
}
.cta-legal {
  font-size: 0.72rem;
  color: var(--muted);
  text-align: center;
  margin-top: 0.5rem;
}

/* Slides without a .slide-visual child — center and widen the content */
.slide:not(:has(.slide-visual)) {
  justify-content: center;
}
.slide:not(:has(.slide-visual)) .slide-inner {
  max-width: 760px;
}

@media (max-width: 768px) {
  .slide {
    flex-direction: column;
    padding: 5rem 1.5rem 3rem;
  }
  .slide-visual {
    display: none;
  }
}

