.demo-sub {
  font-size: 0.9rem;
  color: #8090b0;
  line-height: 1.6;
}

/* ── Snippet list ── */
.snippet-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Snippet block ── */
.snippet-block {
  border-radius: 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.03);
  overflow: hidden;
}

.snippet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.55rem 0.9rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
}

.snippet-lang {
  font-size: 0.72rem;
  font-weight: 500;
  color: #5a6a8a;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.snippet-pre {
  padding: 1rem 1.1rem;
  overflow-x: auto;
}

.snippet-pre code {
  font-family: "JetBrains Mono", "Fira Code", ui-monospace, monospace;
  font-size: 0.82rem;
  line-height: 1.65;
  color: #c8d8f8;
  white-space: pre;
}

/* ── Copy button ── */
.copy-btn {
  position: relative;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 0.4rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  color: #7888a8;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  flex-shrink: 0;
}

.copy-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #c5d3f0;
  border-color: rgba(255, 255, 255, 0.14);
}

.copy-btn:active {
  transform: scale(0.92);
}

.copy-btn:focus-visible {
  outline: 2px solid #4f6ef7;
  outline-offset: 2px;
}

/* Icon states */
.copy-btn__icon {
  position: absolute;
  transition: opacity 0.15s ease, transform 0.2s ease;
}

.copy-btn__icon--check {
  opacity: 0;
  transform: scale(0.7);
  color: #4ade80;
}

/* Copied state */
.copy-btn.is-copied {
  background: rgba(74, 222, 128, 0.1);
  border-color: rgba(74, 222, 128, 0.3);
  color: #4ade80;
}

.copy-btn.is-copied .copy-btn__icon--copy {
  opacity: 0;
  transform: scale(0.7);
}

.copy-btn.is-copied .copy-btn__icon--check {
  opacity: 1;
  transform: scale(1);
  animation: check-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Error state */
.copy-btn.is-error {
  background: rgba(248, 113, 113, 0.1);
  border-color: rgba(248, 113, 113, 0.3);
  color: #f87171;
  animation: err-shake 0.4s ease;
}

@keyframes check-pop {
  0% {
    transform: scale(0.5);
  }
  60% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes err-shake {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-3px);
  }
  75% {
    transform: translateX(3px);
  }
}

