/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --off-white: #f5f3ee;
  --dark: #0a0a0a;
  --gold: #c9a96e;
  --muted: #6b6b6b;
  --border: rgba(10, 10, 10, 0.1);
  --font-serif: "Cormorant Garamond", "Playfair Display", Georgia, serif;
  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--off-white);
  color: var(--dark);
  font-family: var(--font-sans);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 56px;
  background: var(--off-white);
  border-bottom: 1px solid var(--border);
}

.nav-brand {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--dark);
  text-decoration: none;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 40px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--dark);
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  height: 100vh;
  min-height: 600px;
  position: relative;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  background: var(--dark);
}

.hero-image-placeholder {
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, #1a1a14 0%, #0f0f0c 50%, #0a0a0a 100%);
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(10, 10, 10, 0.95) 0%,
    rgba(10, 10, 10, 0.5) 40%,
    rgba(10, 10, 10, 0.1) 100%
  );
}

.hero-grid-lines {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: space-around;
  pointer-events: none;
}

.hero-grid-lines span {
  width: 1px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    rgba(201, 169, 110, 0.08) 50%,
    transparent 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  padding: 0 56px 72px;
  width: 100%;
}

.hero-established {
  font-size: 0.7rem;
  font-weight: 400;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.hero-established::before {
  content: "";
  display: block;
  width: 40px;
  height: 1px;
  background: var(--gold);
}

.hero-headline {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 6vw, 5.5rem);
  font-weight: 600;
  line-height: 1.05;
  color: var(--off-white);
  letter-spacing: -0.01em;
  max-width: 700px;
  margin-bottom: 28px;
}

.hero-headline em {
  font-style: italic;
  color: var(--gold);
}

.hero-sub {
  font-size: 0.9rem;
  color: rgba(245, 243, 238, 0.5);
  font-weight: 300;
