.tooltip-wrap {
  position: relative;
  display: inline-block;
}

/* Bubble */
.tooltip-wrap::after {
  content: attr(data-tooltip);
  position: absolute;
  z-index: 100;
  white-space: nowrap;
  font-size: 0.8rem;
  font-weight: 500;
  line-height: 1;
  padding: 0.45rem 0.75rem;
