*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --accent: #86e8ff;
  --neon-purple: #ae52ff;
  --neon-pink: #ff40d6;
}

body {
  background: #030510;
  color: #f0f4fb;
  font-family: "Inter", "SF Pro Display", system-ui, sans-serif;
  overflow: hidden;
  height: 100vh;
  cursor: none;
}

@media (hover: none) {
  body {
    cursor: auto;
  }
}

/* ── Stage ── */
.stage {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
}

/* ── Hidden layer (colorful content underneath) ── */
.hidden-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(135deg, #0a0520 0%, #150a30 50%, #0d1a2a 100%);
}

.hidden-content {
  position: relative;
  width: 100%;
  height: 100%;
}

.color-block {
  position: absolute;
  border-radius: 16px;
}

.block-1 {
  width: 200px;
  height: 200px;
  background: linear-gradient(135deg, #86e8ff, #3d9eff);
  top: 10%;
  left: 8%;
  transform: rotate(-12deg);
}

.block-2 {
  width: 150px;
  height: 260px;
  background: linear-gradient(135deg, #ae52ff, #7c2aff);
  top: 15%;
  right: 12%;
  transform: rotate(8deg);
}

.block-3 {
  width: 280px;
  height: 140px;
  background: linear-gradient(135deg, #ff40d6, #ff6b9d);
  bottom: 20%;
  left: 15%;
  transform: rotate(5deg);
}

.block-4 {
