  height: 120px;
  background: linear-gradient(135deg, #ffcc66, #ff9f43);
  top: 55%;
  left: 50%;
  border-radius: 50%;
}

.block-5 {
  width: 180px;
  height: 100px;
  background: linear-gradient(135deg, #50c878, #27ae60);
  bottom: 10%;
  right: 20%;
  transform: rotate(-6deg);
}

.block-6 {
  width: 100px;
  height: 200px;
  background: linear-gradient(135deg, #ff6b6b, #ee5a24);
  top: 5%;
  left: 45%;
  transform: rotate(15deg);
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
}

.orb-1 {
  width: 300px;
  height: 300px;
  background: rgba(134, 232, 255, 0.2);
  top: 30%;
  left: 30%;
}

.orb-2 {
  width: 250px;
