if (!window.MotionPreference) {
  const __mql = window.matchMedia("(prefers-reduced-motion: reduce)");
  const __listeners = new Set();

  const MotionPreference = {
    prefersReducedMotion() {
      return __mql.matches;
    },
    setOverride(value) {
      const reduced = Boolean(value);
      document.documentElement.classList.toggle("reduced-motion", reduced);
      window.dispatchEvent(new CustomEvent("motion-preference", { detail: { reduced } }));
      for (const listener of __listeners) {
        try {
          listener({ reduced, override: reduced, systemReduced: __mql.matches });
        } catch {}
      }
    },
    onChange(listener) {
      __listeners.add(listener);
      try {
        listener({
          reduced: __mql.matches,
          override: null,
          systemReduced: __mql.matches,
        });
      } catch {}
      return () => __listeners.delete(listener);
    },
    getState() {
      return { reduced: __mql.matches, override: null, systemReduced: __mql.matches };
    },
  };

  window.MotionPreference = MotionPreference;
}

function prefersReducedMotion() {
  return window.MotionPreference.prefersReducedMotion();
}

function initDemoShell() {
  // No-op shim in imported standalone snippets.
}

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Lenis from "lenis";

gsap.registerPlugin(ScrollTrigger);

initDemoShell({
  title: "Video Scroll Scrub",
  category: "scroll",
  tech: ["gsap", "scroll-trigger", "lenis", "video-currenttime", "canvas-2d"],
});

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

// ── Lenis smooth scroll ───────────────────────────────────────────────────────
const lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

// ── Canvas setup ──────────────────────────────────────────────────────────────
const canvas = document.getElementById("video-canvas");
const ctx = canvas.getContext("2d");
const fallback = document.getElementById("video-fallback");

function resizeCanvas() {
  const wrap = canvas.parentElement;
  canvas.width = wrap.clientWidth;
  canvas.height = wrap.clientHeight;
}

// ── Synthetic video frames (CSS-gradient simulation) ──────────────────────────
// Since we can't ship a real video file in this demo, we generate
// procedural "film frames" on Canvas that look like a scrubbing video.
// In production: replace with a real <video> element and draw to canvas.

const TOTAL_DURATION = 8; // simulated seconds
let currentProgress = 0;
let animating = false;

const scenes = [
  { at: 0.0, label: "Opening", hue1: 220, hue2: 240, sat1: 30, sat2: 25, lig1: 8, lig2: 12 },
  { at: 0.2, label: "Act I", hue1: 15, hue2: 30, sat1: 40, sat2: 30, lig1: 10, lig2: 15 },
  { at: 0.42, label: "Rising", hue1: 200, hue2: 220, sat1: 50, sat2: 40, lig1: 12, lig2: 18 },
  { at: 0.65, label: "Climax", hue1: 350, hue2: 330, sat1: 55, sat2: 45, lig1: 14, lig2: 20 },
  { at: 0.82, label: "Resolution", hue1: 270, hue2: 290, sat1: 35, sat2: 25, lig1: 10, lig2: 15 },
  { at: 0.95, label: "End Credits", hue1: 220, hue2: 240, sat1: 15, sat2: 10, lig1: 6, lig2: 8 },
];

function getSceneAt(progress) {
  let scene = scenes[0];
  for (let i = scenes.length - 1; i >= 0; i--) {
    if (progress >= scenes[i].at) {
      scene = scenes[i];
      break;
    }
  }
  return scene;
}

function lerpColor(a, b, t) {
  return Math.round(a + (b - a) * t);
}

function drawFrame(progress) {
  const w = canvas.width;
  const h = canvas.height;

  // Find scene blend
  let sceneA = scenes[0],
    sceneB = scenes[1],
    blendT = 0;
  for (let i = 0; i < scenes.length - 1; i++) {
    if (progress >= scenes[i].at && progress < scenes[i + 1].at) {
      sceneA = scenes[i];
      sceneB = scenes[i + 1];
      const range = scenes[i + 1].at - scenes[i].at;
      blendT = (progress - scenes[i].at) / range;
      break;
    }
  }
  if (progress >= scenes[scenes.length - 1].at) {
    sceneA = sceneB = scenes[scenes.length - 1];
    blendT = 0;
  }

  // Interpolate hues
  const h1 = lerpColor(sceneA.hue1, sceneB.hue1, blendT);
  const h2 = lerpColor(sceneA.hue2, sceneB.hue2, blendT);
  const s1 = lerpColor(sceneA.sat1, sceneB.sat1, blendT);
  const s2 = lerpColor(sceneA.sat2, sceneB.sat2, blendT);
  const l1 = lerpColor(sceneA.lig1, sceneB.lig1, blendT);
  const l2 = lerpColor(sceneA.lig2, sceneB.lig2, blendT);

  // Background gradient
  const grad = ctx.createLinearGradient(0, 0, w, h);
  grad.addColorStop(0, `hsl(${h1}, ${s1}%, ${l1}%)`);
  grad.addColorStop(0.35, `hsl(${h2}, ${s2}%, ${l2}%)`);
  grad.addColorStop(0.65, `hsl(${h1 + 20}, ${s1}%, ${l1 + 3}%)`);
  grad.addColorStop(1, `hsl(${h2 + 10}, ${s2}%, ${l2 + 2}%)`);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // Light leak / lens flare effect
  const flareX = w * (0.2 + progress * 0.6);
  const flareGrad = ctx.createRadialGradient(flareX, h * 0.3, 0, flareX, h * 0.3, w * 0.5);
  flareGrad.addColorStop(0, `hsla(${h1 + 30}, 80%, 70%, ${0.04 + blendT * 0.06})`);
  flareGrad.addColorStop(1, "transparent");
  ctx.fillStyle = flareGrad;
  ctx.fillRect(0, 0, w, h);

  // Horizon line — simulates ground/horizon in a cinematic shot
  const horizonY = h * (0.48 + Math.sin(progress * Math.PI * 2) * 0.04);
  const horizonGrad = ctx.createLinearGradient(0, horizonY - 2, 0, horizonY + 2);
  horizonGrad.addColorStop(0, "transparent");
  horizonGrad.addColorStop(0.5, `hsla(${h1 + 15}, 60%, 55%, 0.12)`);
  horizonGrad.addColorStop(1, "transparent");
  ctx.fillStyle = horizonGrad;
  ctx.fillRect(0, horizonY - 2, w, 4);

  // Film grain (subtle noise dots)
  ctx.save();
  ctx.globalAlpha = 0.025;
  for (let i = 0; i < 800; i++) {
    const gx = Math.random() * w;
    const gy = Math.random() * h;
    const size = Math.random() * 1.5;
    ctx.fillStyle = Math.random() > 0.5 ? "#ffffff" : "#000000";
    ctx.fillRect(gx, gy, size, size);
  }
  ctx.restore();

  // Vignette
  const vig = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, Math.max(w, h) * 0.75);
  vig.addColorStop(0, "transparent");
  vig.addColorStop(1, "rgba(0, 0, 0, 0.6)");
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, w, h);

  // Timestamp / frame counter
  const simTime = progress * TOTAL_DURATION;
  const mins = Math.floor(simTime / 60)
    .toString()
    .padStart(2, "0");
  const secs = Math.floor(simTime % 60)
    .toString()
    .padStart(2, "0");
  ctx.font = '11px "SF Mono", monospace';
  ctx.fillStyle = "rgba(255,255,255,0.25)";
  ctx.textAlign = "right";
  ctx.fillText(
    `${mins}:${secs} | FRAME ${Math.round(progress * 240)
      .toString()
      .padStart(5, "0")}`,
    w - 16,
    h - 16
  );
}

// ── UI updates ────────────────────────────────────────────────────────────────
const soFill = document.getElementById("so-fill");
const soTime = document.getElementById("so-time");
const scText = document.getElementById("sc-text");

function updateUI(progress) {
  soFill.style.width = `${progress * 100}%`;
  const simTime = progress * TOTAL_DURATION;
  const mins = Math.floor(simTime / 60)
    .toString()
    .padStart(2, "0");
  const secs = Math.floor(simTime % 60)
    .toString()
    .padStart(2, "0");
  soTime.textContent = `${mins}:${secs}`;
  const scene = getSceneAt(progress);
  scText.textContent = scene.label;
}

// ── ScrollTrigger for scrub ───────────────────────────────────────────────────
resizeCanvas();
window.addEventListener("resize", resizeCanvas);
drawFrame(0);

if (!reduced) {
  ScrollTrigger.create({
    trigger: "#scrub-section",
    start: "top top",
    end: "bottom bottom",
    scrub: 0.5,
    onUpdate: (self) => {
      currentProgress = self.progress;
      drawFrame(currentProgress);
      updateUI(currentProgress);
    },
  });
} else {
  // In reduced motion mode, just show a static frame and update on scroll
  window.addEventListener("scroll", () => {
    const section = document.getElementById("scrub-section");
    const rect = section.getBoundingClientRect();
    const spacer = section.querySelector(".scrub-spacer");
    const scrollable = section.offsetHeight - window.innerHeight;
    const prog = Math.max(0, Math.min(1, -rect.top / spacer.offsetHeight));
    drawFrame(prog);
    updateUI(prog);
  });
}

// ── Intro animations ──────────────────────────────────────────────────────────
if (!reduced) {
  gsap.set(".intro h1, .intro p, .scroll-hint", { opacity: 0, y: 20 });
  gsap
    .timeline({ delay: 0.3, defaults: { ease: "expo.out" } })
    .to(".intro h1", { opacity: 1, y: 0, duration: 1 })
    .to(".intro p", { opacity: 1, y: 0, duration: 0.8 }, "-=0.5")
    .to(".scroll-hint", { opacity: 1, y: 0, duration: 0.7 }, "-=0.4");
}

// ── Chapter reveals ───────────────────────────────────────────────────────────
if (!reduced) {
  document.querySelectorAll(".chapter").forEach((ch, i) => {
    gsap.set(ch, { opacity: 0, x: -20 });
    gsap.to(ch, {
      opacity: 1,
      x: 0,
      duration: 0.7,
      ease: "expo.out",
      delay: i * 0.1,
      scrollTrigger: {
        trigger: ".chapters",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });
  });
}

// ── Motion toggle ─────────────────────────────────────────────────────────────
window.addEventListener("motion-preference", (e) => {
  gsap.globalTimeline.paused(e.detail.reduced);
});

snippets.css:
:root {
  color-scheme: light;
  --bg: #f7f1e8;
  --panel: rgba(255, 255, 255, 0.82);
  --stroke: rgba(82, 57, 46, 0.2);
  --text: #3b2a22;
  --muted: rgba(59, 42, 34, 0.6);
  --accent: #b36b3e;
  --accent-2: #f4b183;
  --accent-3: #7b4f35;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Quicksand", sans-serif;
  background: radial-gradient(circle at 10% 10%, rgba(244, 177, 131, 0.28), transparent 55%),
    radial-gradient(circle at 90% 20%, rgba(179, 107, 62, 0.2), transparent 60%), #f6efe6;
  color: var(--text);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

#bg {
  position: fixed;
  inset: 0;
  z-index: 0;
}

.loader {
  position: fixed;
  inset: 0;
  background: #f6efe6;
  display: grid;
  place-items: center;
  gap: 18px;
  z-index: 999;
  color: var(--text);
  font-family: "Playfair Display", serif;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.loader-ring {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  border: 2px solid rgba(179, 107, 62, 0.4);
  border-top-color: var(--accent);
  animation: spin 1.4s linear infinite;
}

.loader-cup {
  position: absolute;
  width: 36px;
  height: 36px;
  border-radius: 8px 8px 12px 12px;
  border: 2px solid var(--accent-3);
  background: rgba(179, 107, 62, 0.1);
  display: grid;
  place-items: center;
}

.steam {
  position: absolute;
  width: 6px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(179, 107, 62, 0.5);
  top: -20px;
  animation: steam 1.2s ease-in-out infinite;
}

.steam:nth-child(2) {
  left: 12px;
  animation-delay: 0.2s;
}

.steam:nth-child(3) {
  left: -12px;
  animation-delay: 0.4s;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes steam {
  0%,
  100% {
    opacity: 0;
    transform: translateY(0);
  }
  50% {
    opacity: 1;
    transform: translateY(-8px);
  }
}

.topbar {
  position: sticky;
  top: 16px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin: 0 clamp(16px, 4vw, 60px);
  padding: 16px 24px;
  border-radius: 999px;
  background: rgba(255, 250, 243, 0.85);
  backdrop-filter: blur(18px);
  border: 1px solid rgba(179, 107, 62, 0.2);
  box-shadow: 0 18px 40px rgba(82, 57, 46, 0.15);
}

.brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.mark {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: linear-gradient(140deg, var(--accent), var(--accent-2));
  display: grid;
  place-items: center;
  font-weight: 700;
  color: #fff7ef;
  font-family: "Playfair Display", serif;
}

.brand-title {
  font-family: "Playfair Display", serif;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.85rem;
  margin: 0;
}

.brand-sub {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.nav {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.nav a {
  color: var(--muted);
  position: relative;
}

.nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 2px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.nav a:hover::after {
  transform: scaleX(1);
}

.cta {
  padding: 0.5rem 1.3rem;
  border-radius: 999px;
  border: 1px solid rgba(179, 107, 62, 0.5);
  background: rgba(179, 107, 62, 0.12);
  color: var(--text);
}

.page {
  position: relative;
  z-index: 2;
  padding: 0 clamp(20px, 6vw, 80px) 80px;
}

.hero {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 40px;
  padding: 80px 0 40px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.35em;
  font-size: 0.7rem;
  color: var(--accent);
  font-family: "Playfair Display", serif;
}

.hero-copy h1 {
  font-family: "Playfair Display", serif;
  font-size: clamp(2.6rem, 5vw, 4.6rem);
  margin: 16px 0;
}

.lead {
  color: var(--muted);
  line-height: 1.7;
  max-width: 55ch;
}

.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 24px;
}

.btn {
  padding: 0.85rem 1.6rem;
  border-radius: 999px;
  border: 1px solid rgba(59, 42, 34, 0.25);
  background: transparent;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
  cursor: pointer;
}

.btn.primary {
  background: linear-gradient(120deg, rgba(179, 107, 62, 0.25), rgba(244, 177, 131, 0.35));
  border-color: rgba(179, 107, 62, 0.6);
}

.btn.ghost {
  border-color: rgba(244, 177, 131, 0.55);
}

.hero-metrics {
  margin-top: 24px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.hero-metrics div {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 14px;
  padding: 14px;
}

.hero-panel {
  display: grid;
  gap: 18px;
}

.panel-card {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 18px;
  padding: 20px;
  box-shadow: 0 0 30px rgba(179, 107, 62, 0.12);
}

.panel-title {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
  color: var(--muted);
}

.marquee {
  overflow: hidden;
  border-top: 1px solid rgba(82, 57, 46, 0.1);
  border-bottom: 1px solid rgba(82, 57, 46, 0.1);
}

.marquee-track {
  display: flex;
  gap: 48px;
  padding: 16px 0;
  text-transform: uppercase;
  letter-spacing: 0.35em;
  font-size: 0.65rem;
  color: var(--muted);
  white-space: nowrap;
}

.section {
  padding: 64px 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 24px;
}

.section-header p {
  color: var(--muted);
}

.section-header.subhead {
  margin-top: 28px;
}

.menu-grid,
.service-grid {
  display: grid;
  gap: 24px;
  margin-top: 28px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.menu-card,
.service-card {
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--stroke);
  border-radius: 18px;
  padding: 22px;
}

.menu-card h3,
.service-card h3 {
  margin: 14px 0 10px;
}

.menu-card p,
.service-card p {
  color: var(--muted);
  line-height: 1.6;
}

.menu-meta {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 0.85rem;
}

.shop-layout {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 320px);
  align-items: start;
}

.shop-grid,
.people-grid {
  display: grid;
  gap: 22px;
  margin-top: 24px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.product-card,
.person-card {
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid var(--stroke);
  border-radius: 18px;
  padding: 20px;
  display: grid;
  gap: 10px;
}

.product-image {
  height: 140px;
  border-radius: 14px;
  background: linear-gradient(140deg, rgba(179, 107, 62, 0.4), rgba(244, 177, 131, 0.4));
  border: 1px solid rgba(179, 107, 62, 0.25);
  display: grid;
  place-items: center;
  font-family: "Playfair Display", serif;
  font-size: 1.2rem;
  color: var(--accent-3);
}

.product-meta {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 0.85rem;
}

.product-price {
  font-family: "Playfair Display", serif;
  font-size: 1.2rem;
  color: var(--accent-3);
}

.add-btn {
  margin-top: 6px;
  padding: 0.6rem 1rem;
  border-radius: 999px;
  border: 1px solid rgba(179, 107, 62, 0.4);
  background: rgba(179, 107, 62, 0.12);
  cursor: pointer;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
}

.cart {
  background: rgba(255, 255, 255, 0.85);
  border: 1px solid var(--stroke);
  border-radius: 18px;
  padding: 20px;
  display: grid;
  gap: 14px;
  position: sticky;
  top: 110px;
}

.cart-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.cart-items {
  display: grid;
  gap: 10px;
  max-height: 280px;
  overflow: auto;
}

.cart-item {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--muted);
}

.cart-total {
  display: flex;
  justify-content: space-between;
  font-weight: 600;
}

.person-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--muted);
}

.avatar {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: linear-gradient(140deg, var(--accent), var(--accent-2));
  display: grid;
  place-items: center;
  color: #fff7ef;
  font-weight: 700;
  font-family: "Playfair Display", serif;
}

.split {
  display: grid;
  gap: 28px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
}

.panel {
  padding: 26px;
  background: rgba(255, 255, 255, 0.75);
  border-radius: 18px;
  border: 1px solid rgba(179, 107, 62, 0.2);
}

.panel ul {
  margin: 16px 0 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.7;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 18px;
}

.chips span {
  padding: 0.45rem 0.9rem;
  border-radius: 999px;
  border: 1px solid rgba(179, 107, 62, 0.4);
  font-size: 0.75rem;
}

.stats {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  text-align: center;
}

.stats h2 {
  font-family: "Playfair Display", serif;
  font-size: 2.4rem;
  margin: 0 0 8px;
  color: var(--accent);
}

.contact {
  display: grid;
  gap: 32px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
}

