}
.pixel-btn::after {
  content: "";
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 100%;
  height: 100%;
  border: 3px solid;
  border-color: inherit;
  opacity: 0.3;
  z-index: -1;
  transition: right 0.1s steps(2), bottom 0.1s steps(2);
}
