*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #0a0c14;
  --text: #f0f4fb;
  --muted: #8a95a8;
  --accent: #86e8ff;
  --border: #263249;
}

.hidden-svg {
  position: absolute;
  width: 0;
  height: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", "SF Pro Display", system-ui, sans-serif;
  min-height: 100vh;
}

/* Overlays */
.overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 100;
}

.noise-overlay {
  filter: url(#noise-filter);
  opacity: 0.06;
  mix-blend-mode: overlay;
  animation: noise-shift 0.5s steps(4) infinite;
}

@keyframes noise-shift {
  0% {
    transform: translate(0, 0);
  }
  25% {
    transform: translate(-2px, 1px);
  }
  50% {
    transform: translate(1px, -1px);
  }
  75% {
    transform: translate(-1px, 2px);
  }
}

.grain-canvas-overlay {
  opacity: 0.08;
  mix-blend-mode: overlay;
}
.grain-canvas-overlay canvas {
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.scanlines-overlay {
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.15) 2px,
    rgba(0, 0, 0, 0.15) 4px
  );
  opacity: 0; /* off by default */
}

.vignette-overlay {
  background: radial-gradient(ellipse at center, transparent 50%, rgba(0, 0, 0, 0.6) 100%);
  opacity: 1;
}

.overlay.off {
  opacity: 0 !important;
}

.reduced-motion .noise-overlay {
  animation: none;
}

/* Page */
.page {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
  padding: 5rem 2rem 4rem;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}
.eyebrow {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--accent);
  margin-bottom: 1rem;
}
h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.subtitle {
  font-size: clamp(0.9rem, 2vw, 1.05rem);
  color: var(--muted);
  max-width: 480px;
  margin: 0.75rem auto 0;
  line-height: 1.6;
}

/* Controls */
.controls {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
}
.toggle {
  display: flex;
