  justify-content: space-between;
  align-items: center;
}

.footer span {
  font-family: "Geist Mono", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  color: var(--muted);
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
  }
  .hf-img--main {
    aspect-ratio: 16 / 9;
  }
  .series-item {
    grid-template-columns: 60px 1fr 100px;
  }
  .si-link {
    display: none;
  }
  .info-inner {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
  .info-portrait {
    align-items: flex-start;
  }
  .contact-body {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 1.25rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .hero,
  .work-section,
  .series-section,
  .info-section,
  .contact-section {
    padding: 4rem 1.5rem;
  }
  .masonry-grid {
    grid-template-columns: 1fr 1fr;
  }
  .photo-item--tall,
  .photo-item--wide {
    grid-column: auto;
    grid-row: auto;
  }
  .series-item {
    grid-template-columns: 1fr;
  }
  .si-number,
  .si-preview {
    display: none;
  }
  .info-portrait {
    display: none;
  }
  .footer {
    padding: 1.5rem;
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

/* ── Reduced Motion ── */
html.reduced-motion .scroll-line::after,
html.reduced-motion .ca-dot {
  animation: none !important;
}

html.reduced-motion .photo-item:hover .pi-img {
  transform: none !important;
}

html.reduced-motion .photo-item:hover .pi-caption {
  opacity: 1;
  transform: none;
}

html.reduced-motion * {
  transition-duration: 0.01ms !important;
}

