  .to(heroLabel, { opacity: 1, y: 0, duration: dur(0.6), ease: "expo.out" })
  .to(
    heroSplit.chars,
    {
      opacity: 1,
      y: 0,
      rotateX: 0,
      duration: dur(0.6),
