/**
 * 34-multimedia-portfolio / main.js
 * Multimedia Engineer Portfolio — GSAP FLIP, Canvas waveform,
 * hero particle field, Lenis smooth scroll.
 */

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { Flip } from "gsap/Flip";
import { SplitText } from "gsap/SplitText";
import Lenis from "lenis";

gsap.registerPlugin(ScrollTrigger, Flip, SplitText);

/* ── Shell ─────────────────────────────────────────────────────── */
initDemoShell({
  title: "Multimedia Engineer Portfolio",
  category: "pages",
  tech: ["gsap", "flip", "canvas-2d", "lenis", "scrolltrigger"],
});

/* ── Helpers ───────────────────────────────────────────────────── */
const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

/** Respect reduced-motion for durations */
function dur(base) {
  return prefersReducedMotion() ? 0 : base;
}

/* ══════════════════════════════════════════════════════════════════
   LENIS + SCROLLTRIGGER WIRING
   ══════════════════════════════════════════════════════════════════ */
const lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

/* ══════════════════════════════════════════════════════════════════
   HERO — PARTICLE WAVEFORM CANVAS
   ══════════════════════════════════════════════════════════════════ */
(function initHeroCanvas() {
  const canvas = $("#heroCanvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");

  let W, H;
  let mouseX = 0.5; // 0–1, normalised
  let mouseY = 0.5;
  let raf;
  let startTime = performance.now();

  /* ── Particles ─────────────────────────────────────────────── */
  const PARTICLE_COUNT = 220;
  const particles = [];

  class Particle {
    constructor(i) {
      this.index = i;
      this.reset();
    }
    reset() {
      // Distribute along the horizontal axis, wave-shaped Y
      this.baseX = (this.index / PARTICLE_COUNT) * 2; // 0..2 → we'll use W
      this.baseXpx = 0; // set on resize
      this.baseYpx = 0;
      this.x = 0;
      this.y = 0;
      this.vx = 0;
      this.vy = 0;
      this.radius = Math.random() * 2.2 + 1;
      // Each particle gets its own phase & colour
      this.phase = (this.index / PARTICLE_COUNT) * Math.PI * 8;
      const hues = ["#ff3cac", "#00f5d4", "#f5f700", "#ff6b2b"];
      this.color = hues[Math.floor(Math.random() * hues.length)];
    }
    update(t, mxPx, myPx) {
      // Waveform base position
      const waveAmp = H * 0.18;
      const freq = 1.8 + mouseX * 1.2; // frequency shifts with mouse X
      this.baseXpx = (this.index / PARTICLE_COUNT) * W;
      this.baseYpx =
        H / 2 +
        Math.sin(this.baseXpx * freq * 0.005 + t * 0.8 + this.phase) * waveAmp * 0.8 +
        Math.sin(this.baseXpx * freq * 0.012 + t * 1.4 + this.phase) * waveAmp * 0.4;

      // Repulsion from mouse
      const dx = this.x - mxPx;
      const dy = this.y - myPx;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const repelRadius = prefersReducedMotion() ? 0 : 90;

      if (dist < repelRadius && dist > 0) {
        const force = (repelRadius - dist) / repelRadius;
        const angle = Math.atan2(dy, dx);
        this.vx += Math.cos(angle) * force * 5;
        this.vy += Math.sin(angle) * force * 5;
      }

      // Spring back to waveform position
      const springStr = 0.07;
      this.vx += (this.baseXpx - this.x) * springStr;
      this.vy += (this.baseYpx - this.y) * springStr;

      // Damping
      this.vx *= 0.82;
      this.vy *= 0.82;

      this.x += this.vx;
      this.y += this.vy;
    }
    draw(ctx) {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fillStyle = this.color;
      ctx.shadowBlur = 8;
      ctx.shadowColor = this.color;
      ctx.fill();
      ctx.shadowBlur = 0;
    }
  }

  function buildParticles() {
    particles.length = 0;
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const p = new Particle(i);
      p.x = (i / PARTICLE_COUNT) * W;
      p.y = H / 2;
      particles.push(p);
    }
  }

  function resize() {
    W = canvas.width = canvas.offsetWidth;
    H = canvas.height = canvas.offsetHeight;
    buildParticles();
  }

  function loop() {
    raf = requestAnimationFrame(loop);
    const t = (performance.now() - startTime) / 1000;
    const mxPx = mouseX * W;
    const myPx = mouseY * H;

    ctx.clearRect(0, 0, W, H);

    // Subtle radial gradient atmosphere
    const grd = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, W * 0.7);
    grd.addColorStop(0, "rgba(255,60,172,0.05)");
    grd.addColorStop(0.5, "rgba(0,245,212,0.03)");
    grd.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, W, H);

    particles.forEach((p) => {
      p.update(t, mxPx, myPx);
      p.draw(ctx);
    });
  }

  // Mouse tracking on hero section
  const heroEl = $("#hero");
  heroEl.addEventListener("mousemove", (e) => {
    const rect = canvas.getBoundingClientRect();
    mouseX = (e.clientX - rect.left) / rect.width;
    mouseY = (e.clientY - rect.top) / rect.height;
  });
  heroEl.addEventListener("mouseleave", () => {
    mouseX = 0.5;
    mouseY = 0.5;
  });

  window.addEventListener("resize", resize);
  resize();
  loop();
})();

/* ══════════════════════════════════════════════════════════════════
   HERO — GLITCH HOVER
   ══════════════════════════════════════════════════════════════════ */
(function initGlitch() {
  const nameEl = $(".hero-name");
  if (!nameEl) return;

  // Wrap name element in a glitch container if not already in HTML
  // The HTML already positions glitch spans absolutely inside .hero-content
  // We add/remove .is-hovered on the wrapper
  const wrapper = document.createElement("div");
  wrapper.className = "hero-name-wrapper";
  nameEl.parentNode.insertBefore(wrapper, nameEl);
  // Move name and glitch spans into wrapper
  const glitch1 = $(".hero-name-glitch--1");
  const glitch2 = $(".hero-name-glitch--2");
  wrapper.appendChild(nameEl);
  if (glitch1) wrapper.appendChild(glitch1);
  if (glitch2) wrapper.appendChild(glitch2);

  wrapper.addEventListener("mouseenter", () => {
    if (!prefersReducedMotion()) wrapper.classList.add("is-hovered");
  });
  wrapper.addEventListener("mouseleave", () => {
    wrapper.classList.remove("is-hovered");
  });

  // Motion preference change
  window.addEventListener("motion-preference", () => {
    wrapper.classList.remove("is-hovered");
  });
})();

/* ══════════════════════════════════════════════════════════════════
   HERO — GSAP ENTRANCE ANIMATIONS
   ══════════════════════════════════════════════════════════════════ */
(function initHeroEntrance() {
  const eyebrow = $(".hero-eyebrow");
  const nameEl = $(".hero-name");
  const tagline = $(".hero-tagline");
  const scrollCue = $(".hero-scroll-cue");

  const tl = gsap.timeline({ delay: 0.15 });

  tl.to(eyebrow, {
    opacity: 1,
    y: 0,
    duration: dur(0.6),
    ease: "expo.out",
    onStart() {
      gsap.set(eyebrow, { y: 12 });
    },
  });

  tl.to(
    nameEl,
    {
      opacity: 1,
      y: 0,
      duration: dur(0.9),
      ease: "expo.out",
      onStart() {
        gsap.set(nameEl, { y: 30 });
      },
    },
    "-=0.35"
  );

  tl.to(
    tagline,
    {
      opacity: 1,
      y: 0,
      duration: dur(0.7),
      ease: "expo.out",
      onStart() {
        gsap.set(tagline, { y: 16 });
      },
    },
    "-=0.55"
  );

  tl.to(
    scrollCue,
    {
      opacity: 1,
      duration: dur(0.6),
      ease: "power2.out",
    },
    "-=0.2"
  );
})();

/* ══════════════════════════════════════════════════════════════════
   GALLERY — GSAP FLIP LAYOUT TOGGLE
   ══════════════════════════════════════════════════════════════════ */
(function initGallery() {
  const gallery = $("#mediaGallery");
  const toggleBtn = $("#layout-toggle");
  if (!gallery || !toggleBtn) return;

  toggleBtn.addEventListener("click", () => {
    // Capture state BEFORE class change
    const state = Flip.getState(".media-card");

    gallery.classList.toggle("list-view");
    toggleBtn.classList.toggle("is-list");

    // Animate from old state to new
    Flip.from(state, {
      duration: dur(0.65),
      ease: "expo.out",
      stagger: { each: dur(0.06) },
      absolute: true,
      onEnter: (els) => gsap.fromTo(els, { opacity: 0 }, { opacity: 1, duration: dur(0.4) }),
      onLeave: (els) => gsap.to(els, { opacity: 0, duration: dur(0.2) }),
    });
  });
})();

/* ══════════════════════════════════════════════════════════════════
   SCROLL REVEAL — MEDIA CARDS
   ══════════════════════════════════════════════════════════════════ */
(function initCardReveal() {
  const cards = $$(".media-card");
  if (!cards.length) return;

  cards.forEach((card, i) => {
    gsap.to(card, {
      opacity: 1,
      y: 0,
      duration: dur(0.7),
      ease: "expo.out",
      delay: i * dur(0.1),
      scrollTrigger: {
        trigger: card,
        start: "top 88%",
        toggleActions: "play none none none",
      },
    });
  });
})();

/* ══════════════════════════════════════════════════════════════════
   CONTACT SECTION — SCROLL REVEAL
   ══════════════════════════════════════════════════════════════════ */
(function initContactReveal() {
  const heading = $(".contact-heading");
  const sub = $(".contact-sub");
  const links = $(".contact-links");
  if (!heading) return;

  const tl = gsap.timeline({
    scrollTrigger: {
      trigger: "#contact",
      start: "top 78%",
      toggleActions: "play none none none",
    },
  });

  tl.to(heading, {
    opacity: 1,
    y: 0,
    duration: dur(0.9),
    ease: "expo.out",
    onStart() {
      gsap.set(heading, { y: 40 });
    },
  });
  tl.to(
    sub,
    {
      opacity: 1,
      y: 0,
      duration: dur(0.6),
      ease: "expo.out",
      onStart() {
        gsap.set(sub, { y: 16 });
      },
    },
    "-=0.55"
  );
  tl.to(
    links,
    {
      opacity: 1,
      y: 0,
      duration: dur(0.5),
      ease: "expo.out",
      onStart() {
        gsap.set(links, { y: 12 });
      },
    },
    "-=0.4"
  );
})();

/* ══════════════════════════════════════════════════════════════════
   WAVEFORM VISUALIZER CANVAS
   ══════════════════════════════════════════════════════════════════ */
(function initWaveform() {
  const canvas = $("#waveformCanvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");

  let W, H;
  let mouseX = 0; // raw px, updated on section mousemove
  let animId;
  let startTime = performance.now();

  const waves = [
    { freq: 0.022, amp: 0.15, speed: 1.0, color: "#ff3cac", lineWidth: 2.5 },
    { freq: 0.034, amp: 0.1, speed: 1.6, color: "#00f5d4", lineWidth: 2 },
    { freq: 0.055, amp: 0.06, speed: 2.3, color: "#f5f700", lineWidth: 1.5 },
  ];

  function resize() {
    W = canvas.width = canvas.offsetWidth;
    H = canvas.height = canvas.offsetHeight;
    mouseX = W / 2;
  }

  function drawWave(t) {
    ctx.clearRect(0, 0, W, H);

    const centerY = H / 2;
    const mxInfluence = (mouseX / W - 0.5) * 0.5;

    waves.forEach((wave, wi) => {
      const amp = wave.amp * H;

      // Create horizontal gradient for this wave
      const grd = ctx.createLinearGradient(0, 0, W, 0);
      if (wi === 0) {
        grd.addColorStop(0, "rgba(255,60,172,0)");
        grd.addColorStop(0.3, "#ff3cac");
        grd.addColorStop(0.7, "#ff6b2b");
        grd.addColorStop(1, "rgba(255,107,43,0)");
      } else if (wi === 1) {
        grd.addColorStop(0, "rgba(0,245,212,0)");
        grd.addColorStop(0.25, "#00f5d4");
        grd.addColorStop(0.75, "#ff3cac");
        grd.addColorStop(1, "rgba(255,60,172,0)");
      } else {
        grd.addColorStop(0, "rgba(245,247,0,0)");
        grd.addColorStop(0.4, "#f5f700");
        grd.addColorStop(0.6, "#00f5d4");
        grd.addColorStop(1, "rgba(0,245,212,0)");
      }

      ctx.beginPath();
      ctx.strokeStyle = grd;
      ctx.lineWidth = wave.lineWidth;
      ctx.shadowBlur = 16;
      ctx.shadowColor = wave.color;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";

      for (let x = 0; x <= W; x += 2) {
        const freqMod = wave.freq + mxInfluence;
        const y =
          centerY +
          Math.sin(x * freqMod + t * wave.speed) * amp +
          Math.sin(x * freqMod * 2.1 + t * wave.speed * 0.5) * amp * 0.3;
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }

      ctx.stroke();
      ctx.shadowBlur = 0;
    });

    // Subtle center line
    ctx.beginPath();
    ctx.setLineDash([4, 8]);
    ctx.strokeStyle = "rgba(68,68,102,0.5)";
    ctx.lineWidth = 1;
    ctx.moveTo(0, centerY);
    ctx.lineTo(W, centerY);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function loop() {
    animId = requestAnimationFrame(loop);
    if (prefersReducedMotion()) {
      // Static single frame
      drawWave(0);
      cancelAnimationFrame(animId);
      return;
    }
    const t = (performance.now() - startTime) / 1000;
    drawWave(t);
  }

  // Mousemove on the waveform section
  const wfSection = $("#waveform");
  wfSection.addEventListener("mousemove", (e) => {
    const rect = canvas.getBoundingClientRect();
    mouseX = e.clientX - rect.left;
  });
  wfSection.addEventListener("mouseleave", () => {
    mouseX = W / 2;
  });

  // Restart animation on motion preference change
  window.addEventListener("motion-preference", () => {
    cancelAnimationFrame(animId);
    if (!prefersReducedMotion()) {
      startTime = performance.now();
      loop();
    } else {
      drawWave(0);
    }
  });

  window.addEventListener("resize", resize);
  resize();
  loop();
})();

/* ══════════════════════════════════════════════════════════════════
   DISCIPLINES MARQUEE — CSS animation, paused when reduced-motion
   ══════════════════════════════════════════════════════════════════ */
(function initDisciplinesMarquee() {
  const marquee = $("#disciplinesMarquee");
  if (!marquee) return;

  // If user prefers reduced motion, freeze the animation immediately
  function applyMotion() {
    if (prefersReducedMotion()) {
      marquee.style.setProperty("--marquee-play-state", "paused");
    } else {
      marquee.style.removeProperty("--marquee-play-state");
    }
  }

  applyMotion();
  window.addEventListener("motion-preference", applyMotion);
})();

/* ══════════════════════════════════════════════════════════════════
   SECTION TITLE ANIMATIONS
   ══════════════════════════════════════════════════════════════════ */
(function initSectionTitles() {
  const titles = $$(".section-title");
  titles.forEach((title) => {
    gsap.fromTo(
      title,
      { opacity: 0, x: -30 },
      {
        opacity: 1,
        x: 0,
        duration: dur(0.8),
        ease: "expo.out",
        scrollTrigger: {
          trigger: title,
          start: "top 85%",
          toggleActions: "play none none none",
        },
      }
    );
  });
})();

/* ══════════════════════════════════════════════════════════════════
   REDUCED MOTION HANDLING (runtime toggle)
   ══════════════════════════════════════════════════════════════════ */
window.addEventListener("motion-preference", () => {
  if (prefersReducedMotion()) {
    document.documentElement.classList.add("reduced-motion");
    lenis.stop();
  } else {
    document.documentElement.classList.remove("reduced-motion");
    lenis.start();
  }
});

// Apply on load if needed
if (prefersReducedMotion()) {
  document.documentElement.classList.add("reduced-motion");
  lenis.stop();
}

snippets.css:
/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0a0a0a;
  --surface: #131210;
  --text: #f2ede8;
  --muted: #8a8078;
  --rust: #c4622d;
  --amber: #d4843a;
  --border: #2a2520;
  --font-display: "Libre Baskerville", Georgia, serif;
  --font-mono: "IBM Plex Mono", "Courier New", monospace;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-display);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Grain Canvas ──────────────────────────────────────────────────────────── */
#grain-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9998;
  opacity: 0.04;
  mix-blend-mode: overlay;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 48px;
  background: rgba(10, 10, 10, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  color: var(--text);
  font-weight: 500;
}

.nav-links {
  display: flex;
  gap: 36px;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--muted);
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.2s;
}
.nav-links a:hover {
  color: var(--text);
}

.nav-watch {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--rust);
  text-decoration: none;
  border: 1px solid var(--rust);
  padding: 7px 18px;
  transition: background 0.2s, color 0.2s;
}
.nav-watch:hover {
  background: var(--rust);
  color: var(--bg);
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 120px 48px 80px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

.hero-inner {
  max-width: 900px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 32px;
}

.hero-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  color: var(--muted);
  text-transform: uppercase;
}

.hero-director {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--rust);
  text-transform: uppercase;
}

.hero-h1 {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
  overflow: hidden;
}

.h1-word {
  display: block;
  clip-path: inset(0 0 0 0);
}

.h1-word--accent {
  color: var(--rust);
  font-style: italic;
}

.hero-details {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.hd-item {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.hd-sep {
  color: var(--border);
}

.hero-tagline {
  font-style: italic;
  font-size: 1.125rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.hero-scroll {
  position: absolute;
  bottom: 40px;
  left: 48px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.hero-scroll span {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  color: var(--muted);
  text-transform: uppercase;
}

.scroll-line {
  width: 1px;
  height: 48px;
  background: var(--muted);
  transform-origin: top;
  animation: scroll-grow 1.5s ease-in-out infinite alternate;
}

@keyframes scroll-grow {
  from {
    transform: scaleY(0.3);
    opacity: 0.4;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

/* ── Section Labels ────────────────────────────────────────────────────────── */
.section-num {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--rust);
}

.section-title {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--muted);
  text-transform: uppercase;
  margin-left: 12px;
}

/* ── Synopsis ──────────────────────────────────────────────────────────────── */
.synopsis-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.synopsis-inner {
  max-width: 860px;
  margin: 0 auto;
}

.synopsis-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.synopsis-quote {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-style: italic;
  line-height: 1.3;
  color: var(--text);
  border-left: 3px solid var(--rust);
  padding-left: 32px;
  margin-bottom: 48px;
}

.synopsis-text p {
  font-size: 1rem;
  line-height: 1.8;
  color: var(--muted);
  max-width: 640px;
}
.synopsis-text p + p {
  margin-top: 20px;
}

/* ── Chapters ──────────────────────────────────────────────────────────────── */
.chapters-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.chapters-header {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.chapter-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 0 32px;
  padding: 40px 0;
  position: relative;
}

.ch-num {
  font-size: 3rem;
  font-weight: 700;
  font-style: italic;
  color: var(--border);
  line-height: 1;
  padding-top: 4px;
}

.ch-content {
  padding-bottom: 32px;
}

.ch-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 6px;
}

.ch-runtime {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  color: var(--rust);
  display: block;
  margin-bottom: 16px;
}

.ch-desc {
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--muted);
  max-width: 580px;
}

.ch-rule {
  grid-column: 1 / -1;
  height: 1px;
  background: var(--border);
}

/* ── Film Stills ───────────────────────────────────────────────────────────── */
.stills-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.stills-header {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.stills-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: 220px 220px;
  gap: 12px;
}

.still-item {
  position: relative;
  overflow: hidden;
}

.still-item--tall {
  grid-row: span 2;
}
.still-item--wide {
  grid-column: span 2;
}

.si-frame {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

/* Film still color treatments */
.si-frame--1 {
  background: #2a1f15;
}
.si-frame--2 {
  background: #0d0d12;
}
.si-frame--3 {
  background: #141d1f;
}
.si-frame--4 {
  background: #1a160f;
}
.si-frame--5 {
  background: #0a0d0a;
}
.si-frame--6 {
  background: #12181e;
}

/* Film scratch marks via pseudo */
.si-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0%,
    transparent 48%,
    rgba(255, 255, 255, 0.015) 48%,
    rgba(255, 255, 255, 0.015) 50%,
    transparent 50%
  );
}

.si-frame::after {
  content: "";
  position: absolute;
  top: 0;
  left: 8%;
  width: 1px;
  height: 100%;
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 38px 0 0 rgba(255, 255, 255, 0.025), 72px 0 0 rgba(255, 255, 255, 0.015);
}

/* Vignette on frames */
.si-frame--1::before {
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.7);
}

.still-item figcaption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px 16px;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  color: rgba(242, 237, 232, 0.5);
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  text-transform: uppercase;
}

/* ── Credits ───────────────────────────────────────────────────────────────── */
.credits-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.credits-inner {
  max-width: 720px;
}

.credits-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.credits-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.credit-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
}

.cr-role {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--muted);
  text-transform: uppercase;
  flex-shrink: 0;
  width: 200px;
}

.cr-name {
  font-size: 1.05rem;
  font-style: italic;
  color: var(--text);
  text-align: right;
}

/* ── Festivals ─────────────────────────────────────────────────────────────── */
.festivals-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.festivals-inner {
  max-width: 1100px;
}

.festivals-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.festivals-row {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.festival-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 28px 32px;
  border: 1px solid var(--border);
  flex: 1;
  min-width: 140px;
}

.festival-badge--winner {
  border-color: var(--rust);
}

.fb-name {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  color: var(--text);
}

.fb-award {
  font-size: 0.75rem;
  font-style: italic;
  color: var(--muted);
  text-align: center;
}

.festival-badge--winner .fb-award {
  color: var(--rust);
}

.fb-year {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-top: 4px;
}

/* ── Watch / CTA ───────────────────────────────────────────────────────────── */
.watch-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.watch-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  max-width: 1100px;
  align-items: start;
}

.watch-h2 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  line-height: 1.05;
  font-weight: 700;
  margin-bottom: 20px;
}

.watch-h2 em {
  font-style: italic;
  color: var(--rust);
}

.watch-text > p {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 40px;
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
}

.watch-btns {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-film {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 14px 28px;
  background: var(--rust);
  color: var(--bg);
  transition: background 0.2s, color 0.2s;
  display: inline-block;
}
.btn-film:hover {
  background: var(--amber);
}

.btn-film--outline {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-film--outline:hover {
  border-color: var(--rust);
  color: var(--rust);
  background: transparent;
}

/* Watch Terminal */
.watch-terminal {
  background: #0d0d0d;
  border: 1px solid var(--border);
  font-family: var(--font-mono);
}

.wt-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}

.wt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  display: inline-block;
}

.wt-title {
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-left: 8px;
}

.wt-body {
  padding: 20px 20px 24px;
}

.wt-body p {
  font-size: 0.7rem;
  line-height: 2;
  color: var(--muted);
}

.wt-loc {
  color: var(--rust);
