/* ── Demo 53: Art Gallery — Contemporary White Museum ── */
:root {
  --white: #ffffff;
  --off-white: #f8f7f5;
  --light: #f0eeea;
  --border: #e0ddd8;
  --text: #1a1714;
  --muted: #8a8580;
  --taupe: #c8c4be;
  --gold: #b8960c;
  --gold-light: #f0d060;
}
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: "Cormorant Garamond", Georgia, serif;
  background: var(--white);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  line-height: 1.6;
  overflow-x: hidden;
}
.section-label {
  display: block;
  font-family: "DM Mono", monospace;
  font-size: 0.62rem;
  font-weight: 400;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 1rem;
}
.btn-dark {
  display: inline-block;
  padding: 0.85rem 2rem;
  background: var(--text);
  color: var(--white);
  font-family: "DM Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 2px;
  transition: background 0.2s, transform 0.2s;
}
.btn-dark:hover {
  background: var(--gold);
  transform: translateY(-2px);
}

/* Nav */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 3rem;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav-logo {
  font-size: 1rem;
  font-weight: 300;
  font-style: italic;
  color: var(--text);
  text-decoration: none;
  letter-spacing: 0.05em;
}
.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}
.nav-links a {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}
.nav-links a:hover {
  color: var(--text);
}
.nav-tickets {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  color: var(--gold);
  text-decoration: none;
  border-bottom: 1px solid rgba(184, 150, 12, 0.4);
  padding-bottom: 1px;
}

/* Hero */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 7rem 3rem 5rem;
  background: var(--off-white);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}
.hero-season {
  font-family: "DM Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  display: block;
  margin-bottom: 2rem;
}
.hero-h1 {
  font-size: clamp(3rem, 6vw, 5.5rem);
  font-weight: 300;
  line-height: 1.15;
  margin-bottom: 1.5rem;
}
.hero-h1 em {
  font-style: italic;
  color: var(--gold);
}
.hero-text p {
  font-size: 1rem;
  color: var(--muted);
  line-height: 1.85;
  max-width: 380px;
  margin-bottom: 2.5rem;
}
.hero-artwork {
  position: relative;
}
.ha-frame {
  position: absolute;
  border-radius: 2px;
}
.ha-frame--main {
  top: 0;
  left: 0;
  right: 15%;
  bottom: 20%;
  background: linear-gradient(145deg, #c8c0b4 0%, #a8a094 40%, #888078 100%);
  min-height: 400px;
}
.ha-frame--accent {
  bottom: 0;
  right: 0;
  width: 40%;
  height: 50%;
  background: linear-gradient(135deg, #e0d8cc 0%, #c8c0b4 100%);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
}
.ha-label {
  position: absolute;
  bottom: 60%;
  left: 0;
  right: 15%;
  padding: 0.75rem 1rem;
  background: rgba(255, 255, 255, 0.9);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.ha-label span:first-child {
  font-size: 0.8rem;
  font-weight: 600;
}
.ha-label span:last-child {
  font-family: "DM Mono", monospace;
  font-size: 0.62rem;
  color: var(--muted);
  letter-spacing: 0.05em;
}
.hero-artwork {
  min-height: 500px;
}

/* Works */
.works-section {
  padding: 5rem 3rem;
  background: var(--white);
  border-top: 1px solid var(--border);
}
.works-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}
.works-count {
  font-family: "DM Mono", monospace;
  font-size: 0.72rem;
  color: var(--muted);
}
.works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
}
.work-item {
  background: var(--white);
  overflow: hidden;
  cursor: pointer;
  position: relative;
}
.work-item--tall {
  grid-row: span 2;
}
.work-item--wide {
  grid-column: span 2;
}
.wi-art {
  min-height: 240px;
  transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.work-item--tall .wi-art {
  min-height: 500px;
}
.work-item--wide .wi-art {
  min-height: 240px;
}
.work-item:hover .wi-art {
  transform: scale(1.04);
}
.wi-art--1 {
  background: linear-gradient(145deg, #d8d0c8, #b0a89c, #888078);
}
.wi-art--2 {
  background: linear-gradient(160deg, #c8c8c0, #a0a098, #787880);
}
.wi-art--3 {
  background: radial-gradient(ellipse at 40% 40%, #e0d0c0 0%, #c0b0a0 40%, #a09080 100%);
}
.wi-art--4 {
  background: linear-gradient(135deg, #c0c8d0, #a0a8b0, #808890);
}
.wi-art--5 {
  background: radial-gradient(ellipse at 60% 60%, #e0e0d8, #b8b8b0, #909088);
}
.wi-art--6 {
  background: linear-gradient(170deg, #d8c8c0, #b8a8a0, #988880);
}
.wi-art--7 {
  background: linear-gradient(145deg, #c8d0d8, #a0a8b0, #808890, #606870);
}
.wi-art--8 {
  background: linear-gradient(135deg, #d0d0c8, #b0b0a8, #909088);
}
.wi-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1rem 1.25rem;
  background: linear-gradient(transparent, rgba(255, 255, 255, 0.95));
  display: flex;
  align-items: flex-end;
  gap: 0.75rem;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.35s, transform 0.35s;
}
.work-item:hover .wi-caption,
.work-item:focus .wi-caption {
  opacity: 1;
  transform: translateY(0);
}
.wi-num {
  font-family: "DM Mono", monospace;
  font-size: 0.6rem;
  color: var(--gold);
  flex-shrink: 0;
}
.wi-caption strong {
  font-size: 0.88rem;
  font-weight: 600;
  display: block;
}
.wi-caption em {
  font-size: 0.72rem;
  font-family: "DM Mono", monospace;
  color: var(--muted);
  font-style: normal;
  display: block;
  letter-spacing: 0.04em;
}

/* Artists */
.artists-section {
  padding: 5rem 3rem;
  border-top: 1px solid var(--border);
}
.artists-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
  margin-top: 1.5rem;
}
.artist-row {
  display: grid;
  grid-template-columns: 40px 1fr 160px 160px 100px;
  align-items: center;
  gap: 1.5rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--border);
  transition: background 0.2s;
}
.artist-row:hover {
  background: var(--off-white);
  padding-left: 0.5rem;
}
.ar-num {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--taupe);
}
.ar-name {
  font-size: 1.25rem;
  font-weight: 300;
  font-style: italic;
}
.ar-origin,
.ar-medium {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.05em;
}
.ar-link {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--gold);
  text-decoration: none;
  text-align: right;
  transition: letter-spacing 0.2s;
}
.ar-link:hover {
  letter-spacing: 0.08em;
}

/* Visit */
.visit-section {
  padding: 5rem 3rem;
  background: var(--off-white);
  border-top: 1px solid var(--border);
}
.visit-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  max-width: 1100px;
  margin: 0 auto;
}
.visit-left h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 300;
  line-height: 1.2;
  margin-bottom: 2rem;
}
.visit-left h2 em {
  font-style: italic;
  color: var(--gold);
}
.visit-details {
  display: flex;
  flex-direction: column;
  margin-bottom: 2.5rem;
  border-top: 1px solid var(--border);
}
.vd-item {
  display: flex;
  justify-content: space-between;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.88rem;
}
.vd-item span:first-child {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.visit-map {
  position: relative;
  height: 350px;
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.vm-inner {
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 40px,
      var(--border) 40px,
      var(--border) 41px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 40px,
      var(--border) 40px,
      var(--border) 41px
    );
}
.vm-pin {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.5rem;
  color: var(--gold);
}

/* Lightbox */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: grid;
  grid-template-columns: 1fr 360px;
  background: var(--text);
}
.lightbox[hidden] {
  display: none;
}
.lb-artwork {
  height: 100%;
}
.wi-art--1.lb-art {
  background: linear-gradient(145deg, #d8d0c8, #b0a89c, #888078);
}
.lb-panel {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2.5rem;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  overflow: auto;
  background: var(--text);
  color: var(--white);
}
.lb-close {
  align-self: flex-end;
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.5);
  font-size: 1rem;
  cursor: pointer;
  font-family: "DM Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  padding: 0.5rem;
  transition: color 0.2s;
}
.lb-close:hover {
  color: white;
}
.lb-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.lb-num {
  font-family: "DM Mono", monospace;
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  color: var(--gold);
  margin-bottom: 1rem;
  display: block;
}
.lb-title {
  font-size: 2.2rem;
  font-weight: 300;
  font-style: italic;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}
.lb-artist {
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 0.3rem;
}
.lb-medium {
  font-family: "DM Mono", monospace;
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.3);
  letter-spacing: 0.08em;
  margin-bottom: 1.5rem;
}
.lb-desc {
  font-size: 0.92rem;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1.85;
}
.lb-nav {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
}
.lb-nav button {
  flex: 1;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.6);
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.2s;
}
.lb-nav button:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
  }
  .visit-inner {
    grid-template-columns: 1fr;
  }
  .works-grid {
    grid-template-columns: 1fr 1fr;
  }
  .work-item--tall {
    grid-row: auto;
  }
  .lightbox {
    grid-template-columns: 1fr;
  }
  .lb-panel {
    max-height: 40vh;
  }
}
@media (max-width: 768px) {
  .nav {
    padding: 1.25rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .works-section,
  .artists-section,
  .visit-section {
    padding: 4rem 1.5rem;
  }
  .artist-row {
    grid-template-columns: 1fr 1fr;
  }
  .ar-num,
  .ar-origin,
  .ar-medium {
    display: none;
  }
}
html.reduced-motion .work-item:hover .wi-art {
  transform: none;
