if (!reduced) {
  gsap.set(".visit-left > *", { opacity: 0, y: 20 });
  gsap.to(".visit-left > *", {
    opacity: 1,
    y: 0,
    duration: 0.8,
    stagger: 0.12,
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".visit-section",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

