if (!window.MotionPreference) {
  const __mql = window.matchMedia("(prefers-reduced-motion: reduce)");
  const __listeners = new Set();

  const MotionPreference = {
    prefersReducedMotion() {
      return __mql.matches;
    },
    setOverride(value) {
      const reduced = Boolean(value);
      document.documentElement.classList.toggle("reduced-motion", reduced);
      window.dispatchEvent(new CustomEvent("motion-preference", { detail: { reduced } }));
      for (const listener of __listeners) {
        try {
          listener({ reduced, override: reduced, systemReduced: __mql.matches });
        } catch {}
      }
    },
    onChange(listener) {
      __listeners.add(listener);
      try {
        listener({
          reduced: __mql.matches,
          override: null,
          systemReduced: __mql.matches,
        });
      } catch {}
      return () => __listeners.delete(listener);
    },
    getState() {
      return { reduced: __mql.matches, override: null, systemReduced: __mql.matches };
    },
  };

  window.MotionPreference = MotionPreference;
}

function prefersReducedMotion() {
  return window.MotionPreference.prefersReducedMotion();
}

function initDemoShell() {
  // No-op shim in imported standalone snippets.
}

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Lenis from "lenis";

gsap.registerPlugin(ScrollTrigger);

initDemoShell({
  title: "SVG Workflow Animation",
  category: "scroll",
  tech: ["gsap", "scrolltrigger", "svg", "stroke-dasharray"],
});

const lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

// Hero entrance
if (!reduced) {
  gsap.set(".hero .eyebrow", { opacity: 0, y: 20 });
  gsap.set(".hero h1", { opacity: 0, y: 40 });
  gsap.set(".hero .subtitle", { opacity: 0, y: 25 });

  gsap
    .timeline({ defaults: { ease: "expo.out" } })
    .to(".hero .eyebrow", { opacity: 1, y: 0, duration: 0.7, delay: 0.3 })
    .to(".hero h1", { opacity: 1, y: 0, duration: 0.9 }, "-=0.4")
    .to(".hero .subtitle", { opacity: 1, y: 0, duration: 0.7 }, "-=0.5");
}

// SVG path drawing — core technique
const connectLines = document.querySelectorAll(".connect-line");

connectLines.forEach((path) => {
  const length = path.getTotalLength();

  // Set up stroke-dasharray for drawing effect
  gsap.set(path, {
    strokeDasharray: length,
    strokeDashoffset: length,
    opacity: 1,
  });

  if (!reduced) {
    // Draw the line as user scrolls through the workflow section
    gsap.to(path, {
      strokeDashoffset: 0,
      duration: 1,
      ease: "none",
      scrollTrigger: {
        trigger: ".workflow-section",
        start: "top 60%",
        end: "bottom 80%",
        scrub: 1.5,
      },
    });
  } else {
    // Show immediately for reduced motion
    gsap.set(path, { strokeDashoffset: 0 });
  }
});

// Node reveals — staggered sequentially as scroll progresses
const nodeOrder = [
  { id: "#node-1", label: "#label-1", delay: 0 },
  { id: "#node-2", label: "#label-2", delay: 0.15 },
  { id: "#node-3a", label: "#label-3a", delay: 0.25 },
  { id: "#node-3b", label: "#label-3b", delay: 0.25 },
  { id: "#node-4", label: "#label-4", delay: 0.4 },
];

nodeOrder.forEach(({ id, label, delay }) => {
  const node = document.querySelector(id);
  const labelEl = document.querySelector(label);
  if (!node) return;

  if (!reduced) {
    gsap.to(node, {
      opacity: 1,
      scale: 1,
      duration: 0.6,
      ease: "back.out(1.7)",
      scrollTrigger: {
        trigger: ".workflow-section",
        start: `top ${70 - delay * 20}%`,
        toggleActions: "play none none reverse",
      },
    });

    if (labelEl) {
      gsap.to(labelEl, {
        opacity: 1,
        x: 0,
        duration: 0.5,
        ease: "expo.out",
        scrollTrigger: {
          trigger: ".workflow-section",
          start: `top ${68 - delay * 20}%`,
          toggleActions: "play none none reverse",
        },
      });
      gsap.set(labelEl, { x: 10 });
    }
  } else {
    gsap.set(node, { opacity: 1 });
    if (labelEl) gsap.set(labelEl, { opacity: 1 });
  }
});

// Colour pulse on nodes after reveal (ambient animation)
if (!reduced) {
  ScrollTrigger.create({
    trigger: ".workflow-section",
    start: "top 30%",
    onEnter: () => {
      const circles = document.querySelectorAll(".node circle");
      circles.forEach((circle, i) => {
        gsap.to(circle, {
          r: 40,
          duration: 1.2,
          ease: "sine.inOut",
          yoyo: true,
          repeat: -1,
          delay: i * 0.3,
        });
      });
    },
  });
}

// Details section reveals
document
  .querySelectorAll(
    ".details-section h2, .details-section h3, .details-section p, .details-section ol"
  )
  .forEach((el) => {
    if (!reduced) {
      gsap.set(el, { opacity: 0, y: 20 });
      gsap.to(el, {
        opacity: 1,
        y: 0,
        duration: 0.6,
        ease: "expo.out",
        scrollTrigger: { trigger: el, start: "top 75%", toggleActions: "play none none reverse" },
      });
    }
  });

document.querySelectorAll(".details-section ol li").forEach((li, i) => {
  if (!reduced) {
    gsap.set(li, { opacity: 0, x: -15 });
    gsap.to(li, {
      opacity: 1,
      x: 0,
      duration: 0.5,
      ease: "expo.out",
      delay: i * 0.08,
      scrollTrigger: { trigger: li, start: "top 75%", toggleActions: "play none none reverse" },
    });
  }
});

// Motion preference listener
window.addEventListener("motion-preference", (e) => {
  if (e.detail.reduced) {
    gsap.globalTimeline.paused(true);
  } else {
    gsap.globalTimeline.paused(false);
  }
});

snippets.css:
:root {
  --bg: #09060e;
  --text: #f8f4ff;
  --muted: #cfc4dc;
  --line: #4a385d;
  --accent: #ff8f66;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  color: var(--text);
  font-family: "Courier New", Courier, monospace;
  background: radial-gradient(circle at 20% 20%, rgba(255, 143, 102, 0.2), transparent 38%),
    radial-gradient(circle at 82% 76%, rgba(126, 122, 255, 0.2), transparent 40%), var(--bg);
}

.topbar {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 30;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.8rem 1rem;
  background: rgba(9, 6, 14, 0.62);
  backdrop-filter: blur(8px);
}

.topbar a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 700;
}

.toggle {
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  color: var(--text);
  padding: 0.35rem 0.7rem;
  cursor: pointer;
  font-family: inherit;
}

main {
  width: min(1080px, 94%);
  margin: 0 auto;
  padding-top: 3.7rem;
}

.hero {
  min-height: 95vh;
  display: grid;
  align-content: center;
  gap: 0.7rem;
}

.kicker {
  margin: 0;
  color: var(--accent);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.8rem;
}

h1 {
  margin: 0;
  font-size: clamp(2.5rem, 10vw, 7rem);
  line-height: 0.9;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  max-width: 58ch;
}

.player {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 1rem;
}

.disc-wrap {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.03);
  display: grid;
  place-items: center;
}

.disc {
  width: 250px;
  height: 250px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: radial-gradient(circle at center, #191420 0 16%, #0f0b14 16% 20%, transparent 20%),
    repeating-radial-gradient(circle at center, #1d1828 0 4px, #0f0b15 4px 8px);
  position: relative;
  animation: spin 8s linear infinite;
}

.disc::after {
  content: "";
  position: absolute;
  inset: 42%;
  border-radius: 50%;
  background: #d0a58f;
}

.tracklist {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.03);
}

.tracklist h2 {
  margin: 0;
}

.tracklist ol {
  margin: 0.8rem 0 0;
  padding-left: 1.3rem;
  color: var(--muted);
  display: grid;
  gap: 0.45rem;
}

.bars {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: repeat(14, minmax(0, 1fr));
  gap: 0.3rem;
  align-items: end;
  height: 96px;
}

.bar {
  border-radius: 6px;
  background: linear-gradient(180deg, #ffa76f, #8c6cff);
  animation: bounce 1s ease-in-out infinite;
}

body.no-motion .disc,
body.no-motion .bar {
  animation: none;
}

@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

@media (max-width: 930px) {
  .player {
    grid-template-columns: 1fr;
  }
}

