:root {
  color-scheme: dark;
  --bg: #0b0d14;
  --panel: rgba(15, 20, 32, 0.82);
  --line: rgba(255, 255, 255, 0.12);
  --text: #f6f5ef;
  --muted: rgba(246, 245, 239, 0.6);
  --accent: #f8d34a;
  --accent-2: #ff6b6b;
  --accent-3: #73f6ff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Rajdhani", "Segoe UI", sans-serif;
  background: radial-gradient(circle at top left, rgba(248, 211, 74, 0.2), transparent 55%),
    radial-gradient(circle at 80% 10%, rgba(115, 246, 255, 0.18), transparent 55%),
    radial-gradient(circle at 20% 80%, rgba(255, 107, 107, 0.18), transparent 60%), #090b12;
  color: var(--text);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

.bg-grid {
  position: fixed;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: 0.2;
  pointer-events: none;
}

.bg-glow {
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 60% 40%, rgba(255, 255, 255, 0.08), transparent 60%);
  pointer-events: none;
}

.shell {
  position: relative;
  z-index: 1;
  padding: 32px clamp(20px, 6vw, 90px) 90px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  padding: 16px 24px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 20px;
  backdrop-filter: blur(16px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.brand-mark {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(140deg, rgba(248, 211, 74, 0.9), rgba(255, 107, 107, 0.9));
  color: #0b0d14;
  display: grid;
  place-items: center;
  font-family: "Press Start 2P", system-ui;
  font-size: 0.7rem;
}

.brand-title {
  font-family: "Press Start 2P", system-ui;
  font-size: 0.85rem;
  margin: 0;
}

.brand-subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.nav {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 0.95rem;
}

.nav a {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.65rem;
}

.nav-cta {
  padding: 0.5rem 1.1rem;
  border-radius: 999px;
  border: 1px solid rgba(248, 211, 74, 0.6);
  color: var(--text);
  background: rgba(248, 211, 74, 0.1);
}

.hero {
  margin-top: 42px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 32px;
  align-items: center;
}

.hero-copy h1 {
  font-family: "Press Start 2P", system-ui;
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  line-height: 1.3;
  margin-bottom: 20px;
}

.kicker {
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-size: 0.7rem;
  color: var(--accent);
  margin-bottom: 14px;
}

.lead {
  color: var(--muted);
  max-width: 52ch;
  line-height: 1.6;
}

.hero-actions {
  display: flex;
  gap: 12px;
  margin-top: 24px;
  flex-wrap: wrap;
