  border-radius: 12px;
  border: 1px solid var(--accent);
  background: transparent;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
  cursor: pointer;
}

.btn.primary {
  background: rgba(248, 211, 74, 0.2);
}

.btn.ghost {
  border-color: rgba(115, 246, 255, 0.5);
}

.hero-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  margin-top: 28px;
}

.hero-stats div {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px 16px;
}

.hero-stats span {
  display: block;
  color: var(--muted);
  font-size: 0.8rem;
}

.hero-stats strong {
  font-size: 1.1rem;
}

