  display: grid;
  place-items: center;
  gap: 14px;
}

#gameboy-stage {
  width: min(360px, 80vw);
  height: min(520px, 60vh);
  border-radius: 28px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(5, 8, 12, 0.8);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.stage-caption {
  text-align: center;
  font-size: 0.85rem;
  color: var(--muted);
}

.stage-caption p {
