}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.7rem;
  color: var(--muted);
  margin-bottom: 20px;
}

.section-header h2 {
  font-family: "Press Start 2P", system-ui;
  font-size: 1rem;
  margin: 0;
  color: var(--text);
}

.card-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 18px;
}

.card h3 {
  margin: 12px 0 8px;
  font-size: 1.1rem;
}

.card p {
  color: var(--muted);
  line-height: 1.5;
}

.card .badge {
  display: inline-flex;
  padding: 4px 8px;
  border-radius: 8px;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  background: rgba(255, 107, 107, 0.2);
  border: 1px solid rgba(255, 107, 107, 0.5);
  color: var(--accent-2);
}

.card-meta {
  display: flex;
