}

.media-orbit {
  background-image: radial-gradient(circle at 20% 25%, rgba(160, 185, 255, 0.9), transparent 55%),
    radial-gradient(circle at 80% 70%, rgba(140, 120, 255, 0.6), transparent 60%),
