if (!window.MotionPreference) {
  const __mql = window.matchMedia("(prefers-reduced-motion: reduce)");
  const __listeners = new Set();

  const MotionPreference = {
    prefersReducedMotion() {
      return __mql.matches;
    },
    setOverride(value) {
      const reduced = Boolean(value);
      document.documentElement.classList.toggle("reduced-motion", reduced);
      window.dispatchEvent(new CustomEvent("motion-preference", { detail: { reduced } }));
      for (const listener of __listeners) {
        try {
          listener({ reduced, override: reduced, systemReduced: __mql.matches });
        } catch {}
      }
    },
    onChange(listener) {
      __listeners.add(listener);
      try {
        listener({
          reduced: __mql.matches,
          override: null,
          systemReduced: __mql.matches,
        });
      } catch {}
      return () => __listeners.delete(listener);
    },
    getState() {
      return { reduced: __mql.matches, override: null, systemReduced: __mql.matches };
    },
  };

  window.MotionPreference = MotionPreference;
}

import * as THREE from "three";

const host = document.getElementById("scene");
const toggle = document.getElementById("toggleMotion");
let motionEnabled = !window.MotionPreference.prefersReducedMotion();

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x03050c);
scene.fog = new THREE.Fog(0x03050c, 10, 40);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 0.7, 7);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
host.appendChild(renderer.domElement);

const product = new THREE.Group();
scene.add(product);

const body = new THREE.Mesh(
  new THREE.CylinderGeometry(1.2, 1.2, 2.4, 48),
  new THREE.MeshStandardMaterial({ color: 0x1e2c47, metalness: 0.6, roughness: 0.25 })
);
product.add(body);

const ring = new THREE.Mesh(
  new THREE.TorusGeometry(1.22, 0.08, 24, 80),
  new THREE.MeshStandardMaterial({
    color: 0x90e8ff,
    emissive: 0x478eb0,
    emissiveIntensity: 0.7,
    metalness: 0.4,
    roughness: 0.2,
  })
);
ring.rotation.x = Math.PI / 2;
ring.position.y = 0.7;
product.add(ring);

const cap = new THREE.Mesh(
  new THREE.CylinderGeometry(1.15, 1.15, 0.35, 48),
  new THREE.MeshStandardMaterial({ color: 0xbccae0, metalness: 0.85, roughness: 0.18 })
);
cap.position.y = 1.35;
product.add(cap);

scene.add(new THREE.AmbientLight(0x98b7ff, 0.45));
const key = new THREE.SpotLight(0x9edbff, 2.2, 60, 0.45, 0.35);
key.position.set(7, 8, 6);
scene.add(key);
const rim = new THREE.PointLight(0xd07cff, 0.8, 30);
rim.position.set(-6, 2, -5);
scene.add(rim);

function getScrollProgress() {
  const max = Math.max(document.body.scrollHeight - window.innerHeight, 1);
  return Math.min(1, Math.max(0, window.scrollY / max));
}

function setLabel() {
  toggle.textContent = motionEnabled ? "Disable motion" : "Enable motion";
}

function animate(time) {
  requestAnimationFrame(animate);
  const t = time * 0.001;
  const p = motionEnabled ? getScrollProgress() : 0;

  const angle = -0.7 + p * 1.35;
  const radius = 7 - p * 2.1;
  camera.position.x += (Math.cos(angle) * radius - camera.position.x) * 0.08;
  camera.position.z += (Math.sin(angle) * radius - camera.position.z) * 0.08;
  camera.position.y += (0.5 + p * 1.4 - camera.position.y) * 0.08;
  camera.lookAt(0, 0.35, 0);

  if (motionEnabled) {
    product.rotation.y += 0.004;
    ring.rotation.z = Math.sin(t * 1.2) * 0.2;
  }

  renderer.render(scene, camera);
}

function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

toggle.addEventListener("click", () => {
  motionEnabled = !motionEnabled;
  setLabel();
});

window.addEventListener("resize", onResize);
setLabel();
animate(0);

snippets.css:
/* ─── Reset & Base ─────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #ffffff;
  --dark: #0d1b2a;
  --text: #0d1b2a;
  --muted: #6b7a8d;
  --accent: #2563eb;
  --light: #f0f4ff;
  --border: #e2e8f0;
  --radius: 12px;
  --radius-sm: 6px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", "Helvetica Neue", Arial,
    sans-serif;
  --font-mono: "SFMono-Regular", "Consolas", "Liberation Mono", "Menlo", monospace;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}
ul {
  list-style: none;
}
img {
  display: block;
  max-width: 100%;
}

/* ─── Shared Section Layout ────────────────────────────────────────────── */
.section {
  padding: clamp(5rem, 10vw, 9rem) clamp(1.5rem, 6vw, 7rem);
  max-width: 1240px;
  margin: 0 auto;
}

.section__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: clamp(3rem, 6vw, 5rem);
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border);
}

.section__label-group {
  display: flex;
  align-items: baseline;
  gap: 1rem;
}

.section-index {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent);
  font-family: var(--font-mono);
  letter-spacing: 0.05em;
}

.section-label {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.section__summary {
  font-size: 0.9rem;
  color: var(--muted);
  max-width: 30ch;
  line-height: 1.6;
  text-align: right;
}

/* ─── Hero ──────────────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100svh;
  background: var(--dark);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.hero__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}

.hero__inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  flex: 1;
  padding: clamp(2rem, 4vw, 4rem) clamp(1.5rem, 6vw, 7rem);
  padding-bottom: 5rem;
}

.hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-top: 1rem;
}

.eyebrow-tag {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
}

.eyebrow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.eyebrow-avail {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 0.04em;
}

.hero__name {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: #ffffff;
  margin-top: auto;
  padding-top: 2rem;
  overflow: hidden;
}

.hero__name .line {
  overflow: hidden;
  display: block;
}

.hero__foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 3rem;
}

.hero__tagline {
  font-size: clamp(1rem, 2vw, 1.2rem);
  font-weight: 400;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.55);
  max-width: 36ch;
}

.hero__ctas {
  display: flex;
  gap: 0.875rem;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  height: 48px;
  padding: 0 1.75rem;
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: transform 0.2s ease, opacity 0.2s ease, background 0.2s ease;
  cursor: pointer;
}

.btn--primary {
  background: var(--accent);
  color: #fff;
}

.btn--primary:hover {
  background: #1d4fd8;
  transform: translateY(-1px);
}

.btn--ghost {
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn--ghost:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.35);
}

.hero__scroll-indicator {
  position: absolute;
  bottom: 2.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  z-index: 2;
}

.scroll-track {
  width: 1px;
  height: 48px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 1px;
  overflow: hidden;
  position: relative;
}

.scroll-thumb {
  position: absolute;
  top: -100%;
  left: 0;
  width: 100%;
  height: 50%;
  background: var(--accent);
  border-radius: 1px;
  animation: scrollThumb 1.8s ease-in-out infinite;
}

@keyframes scrollThumb {
  0% {
    top: -50%;
  }
  100% {
    top: 100%;
  }
}

.scroll-label {
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.3);
}

/* ─── Expertise Section ─────────────────────────────────────────────────── */
.expertise {
  background: var(--bg);
}

.expertise__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .expertise__grid {
    grid-template-columns: 1fr;
  }
}

.expertise-card {
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2.5rem 2rem;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.expertise-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(37, 99, 235, 0.08);
}

/* CSS geometric icons */
.expertise-card__icon {
  width: 48px;
  height: 48px;
  margin-bottom: 1.5rem;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-backend {
  width: 36px;
  height: 36px;
  border: 2.5px solid var(--accent);
  border-radius: 6px;
  position: relative;
}

.icon-backend::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 6px;
  right: 6px;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
  box-shadow: 0 6px 0 var(--accent), 0 12px 0 var(--accent);
}

.icon-platform {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2.5px solid var(--accent);
  position: relative;
}

.icon-platform::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 2.5px solid var(--accent);
}

.icon-platform::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.icon-leadership {
  width: 36px;
  height: 36px;
  position: relative;
}

.icon-leadership::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 28px;
  height: 18px;
  border: 2.5px solid var(--accent);
  border-radius: 14px 14px 6px 6px;
  border-bottom: none;
}

.icon-leadership::after {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 14px;
  border: 2.5px solid var(--accent);
  border-radius: 50%;
}

.expertise-card__title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1.25rem;
  color: var(--text);
}

.expertise-card__list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.expertise-card__list li {
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.5;
  padding-left: 1rem;
  position: relative;
}

.expertise-card__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
}

/* ─── Timeline Section ──────────────────────────────────────────────────── */
.timeline {
  background: var(--bg);
  padding-top: 0;
}

.timeline__track {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.timeline__line {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--border);
  transform: translateX(-50%);
  z-index: 0;
}

.timeline-item {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 0 2.5rem;
  align-items: start;
  padding: 2.5rem 0;
  position: relative;
  z-index: 1;
}

/* Year dot on center line */
.timeline-item::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 2.9rem;
  transform: translateX(-50%);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--bg);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
  z-index: 2;
}

.timeline-item__year {
  font-size: 0.8rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--accent);
  letter-spacing: 0.06em;
  padding-top: 0.35rem;
}

.timeline-item__card {
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
}

.timeline-item__meta {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.875rem;
}

.timeline-item__role {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.01em;
}

.timeline-item__sep {
  color: var(--border);
  font-weight: 300;
}

.timeline-item__company {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
}

.timeline-item__desc {
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.7;
}

/* Left-aligned: year left, empty center col, card right */
.timeline-item--left .timeline-item__year {
  text-align: right;
  grid-column: 1;
  grid-row: 1;
}

.timeline-item--left .timeline-item__card {
  grid-column: 3;
  grid-row: 1;
}

/* Right-aligned: card left, empty center col, year right */
.timeline-item--right .timeline-item__card {
  grid-column: 1;
  grid-row: 1;
}

.timeline-item--right .timeline-item__year {
  grid-column: 3;
  grid-row: 1;
  padding-top: 0.35rem;
}

@media (max-width: 768px) {
  .timeline__line {
    left: 1rem;
  }
  .timeline-item {
    grid-template-columns: 1fr;
    padding-left: 3rem;
  }
  .timeline-item::after {
    left: 1rem;
    transform: translateX(-50%);
  }
  .timeline-item--left .timeline-item__year,
  .timeline-item--right .timeline-item__year {
    grid-column: 1;
    grid-row: 1;
    text-align: left;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
  }
  .timeline-item--left .timeline-item__card,
  .timeline-item--right .timeline-item__card {
    grid-column: 1;
    grid-row: 2;
  }
}

/* ─── Open Source Section ───────────────────────────────────────────────── */
.open-source {
  background: var(--light);
  border-radius: 0;
  max-width: unset;
  padding-left: 0;
  padding-right: 0;
}

.open-source .section__header {
  max-width: 1240px;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1.5rem, 6vw, 7rem);
  padding-right: clamp(1.5rem, 6vw, 7rem);
}

.repos__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 6vw, 7rem);
}

@media (max-width: 900px) {
  .repos__grid {
    grid-template-columns: 1fr;
  }
}

.repo-card {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  cursor: pointer;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  color: var(--text);
}

.repo-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 36px rgba(37, 99, 235, 0.1);
  border-color: rgba(37, 99, 235, 0.3);
}

.repo-card__top {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.repo-card__icon {
  color: var(--muted);
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.repo-card__name {
  font-size: 0.9rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--accent);
  flex: 1;
}

.repo-card__stars {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  margin-left: auto;
  flex-shrink: 0;
}

.repo-card__stars svg {
  color: #f59e0b;
}

.repo-card__desc {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.65;
  flex: 1;
}

.repo-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border);
}

.lang-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.25rem 0.7rem;
  border-radius: 100px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.lang-pill::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.lang-pill--go {
  background: #e0f0ff;
  color: #0078d4;
}
.lang-pill--go::before {
  background: #0078d4;
}
.lang-pill--ts {
  background: #e0e8ff;
  color: #3178c6;
}
.lang-pill--ts::before {
  background: #3178c6;
}
.lang-pill--rust {
  background: #fbe8e0;
  color: #b7410e;
}
.lang-pill--rust::before {
  background: #b7410e;
}

.repo-card__updated {
  font-size: 0.72rem;
  color: var(--muted);
}

/* ─── Contact Section ───────────────────────────────────────────────────── */
.contact {
  background: var(--dark);
  max-width: unset;
  padding-top: clamp(5rem, 10vw, 9rem);
  padding-bottom: 0;
  padding-left: 0;
