if (!window.MotionPreference) {
  const __mql = window.matchMedia("(prefers-reduced-motion: reduce)");
  const __listeners = new Set();

  const MotionPreference = {
    prefersReducedMotion() {
      return __mql.matches;
    },
    setOverride(value) {
      const reduced = Boolean(value);
      document.documentElement.classList.toggle("reduced-motion", reduced);
      window.dispatchEvent(new CustomEvent("motion-preference", { detail: { reduced } }));
      for (const listener of __listeners) {
        try {
          listener({ reduced, override: reduced, systemReduced: __mql.matches });
        } catch {}
      }
    },
    onChange(listener) {
      __listeners.add(listener);
      try {
        listener({
          reduced: __mql.matches,
          override: null,
          systemReduced: __mql.matches,
        });
      } catch {}
      return () => __listeners.delete(listener);
    },
    getState() {
      return { reduced: __mql.matches, override: null, systemReduced: __mql.matches };
    },
  };

  window.MotionPreference = MotionPreference;
}

function prefersReducedMotion() {
  return window.MotionPreference.prefersReducedMotion();
}

function initDemoShell() {
  // No-op shim in imported standalone snippets.
}

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { SplitText } from "gsap/SplitText";
import Lenis from "lenis";
import * as THREE from "three";

gsap.registerPlugin(ScrollTrigger, SplitText);

// ─── Shell ────────────────────────────────────────────────────────────────
initDemoShell({
  title: "Tech Lead Portfolio",
  category: "pages",
  tech: ["three.js", "gsap", "lenis", "scrolltrigger", "splittext"],
});

// ─── Reduced Motion ───────────────────────────────────────────────────────
let reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

window.addEventListener("motion-preference", (e) => {
  reduced = e.detail.reduced;
  document.documentElement.classList.toggle("reduced-motion", reduced);
  ScrollTrigger.refresh();
});

const dur = (d) => (reduced ? 0 : d);

// ─── Lenis ────────────────────────────────────────────────────────────────
const lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

// ─── Three.js Hero Background ─────────────────────────────────────────────
function initHeroCanvas() {
  const canvas = document.getElementById("heroCanvas");
  if (!canvas) return;

  const hero = document.querySelector(".hero");
  const w = hero.offsetWidth;
  const h = hero.offsetHeight;

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(60, w / h, 0.1, 100);
  camera.position.z = 8;

  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(w, h);
  renderer.setClearColor(0x000000, 0);

  const geos = [
    new THREE.IcosahedronGeometry(1, 0),
    new THREE.OctahedronGeometry(1, 0),
    new THREE.TetrahedronGeometry(1, 0),
  ];

  const mat = new THREE.MeshBasicMaterial({
    color: 0x2563eb,
    wireframe: true,
    opacity: 0.15,
    transparent: true,
  });

  const meshes = [];
  for (let i = 0; i < 12; i++) {
    const m = new THREE.Mesh(geos[i % 3], mat);
    m.position.set(
      (Math.random() - 0.5) * 16,
      (Math.random() - 0.5) * 10,
      (Math.random() - 0.5) * 8
    );
    m.scale.setScalar(0.4 + Math.random() * 1.2);
    m.userData.offset = Math.random() * Math.PI * 2;
    meshes.push(m);
    scene.add(m);
  }

  let animId = null;

  function animate() {
    animId = requestAnimationFrame(animate);
    const t = Date.now() * 0.0005;
    meshes.forEach((m, i) => {
      m.rotation.x += 0.002 + i * 0.0003;
      m.rotation.y += 0.003 + i * 0.0002;
      m.position.y += Math.sin(t + m.userData.offset) * 0.002;
    });
    renderer.render(scene, camera);
  }

  if (!reduced) {
    animate();
  } else {
    renderer.render(scene, camera);
  }

  function onResize() {
    const nw = hero.offsetWidth;
    const nh = hero.offsetHeight;
    camera.aspect = nw / nh;
    camera.updateProjectionMatrix();
    renderer.setSize(nw, nh);
  }

  window.addEventListener("resize", onResize);

  // Pause rendering when hero is fully scrolled past
  ScrollTrigger.create({
    trigger: ".hero",
    start: "top top",
    end: "bottom top",
    onLeave: () => {
      if (animId) {
        cancelAnimationFrame(animId);
        animId = null;
      }
    },
    onEnterBack: () => {
      if (!animId && !reduced) animate();
    },
  });
}

// ─── Hero Animations ──────────────────────────────────────────────────────
function animateHero() {
  const nameEl = document.getElementById("heroName");
  const taglineEl = document.getElementById("heroTagline");

  if (nameEl) {
    const splitName = new SplitText(nameEl, { type: "words,lines", linesClass: "line" });
    gsap.set(splitName.words, { y: 50, opacity: 0 });
    gsap.to(splitName.words, {
      y: 0,
      opacity: 1,
      duration: dur(1),
      ease: "expo.out",
      stagger: { each: dur(0.06) },
      delay: dur(0.3),
    });
  }

  if (taglineEl) {
    gsap.from(taglineEl, {
      y: reduced ? 0 : 24,
      opacity: 0,
      duration: dur(0.9),
      ease: "expo.out",
      delay: dur(0.7),
    });
  }

  gsap.from(".hero__eyebrow", {
    opacity: 0,
    y: reduced ? 0 : -12,
    duration: dur(0.7),
    ease: "expo.out",
    delay: dur(0.15),
  });

  gsap.from(".hero__ctas", {
    opacity: 0,
    y: reduced ? 0 : 18,
    duration: dur(0.8),
    ease: "expo.out",
    delay: dur(0.9),
  });

  gsap.from(".hero__scroll-indicator", {
    opacity: 0,
    duration: dur(1),
    delay: dur(1.4),
  });
}

// ─── Expertise Cards ──────────────────────────────────────────────────────
function animateExpertise() {
  const cards = document.querySelectorAll(".expertise-card");
  if (!cards.length) return;

  gsap.set(cards, { scale: 0.92, opacity: 0 });

  gsap.to(cards, {
    scale: 1,
    opacity: 1,
    duration: dur(0.75),
    ease: "expo.out",
    stagger: { each: dur(0.1) },
    scrollTrigger: {
      trigger: ".expertise__grid",
      start: "top 78%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Timeline Items ───────────────────────────────────────────────────────
function animateTimeline() {
  document.querySelectorAll(".timeline-item").forEach((item) => {
    const isLeft = item.classList.contains("timeline-item--left");
    const card = item.querySelector(".timeline-item__card");
    const year = item.querySelector(".timeline-item__year");

    if (card) {
      gsap.set(card, { x: reduced ? 0 : isLeft ? 48 : -48, opacity: 0 });
      gsap.to(card, {
        x: 0,
        opacity: 1,
        duration: dur(0.8),
        ease: "expo.out",
        scrollTrigger: {
          trigger: item,
          start: "top 80%",
          toggleActions: "play none none reverse",
        },
      });
    }

    if (year) {
      gsap.set(year, { x: reduced ? 0 : isLeft ? -24 : 24, opacity: 0 });
      gsap.to(year, {
        x: 0,
        opacity: 1,
        duration: dur(0.7),
        ease: "expo.out",
        delay: dur(0.08),
        scrollTrigger: {
          trigger: item,
          start: "top 80%",
          toggleActions: "play none none reverse",
        },
      });
    }
  });

  // Grow the center line in from top
  gsap.from(".timeline__line", {
    scaleY: 0,
    transformOrigin: "top center",
    duration: dur(1.5),
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".timeline__track",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Repo Cards ───────────────────────────────────────────────────────────
function animateRepos() {
  const cards = document.querySelectorAll(".repo-card");
  if (!cards.length) return;

  gsap.set(cards, { y: reduced ? 0 : 40, opacity: 0 });

  gsap.to(cards, {
    y: 0,
    opacity: 1,
    duration: dur(0.75),
    ease: "expo.out",
    stagger: { each: dur(0.1) },
    scrollTrigger: {
      trigger: ".repos__grid",
      start: "top 78%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Contact CTA ──────────────────────────────────────────────────────────
function animateContact() {
  const ctaEl = document.getElementById("contactCta");
  if (ctaEl) {
    const splitCta = new SplitText(ctaEl, { type: "words,lines", linesClass: "line" });
    gsap.set(splitCta.words, { y: 60, opacity: 0 });

    gsap.to(splitCta.words, {
      y: 0,
      opacity: 1,
      duration: dur(0.95),
      ease: "expo.out",
      stagger: { each: dur(0.06) },
      scrollTrigger: {
        trigger: ".contact__inner",
        start: "top 80%",
        toggleActions: "play none none reverse",
      },
    });
  }

  gsap.from(".contact__kicker", {
    opacity: 0,
    y: reduced ? 0 : 16,
    duration: dur(0.7),
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".contact__inner",
      start: "top 80%",
      toggleActions: "play none none reverse",
    },
  });

  gsap.from(".contact__links", {
    opacity: 0,
    y: reduced ? 0 : 20,
    duration: dur(0.8),
    ease: "expo.out",
    delay: dur(0.35),
    scrollTrigger: {
      trigger: ".contact__inner",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Section Headers ──────────────────────────────────────────────────────
function animateSectionHeaders() {
  document.querySelectorAll(".section__header").forEach((el) => {
    gsap.from(el, {
      opacity: 0,
      y: reduced ? 0 : 16,
      duration: dur(0.65),
      ease: "expo.out",
      scrollTrigger: {
        trigger: el,
        start: "top 88%",
        toggleActions: "play none none reverse",
      },
    });
  });
}

// ─── Init ─────────────────────────────────────────────────────────────────
initHeroCanvas();
animateHero();
animateSectionHeaders();
animateExpertise();
animateTimeline();
animateRepos();
animateContact();

snippets.css:
/* ═══════════════════════════════════════════════════════
   MAISON DORÉE — Warm Editorial Style
   Palette: Cream, Terracotta, Deep Brown, Gold
   Fonts: Playfair Display (headlines), Cormorant Garamond (body), DM Sans (UI)
   Feel: Luxury French restaurant, editorial magazine
═══════════════════════════════════════════════════════ */

:root {
  --cream: #f5f0e8;
  --cream-dark: #ede5d8;
  --parchment: #e8ddc8;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --brown: #2c1a0e;
  --brown-mid: #4a2e1a;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --charcoal: #1a1209;
  --warm-gray: #7a6a58;
  --warm-muted: #9a8878;

  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Cormorant Garamond", Georgia, serif;
  --font-ui: "DM Sans", system-ui, sans-serif;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--brown);
  overflow-x: hidden;
  font-size: 18px;
  line-height: 1.7;
}

/* ── Navigation ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 3rem;
  transition: all 0.4s ease;
}

.nav.scrolled {
  background: rgba(245, 240, 232, 0.95);
  backdrop-filter: blur(12px);
  padding: 1rem 3rem;
  border-bottom: 1px solid rgba(201, 168, 76, 0.2);
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--cream);
  letter-spacing: 0.5px;
  transition: color 0.4s ease;
}

.nav.scrolled .nav-logo {
  color: var(--brown);
}

.nav-links {
  list-style: none;
  display: flex;
  gap: 2.5rem;
}

.nav-links a {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: rgba(245, 240, 232, 0.8);
  text-decoration: none;
  transition: color 0.3s ease;
}

.nav.scrolled .nav-links a {
  color: var(--warm-gray);
}

.nav-links a:hover {
  color: var(--gold);
}
.nav.scrolled .nav-links a:hover {
  color: var(--terracotta);
}

.nav-cta {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--gold);
  text-decoration: none;
  border: 1px solid var(--gold);
  padding: 0.5rem 1.2rem;
  border-radius: 1px;
  transition: all 0.3s ease;
}

.nav-cta:hover {
  background: var(--gold);
  color: var(--brown);
}

.nav.scrolled .nav-cta {
  color: var(--terracotta);
  border-color: var(--terracotta);
}
.nav.scrolled .nav-cta:hover {
  background: var(--terracotta);
  color: var(--cream);
}

/* ── Hero ── */
.hero {
  position: relative;
  height: 100vh;
  min-height: 700px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-image {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(193, 113, 74, 0.3) 0%, rgba(44, 26, 14, 0.2) 100%),
    radial-gradient(ellipse at 70% 40%, rgba(201, 168, 76, 0.15) 0%, transparent 60%);
  background-color: var(--brown);

  /* Simulated food photo with CSS gradients */
  background-image: radial-gradient(
      ellipse at 30% 60%,
      rgba(201, 168, 76, 0.08) 0%,
      transparent 50%
    ), radial-gradient(ellipse at 70% 30%, rgba(193, 113, 74, 0.12) 0%, transparent 50%),
    linear-gradient(160deg, #1a0e06 0%, #2c1a0e 40%, #3a2010 70%, #1a0e06 100%);
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(26, 18, 9, 0.3) 0%,
    rgba(26, 18, 9, 0.1) 40%,
    rgba(26, 18, 9, 0.6) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: 0 2rem;
}

.hero-pre {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 400;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 2rem;
  opacity: 0.9;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(3.5rem, 8vw, 7rem);
  font-weight: 400;
  line-height: 1.05;
  color: var(--cream);
  margin-bottom: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.1em;
}

.hero-title .line {
  display: block;
  overflow: hidden;
}

.hero-title .italic {
  font-style: italic;
  color: var(--gold-light);
}

.hero-desc {
  font-family: var(--font-body);
  font-size: 1.15rem;
  font-weight: 300;
  color: rgba(245, 240, 232, 0.75);
  max-width: 500px;
  margin: 0 auto 3rem;
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-gold {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 1rem 2.5rem;
  background: var(--gold);
  color: var(--brown);
  border: none;
  border-radius: 1px;
  transition: all 0.3s ease;
  display: inline-block;
}

.btn-gold:hover {
  background: var(--gold-light);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(201, 168, 76, 0.3);
}

.btn-ghost-warm {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 1rem 2.5rem;
  color: var(--cream);
  border: 1px solid rgba(245, 240, 232, 0.3);
  border-radius: 1px;
  transition: all 0.3s ease;
  display: inline-block;
}

.btn-ghost-warm:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.btn-outline-warm {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.8rem 2rem;
  color: var(--terracotta);
  border: 1px solid var(--terracotta);
  border-radius: 1px;
  transition: all 0.3s ease;
  display: inline-block;
}

.btn-outline-warm:hover {
  background: var(--terracotta);
  color: var(--cream);
}

.hero-scroll {
  position: absolute;
  bottom: 3rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.8rem;
  z-index: 2;
}

.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--gold), transparent);
  animation: scrollPulse 2s ease-in-out infinite;
}

@keyframes scrollPulse {
  0%,
  100% {
    opacity: 0.4;
    transform: scaleY(1);
  }
  50% {
    opacity: 0.9;
    transform: scaleY(1.2);
  }
}

.hero-scroll span {
  font-family: var(--font-ui);
  font-size: 0.6rem;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gold-light);
  opacity: 0.6;
}

/* ── Section Shared ── */
.section-label {
  display: block;
  font-family: var(--font-ui);
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--terracotta);
  margin-bottom: 1.2rem;
}

/* ── Philosophy ── */
.philosophy-section {
  padding: 8rem 2rem;
  background: var(--brown);
  position: relative;
  overflow: hidden;
}

.philosophy-inner {
  max-width: 900px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 4rem;
  align-items: center;
}

.philosophy-deco {
  position: relative;
}

.deco-circle {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  border: 1px solid rgba(201, 168, 76, 0.2);
  position: relative;
}

.deco-circle::after {
  content: "";
  position: absolute;
  inset: 20px;
  border-radius: 50%;
  border: 1px solid rgba(201, 168, 76, 0.1);
}

.deco-line-h {
  width: 60px;
  height: 1px;
  background: var(--gold);
  margin-top: 2rem;
  opacity: 0.4;
}

.philosophy-text h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 400;
  color: var(--cream);
  line-height: 1.25;
  margin-bottom: 0.5rem;
}

.philosophy-text h2 em {
  font-style: italic;
  color: var(--gold-light);
}

.attr {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  letter-spacing: 1.5px;
  color: var(--warm-muted);
  margin-bottom: 2rem;
}

.body-text {
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 300;
  color: rgba(232, 221, 200, 0.7);
  line-height: 1.9;
}

/* ── Menu ── */
.menu-section {
  padding: 8rem 2rem;
  background: var(--cream-dark);
}

.menu-header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 5rem;
}

.menu-header h2 {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 4vw, 3.5rem);
  font-weight: 400;
  color: var(--brown);
  margin-top: 0.5rem;
}

.menu-grid {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.menu-item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-top: 1px solid rgba(44, 26, 14, 0.12);
}

.menu-item:last-child {
  border-bottom: 1px solid rgba(44, 26, 14, 0.12);
}

.menu-item--reverse {
  direction: rtl;
}
.menu-item--reverse > * {
  direction: ltr;
}

.menu-img {
  height: 360px;
  background-color: var(--brown-mid);
  position: relative;
  overflow: hidden;
}

.menu-img--1 {
  background: linear-gradient(135deg, #3a1e0a 0%, #5a2e12 40%, #8a4a22 70%, #3a1e0a 100%);
}
.menu-img--2 {
  background: linear-gradient(135deg, #1a1005 0%, #3a2010 40%, #6a3820 70%, #1a1005 100%);
}
.menu-img--3 {
  background: linear-gradient(135deg, #2a1808 0%, #4a2810 40%, #7a4830 70%, #2a1808 100%);
}

.menu-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(201, 168, 76, 0.08) 0%, transparent 70%);
}

.menu-info {
  padding: 4rem 4rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: var(--cream);
}

.menu-course {
  font-family: var(--font-ui);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--terracotta);
  margin-bottom: 1rem;
}

.menu-info h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 400;
  color: var(--brown);
  margin-bottom: 1rem;
  line-height: 1.2;
}

.menu-info p {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 300;
  color: var(--warm-gray);
  line-height: 1.8;
  margin-bottom: 2rem;
}

.menu-price {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 400;
  color: var(--gold);
  letter-spacing: 1px;
}

.menu-footer {
  text-align: center;
  margin-top: 4rem;
  padding-top: 3rem;
  border-top: 1px solid rgba(44, 26, 14, 0.12);
}

.menu-footer p {
  font-family: var(--font-body);
  font-size: 1rem;
  font-style: italic;
  color: var(--warm-gray);
  margin-bottom: 1.5rem;
}

/* ── Story ── */
.story-section {
  padding: 8rem 2rem;
  background: var(--parchment);
}

.story-grid {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6rem;
  align-items: center;
}

.story-images {
  position: relative;
}

.story-img {
  border-radius: 2px;
}

.story-img--main {
  width: 100%;
  height: 500px;
  background: linear-gradient(160deg, #2c1a0e 0%, #4a2e1a 40%, #6a3820 70%, #2c1a0e 100%);
}

.story-img--accent {
  width: 55%;
  height: 200px;
  position: absolute;
  bottom: -3rem;
  right: -3rem;
  background: linear-gradient(160deg, #c1714a 0%, #a05a38 50%, #c1714a 100%);
  border: 4px solid var(--parchment);
}

.story-year {
  position: absolute;
  top: 2rem;
  left: -2rem;
  font-family: var(--font-display);
  font-size: 5rem;
  font-weight: 900;
  color: rgba(201, 168, 76, 0.12);
  line-height: 1;
  pointer-events: none;
  user-select: none;
}

.story-content .section-label {
  margin-bottom: 1.5rem;
}

.story-content h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.5vw, 2.8rem);
  font-weight: 400;
  color: var(--brown);
  line-height: 1.2;
  margin-bottom: 2rem;
}

.story-content p {
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 300;
  color: var(--warm-gray);
  line-height: 1.9;
  margin-bottom: 1.5rem;
}

.story-awards {
  display: flex;
  gap: 2.5rem;
  margin-top: 3rem;
  padding-top: 2.5rem;
  border-top: 1px solid rgba(44, 26, 14, 0.15);
}

.award {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.award-num {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--terracotta);
  line-height: 1;
}

.award span:last-child {
  font-family: var(--font-ui);
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--warm-muted);
}

/* ── Reservation ── */
.reservation-section {
  padding: 8rem 2rem;
  background: var(--brown);
  text-align: center;
}

.res-inner {
  max-width: 600px;
  margin: 0 auto;
}

.reservation-section .section-label {
  color: var(--gold);
}

.reservation-section h2 {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 4vw, 3.5rem);
  font-weight: 400;
  color: var(--cream);
  margin-bottom: 1.5rem;
}

.reservation-section p {
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 300;
  color: rgba(232, 221, 200, 0.65);
  line-height: 1.8;
  margin-bottom: 3rem;
}

.res-info {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 3rem;
  padding: 2.5rem;
  border: 1px solid rgba(201, 168, 76, 0.2);
  border-radius: 2px;
  text-align: left;
}

.res-detail {
  display: flex;
  gap: 1rem;
  align-items: baseline;
}

.res-label {
  font-family: var(--font-ui);
  font-size: 0.65rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--gold);
  min-width: 80px;
}

.res-detail span:last-child {
  font-family: var(--font-body);
  font-size: 1rem;
  color: rgba(232, 221, 200, 0.75);
}

/* ── Footer ── */
.footer {
  padding: 3rem 2rem;
  background: var(--charcoal);
  text-align: center;
  border-top: 1px solid rgba(201, 168, 76, 0.1);
}

.footer-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  color: var(--gold);
  margin-bottom: 0.8rem;
}

.footer p {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--warm-muted);
  letter-spacing: 0.5px;
}

.footer-copy {
  margin-top: 1rem;
  font-size: 0.7rem !important;
  color: rgba(122, 106, 88, 0.5) !important;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .philosophy-inner {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .philosophy-deco {
    display: none;
  }
  .menu-item,
  .menu-item--reverse {
    grid-template-columns: 1fr;
    direction: ltr;
  }
  .menu-img {
    height: 250px;
  }
  .story-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .story-img--accent {
    display: none;
  }
  .story-year {
    display: none;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 1rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .hero-title {
    font-size: clamp(2.5rem, 10vw, 5rem);
  }
  .menu-info {
    padding: 2.5rem 2rem;
  }
  .story-awards {
    flex-direction: column;
    gap: 1.5rem;
  }
  .res-info {
    padding: 1.5rem;
  }
}

html.reduced-motion * {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

