  align-items: baseline;
}

.section-header p {
  color: var(--muted);
}

.cards {
  display: grid;
  gap: 24px;
  margin-top: 28px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.card {
  padding: 22px;
  border-radius: 18px;
  background: rgba(8, 10, 18, 0.85);
  border: 1px solid rgba(42, 241, 255, 0.15);
  box-shadow: 0 0 25px rgba(42, 241, 255, 0.12);
}

.card-tag {
  font-family: "Oxanium", sans-serif;
  letter-spacing: 0.3em;
  font-size: 0.7rem;
  color: var(--neon-yellow);
}

.card p {
  color: var(--muted);
  line-height: 1.6;
}

.card-meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--muted);
}

.split {
  display: grid;
  gap: 28px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
}

.panel {
  padding: 26px;
  background: rgba(10, 12, 20, 0.8);
  border-radius: 18px;
  border: 1px solid rgba(255, 56, 199, 0.18);
}

.panel ul {
  margin: 16px 0 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.7;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 18px;
}

.chips span {
  padding: 0.45rem 0.9rem;
  border-radius: 999px;
  border: 1px solid rgba(42, 241, 255, 0.35);
  font-size: 0.75rem;
}

.stats {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  text-align: center;
}

.stats h2 {
  font-family: "Oxanium", sans-serif;
  font-size: 2.4rem;
  margin: 0 0 8px;
  color: var(--neon-cyan);
}

.lab-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.lab-card {
  padding: 18px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(8, 10, 18, 0.85);
}

.contact {
  display: grid;
  gap: 32px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
}

.contact-form {
  display: grid;
  gap: 16px;
}

.contact-form input,
.contact-form textarea {
  background: rgba(6, 8, 14, 0.8);
  border: 1px solid rgba(42, 241, 255, 0.2);
  border-radius: 12px;
  padding: 12px 14px;
  color: var(--text);
  font-size: 0.95rem;
}

.contact-form input:focus,
.contact-form textarea:focus {
  outline: none;
  border-color: var(--neon-cyan);
  box-shadow: 0 0 18px rgba(42, 241, 255, 0.3);
}

@media (max-width: 900px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
  }

  .nav {
    flex-wrap: wrap;
  }
}

@media (max-width: 640px) {
  .page {
    padding: 0 18px 80px;
  }
}

