const lenis = window.Lenis
  ? new Lenis({
      smoothWheel: true,
      smoothTouch: false,
      lerp: 0.08,
    })
  : null;

const projects = [
  {
    id: "01",
    title: "Night City Grid",
    copy: "Realtime city telemetry dashboard with adaptive neon layers.",
    tags: ["UI/UX", "2026"],
  },
  {
    id: "02",
    title: "Ghostwire Relay",
    copy: "Cyberpunk launch site with kinetic typography and motion gates.",
    tags: ["WebGL", "2025"],
  },
  {
    id: "03",
    title: "Synapse Archive",
    copy: "Data storytelling interface for biotech intelligence.",
    tags: ["Brand", "2025"],
  },
  {
    id: "04",
    title: "Signal Loom",
    copy: "Identity system with neon typography and modular UI kits.",
    tags: ["System", "2024"],
  },
];

const abilities = [
  "Realtime HUD systems",
  "Motion-first UI choreography",
  "Neon brand systems",
  "3D dashboards and data overlays",
];

const skills = ["Figma", "Three.js", "GSAP", "Lenis", "WebGL", "TypeScript", "Framer"];

const stats = [
  { value: "12", label: "Years crafting motion-forward narratives." },
  { value: "38", label: "Launches for cyber-native brands." },
  { value: "94%", label: "Repeat collaboration rate." },
];

const lab = [
  { title: "Drift Ticker", desc: "Marquee speed reacts to Lenis velocity." },
  { title: "Neon Pulse", desc: "Ambient glow synced to scroll momentum." },
  { title: "City Grid", desc: "3D skyline driven by motion signals." },
];

const projectGrid = document.getElementById("project-cards");
const abilityList = document.getElementById("abilities-list");
const skillChips = document.getElementById("skill-chips");
const statsGrid = document.getElementById("stats-grid");
const labGrid = document.getElementById("lab-grid");

if (projectGrid) {
  projectGrid.innerHTML = projects
    .map(
      (project) => `
        <article class="card">
          <div class="card-tag">${project.id}</div>
          <h3>${project.title}</h3>
          <p>${project.copy}</p>
          <div class="card-meta">
            <span>${project.tags[0]}</span>
            <span>${project.tags[1]}</span>
          </div>
        </article>
      `
    )
    .join("");
}

if (abilityList) {
  abilityList.innerHTML = abilities.map((item) => `<li>${item}</li>`).join("");
}

if (skillChips) {
  skillChips.innerHTML = skills.map((skill) => `<span>${skill}</span>`).join("");
}

if (statsGrid) {
  statsGrid.innerHTML = stats
    .map(
      (stat) => `
        <div>
          <h2>${stat.value}</h2>
          <p>${stat.label}</p>
        </div>
      `
    )
    .join("");
}

if (labGrid) {
  labGrid.innerHTML = lab
    .map(
      (item) => `
        <article class="lab-card">
          <h3>${item.title}</h3>
          <p>${item.desc}</p>
        </article>
      `
    )
    .join("");
}

let scrollVelocity = 0;
let tickerX = 0;
const tickerTrack = document.getElementById("tickerTrack");

function raf(time) {
  if (lenis) lenis.raf(time);
  scrollVelocity *= 0.9;
  document.documentElement.style.setProperty("--scan-shift", `${scrollVelocity * 0.6}px`);
  requestAnimationFrame(raf);
}
requestAnimationFrame(raf);

if (lenis) {
  lenis.on("scroll", ({ velocity }) => {
    scrollVelocity = Math.max(Math.min(velocity, 40), -40);
  });
}

if (tickerTrack) {
  const loop = () => {
    tickerX -= 0.35 + Math.abs(scrollVelocity) * 0.02;
    tickerTrack.style.transform = `translateX(${tickerX}px)`;
    if (Math.abs(tickerX) > tickerTrack.scrollWidth / 2) {
      tickerX = 0;
    }
    requestAnimationFrame(loop);
  };
  loop();
}

if (window.gsap) {
  gsap.from(".hero-copy", { opacity: 0, y: 30, duration: 1, ease: "power3.out" });
  gsap.from(".hero-panel", { opacity: 0, x: 30, duration: 1, delay: 0.15, ease: "power3.out" });
  gsap.utils.toArray(".card, .panel, .chips span, .stats div, .lab-card").forEach((item, index) => {
    gsap.from(item, {
      opacity: 0,
      y: 24,
      duration: 0.8,
      delay: index * 0.04,
      ease: "power2.out",
    });
  });
}

class NeonCity {
  constructor(container) {
    this.container = container;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 200);
    this.camera.position.set(0, 8, 24);

    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(this.renderer.domElement);

    this.clock = new THREE.Clock();
    this.city = new THREE.Group();
    this.scene.add(this.city);

    this.addLights();
    this.buildGrid();
    this.buildCity();
    this.buildParticles();

    this.bindEvents();
    this.animate();
  }

  addLights() {
    this.scene.add(new THREE.AmbientLight(0x8b4dff, 0.4));
    const key = new THREE.DirectionalLight(0x2af1ff, 0.8);
    key.position.set(10, 20, 10);
    this.scene.add(key);

    const rim = new THREE.DirectionalLight(0xff38c7, 0.6);
    rim.position.set(-10, 8, -10);
    this.scene.add(rim);
  }

  buildGrid() {
    const size = 120;
    const divisions = 30;
    const grid = new THREE.GridHelper(size, divisions, 0x2af1ff, 0x2af1ff);
    grid.material.opacity = 0.2;
    grid.material.transparent = true;
    grid.position.y = -2;
    this.scene.add(grid);
  }

  buildCity() {
    const blockMat = new THREE.MeshStandardMaterial({
      color: 0x110b1f,
      roughness: 0.4,
      metalness: 0.6,
      emissive: 0x2af1ff,
      emissiveIntensity: 0.2,
    });

    for (let i = 0; i < 80; i++) {
      const w = 0.6 + Math.random() * 1.4;
      const h = 1 + Math.random() * 8;
      const d = 0.6 + Math.random() * 1.4;
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), blockMat.clone());
      mesh.position.set((Math.random() - 0.5) * 30, h / 2 - 2, (Math.random() - 0.5) * 30);
      mesh.material.emissiveIntensity = 0.2 + Math.random() * 0.6;
      this.city.add(mesh);
    }
  }

  buildParticles() {
    const count = 220;
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 40;
      positions[i * 3 + 1] = Math.random() * 18;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 40;
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));

    const material = new THREE.PointsMaterial({ color: 0xff38c7, size: 0.08 });
    this.particles = new THREE.Points(geometry, material);
    this.scene.add(this.particles);
  }

  bindEvents() {
    window.addEventListener("resize", () => this.onResize());
  }

  onResize() {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }

  animate() {
    const t = this.clock.getElapsedTime();
    const drift = scrollVelocity * 0.004;
    this.city.rotation.y = t * 0.05 + drift;
    this.city.position.z = Math.sin(t * 0.2) * 1.2;
    this.particles.rotation.y = t * 0.08;
    this.renderer.render(this.scene, this.camera);
    requestAnimationFrame(() => this.animate());
  }
}

const bg = document.getElementById("cyber-bg");
if (bg && window.THREE) {
  new NeonCity(bg);
}

snippets.css:
@import url("https://fonts.googleapis.com/css2?family=Black+Ops+One&family=Orbitron:wght@400;700;900&family=Rajdhani:wght@300;400;500;600;700&display=swap");

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --pink: #ffb6c1;
  --pink-dark: #ff69b4;
  --pink-light: #ffc0cb;
  --dark-bg: #0a0a0a;
  --dark-bg-2: #1a0a0a;
  --text-white: #ffffff;
  --text-gray: #cccccc;
}

body {
  font-family: "Rajdhani", sans-serif;
  background: var(--dark-bg);
  color: var(--text-white);
  overflow-x: hidden;
  position: relative;
}

#canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

.container {
  position: relative;
  z-index: 1;
}

/* Navbar */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  padding: 1.5rem 6rem;
  background: rgba(10, 10, 10, 0.8);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 182, 193, 0.2);
  z-index: 1000;
  transform: translateY(-100%);
  opacity: 0;
  transition:
    transform 0.6s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.6s ease,
    padding 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.navbar.visible {
  transform: translateY(0);
  opacity: 1;
}

.navbar.hidden {
  transform: translateY(-100%);
  opacity: 0;
}

.navbar.scrolled {
  padding: 1rem 6rem;
  background: rgba(10, 10, 10, 0.95);
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.5);
  border-bottom: 1px solid rgba(255, 182, 193, 0.3);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1400px;
  margin: 0 auto;
}

.nav-logo {
  font-family: "Black Ops One", cursive;
  font-size: 1.5rem;
  font-weight: 400;
  opacity: 0;
  transform: translateX(-30px);
  transition: opacity 0.6s ease 0.2s, transform 0.6s cubic-bezier(0.4, 0, 0.2, 1) 0.2s;
}

.navbar.visible .nav-logo {
  opacity: 1;
  transform: translateX(0);
}

.logo-link {
  color: var(--pink);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-shadow: 0 0 10px rgba(255, 182, 193, 0.5), 2px 2px 0px rgba(0, 0, 0, 0.8);
  transition: all 0.3s ease;
}

.logo-link:hover {
  color: var(--pink-light);
  text-shadow: 0 0 20px rgba(255, 182, 193, 0.8), 2px 2px 0px rgba(0, 0, 0, 0.8);
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: 3rem;
  align-items: center;
  opacity: 0;
  transform: translateX(30px);
  transition: opacity 0.6s ease 0.4s, transform 0.6s cubic-bezier(0.4, 0, 0.2, 1) 0.4s;
}

.navbar.visible .nav-menu {
  opacity: 1;
  transform: translateX(0);
}

.nav-item {
  position: relative;
  opacity: 0;
  transform: translateY(-20px);
  transition: opacity 0.4s ease, transform 0.4s ease;
}

.navbar.visible .nav-item {
  opacity: 1;
  transform: translateY(0);
}

.navbar.visible .nav-item:nth-child(1) {
  transition-delay: 0.5s;
}
.navbar.visible .nav-item:nth-child(2) {
  transition-delay: 0.6s;
}
.navbar.visible .nav-item:nth-child(3) {
  transition-delay: 0.7s;
}
.navbar.visible .nav-item:nth-child(4) {
  transition-delay: 0.8s;
}
.navbar.visible .nav-item:nth-child(5) {
  transition-delay: 0.9s;
}

.nav-link {
  font-family: "Orbitron", sans-serif;
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--text-white);
  text-decoration: none;
  padding: 0.5rem 0;
  position: relative;
  transition: color 0.3s ease, transform 0.3s ease;
}

.nav-link::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--pink);
  transition: width 0.3s ease;
  box-shadow: 0 0 10px rgba(255, 182, 193, 0.5);
}

.nav-link:hover {
  color: var(--pink);
  transform: translateY(-2px);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-link.active {
  color: var(--pink);
}

.nav-link.active::after {
  width: 100%;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  cursor: pointer;
  gap: 5px;
  opacity: 0;
  transform: scale(0.8);
  transition: opacity 0.6s ease 0.6s, transform 0.6s cubic-bezier(0.4, 0, 0.2, 1) 0.6s;
}

.navbar.visible .nav-toggle {
  opacity: 1;
  transform: scale(1);
}

.bar {
  width: 25px;
  height: 3px;
  background: var(--pink);
  transition: all 0.3s ease;
  box-shadow: 0 0 5px rgba(255, 182, 193, 0.5);
}

.nav-toggle.active .bar:nth-child(1) {
  transform: rotate(45deg) translate(8px, 8px);
}

.nav-toggle.active .bar:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active .bar:nth-child(3) {
  transform: rotate(-45deg) translate(7px, -7px);
}

/* Hero Section */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 4rem 6rem;
  padding-top: 8rem;
  position: relative;
}

.main-title {
  font-family: "Black Ops One", cursive;
  font-size: clamp(8rem, 20vw, 16rem);
  font-weight: 400;
  color: var(--pink);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  line-height: 0.9;
  text-shadow: 0 0 20px rgba(255, 182, 193, 0.5), 0 0 40px rgba(255, 182, 193, 0.3), 4px 4px 0px
    rgba(0, 0, 0, 0.8), 8px 8px 0px rgba(0, 0, 0, 0.6);
  margin-top: 2rem;
  position: relative;
  z-index: 2;
}

.subtitle-section {
  display: flex;
  align-items: baseline;
  gap: 2rem;
  margin-top: -4rem;
  position: relative;
  z-index: 2;
}

.subtitle {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--text-white);
}

.copyright {
  font-family: "Rajdhani", sans-serif;
  font-size: clamp(0.875rem, 1.5vw, 1rem);
  font-weight: 400;
  color: var(--text-white);
  letter-spacing: 0.1em;
}

.hero-bottom {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-top: auto;
  padding-top: 4rem;
}

.hero-left {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.scroll-cta {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(1rem, 2vw, 1.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--text-white);
}

.hero-description {
  font-family: "Rajdhani", sans-serif;
  font-size: clamp(0.875rem, 1.5vw, 1rem);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-white);
  max-width: 500px;
}

.hero-buttons {
  display: flex;
  gap: 1.5rem;
}

.btn {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 2rem;
  background: var(--pink);
  border: none;
  color: var(--text-white);
  font-family: "Orbitron", sans-serif;
  font-size: clamp(0.875rem, 1.2vw, 1rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.btn::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 40px;
  height: 100%;
  background: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.3);
  font-size: 1.2rem;
  position: relative;
  z-index: 1;
}

.btn:hover {
  background: var(--pink-dark);
  transform: translateY(-2px);
  box-shadow: 0 10px 30px rgba(255, 182, 193, 0.4);
}

/* Sections */
.section {
  min-height: 100vh;
  padding: 8rem 6rem;
  position: relative;
}

.section-title {
  font-family: "Black Ops One", cursive;
  font-size: clamp(4rem, 10vw, 8rem);
  color: var(--pink);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 4rem;
  text-shadow: 0 0 20px rgba(255, 182, 193, 0.5), 2px 2px 0px rgba(0, 0, 0, 0.8);
}

/* About Section */
.content-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 3rem;
  margin-top: 4rem;
}

.content-item {
  padding: 2rem;
  border: 1px solid rgba(255, 182, 193, 0.2);
  background: rgba(255, 182, 193, 0.05);
  transition: all 0.3s ease;
}

.content-item:hover {
  border-color: var(--pink);
  background: rgba(255, 182, 193, 0.1);
  transform: translateY(-5px);
}

.content-item h3 {
  font-family: "Orbitron", sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--pink);
  margin-bottom: 1rem;
}

.content-item p {
  font-family: "Rajdhani", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-gray);
}

/* Projects Section */
.projects-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 3rem;
  margin-top: 4rem;
}

.project-card {
  padding: 2.5rem;
  border: 1px solid rgba(255, 182, 193, 0.2);
  background: rgba(255, 182, 193, 0.05);
  position: relative;
  transition: all 0.3s ease;
  cursor: pointer;
  overflow: hidden;
}

.project-card::after {
  content: "CLICK TO EXPAND →";
  position: absolute;
  bottom: 1rem;
  left: 2.5rem;
  font-family: "Orbitron", sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--pink);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.project-card:hover {
  border-color: var(--pink);
  background: rgba(255, 182, 193, 0.1);
  transform: translateY(-10px);
