/* Card image area */
.card-image {
  aspect-ratio: 1 / 1;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.card-image .shape-inner {
  position: absolute;
  width: 50%;
  height: 50%;
