  padding: 14px 0;
  border-radius: var(--radius-sm);
  background: var(--page-accent);
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  transition: background 0.25s;
}

.btn-add-large:hover {
