.cart-sidebar.open {
  pointer-events: auto;
  opacity: 1;
  visibility: visible;
}

.cart-sidebar-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
}

.cart-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 380px;
  height: 100%;
  background: var(--page-surface);
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.1);
