.cart-item-meta {
  font-size: 0.78rem;
  color: var(--page-muted);
  margin-top: 2px;
}

.cart-item-price {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--page-text);
  flex-shrink: 0;
}

.cart-item-remove {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 0.75rem;
  color: var(--page-muted);
  flex-shrink: 0;
  transition: background 0.2s, color 0.2s;
}

.cart-item-remove:hover {
  background: rgba(239, 68, 68, 0.1);
  color: var(--page-badge);
}

/* Cart footer */
.cart-footer {
  padding: 20px 24px;
  border-top: 1px solid var(--page-border);
}

.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 16px;
  font-size: 1rem;
  font-weight: 700;
  color: var(--page-text);
}

.btn-checkout {
  width: 100%;
  padding: 14px 0;
  border-radius: var(--radius-sm);
  background: var(--page-cart);
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  transition: background 0.25s;
}

.btn-checkout:hover {
  background: #111;
}

/* ═══════════════════════════════════════════════════════════════════
   VIEW TRANSITION NAMES
   ═══════════════════════════════════════════════════════════════════ */
.product-card.vt-active .card-image {
  view-transition-name: product-hero;
}

.product-card.vt-active .card-title {
  view-transition-name: product-title;
}

.detail-overlay.open .detail-image {
  view-transition-name: product-hero;
}

/* View Transition animation tuning */
::view-transition-old(product-hero),
::view-transition-new(product-hero) {
  animation-duration: 0.4s;
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

::view-transition-old(product-title),
::view-transition-new(product-title) {
  animation-duration: 0.35s;
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ═══════════════════════════════════════════════════════════════════
   REDUCED MOTION
   ═══════════════════════════════════════════════════════════════════ */
.reduced-motion .product-card {
  opacity: 1 !important;
  transform: none !important;
}

.reduced-motion .hero-headline .word {
  opacity: 1 !important;
  transform: none !important;
}

.reduced-motion .product-card:hover {
  transform: none;
}

.reduced-motion .cart-panel {
  transition: none;
}

.reduced-motion .detail-overlay {
  transition: none;
}

.reduced-motion .cart-sidebar {
  transition: none;
}

/* ═══════════════════════════════════════════════════════════════════
   RESPONSIVE
   ═══════════════════════════════════════════════════════════════════ */
@media (max-width: 900px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
  }
}

@media (max-width: 600px) {
  .product-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .hero-section {
    padding: 40px 16px 16px;
  }

  .grid-section {
    padding: 24px 16px 60px;
  }

  .header-inner {
    padding: 14px 16px;
  }

  .filter-nav {
    padding: 0 16px 12px;
    gap: 6px;
  }

  .filter-pill {
    padding: 6px 14px;
    font-size: 0.78rem;
  }

  /* Detail panel - stacked layout on mobile */
  .detail-panel {
    grid-template-columns: 1fr;
    width: 95%;
    max-height: 85vh;
  }

  .detail-image {
    border-radius: var(--radius) var(--radius) 0 0;
    aspect-ratio: 16 / 10;
    min-height: 200px;
  }

  .detail-info {
    padding: 24px 20px 32px;
  }

  /* Cart panel full width on mobile */
  .cart-panel {
    width: 100%;
  }
}

/* ═══════════════════════════════════════════════════════════════════
   ENTRANCE ANIMATION HELPERS
   ═══════════════════════════════════════════════════════════════════ */
.product-card {
  opacity: 0;
  transform: translateY(30px);
}

.product-card.in-view {
  opacity: 1;
  transform: translateY(0);
}

