import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { TextPlugin } from "gsap/TextPlugin";
import Lenis from "lenis";

gsap.registerPlugin(ScrollTrigger, TextPlugin);

initDemoShell({
  title: "Data Dashboard",
  category: "pages",
  tech: ["gsap", "canvas-2d", "scrolltrigger", "lenis", "textplugin"],
});

const lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

// ─── Hero ───────────────────────────────────────────────────────────────────
if (!reduced) {
  const heroTl = gsap.timeline({ defaults: { ease: "expo.out" } });
  gsap.set([".hero-badge", ".hero-title", ".hero-sub", ".hero-cta"], { opacity: 0, y: 30 });
  heroTl
    .to(".hero-badge", { opacity: 1, y: 0, duration: 0.6, delay: 0.4 })
    .to(".hero-title", { opacity: 1, y: 0, duration: 1 }, "-=0.3")
    .to(".hero-sub", { opacity: 1, y: 0, duration: 0.7 }, "-=0.5")
    .to(".hero-cta", { opacity: 1, y: 0, duration: 0.6 }, "-=0.4");
}

// Gradient hue shift on scroll — hero title (Demo 37 technique)
if (!reduced) {
  ScrollTrigger.create({
    trigger: document.body,
    start: "top top",
    end: "bottom bottom",
    onUpdate: (self) => {
      const hue = self.progress * 360;
      document.documentElement.style.setProperty("--hue-shift", `${hue}deg`);
    },
  });
}

// ─── Metrics Counters (Demo 36 technique) ───────────────────────────────────
const metricCards = document.querySelectorAll(".metric-card");

metricCards.forEach((card, i) => {
  const valueEl = card.querySelector(".metric-value");
  const target = parseFloat(card.dataset.target);
  const suffix = card.dataset.suffix || "";
  let currentValue = 0;

  if (!reduced) {
    // Card entrance
    gsap.set(card, { opacity: 0, y: 40, scale: 0.95 });
    gsap.to(card, {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 0.8,
      ease: "expo.out",
      delay: i * 0.07,
      scrollTrigger: {
        trigger: ".metrics-grid",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });

    // Progress bar fill
    const bar = card.querySelector(".metric-bar-fill");
    if (bar) {
      gsap.set(bar, { scaleX: 0, transformOrigin: "left center" });
      gsap.to(bar, {
        scaleX: 1,
        duration: 1.2,
        ease: "expo.out",
        delay: i * 0.1 + 0.5,
        scrollTrigger: {
          trigger: ".metrics-grid",
          start: "top 75%",
          toggleActions: "play none none reverse",
        },
      });
    }

    // Counter animation scrubbed to scroll
    ScrollTrigger.create({
      trigger: card,
      start: "top 80%",
      end: "top 20%",
      onUpdate: (self) => {
        const progress = self.progress;
        currentValue = target * progress;

        let display;
        if (target >= 1000) {
          display = Math.round(currentValue).toLocaleString();
        } else if (target < 10) {
          display = currentValue.toFixed(1);
        } else {
          display = Math.round(currentValue);
        }
        valueEl.textContent = display + suffix;
      },
    });
  } else {
    valueEl.textContent = target >= 1000 ? target.toLocaleString() + suffix : target + suffix;
  }
});

// ─── Section Headers ─────────────────────────────────────────────────────────
document.querySelectorAll(".section-header").forEach((header) => {
  if (!reduced) {
    gsap.set(header.children, { opacity: 0, y: 30 });
    gsap.to(header.children, {
      opacity: 1,
      y: 0,
      duration: 0.8,
      ease: "expo.out",
      stagger: 0.1,
      scrollTrigger: { trigger: header, start: "top 75%", toggleActions: "play none none reverse" },
    });
  }
});

// ─── Canvas Charts ───────────────────────────────────────────────────────────
function animateBarChart(canvas, progress) {
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;
  const data2024 = [22, 28, 25, 32, 30, 38, 35, 41, 38, 44, 42, 48];
  const data2025 = [48, 52, 45, 58, 62, 55, 68, 72, 65, 78, 82, 90];
  const months = ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"];
  const padding = { top: 16, right: 16, bottom: 32, left: 32 };
  const chartW = W - padding.left - padding.right;
  const chartH = H - padding.top - padding.bottom;
  const maxVal = Math.max(...data2025) * 1.1;
  const barGroupW = chartW / data2024.length;
  const barW = barGroupW * 0.35;

  ctx.clearRect(0, 0, W, H);
  ctx.font = "10px -apple-system, sans-serif";
  ctx.fillStyle = "rgba(138, 149, 168, 0.5)";

  // Grid lines
  for (let i = 0; i <= 4; i++) {
    const y = padding.top + chartH - (chartH * i) / 4;
    ctx.beginPath();
    ctx.strokeStyle = "rgba(38, 50, 73, 0.8)";
    ctx.lineWidth = 1;
    ctx.moveTo(padding.left, y);
    ctx.lineTo(W - padding.right, y);
    ctx.stroke();
    ctx.fillText(Math.round((maxVal * i) / 4), 2, y + 4);
  }

  // Bars
  data2024.forEach((val, i) => {
    const x = padding.left + i * barGroupW;
    const barH2024 = (val / maxVal) * chartH * Math.min(1, progress * 1.5);
    const barH2025 = (data2025[i] / maxVal) * chartH * Math.min(1, progress * 1.5);

    // 2024 bar
    ctx.fillStyle = "rgba(134, 232, 255, 0.35)";
    ctx.fillRect(x + barGroupW * 0.1, padding.top + chartH - barH2024, barW, barH2024);

    // 2025 bar
    ctx.fillStyle = "rgba(174, 82, 255, 0.7)";
    ctx.fillRect(x + barGroupW * 0.1 + barW + 2, padding.top + chartH - barH2025, barW, barH2025);

    // Month label
    ctx.fillStyle = "rgba(138, 149, 168, 0.7)";
    ctx.fillText(months[i], x + barGroupW * 0.3, H - 8);
  });
}

function animateDonutChart(canvas, progress) {
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;
  const cx = W / 2;
  const cy = H / 2;
  const outerR = Math.min(W, H) * 0.42;
  const innerR = outerR * 0.58;
  const data = [
    { val: 0.62, color: "#86e8ff", label: "SaaS" },
    { val: 0.28, color: "#ae52ff", label: "Enterprise" },
    { val: 0.1, color: "#ffcc66", label: "Add-ons" },
  ];

  ctx.clearRect(0, 0, W, H);

  let startAngle = -Math.PI / 2;
  data.forEach((seg) => {
    const sweep = seg.val * 2 * Math.PI * Math.min(1, progress);
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, outerR, startAngle, startAngle + sweep);
    ctx.arc(cx, cy, innerR, startAngle + sweep, startAngle, true);
    ctx.closePath();
    ctx.fillStyle = seg.color;
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;
    startAngle += sweep;
  });

  // Center text
  ctx.font = `bold 18px -apple-system, sans-serif`;
  ctx.fillStyle = "#f0f4fb";
  ctx.textAlign = "center";
  ctx.fillText("Revenue", cx, cy - 4);
  ctx.font = `12px -apple-system, sans-serif`;
  ctx.fillStyle = "#8a95a8";
  ctx.fillText("Q4 2025", cx, cy + 14);
}

function animateAreaChart(canvas, progress) {
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;
  const padding = { top: 16, right: 16, bottom: 24, left: 40 };
  const chartW = W - padding.left - padding.right;
  const chartH = H - padding.top - padding.bottom;

  // Generate random-ish API request data
  const points = Array.from({ length: 30 }, (_, i) => {
    const base = 2.5 + Math.sin(i * 0.4) * 0.6;
    const noise = Math.sin(i * 1.7 + 2) * 0.3 + Math.sin(i * 0.9) * 0.2;
    return base + noise;
  });
  const maxVal = Math.max(...points) * 1.1;

  ctx.clearRect(0, 0, W, H);

  // Grid
  ctx.strokeStyle = "rgba(38, 50, 73, 0.6)";
  ctx.lineWidth = 1;
  for (let i = 0; i <= 3; i++) {
    const y = padding.top + (chartH * i) / 3;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(W - padding.right, y);
    ctx.stroke();
    ctx.font = "9px -apple-system, sans-serif";
    ctx.fillStyle = "rgba(138, 149, 168, 0.6)";
    ctx.fillText(`${(maxVal - (maxVal * i) / 3).toFixed(1)}M`, 2, y + 4);
  }

  const visiblePoints = Math.max(2, Math.round(points.length * progress));
  const step = chartW / (points.length - 1);

  // Area fill
  ctx.beginPath();
  ctx.moveTo(padding.left, padding.top + chartH);
  points.slice(0, visiblePoints).forEach((val, i) => {
    const x = padding.left + i * step;
    const y = padding.top + chartH - (val / maxVal) * chartH;
    if (i === 0) ctx.lineTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.lineTo(padding.left + (visiblePoints - 1) * step, padding.top + chartH);
  ctx.closePath();

  const grad = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
  grad.addColorStop(0, "rgba(134, 232, 255, 0.25)");
  grad.addColorStop(1, "rgba(134, 232, 255, 0)");
  ctx.fillStyle = grad;
  ctx.fill();

  // Line
  ctx.beginPath();
  points.slice(0, visiblePoints).forEach((val, i) => {
    const x = padding.left + i * step;
    const y = padding.top + chartH - (val / maxVal) * chartH;
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.strokeStyle = "#86e8ff";
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Chart animation on scroll
const barCanvas = document.getElementById("bar-chart");
const donutCanvas = document.getElementById("donut-chart");
const areaCanvas = document.getElementById("area-chart");

// Initialize charts at 0
animateBarChart(barCanvas, 0);
animateDonutChart(donutCanvas, 0);
animateAreaChart(areaCanvas, 0);

if (!reduced) {
  // Chart cards entrance
  document.querySelectorAll(".chart-card").forEach((card, i) => {
    gsap.set(card, { opacity: 0, y: 40 });
    gsap.to(card, {
      opacity: 1,
      y: 0,
      duration: 0.8,
      ease: "expo.out",
      delay: i * 0.1,
      scrollTrigger: {
        trigger: ".charts-grid",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });
  });

  // Bar chart animated on scroll
  ScrollTrigger.create({
    trigger: barCanvas,
    start: "top 80%",
    end: "top 10%",
    onUpdate: (self) => animateBarChart(barCanvas, self.progress),
  });

  // Donut chart
  ScrollTrigger.create({
    trigger: donutCanvas,
    start: "top 80%",
    end: "top 10%",
    onUpdate: (self) => animateDonutChart(donutCanvas, self.progress),
  });

  // Area chart
  ScrollTrigger.create({
    trigger: areaCanvas,
    start: "top 85%",
    end: "top 20%",
    onUpdate: (self) => animateAreaChart(areaCanvas, self.progress),
  });
} else {
  // Show full charts immediately for reduced motion
  animateBarChart(barCanvas, 1);
  animateDonutChart(donutCanvas, 1);
  animateAreaChart(areaCanvas, 1);
}

// ─── Timeline ────────────────────────────────────────────────────────────────
document.querySelectorAll(".tl-item").forEach((item, i) => {
  if (!reduced) {
    const side = item.dataset.side === "left" ? -40 : 40;
    gsap.set(item, { opacity: 0, x: side });
    gsap.to(item, {
      opacity: 1,
      x: 0,
      duration: 0.8,
      ease: "expo.out",
      scrollTrigger: { trigger: item, start: "top 75%", toggleActions: "play none none reverse" },
    });
  }
});

// ─── Team Grid ───────────────────────────────────────────────────────────────
document.querySelectorAll(".team-card").forEach((card, i) => {
  if (!reduced) {
    gsap.set(card, { opacity: 0, scale: 0.85, y: 20 });
    gsap.to(card, {
      opacity: 1,
      scale: 1,
      y: 0,
      duration: 0.7,
      ease: "back.out(1.5)",
      delay: i * 0.08,
      scrollTrigger: {
        trigger: ".team-grid",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });
  }
});

// ─── CTA ─────────────────────────────────────────────────────────────────────
if (!reduced) {
  gsap.set(".cta-section h2, .cta-section p, .cta-section a", { opacity: 0, y: 30 });
  gsap.to(".cta-section h2, .cta-section p, .cta-section a", {
    opacity: 1,
    y: 0,
    duration: 0.8,
    stagger: 0.12,
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".cta-section",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Motion preference ───────────────────────────────────────────────────────
window.addEventListener("motion-preference", (e) => {
  if (e.detail.reduced) {
    gsap.globalTimeline.paused(true);
    animateBarChart(barCanvas, 1);
    animateDonutChart(donutCanvas, 1);
    animateAreaChart(areaCanvas, 1);
  } else {
    gsap.globalTimeline.paused(false);
  }
});

snippets.css:
/* ═══════════════════════════════════════════════════════
   IRONFORM — Brutalist Bold Style
   Palette: Pure Black, Neon Yellow, White, Concrete Gray
   Fonts: Barlow Condensed (display), Barlow (body)
   Feel: Raw, aggressive, no-nonsense fitness brand
═══════════════════════════════════════════════════════ */

:root {
  --black: #0a0a0a;
  --black-mid: #151515;
  --concrete: #1e1e1e;
  --gray: #2a2a2a;
  --gray-mid: #444;
  --gray-light: #888;
  --white: #f5f5f5;
  --yellow: #f0e000;
  --yellow-d: #c8bb00;
  --yellow-dim: rgba(240, 224, 0, 0.12);

  --font-display: "Barlow Condensed", "Arial Narrow", sans-serif;
  --font-body: "Barlow", system-ui, sans-serif;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--white);
  overflow-x: hidden;
}

/* ── Nav ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.2rem 3rem;
  background: var(--black);
  border-bottom: 3px solid var(--yellow);
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 900;
  letter-spacing: -1px;
  color: var(--white);
}

.nav-logo span {
  color: var(--yellow);
}

.nav-links {
  list-style: none;
  display: flex;
  gap: 3rem;
}

.nav-links a {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--gray-light);
  text-decoration: none;
  transition: color 0.15s ease;
}

.nav-links a:hover {
  color: var(--yellow);
}

.nav-cta {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--black);
  background: var(--yellow);
  text-decoration: none;
  padding: 0.6rem 1.5rem;
  border: none;
  transition: background 0.15s ease, transform 0.15s ease;
  display: inline-block;
}

.nav-cta:hover {
  background: var(--yellow-d);
  transform: translateY(-1px);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 8rem 4rem 6rem;
  overflow: hidden;
  background: var(--black);
}

.hero-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero-stripe {
  position: absolute;
  background: var(--yellow);
  opacity: 0.04;
}

.hero-stripe--1 {
  width: 3px;
  top: 0;
  bottom: 0;
  right: 28%;
}

.hero-stripe--2 {
  height: 3px;
  left: 0;
  right: 0;
  bottom: 30%;
  opacity: 0.03;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 900px;
}

.hero-tag {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gray-light);
  margin-bottom: 2rem;
  border-left: 3px solid var(--yellow);
  padding-left: 1rem;
}

.hero-title {
  display: flex;
  flex-direction: column;
  margin-bottom: 2.5rem;
  line-height: 0.92;
}

.hero-line {
  font-family: var(--font-display);
  font-size: clamp(5rem, 14vw, 12rem);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -3px;
  color: var(--white);
  display: block;
}

.hero-line--yellow {
  color: var(--yellow);
}

.hero-line--outline {
  color: transparent;
  -webkit-text-stroke: 3px var(--white);
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 400;
  color: var(--gray-light);
  max-width: 500px;
  margin-bottom: 3rem;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-yellow {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 1.1rem 2.5rem;
  background: var(--yellow);
  color: var(--black);
  border: none;
  display: inline-block;
  transition: all 0.15s ease;
  cursor: pointer;
}

.btn-yellow:hover {
  background: var(--yellow-d);
  transform: translateY(-2px);
}

.btn-border-white {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 1.1rem 2.5rem;
  background: transparent;
  color: var(--white);
  border: 2px solid var(--gray-mid);
  display: inline-block;
  transition: all 0.15s ease;
}

.btn-border-white:hover {
  border-color: var(--yellow);
  color: var(--yellow);
}

/* Ticker */
.hero-ticker {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--yellow);
  overflow: hidden;
  padding: 0.7rem 0;
}

.ticker-track {
  display: flex;
  gap: 2rem;
  white-space: nowrap;
  animation: ticker 25s linear infinite;
  width: max-content;
}

.ticker-track span {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 900;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--black);
}

@keyframes ticker {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* ── Stats Bar ── */
.stats-bar {
  display: flex;
  align-items: stretch;
  background: var(--concrete);
  border-bottom: 3px solid var(--yellow);
}

.stat-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3.5rem 2rem;
  gap: 0.5rem;
}

.stat-divider {
  width: 1px;
  background: var(--gray);
  align-self: stretch;
}

.stat-big {
  font-family: var(--font-display);
  font-size: clamp(3rem, 5vw, 5rem);
  font-weight: 900;
  color: var(--yellow);
  line-height: 1;
  letter-spacing: -2px;
  font-variant-numeric: tabular-nums;
}

.stat-sub {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gray-light);
}

/* ── Programs ── */
.programs-section {
  padding: 7rem 4rem;
  background: var(--black-mid);
}

.programs-header {
  margin-bottom: 4rem;
  max-width: 600px;
}

.section-tag {
  display: block;
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--yellow);
  margin-bottom: 1rem;
  border-left: 3px solid var(--yellow);
  padding-left: 1rem;
}

.programs-header h2 {
  font-family: var(--font-display);
  font-size: clamp(3.5rem, 7vw, 6rem);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -2px;
  text-transform: uppercase;
}

.programs-header h2 em {
  font-style: italic;
  color: var(--yellow);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border: 2px solid var(--gray);
}

.program-card {
  padding: 3rem 2.5rem;
  border-right: 2px solid var(--gray);
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
  transition: transform 0.2s ease;
}

.program-card:last-child {
  border-right: none;
}

.program-card--dark {
  background: var(--concrete);
}
.program-card--yellow {
  background: var(--yellow);
}

.program-card--yellow h3,
.program-card--yellow p,
.program-card--yellow .program-meta span {
  color: var(--black) !important;
}

.program-num {
  font-family: var(--font-display);
  font-size: 4rem;
  font-weight: 900;
  line-height: 1;
  color: rgba(255, 255, 255, 0.08);
  letter-spacing: -2px;
}

.program-card--yellow .program-num {
  color: rgba(0, 0, 0, 0.1);
}

.program-card h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 900;
  letter-spacing: -0.5px;
  text-transform: uppercase;
  color: var(--white);
}

.program-card p {
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--gray-light);
  line-height: 1.7;
  flex: 1;
}

.program-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.program-meta span {
  font-family: var(--font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--gray-light);
  padding: 0.3rem 0.6rem;
  border: 1px solid var(--gray);
}

.program-card--yellow .program-meta span {
  border-color: rgba(0, 0, 0, 0.2);
}

.btn-yellow-sm {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.8rem 1.5rem;
  background: var(--yellow);
  color: var(--black);
  display: inline-block;
  transition: all 0.15s ease;
  align-self: flex-start;
}

.btn-yellow-sm:hover {
  background: var(--yellow-d);
}

.btn-black-sm {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.8rem 1.5rem;
  background: var(--black);
  color: var(--yellow);
  border: 2px solid var(--black);
  display: inline-block;
  transition: all 0.15s ease;
  align-self: flex-start;
}

.btn-black-sm:hover {
  background: var(--black-mid);
}

/* ── Transform ── */
.transform-section {
  padding: 7rem 4rem;
  background: var(--black);
  border-top: 3px solid var(--yellow);
  border-bottom: 3px solid var(--yellow);
}

.transform-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6rem;
  align-items: center;
}

.transform-text .section-tag {
  margin-bottom: 1.5rem;
}

.transform-text h2 {
  font-family: var(--font-display);
  font-size: clamp(3rem, 6vw, 5rem);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -2px;
  text-transform: uppercase;
  margin-bottom: 2rem;
}

.transform-text h2 em {
  font-style: italic;
  color: var(--yellow);
}

.result-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 3rem;
}

.result-list li {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--gray-light);
  display: flex;
  align-items: center;
  gap: 0.8rem;
  line-height: 1.5;
}

.check {
  color: var(--yellow);
  font-size: 1.1rem;
  flex-shrink: 0;
}

.transform-visual {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.tv-box {
  flex: 1;
  aspect-ratio: 3 / 4;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2rem;
  border: 2px solid var(--gray);
  position: relative;
  overflow: hidden;
}

.tv-box--before {
  background: linear-gradient(160deg, #1a1a1a 0%, #222 100%);
}

.tv-box--after {
  background: linear-gradient(160deg, #1a1a00 0%, #2a2a00 100%);
  border-color: var(--yellow);
}

.tv-label {
  font-family: var(--font-display);
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gray-light);
}

.tv-box--after .tv-label {
  color: var(--yellow);
}

.tv-week {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--gray-mid);
  align-self: flex-end;
}

.tv-box--after .tv-week {
  color: var(--yellow);
}

.tv-arrow {
  font-size: 2.5rem;
  color: var(--yellow);
  font-weight: 900;
  flex-shrink: 0;
}

/* ── Testimonials ── */
.testimonials-section {
  padding: 7rem 4rem;
  background: var(--black-mid);
}

.testi-header {
  margin-bottom: 4rem;
}

.testi-header h2 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -2px;
  text-transform: uppercase;
  margin-top: 1rem;
}

.testi-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  background: var(--gray);
}

.testi-card {
  background: var(--concrete);
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.testi-card--yellow {
  background: var(--yellow);
}

.testi-quote {
  font-family: var(--font-body);
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--gray-light);
  flex: 1;
}

.testi-card--yellow .testi-quote {
  color: var(--black);
}

.testi-person {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.testi-avatar {
  width: 44px;
  height: 44px;
  background: var(--gray);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 900;
  color: var(--white);
  flex-shrink: 0;
}

.testi-card--yellow .testi-avatar {
  background: var(--black);
}

.testi-person > div {
  flex: 1;
}

.testi-person strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--white);
}

.testi-card--yellow .testi-person strong {
  color: var(--black);
}

.testi-person span {
  font-family: var(--font-body);
  font-size: 0.78rem;
  color: var(--gray-light);
}

.testi-card--yellow .testi-person span {
  color: rgba(0, 0, 0, 0.5);
}

.testi-stars {
  color: var(--yellow);
  font-size: 0.8rem;
}

.testi-card--yellow .testi-stars {
  color: var(--black);
}

/* ── Join ── */
.join-section {
  padding: 8rem 4rem;
  background: var(--yellow);
  text-align: center;
}

.join-inner h2 {
  font-family: var(--font-display);
  font-size: clamp(4rem, 10vw, 9rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -4px;
  text-transform: uppercase;
  color: var(--black);
  margin-bottom: 1.5rem;
}

.join-inner h2 em {
  font-style: italic;
  color: var(--black-mid);
}

.join-inner p {
  font-family: var(--font-body);
  font-size: 1.1rem;
  color: rgba(0, 0, 0, 0.6);
  margin-bottom: 3rem;
}

.btn-giant {
  font-size: 1.3rem !important;
  padding: 1.5rem 4rem !important;
  background: var(--black) !important;
  color: var(--yellow) !important;
  border: none !important;
}

.btn-giant:hover {
  background: var(--black-mid) !important;
  transform: translateY(-3px) !important;
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4) !important;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .programs-grid {
    grid-template-columns: 1fr;
  }
  .program-card {
    border-right: none;
    border-bottom: 2px solid var(--gray);
  }
  .program-card:last-child {
    border-bottom: none;
  }
  .transform-inner {
    grid-template-columns: 1fr;
  }
  .transform-visual {
    max-width: 400px;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 1rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .hero {
    padding: 6rem 2rem 4rem;
  }
  .hero-line {
    font-size: clamp(3.5rem, 15vw, 7rem);
  }
  .programs-section {
    padding: 5rem 2rem;
  }
  .stats-bar {
    flex-wrap: wrap;
  }
  .stat-divider {
    display: none;
  }
  .stat-item {
    width: 50%;
    border-bottom: 1px solid var(--gray);
  }
  .testi-grid {
    grid-template-columns: 1fr;
  }
  .transform-section,
  .testimonials-section {
    padding: 5rem 2rem;
  }
  .join-section {
    padding: 6rem 2rem;
  }
  .join-inner h2 {
    font-size: clamp(3rem, 12vw, 7rem);
  }
}

html.reduced-motion .ticker-track {
  animation: none !important;
}
html.reduced-motion * {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

