/* ═══════════════════════════════════════════════════════════════════════
   SaaS Landing Page — Styles
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --page-bg: #0d0d1a;
  --page-surface: #151528;
  --page-border: #252545;
  --page-text: #f0eef5;
  --page-muted: #8a85a0;
  --page-accent: #6366f1;
  --page-accent-light: #818cf8;
  --page-accent-glow: rgba(99, 102, 241, 0.2);
  --page-success: #34d399;
  --page-gradient-start: #6366f1;
  --page-gradient-end: #8b5cf6;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: var(--page-bg);
  color: var(--page-text);
  font-family: "SF Pro Display", "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ── Sections ── */
.section {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 6rem 2rem;
}

/* ═══════════════════════════════════════════════════════════════════════
   HERO
   ═══════════════════════════════════════════════════════════════════════ */

.hero-section {
  text-align: center;
  padding-bottom: 4rem;
  gap: 2.5rem;
}

.hero-content {
  position: relative;
  z-index: 2;
}

.hero-title {
  font-size: clamp(2.2rem, 7vw, 5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 1.25rem;
  background: linear-gradient(135deg, var(--page-text) 0%, var(--page-accent-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.35rem);
  color: var(--page-muted);
  font-weight: 400;
  letter-spacing: 0.01em;
  margin-bottom: 2.5rem;
  opacity: 0;
  transform: translateY(20px);
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero visual */
.hero-visual {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  width: 100%;
  max-width: 600px;
  margin-top: 1rem;
}

.hero-glow {
  position: absolute;
  width: 500px;
  height: 500px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, var(--page-accent-glow) 0%, transparent 70%);
  filter: blur(100px);
  pointer-events: none;
  z-index: -1;
}

/* ═══════════════════════════════════════════════════════════════════════
   CSS DEVICE MOCKUPS
   ═══════════════════════════════════════════════════════════════════════ */

/* ── Laptop ── */
.device-laptop {
  position: relative;
  width: 340px;
  aspect-ratio: 16 / 10;
  background: var(--page-surface);
  border: 2px solid var(--page-border);
  border-radius: 12px 12px 0 0;
  overflow: hidden;
}

.laptop-screen {
  width: 100%;
  height: 100%;
  padding: 8px;
}

.screen-ui {
  width: 100%;
  height: 100%;
  display: flex;
  border-radius: 4px;
  overflow: hidden;
  background: #0e0e22;
}

.screen-sidebar {
  width: 22%;
  height: 100%;
  background: linear-gradient(180deg, #1a1a3a 0%, #151530 100%);
  border-right: 1px solid var(--page-border);
}

.screen-main {
  flex: 1;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.screen-topbar {
  height: 12px;
  background: var(--page-border);
  border-radius: 3px;
  width: 60%;
}

.screen-chart {
  flex: 1;
  background: linear-gradient(
    180deg,
    rgba(99, 102, 241, 0.15) 0%,
    rgba(99, 102, 241, 0.05) 60%,
