  background: var(--page-surface);
  border: 3px solid var(--page-border);
  border-radius: 24px;
  overflow: hidden;
}

.device-phone::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
  width: 50px;
  height: 8px;
  background: #0a0a18;
  border-radius: 10px;
  z-index: 2;
}

.phone-screen {
  width: 100%;
  height: 100%;
  padding: 20px 8px 8px;
}

.phone-ui {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.phone-header {
  height: 14px;
  background: var(--page-border);
