/* ── Demo 47: Music Platform — Neon Cyberpunk ── */
/* Palette: Black / Neon Magenta / Cyan / Lime */
/* Fonts: Space Mono (display/code) + Space Grotesk (body) */

:root {
  --black: #080810;
  --dark: #0d0d1a;
  --panel: #111120;
  --border: #1e1e38;
  --text: #e8e8f8;
  --muted: #6b6b90;
  --faint: #2a2a48;

  --magenta: #ff2d78;
  --cyan: #00e5ff;
  --lime: #a8ff3e;
  --purple: #9b4dff;
  --gold: #ffcc00;

  --neon-glow-m: 0 0 8px rgba(255, 45, 120, 0.6), 0 0 25px rgba(255, 45, 120, 0.25);
  --neon-glow-c: 0 0 8px rgba(0, 229, 255, 0.6), 0 0 25px rgba(0, 229, 255, 0.25);
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Space Grotesk", -apple-system, sans-serif;
  background: var(--black);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ── Scan lines overlay ── */
.scanlines {
  position: fixed;
  inset: 0;
  z-index: 200;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.06) 2px,
    rgba(0, 0, 0, 0.06) 4px
  );
}

/* ── Navigation ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 2.5rem;
  background: rgba(8, 8, 16, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-mark {
  font-size: 1.2rem;
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

.brand-name {
  font-family: "Space Mono", monospace;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text);
}

.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}

.nav-links a {
  text-decoration: none;
  font-family: "Space Mono", monospace;
  font-size: 0.72rem;
  font-weight: 400;
  letter-spacing: 0.12em;
  color: var(--muted);
  text-transform: uppercase;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--cyan);
  text-shadow: var(--neon-glow-c);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav-live {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: "Space Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.15em;
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

.live-dot {
  width: 6px;
  height: 6px;
  background: var(--magenta);
  border-radius: 50%;
  animation: pulse-dot 1.2s ease-in-out infinite;
  box-shadow: var(--neon-glow-m);
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}

/* ── Buttons ── */
.btn-neon {
  display: inline-block;
  padding: 0.7rem 1.5rem;
  background: transparent;
  color: var(--magenta);
  border: 1px solid var(--magenta);
  font-family: "Space Mono", monospace;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: inset 0 0 0 0 var(--magenta);
}

.btn-neon:hover {
  background: var(--magenta);
  color: var(--black);
  box-shadow: var(--neon-glow-m);
}

.btn-neon--lg {
  padding: 1rem 2.5rem;
  font-size: 0.82rem;
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.9rem 1.8rem;
  background: transparent;
  color: var(--text);
  border: 1px solid var(--faint);
  font-family: "Space Grotesk", sans-serif;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
}

.btn-ghost:hover {
  border-color: var(--cyan);
  color: var(--cyan);
}

.play-icon {
  font-size: 0.7rem;
}

.btn-outline {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
  font-family: "Space Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  transition: border-color 0.2s, color 0.2s;
}

.btn-outline:hover {
  border-color: var(--cyan);
  color: var(--cyan);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 7rem 2.5rem 5rem;
  overflow: hidden;
}

#waveform-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
}

.hero-tag {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 2rem;
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.tag-prefix {
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
  font-size: 0.9rem;
}

.hero-h1 {
  font-family: "Space Mono", monospace;
  font-size: clamp(3.5rem, 9vw, 8rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--text);
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: column;
}

.h1-line--neon {
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

.hero-sub {
  font-size: 1rem;
  color: var(--muted);
  line-height: 1.8;
  max-width: 520px;
  margin-bottom: 2.5rem;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

/* EQ bars */
.eq-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 32px;
}

.eq-bars span {
  width: 4px;
  background: var(--magenta);
  border-radius: 1px;
  animation: eq-bounce 0.8s ease-in-out infinite alternate;
  box-shadow: 0 0 4px rgba(255, 45, 120, 0.5);
}

.eq-bars span:nth-child(1) {
  height: 60%;
  animation-delay: 0.0s;
}
.eq-bars span:nth-child(2) {
  height: 90%;
  animation-delay: 0.1s;
}
.eq-bars span:nth-child(3) {
  height: 40%;
  animation-delay: 0.2s;
}
.eq-bars span:nth-child(4) {
  height: 100%;
  animation-delay: 0.15s;
}
.eq-bars span:nth-child(5) {
  height: 70%;
  animation-delay: 0.3s;
}
.eq-bars span:nth-child(6) {
  height: 55%;
  animation-delay: 0.25s;
}
.eq-bars span:nth-child(7) {
  height: 85%;
  animation-delay: 0.05s;
}
.eq-bars span:nth-child(8) {
  height: 45%;
  animation-delay: 0.35s;
}
.eq-bars span:nth-child(9) {
  height: 75%;
  animation-delay: 0.1s;
}
.eq-bars span:nth-child(10) {
  height: 95%;
  animation-delay: 0.2s;
}
.eq-bars span:nth-child(11) {
  height: 50%;
  animation-delay: 0.4s;
}
.eq-bars span:nth-child(12) {
  height: 80%;
  animation-delay: 0.15s;
}
.eq-bars span:nth-child(13) {
  height: 65%;
  animation-delay: 0.05s;
}
.eq-bars span:nth-child(14) {
  height: 90%;
  animation-delay: 0.3s;
}
.eq-bars span:nth-child(15) {
  height: 40%;
  animation-delay: 0.0s;
}

@keyframes eq-bounce {
  from {
    transform: scaleY(0.35);
  }
  to {
    transform: scaleY(1);
  }
}

/* Now playing card */
.now-playing {
  position: absolute;
  right: 3rem;
  bottom: 4rem;
  width: 280px;
  padding: 1.25rem;
  background: rgba(13, 13, 26, 0.9);
  border: 1px solid var(--magenta);
  box-shadow: var(--neon-glow-m);
  z-index: 2;
}

.np-label {
  font-family: "Space Mono", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  color: var(--magenta);
  margin-bottom: 0.5rem;
}

.np-title {
  font-family: "Space Mono", monospace;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.2rem;
}

.np-artist {
  font-size: 0.78rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.np-bar {
  height: 2px;
  background: var(--faint);
  margin-bottom: 0.5rem;
  overflow: hidden;
}

.np-progress {
  height: 100%;
  width: 50%;
  background: var(--magenta);
  box-shadow: 0 0 6px var(--magenta);
}

.np-time {
  display: flex;
  justify-content: space-between;
  font-family: "Space Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
}

/* ── Section tag ── */
.section-tag {
  display: block;
  font-family: "Space Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.15em;
  color: var(--cyan);
  text-shadow: var(--neon-glow-c);
  margin-bottom: 1rem;
}

.neon-text {
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

/* ── Shows Section ── */
.shows-section {
  padding: 5rem 2.5rem;
  border-top: 1px solid var(--border);
}

.shows-header {
  margin-bottom: 2.5rem;
}

.shows-header h2 {
  font-family: "Space Mono", monospace;
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
  line-height: 1;
}

.shows-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
}

.show-card--featured {
  grid-row: 1 / 3;
}

.show-card {
  background: var(--dark);
  overflow: hidden;
  transition: background 0.3s;
  cursor: pointer;
}

.show-card:hover {
  background: var(--panel);
}

.sc-art {
  height: 200px;
  position: relative;
}

.show-card--featured .sc-art {
  height: 300px;
}

.sc-art--1 {
  background: radial-gradient(ellipse at 30% 50%, rgba(255, 45, 120, 0.4) 0%, transparent 60%),
    radial-gradient(ellipse at 70% 30%, rgba(155, 77, 255, 0.35) 0%, transparent 50%), var(--dark);
}

.sc-art--2 {
  background: radial-gradient(ellipse at 50% 70%, rgba(0, 229, 255, 0.3) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 20%, rgba(168, 255, 62, 0.2) 0%, transparent 50%), var(--dark);
}

.sc-art--3 {
  background: radial-gradient(ellipse at 80% 50%, rgba(155, 77, 255, 0.4) 0%, transparent 60%),
    radial-gradient(ellipse at 30% 80%, rgba(0, 229, 255, 0.2) 0%, transparent 50%), var(--dark);
}

.sc-art--4 {
  background: radial-gradient(ellipse at 50% 30%, rgba(255, 204, 0, 0.25) 0%, transparent 55%),
    radial-gradient(ellipse at 70% 70%, rgba(255, 45, 120, 0.25) 0%, transparent 50%), var(--dark);
}

.sc-info {
  padding: 1.5rem;
  border-top: 1px solid var(--border);
}

.sc-info--sm {
  padding: 1.2rem;
}

.sc-genre {
  font-family: "Space Mono", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  color: var(--cyan);
  display: block;
  margin-bottom: 0.4rem;
}

.sc-info h3 {
  font-family: "Space Mono", monospace;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.6rem;
}

.sc-info--sm h3 {
  font-size: 0.95rem;
}

.sc-info p {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.65;
  margin-bottom: 0.8rem;
}

.sc-meta {
  font-family: "Space Mono", monospace;
  font-size: 0.65rem;
  color: var(--muted);
  margin-bottom: 1rem;
  display: flex;
  gap: 0.4rem;
}

.dot {
  color: var(--faint);
}

.sc-stats {
  display: flex;
  gap: 1.5rem;
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  color: var(--text);
}

.sc-stats span {
  display: flex;
  gap: 0.4rem;
}
.sc-stats em {
  font-style: normal;
  color: var(--muted);
  font-size: 0.65rem;
  align-self: flex-end;
}

/* ── Charts Section ── */
.charts-section {
  padding: 5rem 2.5rem;
  background: var(--dark);
  border-top: 1px solid var(--border);
}

.charts-inner {
  max-width: 900px;
}

.charts-header {
  margin-bottom: 3rem;
}

.charts-header h2 {
  font-family: "Space Mono", monospace;
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
}

.chart-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  border: 1px solid var(--border);
}

.chart-item {
  display: grid;
  grid-template-columns: 50px 1fr 200px 70px 50px;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  transition: background 0.2s;
  cursor: pointer;
}

.chart-item:last-child {
  border-bottom: none;
}

.chart-item:hover {
  background: var(--panel);
}

.ci-rank {
  font-family: "Space Mono", monospace;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

.ci-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.ci-info strong {
  font-family: "Space Mono", monospace;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: 0.02em;
}

.ci-info span {
  font-size: 0.75rem;
  color: var(--muted);
}

.ci-bar-wrap {
  height: 2px;
  background: var(--faint);
  overflow: hidden;
}

.ci-bar {
  height: 100%;
  width: var(--w, 0%);
  background: linear-gradient(90deg, var(--magenta), var(--purple));
  transform-origin: left;
  transform: scaleX(0);
  box-shadow: 0 0 4px var(--magenta);
}

.ci-plays {
  font-family: "Space Mono", monospace;
  font-size: 0.72rem;
  color: var(--muted);
  text-align: right;
}

.ci-delta {
  font-family: "Space Mono", monospace;
  font-size: 0.65rem;
  font-weight: 700;
  text-align: center;
}

.ci-delta.up {
  color: var(--lime);
}
.ci-delta.down {
  color: var(--magenta);
}
.ci-delta.new {
  color: var(--gold);
}

/* ── Artists Section ── */
.artists-section {
  padding: 5rem 2.5rem;
  border-top: 1px solid var(--border);
}

.artists-header {
  margin-bottom: 3rem;
}

.artists-header h2 {
  font-family: "Space Mono", monospace;
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
}

/* Marquee */
.artists-marquee-wrap {
  overflow: hidden;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 1rem 0;
  margin-bottom: 4rem;
}

.marquee-track {
  display: flex;
  gap: 1rem;
  width: max-content;
  animation: marquee-scroll 28s linear infinite;
}

@keyframes marquee-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

.artist-chip {
  flex-shrink: 0;
  padding: 0.5rem 1.25rem;
  border: 1px solid var(--border);
  font-family: "Space Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  color: var(--muted);
  white-space: nowrap;
  transition: border-color 0.2s, color 0.2s;
}

.chip--accent {
  border-color: rgba(255, 45, 120, 0.4);
  color: var(--magenta);
}

/* Platform stats */
.platform-stats {
  display: flex;
  align-items: center;
  gap: 3rem;
  padding: 2.5rem 2rem;
  border: 1px solid var(--border);
  background: var(--panel);
}

.ps-item {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.ps-num {
  font-family: "Space Mono", monospace;
  font-size: 2.2rem;
  font-weight: 700;
  color: var(--cyan);
  text-shadow: var(--neon-glow-c);
  line-height: 1;
}

.ps-label {
  font-size: 0.75rem;
  color: var(--muted);
  letter-spacing: 0.05em;
}

.ps-div {
  width: 1px;
  height: 50px;
  background: var(--border);
}

/* ── Studio / CTA ── */
.studio-section {
  padding: 5rem 2.5rem;
  background: var(--dark);
  border-top: 1px solid var(--border);
}

.studio-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.studio-left h2 {
  font-family: "Space Mono", monospace;
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  margin-bottom: 1.2rem;
}

.studio-left p {
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.8;
  max-width: 400px;
  margin-bottom: 2rem;
}

.studio-links {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Terminal */
.studio-terminal {
  background: #0a0a14;
  border: 1px solid var(--border);
  border-top: 1px solid var(--cyan);
  box-shadow: var(--neon-glow-c);
  font-family: "Space Mono", monospace;
  font-size: 0.82rem;
  overflow: hidden;
}

.terminal-bar {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.6rem 1rem;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}

.tb-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.tb-dot--red {
  background: #ff5f56;
}
.tb-dot--yellow {
  background: #ffbd2e;
}
.tb-dot--green {
  background: #27c93f;
}

.tb-title {
  margin-left: 0.5rem;
  font-size: 0.7rem;
  color: var(--muted);
}

.terminal-body {
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-height: 180px;
}

.terminal-body p {
  line-height: 1.5;
}

.t-prompt {
  color: var(--lime);
  margin-right: 0.5rem;
}

.t-output {
  color: var(--muted);
  padding-left: 1.2rem;
}

.t-success {
  color: var(--lime);
}

.t-val {
  color: var(--text);
}

.t-neon {
  color: var(--magenta);
  text-shadow: var(--neon-glow-m);
}

.t-cursor {
  color: var(--cyan);
  animation: cursor-blink 1s step-end infinite;
}

@keyframes cursor-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* ── Footer ── */
.footer {
  padding: 1.5rem 2.5rem;
  background: var(--black);
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: "Space Mono", monospace;
  font-size: 0.78rem;
  color: var(--muted);
}

.footer-brand .brand-mark {
  font-size: 0.9rem;
}

.footer p {
  font-family: "Space Mono", monospace;
  font-size: 0.65rem;
  color: var(--muted);
  letter-spacing: 0.05em;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .shows-grid {
    grid-template-columns: 1fr 1fr;
  }
  .show-card--featured {
    grid-column: 1 / 3;
    grid-row: auto;
  }
  .studio-inner {
    grid-template-columns: 1fr;
  }
  .chart-item {
    grid-template-columns: 40px 1fr 100px 60px 40px;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .now-playing {
    display: none;
  }
  .shows-grid {
    grid-template-columns: 1fr;
  }
  .show-card--featured {
    grid-column: auto;
  }
  .chart-item {
    grid-template-columns: 40px 1fr 50px 40px;
  }
  .ci-bar-wrap {
    display: none;
  }
  .platform-stats {
    flex-wrap: wrap;
    gap: 1.5rem;
  }
}

/* ── Reduced Motion ── */
html.reduced-motion .eq-bars span,
html.reduced-motion .live-dot,
html.reduced-motion .t-cursor,
html.reduced-motion .marquee-track {
  animation: none !important;
}

html.reduced-motion .eq-bars span {
  height: 60% !important;
  transform: none !important;
}

html.reduced-motion * {
  transition-duration: 0.01ms !important;
}

