:root {
  color-scheme: dark;
  --bg: #06070c;
  --panel: rgba(12, 14, 22, 0.82);
  --stroke: rgba(255, 255, 255, 0.1);
  --text: #f5f2ef;
  --muted: rgba(245, 242, 239, 0.6);
  --red: #ff2e3a;
  --red-soft: rgba(255, 46, 58, 0.2);
  --blue: #6dd5ff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Space Grotesk", sans-serif;
  background: radial-gradient(circle at 10% 10%, rgba(255, 46, 58, 0.15), transparent 55%),
    radial-gradient(circle at 80% 20%, rgba(109, 213, 255, 0.15), transparent 60%), #05060a;
  color: var(--text);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

#bg {
  position: fixed;
  inset: 0;
  z-index: 0;
}

.speed-lines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background: repeating-linear-gradient(
    100deg,
    rgba(255, 255, 255, 0.06) 0,
    rgba(255, 255, 255, 0.06) 1px,
    transparent 1px,
    transparent 18px
  );
  opacity: 0.25;
  transform: translateX(var(--speed-shift, 0px));
  transition: opacity 0.4s ease;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px clamp(20px, 6vw, 80px);
  backdrop-filter: blur(14px);
  background: rgba(5, 6, 10, 0.85);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.logo {
  display: flex;
  align-items: center;
  gap: 16px;
}

.logo-mark {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  background: linear-gradient(140deg, var(--red), #ff7a45);
  box-shadow: 0 0 26px rgba(255, 46, 58, 0.45);
}

.logo-title {
  font-family: "Bebas Neue", sans-serif;
  font-size: 1.4rem;
  letter-spacing: 0.1em;
  margin: 0;
}

.logo-sub {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.85rem;
}

.nav {
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
}

.nav a {
  color: var(--muted);
}

.nav-cta {
  padding: 0.5rem 1.2rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--text);
  background: rgba(255, 46, 58, 0.15);
}

.page {
  position: relative;
  z-index: 2;
  padding: 0 clamp(20px, 6vw, 80px) 80px;
}

.hero {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 36px;
  padding: 64px 0 40px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--blue);
  font-size: 0.7rem;
}

.hero-copy h1 {
  font-family: "Bebas Neue", sans-serif;
  font-size: clamp(2.8rem, 5vw, 4.5rem);
  margin: 16px 0;
}

.lead {
  color: var(--muted);
  line-height: 1.6;
  max-width: 60ch;
}

.hero-actions {
  margin-top: 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  padding: 0.85rem 1.6rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: transparent;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
}

.btn.primary {
  background: rgba(255, 46, 58, 0.25);
  border-color: rgba(255, 46, 58, 0.6);
}

.btn.ghost {
  border-color: rgba(109, 213, 255, 0.6);
}

.hero-metrics {
  margin-top: 24px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.hero-metrics div {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 14px;
  padding: 14px;
}

.hero-metrics span {
  display: block;
  color: var(--muted);
  font-size: 0.8rem;
}

.hero-panel {
  display: grid;
  gap: 18px;
}

.panel-card {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 18px;
  padding: 20px;
}

.panel-title {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
  color: var(--muted);
}

.marquee {
  margin: 24px 0 0;
  overflow: hidden;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.marquee-track {
  display: flex;
  gap: 48px;
  padding: 14px 0;
  text-transform: uppercase;
  letter-spacing: 0.35em;
  font-size: 0.7rem;
  color: var(--muted);
  white-space: nowrap;
  will-change: transform;
}

.section {
  padding: 56px 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
}

.section-header p {
  color: var(--muted);
}

.grid {
  margin-top: 24px;
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.card {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 16px;
  padding: 20px;
}

.card span {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.65rem;
  color: var(--blue);
}

.card p {
  color: var(--muted);
}

.split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}

.list {
  list-style: none;
  padding: 0;
  margin: 18px 0 0;
  display: grid;
  gap: 12px;
}

.list li {
  padding: 12px 16px;
  border-radius: 12px;
  background: rgba(12, 14, 20, 0.8);
  border: 1px solid var(--stroke);
}

.pill-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.pill-grid span {
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid rgba(109, 213, 255, 0.5);
  font-size: 0.75rem;
}

.stats {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.stats div {
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 16px;
  padding: 20px;
  text-align: center;
}

.stats h2 {
  font-family: "Bebas Neue", sans-serif;
  font-size: 2.4rem;
  margin: 0 0 8px;
  color: var(--red);
}

.lab-grid {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.lab-card {
  padding: 18px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(8, 10, 16, 0.8);
}

.contact-cards {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

.contact-card {
  padding: 18px;
  border-radius: 14px;
  background: rgba(12, 14, 20, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.contact-card p {
  margin: 6px 0 0;
  color: var(--muted);
}

@media (max-width: 900px) {
  .site-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .nav {
    flex-wrap: wrap;
  }
}

@media (max-width: 640px) {
  .page {
    padding: 0 18px 80px;
  }
}

