if (!window.MotionPreference) {
  const __mql = window.matchMedia("(prefers-reduced-motion: reduce)");
  const __listeners = new Set();

  const MotionPreference = {
    prefersReducedMotion() {
      return __mql.matches;
    },
    setOverride(value) {
      const reduced = Boolean(value);
      document.documentElement.classList.toggle("reduced-motion", reduced);
      window.dispatchEvent(new CustomEvent("motion-preference", { detail: { reduced } }));
      for (const listener of __listeners) {
        try {
          listener({ reduced, override: reduced, systemReduced: __mql.matches });
        } catch {}
      }
    },
    onChange(listener) {
      __listeners.add(listener);
      try {
        listener({
          reduced: __mql.matches,
          override: null,
          systemReduced: __mql.matches,
        });
      } catch {}
      return () => __listeners.delete(listener);
    },
    getState() {
      return { reduced: __mql.matches, override: null, systemReduced: __mql.matches };
    },
  };

  window.MotionPreference = MotionPreference;
}

function prefersReducedMotion() {
  return window.MotionPreference.prefersReducedMotion();
}

function initDemoShell() {
  // No-op shim in imported standalone snippets.
}

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);
initDemoShell({
  title: "Grand Résidence — Luxury Hotel",
  category: "pages",
  tech: ["gsap", "css-scroll-snap", "lenis", "playfair", "lato"],
});

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

// Nav color based on panel
const nav = document.getElementById("nav");
const snapContainer = document.getElementById("snap-container");
const panels = document.querySelectorAll(".snap-panel");
const lightPanels = new Set(["panel-room", "panel-dining"]);

function updateNav() {
  const containerRect = snapContainer.getBoundingClientRect();
  let visiblePanel = null;
  panels.forEach((p) => {
    const r = p.getBoundingClientRect();
    const overlap = Math.min(r.bottom, containerRect.bottom) - Math.max(r.top, containerRect.top);
    if (!visiblePanel || overlap > 0) visiblePanel = p;
  });
  if (visiblePanel) {
    const isLight = lightPanels.has(
      [...visiblePanel.classList].find((c) => c.startsWith("panel-"))
    );
    nav.classList.toggle("on-light", !!isLight);
  }
}

snapContainer.addEventListener("scroll", updateNav);
updateNav();

// Hero entrance
if (!reduced) {
  gsap.set([".ph-season", ".ph-center > *", ".ph-bottom"], { opacity: 0, y: 20 });
  gsap
    .timeline({ delay: 0.5, defaults: { ease: "expo.out" } })
    .to(".ph-season", { opacity: 1, y: 0, duration: 0.8 })
    .to(".ph-center > *", { opacity: 1, y: 0, duration: 1, stagger: 0.15 }, "-=0.4")
    .to(".ph-bottom", { opacity: 1, y: 0, duration: 0.7 }, "-=0.3");
}

// IntersectionObserver for panel entrance animations
const observer = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting || reduced) return;
      const panel = entry.target;

      if (panel.classList.contains("panel-room")) {
        gsap.set([".pr-content > *"], { opacity: 0, x: 30 });
        gsap.to(".pr-content > *", {
          opacity: 1,
          x: 0,
          duration: 0.9,
          stagger: 0.1,
          ease: "expo.out",
          delay: 0.2,
        });
        gsap.set(".pr-image--1", { scale: 1.05 });
        gsap.to(".pr-image--1", { scale: 1, duration: 1.2, ease: "power2.out" });
      }

      if (panel.classList.contains("panel-amenities")) {
        gsap.set(".amen-item", { opacity: 0, y: 20 });
        gsap.to(".amen-item", {
          opacity: 1,
          y: 0,
          duration: 0.6,
          stagger: 0.08,
          ease: "expo.out",
          delay: 0.3,
        });
      }

      if (panel.classList.contains("panel-dining")) {
        gsap.set([".pd-content > *"], { opacity: 0, x: 30 });
        gsap.to(".pd-content > *", {
          opacity: 1,
          x: 0,
          duration: 0.9,
          stagger: 0.1,
          ease: "expo.out",
          delay: 0.2,
        });
      }

      if (panel.classList.contains("panel-contact")) {
        gsap.set([".pc2-content > *", ".rf-field", ".rf-row"], { opacity: 0, y: 18 });
        gsap.to([".pc2-content > *", ".rf-row", ".rf-field", ".btn-submit"], {
          opacity: 1,
          y: 0,
          duration: 0.7,
          stagger: 0.08,
          ease: "expo.out",
          delay: 0.2,
        });
      }

      observer.unobserve(panel);
    });
  },
  { root: snapContainer, threshold: 0.5 }
);

panels.forEach((p) => observer.observe(p));

// Amenity icon hover sparkle
if (!reduced) {
  document.querySelectorAll(".amen-item").forEach((item) => {
    item.addEventListener("mouseenter", () => {
      gsap.to(item.querySelector(".ai-icon"), { rotation: 45, duration: 0.3, ease: "back.out(2)" });
    });
    item.addEventListener("mouseleave", () => {
      gsap.to(item.querySelector(".ai-icon"), { rotation: 0, duration: 0.3, ease: "back.out(2)" });
    });
  });
}

// Hero scroll hint button click → scroll snap to room panel
document.getElementById("hero-btn")?.addEventListener("click", (e) => {
  e.preventDefault();
  document.getElementById("rooms").scrollIntoView({ behavior: "smooth" });
});

window.addEventListener("motion-preference", (e) => {
  gsap.globalTimeline.paused(e.detail.reduced);
});

snippets.css:
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #070a12;
  --panel: #121a2b;
  --border: #263249;
  --text: #f0f4fb;
  --muted: #8a95a8;
  --accent: #86e8ff;
  --neon-purple: #ae52ff;
  --neon-pink: #ff40d6;
}

html {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", "SF Pro Display", system-ui, sans-serif;
}

body {
  overflow-x: hidden;
}

/* ── Intro ── */
.intro {
  min-height: 70vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 2rem;
}

.eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--accent);
  margin-bottom: 1rem;
}

h1 {
  font-size: clamp(2.2rem, 6vw, 4rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, #fff, var(--accent), var(--neon-purple));
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: clamp(0.9rem, 2vw, 1.05rem);
  color: var(--muted);
  max-width: 500px;
  margin-top: 0.75rem;
  line-height: 1.6;
}

/* ── Pinned sections ── */
.pinned-section {
  position: relative;
  min-height: 100vh;
}

.pin-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 100vh;
  gap: 2rem;
  padding: 0 4rem;
  align-items: center;
}

/* ── Left side: steps ── */
.pin-left {
  display: flex;
  gap: 2rem;
  align-items: flex-start;
  padding: 2rem 0;
}

.step-indicators {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-top: 0.5rem;
}

.step-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  transition: background 0.4s ease, box-shadow 0.4s ease;
}

.step-dot.active {
  background: var(--accent);
  box-shadow: 0 0 12px rgba(134, 232, 255, 0.4);
}

.pin-text {
  position: relative;
}

.step-text {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.4s ease, transform 0.4s ease;
  pointer-events: none;
}

.step-text.active {
  position: relative;
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.step-label {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: 0.75rem;
}

.step-text h2 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  margin-bottom: 1rem;
  -webkit-text-fill-color: var(--text);
}

.step-text p {
  font-size: 1rem;
  color: var(--muted);
  line-height: 1.7;
  max-width: 400px;
}

/* ── Right side: visuals ── */
.pin-right {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Visual stage (section 1) */
.visual-stage {
  position: relative;
  width: 360px;
  height: 360px;
}

.vis-element {
  position: absolute;
  will-change: transform, opacity;
}

.vis-circle {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), rgba(134, 232, 255, 0.3));
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
}

.vis-square {
  width: 80px;
  height: 80px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--neon-purple), rgba(174, 82, 255, 0.3));
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
}

.vis-triangle {
  width: 0;
  height: 0;
  border-left: 45px solid transparent;
  border-right: 45px solid transparent;
  border-bottom: 78px solid var(--neon-pink);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
  filter: drop-shadow(0 0 16px rgba(255, 64, 214, 0.3));
}

.vis-line {
  position: absolute;
  height: 2px;
  background: var(--border);
  border-radius: 1px;
  opacity: 0;
  will-change: transform, opacity;
}

.vis-line-1 {
  width: 120px;
  top: 30%;
  left: 10%;
}
.vis-line-2 {
  width: 80px;
  top: 60%;
  right: 10%;
}
.vis-line-3 {
  width: 160px;
  bottom: 20%;
  left: 25%;
}

/* Metric bars (section 2) */
.metric-bars {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  width: 100%;
  max-width: 360px;
}

.metric-bar {
  position: relative;
}

.bar-fill {
  height: 8px;
  border-radius: 4px;
  background: var(--color, var(--accent));
  width: 0%;
  will-change: width;
  transition: width 0.05s linear;
}

.bar-label {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ── Outro ── */
.outro {
  min-height: 50vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 2rem;
}

.outro h2 {
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
  -webkit-text-fill-color: var(--text);
}

.btn-back {
  display: inline-block;
  padding: 0.7rem 2rem;
  border-radius: 999px;
  border: 1px solid rgba(134, 232, 255, 0.3);
  color: var(--accent);
  text-decoration: none;
  font: 600 0.85rem / 1 "Inter", system-ui, sans-serif;
  transition: all 0.25s ease;
}

.btn-back:hover {
  background: rgba(134, 232, 255, 0.08);
  border-color: var(--accent);
}

/* ── Reduced motion ── */
.reduced-motion .vis-element,
.reduced-motion .vis-line,
.reduced-motion .step-text {
  opacity: 1 !important;
  transform: none !important;
}

.reduced-motion .bar-fill {
  transition: none;
}

@media (max-width: 768px) {
  .pin-content {
    grid-template-columns: 1fr;
    padding: 0 1.5rem;
  }

  .pin-right {
    min-height: 300px;
  }
  .visual-stage {
    width: 260px;
    height: 260px;
  }
}

