/* ── Demo 54: Esports Tournament — NEXUS ── */
/* Black / Lime #a3ff12 / Orange #ff6520 / Rajdhani */
:root {
  --black: #060608;
  --dark: #0c0e10;
  --panel: #111418;
  --border: #1e2428;
  --text: #e8eef0;
  --muted: #6a7480;
  --lime: #a3ff12;
  --lime-dim: rgba(163, 255, 18, 0.12);
  --orange: #ff6520;
  --cyan: #12d8ff;
  --glow-lime: 0 0 10px rgba(163, 255, 18, 0.5), 0 0 30px rgba(163, 255, 18, 0.2);
  --glow-orange: 0 0 10px rgba(255, 101, 32, 0.5);
}
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: "Rajdhani", -apple-system, sans-serif;
  background: var(--black);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  line-height: 1.5;
}
.scanline {
  position: fixed;
  inset: 0;
  z-index: 200;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 3px,
    rgba(0, 0, 0, 0.04) 3px,
    rgba(0, 0, 0, 0.04) 6px
  );
}
.section-tag {
  display: block;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  color: var(--lime);
  margin-bottom: 0.75rem;
}
.lime-text {
  color: var(--lime);
  text-shadow: var(--glow-lime);
}
.btn-lime {
  display: inline-block;
  padding: 0.85rem 2rem;
  background: var(--lime);
  color: var(--black);
  font-family: "Rajdhani", sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  clip-path: polygon(8px 0%, 100% 0%, calc(100% - 8px) 100%, 0% 100%);
  transition: background 0.2s, box-shadow 0.2s;
}
.btn-lime:hover {
  background: #c0ff40;
  box-shadow: var(--glow-lime);
}
.btn-ghost-e {
  display: inline-block;
  padding: 0.85rem 1.75rem;
  border: 1px solid var(--lime);
  color: var(--lime);
  font-family: "Rajdhani", sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  clip-path: polygon(8px 0%, 100% 0%, calc(100% - 8px) 100%, 0% 100%);
  transition: background 0.2s;
}
.btn-ghost-e:hover {
  background: var(--lime-dim);
}

/* Nav */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2.5rem;
  background: rgba(6, 6, 8, 0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nb-icon {
  font-size: 1.2rem;
  color: var(--lime);
  text-shadow: var(--glow-lime);
}
.nav-brand span {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--text);
}
.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}
.nav-links a {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}
.nav-links a:hover {
  color: var(--lime);
}
.nav-live {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  color: var(--orange);
}
.nl-dot {
  width: 6px;
  height: 6px;
  background: var(--orange);
  border-radius: 50%;
  animation: blink 1s step-end infinite;
  box-shadow: var(--glow-orange);
}
@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* Hero */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 7rem 2.5rem 5rem;
  overflow: hidden;
}
#hero-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.hero-inner {
  position: relative;
  z-index: 1;
}
.hero-badge {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.2em;
  color: var(--orange);
  margin-bottom: 1.5rem;
  display: block;
}
.hero-h1 {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.02em;
  margin-bottom: 2rem;
}
.h1-lime {
  color: var(--lime);
  text-shadow: var(--glow-lime);
}
.hero-prize {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 2rem;
}
.hp-label {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  color: var(--muted);
}
.hp-amount {
  font-family: "JetBrains Mono", monospace;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--lime);
  line-height: 1;
  text-shadow: var(--glow-lime);
}
.hero-ctas {
  display: flex;
  gap: 1rem;
  margin-bottom: 3rem;
}
.hero-stats-row {
  display: flex;
  gap: 3rem;
  flex-wrap: wrap;
}
.hsr-item {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.hsr-num {
  font-family: "JetBrains Mono", monospace;
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1;
}
.hsr-label {
  font-size: 0.72rem;
  color: var(--muted);
  letter-spacing: 0.08em;
}

/* Bracket */
.bracket-section {
  padding: 5rem 2.5rem;
  border-top: 1px solid var(--border);
}
.bracket-header {
  margin-bottom: 2.5rem;
}
.bracket-header h2 {
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1;
}
.bracket-visual {
  position: relative;
  overflow-x: auto;
  padding: 1rem 0;
}
#bracket-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.bracket-teams {
  display: grid;
  grid-template-columns: 180px 180px 180px;
  gap: 0;
  position: relative;
  z-index: 1;
  min-height: 320px;
  padding: 1rem 0;
}
.bt-match {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.bt-match.qf {
  grid-column: 1;
}
.bt-match.sf {
  grid-column: 2;
}
.bt-match.final {
  grid-column: 3;
  align-self: center;
}
.bt-match.qf[style*="--row:1"] {
  grid-row: 1;
}
.bt-match.qf[style*="--row:2"] {
  grid-row: 2;
}
.bt-match.qf[style*="--row:3"] {
  grid-row: 3;
}
.bt-match.qf[style*="--row:4"] {
  grid-row: 4;
}
.bt-match.sf[style*="--row:1"] {
  grid-row: 1 / 3;
  align-self: center;
}
.bt-match.sf[style*="--row:2"] {
  grid-row: 3 / 5;
  align-self: center;
}
.bt-match.final {
  grid-row: 1 / 5;
}
.bt-team {
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border);
  background: var(--panel);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted);
  transition: all 0.2s;
}
.bt-team--win {
  border-color: rgba(163, 255, 18, 0.3);
  color: var(--lime);
  background: var(--lime-dim);
}
.bt-team--active {
  border-color: var(--orange);
  color: var(--orange);
  animation: pulse-border 1.5s ease-in-out infinite;
}
@keyframes pulse-border {
  0%,
  100% {
    border-color: var(--orange);
  }
  50% {
    border-color: rgba(255, 101, 32, 0.3);
  }
}

/* Players */
.players-section {
  padding: 5rem 2.5rem;
  border-top: 1px solid var(--border);
}
.players-section h2 {
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 700;
  margin-bottom: 2.5rem;
}
.players-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
}
.player-card {
  background: var(--dark);
  padding: 1.5rem;
  position: relative;
  transition: background 0.2s;
}
.player-card:hover {
  background: var(--panel);
}
.player-card--featured {
  border-top: 2px solid var(--lime);
}
.pc-rank {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.7rem;
  color: var(--muted);
  margin-bottom: 1rem;
}
.player-card--featured .pc-rank {
  color: var(--lime);
}
.pc-avatar {
  width: 60px;
  height: 60px;
  border-radius: 2px;
  margin-bottom: 1rem;
}
.pc-avatar--1 {
  background: linear-gradient(135deg, #1a2a10, #2a4a18, #1a3a0c);
}
.pc-avatar--2 {
  background: linear-gradient(135deg, #1a0a20, #300a38, #200a28);
}
.pc-avatar--3 {
  background: linear-gradient(135deg, #0a1a2a, #0a2a40, #0a1a30);
}
.pc-avatar--4 {
  background: linear-gradient(135deg, #2a1a08, #401a08, #2a1a10);
}
.pc-handle {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text);
}
.pc-real {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  color: var(--muted);
  margin-bottom: 0.2rem;
}
.pc-team {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--lime);
  margin-bottom: 1rem;
}
.pc-stats {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.pcs-item {
  display: flex;
  justify-content: space-between;
}
.pcs-val {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
}
.pcs-key {
  font-size: 0.68rem;
  color: var(--muted);
}

/* Prize */
.prize-section {
  padding: 5rem 2.5rem;
  background: var(--dark);
  border-top: 1px solid var(--border);
}
.prize-inner {
  max-width: 700px;
}
.prize-section h2 {
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 3rem;
}
.prize-bars {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.pb-item {
  display: grid;
  grid-template-columns: 60px 1fr 120px;
  align-items: center;
  gap: 1rem;
}
.pb-place {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.72rem;
  color: var(--muted);
}
.pb-bar {
  height: 4px;
  background: var(--border);
}
.pb-fill {
  height: 100%;
  width: var(--w, 0%);
  background: var(--lime);
  transform-origin: left;
  transform: scaleX(0);
  box-shadow: 0 0 6px var(--lime);
}
.pb-amount {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.75rem;
  color: var(--lime);
  text-align: right;
}

/* Footer */
.footer-e {
  padding: 1.5rem 2.5rem;
  background: var(--black);
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 1rem;
}
.footer-e span {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  color: var(--muted);
}
.footer-e span:last-child {
  margin-left: auto;
}

@media (max-width: 900px) {
  .players-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .nav-links {
    display: none;
  }
  .players-grid {
    grid-template-columns: 1fr;
  }
  .bracket-section {
    padding: 4rem 1.5rem;
  }
}
html.reduced-motion .nl-dot,
html.reduced-motion .bt-team--active {
  animation: none !important;
}
html.reduced-motion * {
  transition-duration: 0.01ms !important;
}

