        background:
          "radial-gradient(ellipse 600px 400px at 20% 30%, rgba(56,189,248,0.25) 0%, transparent 70%), radial-gradient(ellipse 500px 350px at 80% 70%, rgba(168,85,247,0.25) 0%, transparent 70%), #0f172a",
