  --border: #e2e8f0;
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f172a;
    --text: #f1f5f9;
    --text-muted: #94a3b8;
    --border: #1e293b;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  padding: 2rem;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
}

/* ── Tablet (iPad) ─────────────────────────── */
@media (max-width: 1024px) {
  body {
    padding: 1.25rem;
  }
}

/* ── Phone landscape / large phone ─────────── */
@media (max-width: 768px) {
  body {
    padding: 1rem 0.75rem;
  }
}

/* ── Small phone ────────────────────────────── */
@media (max-width: 480px) {
  body {
    padding: 0.75rem 0.5rem;
  }
}

.chart-container {
  width: 100%;
  max-width: 1200px;
  background: rgba(255, 255, 255, 0.02);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 3rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.1);
}

@media (max-width: 1024px) {
  .chart-container {
    padding: 2rem;
    border-radius: 18px;
  }
}

@media (max-width: 768px) {
  .chart-container {
    padding: 1.25rem 1rem;
    border-radius: 14px;
  }
}

@media (max-width: 480px) {
  .chart-container {
    padding: 1rem 0.75rem;
    border-radius: 10px;
  }
}

.chart-header {
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .chart-header {
    margin-bottom: 1.25rem;
  }
}

.main-title {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--google-blue);
  margin-bottom: 0.5rem;
  letter-spacing: -0.02em;
}

@media (max-width: 1024px) {
  .main-title {
    font-size: 1.8rem;
  }
}

@media (max-width: 768px) {
  .main-title {
    font-size: 1.35rem;
  }
}

@media (max-width: 480px) {
  .main-title {
    font-size: 1.1rem;
  }
}

.source-info {
  font-size: 0.9rem;
  color: var(--text-muted);
}

@media (max-width: 480px) {
  .source-info {
    font-size: 0.75rem;
  }
}

.url {
  color: var(--google-blue);
  opacity: 0.8;
}

.sankey-wrapper {
  margin: 2rem 0;
  overflow: hidden;
}

@media (max-width: 768px) {
  .sankey-wrapper {
    margin: 1rem 0;
  }
}

#sankey-svg {
  width: 100%;
  height: auto;
  overflow: visible;
  display: block;
}

.node-label {
  font-size: 14px;
  font-weight: 600;
  fill: var(--text);
}

.node-value {
  font-size: 16px;
  font-weight: 700;
}

.node-change {
  font-size: 12px;
  font-weight: 500;
  fill: var(--text-muted);
}

.node-label.revenue {
  font-size: 18px;
  fill: var(--google-blue);
}

.link {
  transition: opacity 0.3s ease;
}

.chart-footer {
  margin-top: 2rem;
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  justify-content: flex-end;
}

@media (max-width: 768px) {
  .chart-footer {
    margin-top: 1rem;
    padding-top: 1rem;
  }
}

.brand {
  font-weight: 800;
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--text-muted);
}

@media (max-width: 480px) {
  .brand {
    font-size: 0.65rem;
  }
}

.brand .accent {
  color: var(--google-blue);
}

