const links = [
  { source: 0, target: 6, value: 48.5 },
  { source: 1, target: 6, value: 8.7 },
  { source: 2, target: 6, value: 7.4 },
  { source: 6, target: 7, value: 64.6 },
  { source: 3, target: 7, value: 9.3 },
  { source: 4, target: 7, value: 10.3 },
